inline const Widget* find_widget(const Snapshot& view,const WidgetKey& key) {
    for(const auto& w:view.widgets)if(w.spec.key==key)return &w;
    return nullptr;
}
inline bool in_modal_scope(const Snapshot& view,const WidgetKey& key) {
    if(!view.modal_root)return true;
    const auto* current=find_widget(view,key);
    for(std::size_t depth=0;current&&depth<=view.widgets.size();++depth) {
        if(current->spec.key==*view.modal_root)return true;
        if(current->spec.parent.empty())return false;
        const auto parent=current->spec.parent;current=nullptr;
        for(const auto& candidate:view.widgets)if(candidate.spec.key.id==parent){current=&candidate;break;}
    }
    return false;
}
struct Availability {
    Rect bounds,clip; // Resolved client bounds and their visible intersection.
    bool visible=false,enabled=false;
};
using ScrollLookup=std::function<Point(const WidgetKey&)>;
// Declared bounds describe the unscrolled layout. A group's positive scroll
// offset moves its descendants left/up, including nested groups; its own frame
// stays fixed. Supplying no lookup resolves the layout at zero scroll.
inline Availability availability(const Snapshot& view,const WidgetKey& key,const ScrollLookup& scroll={}) {
    struct Resolved {Availability area;Point children_translation;Rect children_clip;};
    std::map<std::string,Resolved,std::less<>> resolved;
    for(const auto& w:view.widgets) {
        Point translation;
        const Resolved* parent=nullptr;
        if(!w.spec.parent.empty()) {
            parent=&resolved.at(w.spec.parent);translation=parent->children_translation;
        }
        const Rect bounds{w.state.bounds.x+translation.x,w.state.bounds.y+translation.y,
            w.state.bounds.width,w.state.bounds.height};
        Availability a{bounds,intersect(bounds,{0,0,view.client_size.width,view.client_size.height}),
            w.state.visible,w.state.enabled};
        if(!w.spec.page.empty()) {
            a.visible=a.visible&&view.active_page==w.spec.page;
            for(const auto& page:view.pages)if(page.id==w.spec.page) {
                a.visible=a.visible&&page.visible;a.enabled=a.enabled&&page.enabled;
            }
        }
        if(parent) {
            a.clip=intersect(a.clip,parent->children_clip);
            a.visible=a.visible&&parent->area.visible;a.enabled=a.enabled&&parent->area.enabled;
        }
        a.visible=a.visible&&has_area(a.clip);
        auto children_clip=a.clip;
        if(w.state.content_clip) {
            const auto clip=*w.state.content_clip;
            children_clip=intersect(children_clip,{bounds.x+clip.x,bounds.y+clip.y,clip.width,clip.height});
        }
        if(w.spec.kind==Kind::group&&scroll) {
            const auto offset=scroll(w.spec.key);
            if(!std::isfinite(offset.x)||!std::isfinite(offset.y)||offset.x<0||offset.y<0||
               offset.x>coordinate_limit||offset.y>coordinate_limit)
                throw std::invalid_argument("Invalid group scroll offset");
            translation.x-=offset.x;translation.y-=offset.y;
        }
        resolved.emplace(w.spec.key.id,Resolved{a,translation,children_clip});
        if(w.spec.key==key){a.enabled=a.enabled&&in_modal_scope(view,key);return a;}
    }
    return {};
}
inline bool focusable(const Widget& w) {
    return w.spec.kind!=Kind::group&&w.spec.kind!=Kind::label&&
        (w.spec.kind!=Kind::bitmap||w.spec.pointer_input||!w.state.actions.empty());
}
inline void validate_snapshot(const Snapshot& view) {
    const auto require=[](bool ok,const char* message){if(!ok)throw std::invalid_argument(message);};
    const auto text=[&](const std::string& s){require(valid_utf8(s),"Invalid UTF-8 presentation text");};
    require(valid_rect({0,0,view.client_size.width,view.client_size.height}),"Invalid client size");
    require(valid_rect(view.page_bar),"Invalid page navigation bounds");
    device_rect({0,0,view.client_size.width,view.client_size.height},view.display_scale);
    (void)pixel_row_bytes(0,view.bitmap_format);
    text(view.title);
    std::set<std::string> pages;
    for(const auto& page:view.pages) {
        text(page.id);text(page.label);
        require(!page.id.empty()&&pages.insert(page.id).second,"Page IDs must be nonempty and unique");
    }
    require(!view.active_page||pages.contains(*view.active_page),"Unknown active page");
    std::map<std::string,const Widget*,std::less<>> widgets;
    for(const auto& w:view.widgets) {
        const auto& s=w.spec;const auto& v=w.state;
        switch(s.kind) {
            case Kind::group:case Kind::label:case Kind::button:case Kind::toggle:case Kind::choice:
            case Kind::text:case Kind::list:case Kind::bitmap:case Kind::menu:break;
            default:throw std::invalid_argument("Unknown widget kind");
        }
        switch(s.text_policy.submit) {
            case SubmitKey::none:case SubmitKey::enter:case SubmitKey::control_enter:break;
            default:throw std::invalid_argument("Unknown text submission policy");
        }
        text(s.key.id);text(s.page);text(s.parent);text(s.binding);
        require(!s.key.id.empty()&&s.key.generation!=0&&widgets.emplace(s.key.id,&w).second,"Invalid or duplicate widget key");
        require(s.page.empty()||pages.contains(s.page),"Unknown widget page");
        if(!s.parent.empty()) {
            const auto found=widgets.find(s.parent);
            require(found!=widgets.end()&&found->second!=&w&&found->second->spec.kind==Kind::group,"Parent must be an earlier group");
            require(found->second->spec.page==s.page,"Child and parent must use the same page");
        }
        require(valid_rect(v.bounds)&&valid_rect({0,0,v.content_size.width,v.content_size.height}),"Invalid widget geometry");
        validate_font(v.font);validate_wrap(v.wrap);
        if(v.content_clip)require(s.kind==Kind::group&&valid_rect(*v.content_clip),"Invalid group content clip");
        for(const auto* value:{&v.label,&v.text,&v.help,&v.accessible_name,&v.placeholder,&v.display_text})text(*value);
        require(std::isfinite(s.row_height)&&s.row_height>0&&s.row_height<=coordinate_limit,"Invalid row height");
        if(s.kind==Kind::text)require(text_error(v.text,s.text_policy).empty(),"Invalid editor state");
        require(v.options.empty()||s.kind==Kind::choice||s.kind==Kind::menu||s.kind==Kind::text,"Options on unsupported widget");
        require(v.actions.empty()||s.kind==Kind::bitmap,"Actions on unsupported widget");
        require(v.records.empty()||s.kind==Kind::list,"Records on unsupported widget");
        require(!v.selected||s.kind==Kind::list||s.kind==Kind::choice,"Selection on unsupported widget");
        if(v.selected){text(*v.selected);require(!v.selected->empty(),"Empty selected ID");}
        std::set<std::string> ids;
        for(const auto& option:v.options) {
            text(option.id);text(option.label);text(option.value);
            require(!option.id.empty()&&ids.insert(option.id).second,"Option IDs must be nonempty and unique");
            if(s.kind==Kind::text)require(text_error(option.value,s.text_policy).empty(),"Invalid suggested text");
        }
        ids.clear();
        for(const auto& action:v.actions) {
            text(action.id);text(action.label);
            require(!action.id.empty()&&!action.label.empty()&&action.value.empty()&&ids.insert(action.id).second,
                    "Action IDs and labels must be nonempty, IDs unique, and values empty");
        }
        ids.clear();
        require(double(v.records.size())*s.row_height<=coordinate_limit,"List is too tall");
        for(const auto& record:v.records) {
            text(record.id);text(record.accessible_text);
            require(!record.id.empty()&&ids.insert(record.id).second,"Record IDs must be nonempty and unique");
            for(const auto& cell:record.cells) {
                text(cell.text);validate_font(cell.font);validate_wrap(cell.wrap);require(valid_rect(cell.bounds),"Invalid record cell geometry");
            }
        }
        text(v.bitmap.source_id);
    }
    if(view.modal_root) {
        const auto* root=find_widget(view,*view.modal_root);
        require(root&&root->spec.kind==Kind::group,"Modal root must name a current group");
        for(auto* current=root;current;) {
            require(current->state.visible&&current->state.enabled,"Modal root and ancestors must be visible and enabled");
            if(!current->spec.page.empty()) {
                const auto page=std::find_if(view.pages.begin(),view.pages.end(),[&](const Page& p){return p.id==current->spec.page;});
                require(page!=view.pages.end()&&page->visible&&page->enabled&&view.active_page==page->id,
                    "Modal root must be on an available active page");
            }
            if(current->spec.parent.empty())break;
            const auto parent=std::find_if(view.widgets.begin(),view.widgets.end(),[&](const Widget& w){return w.spec.key.id==current->spec.parent;});
            current=parent==view.widgets.end()?nullptr:&*parent;
        }
    }
    std::set<std::tuple<ShortcutKey,bool,bool,bool>> strokes;
    for(const auto& binding:view.key_bindings) {
        require(binding.key>=ShortcutKey::escape&&binding.key<=ShortcutKey::f12,"Unknown shortcut key");
        const auto* target=find_widget(view,binding.target);
        require(target&&target->spec.kind==Kind::button,"Shortcut must target a current button");
        require(strokes.emplace(binding.key,binding.control,binding.shift,binding.alt).second,"Duplicate shortcut");
    }
}
// Shared event policy for an already validated presentation. Scroll offsets
// must match the presentation being checked. A successful normalization may
// convert SelectRecord into its declared combined ActivateRecord; callers must
// discard events for which this returns false. Lifetime and dispatch guards
// remain the adapter's responsibility.
inline bool normalize_widget_event(const Snapshot& view,WidgetEvent& event,const ScrollLookup& scroll={}) {
    const auto* w=find_widget(view,event.target);const auto a=availability(view,event.target,scroll);
    if(!w||!a.visible||!a.enabled)return false;
    const auto kind=w->spec.kind;
    // Convert configured row selection into one combined activation event.
    if(auto* select=std::get_if<SelectRecord>(&event.input);select&&w->spec.activate_on_select)
        for(const auto& row:w->state.records)if(row.id==select->id&&row.activatable) {
            auto id=select->id;event.input=ActivateRecord{std::move(id)};break;
        }
    return std::visit([&](const auto& input)->bool {
        using T=std::decay_t<decltype(input)>;
        if constexpr(std::is_same_v<T,Activate>)return kind==Kind::button;
        else if constexpr(std::is_same_v<T,SetChecked>)return kind==Kind::toggle&&input.value!=w->state.checked;
        else if constexpr(std::is_same_v<T,EditText>)return kind==Kind::text&&!w->spec.text_policy.read_only&&
            input.base_text==w->state.text&&input.value!=w->state.text&&text_error(input.value,w->spec.text_policy).empty();
        else if constexpr(std::is_same_v<T,ChooseOption>) {
            if(kind!=Kind::choice&&kind!=Kind::text&&kind!=Kind::menu)return false;
            if(kind==Kind::text&&w->spec.text_policy.read_only)return false;
            for(const auto& option:w->state.options)if(option.id==input.id)
                return option.enabled&&(kind!=Kind::choice||w->state.selected!=option.id);
            return false;
        } else if constexpr(std::is_same_v<T,SelectRecord>||std::is_same_v<T,ActivateRecord>) {
            if(kind!=Kind::list)return false;
            for(const auto& row:w->state.records)if(row.id==input.id)
                return row.enabled&&(!std::is_same_v<T,ActivateRecord>||row.activatable);
            return false;
        } else if constexpr(std::is_same_v<T,SubmitText>)return kind==Kind::text&&
            !w->spec.text_policy.read_only&&w->spec.text_policy.submit!=SubmitKey::none;
        else if constexpr(std::is_same_v<T,InvokeAction>) {
            if(kind!=Kind::bitmap)return false;
            for(const auto& action:w->state.actions)if(action.id==input.id)return action.enabled;
            return false;
        } else {
            switch(input.kind) {case PointerKind::click:case PointerKind::double_click:case PointerKind::move:case PointerKind::wheel:break;
                default:return false;}
            return w->spec.pointer_input&&contains(a.clip,input.position)&&
                std::isfinite(input.wheel_x)&&std::isfinite(input.wheel_y)&&
                (input.kind!=PointerKind::wheel||input.wheel_x!=0||input.wheel_y!=0);
        }
    },event.input);
}
inline bool normalize_event(const Snapshot& view,Event& event,const ScrollLookup& scroll={}) {
    if(const auto* key=std::get_if<ShortcutEvent>(&event)) {
        std::optional<WidgetKey> target;
        for(const auto& binding:view.key_bindings)
            if(binding.key==key->key&&binding.control==key->control&&binding.shift==key->shift&&binding.alt==key->alt){target=binding.target;break;}
        if(!target)return false;
        event=WidgetEvent{*target,Activate{}};
    }
    return std::visit([&](auto& value)->bool {
        using T=std::decay_t<decltype(value)>;
        if constexpr(std::is_same_v<T,WidgetEvent>)return normalize_widget_event(view,value,scroll);
        else if constexpr(std::is_same_v<T,PageEvent>) {
            if(view.modal_root)return false;
            for(const auto& page:view.pages)if(page.id==value.id)
                return page.enabled&&page.visible&&view.active_page!=page.id;
            return false;
        } else if constexpr(std::is_same_v<T,ResizeEvent>) {
            return valid_rect({0,0,value.client_size.width,value.client_size.height})&&
                std::isfinite(value.display_scale)&&value.display_scale>0&&value.display_scale<=16;
        } else if constexpr(std::is_same_v<T,ShortcutEvent>)return false;
        else return true;
    },event);
}
// The adapter owns native objects. The caller retains application state.
// All methods run on the UI thread. present() and focus/scroll never emit input.
class Adapter {
public:
    virtual ~Adapter()=default;
    virtual void present(Snapshot snapshot)=0;
    virtual Size measure_text(const TextMeasureRequest& request) const=0;
    virtual Availability resolved_availability(const WidgetKey& target) const=0;
    virtual std::optional<WidgetKey> focused() const=0;
    virtual bool focus(std::optional<WidgetKey> target)=0;
    virtual bool focus_next(bool reverse=false)=0;
    virtual void scroll(const WidgetKey& target,Point offset)=0;
    virtual Point scroll_offset(const WidgetKey& target) const=0;
    virtual TextSelection text_selection(const WidgetKey& target) const=0;
    virtual void text_selection(const WidgetKey& target,TextSelection selection)=0;
    virtual bool open_popup(const WidgetKey& target)=0;
    virtual void close_popup(const WidgetKey& target)=0;
    virtual void invalidate(const WidgetKey& target,PixelRect damage)=0;
    virtual bool closed() const=0;
    virtual void close()=0;
};
}

#pragma once
#include <algorithm>
#include <cmath>
#include <optional>
#include <span>
#include <stdexcept>
#include <vector>

namespace gui {
// Logical client coordinates; all rectangles are half open.
struct Point { double x=0, y=0; bool operator==(const Point&) const = default; };
struct Size { double width=0, height=0; bool operator==(const Size&) const = default; };
struct Rect {
    double x=0, y=0, width=0, height=0;
    bool operator==(const Rect&) const = default;
};
inline constexpr double coordinate_limit=1000000;
inline bool valid_rect(Rect r) {
    return std::isfinite(r.x)&&std::isfinite(r.y)&&std::isfinite(r.width)&&std::isfinite(r.height)&&
        std::abs(r.x)<=coordinate_limit&&std::abs(r.y)<=coordinate_limit&&
        r.width>=0&&r.height>=0&&r.width<=coordinate_limit&&r.height<=coordinate_limit&&
        std::abs(r.x+r.width)<=coordinate_limit&&std::abs(r.y+r.height)<=coordinate_limit;
}
inline bool has_area(Rect r) { return r.width>0&&r.height>0; }
inline bool contains(Rect r,Point p) {
    return p.x>=r.x&&p.y>=r.y&&p.x<r.x+r.width&&p.y<r.y+r.height;
}
namespace geometry_detail {
// Subtraction and re-addition can round to opposite sides of an endpoint,
// especially when a negative origin crosses zero. Keep the reconstructed
// endpoint inside the requested edge, without adding tolerance to the contract.
inline double extent_to(double origin,double end) {
    const auto extent=std::max(0.0,end-origin);
    return extent>0&&origin+extent>end?std::nextafter(extent,0.0):extent;
}
}
inline Rect intersect(Rect a,Rect b) {
    const auto x=std::max(a.x,b.x),y=std::max(a.y,b.y);
    return {x,y,geometry_detail::extent_to(x,std::min(a.x+a.width,b.x+b.width)),
                geometry_detail::extent_to(y,std::min(a.y+a.height,b.y+b.height))};
}
struct DeviceRect { int x=0,y=0; unsigned width=0,height=0; };
// Snap endpoints independently. Shared edges therefore share device coordinates.
inline DeviceRect device_rect(Rect r,double scale) {
    if(!valid_rect(r)||!std::isfinite(scale)||scale<=0||scale>16)
        throw std::invalid_argument("Invalid rectangle or display scale");
    const auto x=static_cast<int>(std::round(r.x*scale));
    const auto y=static_cast<int>(std::round(r.y*scale));
    const auto right=static_cast<int>(std::round((r.x+r.width)*scale));
    const auto bottom=static_cast<int>(std::round((r.y+r.height)*scale));
    return {x,y,static_cast<unsigned>(right-x),static_cast<unsigned>(bottom-y)};
}
// Native pointer -> logical client point -> local backing pixel. Captions are
// separate widgets and must not be included in the bitmap rectangle.
inline std::optional<Point> pixel_at(Rect area,unsigned width,unsigned height,Point logical) {
    if(!valid_rect(area)||!has_area(area)||!contains(area,logical)||!width||!height)return {};
    return Point{std::min(double(width-1),std::floor((logical.x-area.x)*width/area.width)),
                 std::min(double(height-1),std::floor((logical.y-area.y)*height/area.height))};
}
enum class Axis { horizontal, vertical };
struct Allocation { double fixed=0,weight=1; };
// Fixed sizes consume available space in order. Remaining space is shared by
// nonnegative weights. This helper emits absolute rectangles for the contract.
inline std::vector<Rect> arrange(Rect area,Axis axis,std::span<const Allocation> items,double gap=0) {
    if(!valid_rect(area)||(axis!=Axis::horizontal&&axis!=Axis::vertical)||
       !std::isfinite(gap)||gap<0||gap>coordinate_limit)
        throw std::invalid_argument("Invalid layout");
    double fixed=0,largest_weight=0;
    for(auto item:items) {
        if(!std::isfinite(item.fixed)||!std::isfinite(item.weight)||item.fixed<0||item.weight<0||
           item.fixed>coordinate_limit||item.weight>coordinate_limit)
            throw std::invalid_argument("Invalid allocation");
        fixed=std::min(coordinate_limit,fixed+item.fixed);
        if(item.fixed==0)largest_weight=std::max(largest_weight,item.weight);
    }
    // Normalize before summing and multiplying: tiny positive weights must
    // still share space even when extent * weight would underflow.
    double weight=0;
    if(largest_weight>0)
        for(auto item:items)if(item.fixed==0)weight+=item.weight/largest_weight;
    double extent=axis==Axis::horizontal?area.width:area.height;
    double flexible=std::max(0.0,extent-fixed-gap*double(items.empty()?0:items.size()-1));
    double cursor=0;
    std::vector<Rect> result;result.reserve(items.size());
    for(auto item:items) {
        double length=std::min(std::max(0.0,extent-cursor),
            item.fixed>0?item.fixed:(weight>0?flexible*((item.weight/largest_weight)/weight):0));
        const auto origin=(axis==Axis::horizontal?area.x:area.y)+cursor;
        const auto end=axis==Axis::horizontal?area.x+area.width:area.y+area.height;
        // Translation can round an endpoint past its parent by one ULP even
        // when the local allocation fits. Constrain against the absolute edge.
        length=std::min(length,geometry_detail::extent_to(origin,end));
        result.push_back(axis==Axis::horizontal?Rect{origin,area.y,length,area.height}:
            Rect{area.x,origin,area.width,length});
        cursor=std::min(extent,cursor+length+gap);
    }
    return result;
}
}

#pragma once
#include "contract.hpp"

namespace gui {
// Shared transient chrome stays in logical client coordinates, just like the
// application snapshot. Native and software hosts consume the same geometry.
inline double popup_row_height(Size client,std::size_t count,double natural=24) {
    return count?std::min(natural,std::max(1.0,client.height/double(count))):natural;
}
inline Rect popup_bounds(Size client,Rect anchor,std::size_t count,double row_height) {
    const double width=std::min(client.width,std::max(180.0,anchor.width));
    const double height=double(count)*row_height;
    return {std::clamp(anchor.x,0.0,std::max(0.0,client.width-width)),
        std::clamp(anchor.y+anchor.height,0.0,std::max(0.0,client.height-height)),width,height};
}
inline Rect prompt_bounds(Size client) {
    const double width=std::min(440.0,client.width),height=std::min(144.0,client.height);
    return {(client.width-width)/2,(client.height-height)/2,width,height};
}
inline Rect prompt_field_bounds(Size client) {
    const auto box=prompt_bounds(client);return intersect(box,{box.x+12,box.y+46,std::max(0.0,box.width-24),28});
}
inline Rect prompt_cancel_bounds(Size client) {
    const auto box=prompt_bounds(client);return intersect(box,{box.x+12,box.y+box.height-36,90,24});
}
inline Rect prompt_accept_bounds(Size client) {
    const auto box=prompt_bounds(client);return intersect(box,{box.x+box.width-102,box.y+box.height-36,90,24});
}
inline Color tone_color(const Palette& palette,Tone tone) {
    switch(tone) {case Tone::muted:return palette.muted;case Tone::accent:return palette.accent;case Tone::error:return palette.error;default:return palette.text;}
}
struct PageTab {std::string id,label;Rect bounds;bool enabled=true,selected=false;};
// Chrome is computed once in logical client coordinates. Hosts render these
// rectangles; they never choose page sizes or positions from application IDs.
inline std::vector<PageTab> page_tabs(const Snapshot& snapshot) {
    std::vector<PageTab> result;
    const auto count=std::count_if(snapshot.pages.begin(),snapshot.pages.end(),[](const Page& p){return p.visible;});
    if(count==0||!has_area(snapshot.page_bar))return result;
    const auto width=snapshot.page_bar.width/double(count);
    for(const auto& page:snapshot.pages)if(page.visible)
        result.push_back({page.id,page.label,{snapshot.page_bar.x+double(result.size())*width,snapshot.page_bar.y,width,snapshot.page_bar.height},
            page.enabled&&!snapshot.modal_root,snapshot.active_page==page.id});
    return result;
}
inline std::string visible_text(const Widget& widget) {
    switch(widget.spec.kind) {
    case Kind::label:return widget.state.text;
    case Kind::text:return widget.state.text.empty()?widget.state.placeholder:widget.state.text;
    case Kind::choice:
        if(!widget.state.display_text.empty())return widget.state.display_text;
        for(const auto& option:widget.state.options)if(widget.state.selected==option.id)return option.label;
        return widget.state.placeholder;
    default:return widget.state.label;
    }
}
inline std::vector<WidgetKey> paint_order(const Snapshot& snapshot) {
    std::vector<WidgetKey> result;result.reserve(snapshot.widgets.size());
    for(const auto& widget:snapshot.widgets)if(!snapshot.modal_root||!in_modal_scope(snapshot,widget.spec.key))result.push_back(widget.spec.key);
    if(snapshot.modal_root)for(const auto& widget:snapshot.widgets)if(in_modal_scope(snapshot,widget.spec.key))result.push_back(widget.spec.key);
    return result;
}
