#!/usr/bin/env python3
"""Check application sources and concrete GUI/domain dependencies before compiling.

This is an architectural tripwire, not a C++ parser or a security boundary. Keep
executable conformance and public-interface review alongside it.
"""
from pathlib import Path
import argparse
import posixpath
import re
import sys

PUBLIC_GUI = {'gui/contract.hpp', 'gui/layout.hpp', 'gui/runtime.hpp'}
SOURCE_SUFFIXES = {'.c', '.cc', '.cpp', '.cxx', '.h', '.hh', '.hpp', '.hxx',
                   '.ipp', '.tpp', '.inc', '.ixx', '.cppm', '.rs'}
# Keep string contents while removing comments, so includes and widget IDs remain
# visible and an explanatory comment cannot create a false dependency.
TOKENS = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|/\*.*?\*/|//[^\n]*', re.S)
RUST_LITERAL = re.compile(
    r'(?:br|r)(?P<hashes>\#*)".*?"(?P=hashes)|'
    r'b?"(?:\\.|[^"\\])*"|'
    r"b?'(?:\\(?:u\{[0-9a-fA-F_]+\}|x[0-9a-fA-F]{2}|.)|[^'\\])'", re.S)
RUST_TOKEN = re.compile(r'[A-Za-z_][A-Za-z0-9_]*|::|[^\s]')
RUST_BACKENDS = {'gui', 'fl', 'fltk', 'sdl', 'sdl2', 'rev', 'backends', 'host', 'hosts'}


def rust_code(source):
    """Keep Rust identifiers and attribute literals without comments or lifetimes loss."""
    tokens, literals, index = [], {}, 0
    while index < len(source):
        if source.startswith('//', index):
            end = source.find('\n', index)
            index = len(source) if end < 0 else end
            continue
        if source.startswith('/*', index):
            index += 2
            depth = 1
            while index < len(source) and depth:
                if source.startswith('/*', index): depth += 1; index += 2
                elif source.startswith('*/', index): depth -= 1; index += 2
                else: index += 1
            continue
        literal = RUST_LITERAL.match(source, index)
        if literal:
            value = literal[0]
            name = 'RUST_LITERAL_' + str(len(literals))
            if '"' in value:
                begin, end = value.find('"') + 1, value.rfind('"')
                contents = value[begin:end]
                if literal['hashes'] is None:
                    contents = re.sub(r'\\u\{([0-9a-fA-F_]+)\}',
                                      lambda m: chr(int(m[1].replace('_', ''), 16)), contents)
                    contents = re.sub(r'\\x([0-9a-fA-F]{2})', lambda m: chr(int(m[1], 16)), contents)
                    contents = re.sub(r'\\([\\"nrt0])',
                                      lambda m: {'n':'\n', 'r':'\r', 't':'\t', '0':'\0'}.get(m[1], m[1]), contents)
                literals[name] = contents
            else:
                literals[name] = ''
            tokens.append(name)
            index = literal.end()
            continue
        token = RUST_TOKEN.match(source, index)
        if token:
            tokens.append(token[0]); index = token.end()
        else:
            index += 1
    return ' '.join(tokens), literals


def rust_violations(source):
    code, literals = rust_code(source)
    result = []
    imports = re.findall(r'\b(?:use|extern\s+crate)\s+([^;]+);', code)
    if any(RUST_BACKENDS.intersection(name.lower() for name in re.findall(r'\b\w+\b', entry))
           for entry in imports):
        result.append('concrete Rust GUI/backend import')
    if re.search(r'\b(?:gui|fltk|sdl2?|rev|backends|hosts?)\s*::', code, re.I) or re.search(
            r'\b(?:SDL_\w+|Fl_\w+|Rev_\w+|foundation_gui_\w+|gui_\w+|fltk_\w+|'
            r'(?:Terminal|Framebuffer|Web|Memory|Interactive|Retained)Adapter)\b', code):
        result.append('concrete Rust backend dependency')
    for block in re.findall(r'\bextern\s+RUST_LITERAL_\d+\s*\{([^}]+)\}', code):
        if any(re.match(r'(?:sdl_|sdl2_|rev_|Rev|fltk_|Fl_)', name)
               for name in re.findall(r'\bfn\s+(\w+)', block)):
            result.append('concrete Rust backend foreign symbol')
    for attribute in re.findall(r'#\s*!?\s*\[([^\]]+)\]', code):
        for field in ('name', 'link_name'):
            if field == 'name' and not re.match(r'\s*link\s*\(', attribute):
                continue
            match = re.search(r'\b' + field + r'\s*=\s*(\w+)', attribute)
            if not match:
                continue
            if match[1] not in literals:
                result.append('computed Rust native linkage hides dependency boundary')
                continue
            name = literals[match[1]]
            if re.search(r'^(?:lib)?(?:gui|foundation_gui|fltk|fl|sdl2?(?:main)?|rev)(?:\b|[_0-9.-])', name, re.I):
                result.append('concrete Rust backend linkage: ' + name)
        path = re.search(r'\bpath\s*=\s*(RUST_LITERAL_\d+)', attribute)
        if path and any(part.lower() in RUST_BACKENDS for part in Path(literals[path[1]]).parts):
            result.append('concrete Rust backend module path')
    return result


def uncomment(source):
    return TOKENS.sub(lambda m: ('\n' * m[0].count('\n') if m[0].startswith(('/',)) else m[0]),
                      source.replace('\\\n', ''))


def include_entries(source):
    for directive, body in re.findall(r'^\s*#\s*(include|include_next)\b\s*([^\n]+)', uncomment(source), re.M):
        match = re.fullmatch(r'\s*(?:<([^>]+)>|"([^"]+)")\s*', body)
        if directive == 'include_next' or not match:
            yield None, False
        else:
            yield match[1] or match[2], match[2] is not None


def includes(source):
    return (name for name, _ in include_entries(source))


def shared_violations(source):
    result = []
    source = uncomment(source)
    for include in includes(source):
        if include is None:
            result.append('computed include hides the application dependency boundary')
            continue
        name = posixpath.normpath(include.replace('\\', '/'))
        gui = re.search(r'(?:^|/)(gui/.*)$', name)
        if gui and gui[1] not in PUBLIC_GUI:
            result.append(include)
        if any(part.lower() in ('fl', 'sdl', 'sdl2', 'backends', 'hosts', 'host')
               for part in name.split('/')) or re.search(r'(?:^|/)(?:windows\.h|SDL[^/]*)$', name, re.I):
            result.append(include)
    code = re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', '""', source)
    if re.search(r'\b(?:import\s+Rev|Rev\s*::|Fl_\w+|Fl\s*::|SDL_\w+|'
                 r'(?:Terminal|Framebuffer|Web|Memory|Interactive|Retained)Adapter|'
                 r'gui\s*::\s*(?:fltk|rev)\b)', code):
        result.append('concrete backend dependency')
    return result


def without_includes(source):
    return re.sub(r'^\s*#\s*include\b[^\n]*', '', source, flags=re.M)


def composition_root(root, path):
    return path.parent == root / 'hosts' and path.name.endswith(('_main.cpp', '_main.rs'))


def sources(directory):
    return sorted(path for path in directory.rglob('*')
                  if path.is_file() and path.suffix in SOURCE_SUFFIXES)


def resolve_include(root, path, name, quoted=True):
    if name is None:
        return None
    candidates = ([path.parent / name] if quoted else []) + [root / name, root.parent / 'include' / name]
    for candidate in candidates:
        if candidate.is_file():
            resolved = candidate.resolve()
            if root.parent != resolved and root.parent not in resolved.parents:
                raise ValueError('local include escapes project: ' + name)
            return resolved
    return None  # External public/standard headers are checked by name/compiler.


def analyze(root):
    root = Path(root).resolve()
    failures, dependencies, visited = [], set(), set()
    shared_paths = sources(root / 'shared')
    identities = {'entries.'}
    for path in shared_paths:
        if path.suffix == '.rs':
            identities.update(value for value in rust_code(path.read_text())[1].values()
                              if re.fullmatch(r'[A-Za-z][A-Za-z0-9_]*\.[A-Za-z0-9_.-]+', value))
        else:
            identities.update(re.findall(r'"([A-Za-z][A-Za-z0-9_]*\.[A-Za-z0-9_.-]+)"', without_includes(uncomment(path.read_text()))))

    def walk(path, layer):
        key = (path, layer)
        if key in visited:
            return
        visited.add(key); dependencies.add(path)
        if path.suffix == '.rs':
            source = path.read_text()
            issues = rust_violations(source) if layer == 'shared' else []
            if layer == 'host':
                code, literals = rust_code(source)
                if any(value.startswith('entries.') or value in identities for value in literals.values()):
                    issues.append('application identity in Rust host')
                if re.search(r'\bfoundation\s*::\s*(?:Store|Record|InsertResult|InsertError)\b', code) or re.search(
                        r'\buse\s+foundation\s*::\s*\{[^;]*(?:Store|Record|InsertResult|InsertError)\b', code):
                    issues.append('application domain dependency in Rust host')
                app_types = re.findall(r'\bfoundation\s*::\s*ui\s*::\s*(\w+)', code)
                if any(name != 'Application' or not composition_root(root, path) for name in app_types):
                    issues.append('application implementation in Rust host')
            failures.extend(str(path) + ': ' + issue for issue in issues)
            return
        text = uncomment(path.read_text())
        issues = shared_violations(text) if layer == 'shared' else []
        if layer == 'host':
            literals = re.findall(r'"((?:\\.|[^"\\])*)"', without_includes(text))
            if any(value.startswith('entries.') or value in identities for value in literals):
                issues.append('application identity in host')
            if re.search(r'\bfoundation\s*::\s*(?:Store|Record|InsertResult|InsertError)\b', text):
                issues.append('application domain dependency in host')
            app_types = re.findall(r'\bfoundation\s*::\s*ui\s*::\s*(\w+)', text)
            if any(name != 'Application' or not composition_root(root, path) for name in app_types):
                issues.append('application implementation in host')
        for name, quoted in include_entries(text):
            if name is None:
                if layer == 'host': issues.append('computed include hides host dependency boundary')
                continue
            try:
                target = resolve_include(root, path, name, quoted)
            except ValueError as error:
                issues.append(str(error)); continue
            if target is None:
                continue
            if layer == 'shared' and any(directory in target.parents for directory in (root/'host', root/'hosts')):
                issues.append('host dependency through ' + name); continue
            if layer == 'host' and root.parent / 'include/foundation' in target.parents:
                issues.append('application domain header through ' + name); continue
            if layer == 'host' and root / 'shared' in target.parents:
                # Composition roots may name the public application type. A
                # helper cannot smuggle feature code into generic host services.
                if target != root/'shared/application.hpp' or not composition_root(root, path):
                    issues.append('shared application implementation through ' + name)
                dependencies.add(target)
                continue
            walk(target, layer)
        failures.extend(str(path) + ': ' + issue for issue in issues)

    for path in shared_paths:
        walk(path.resolve(), 'shared')
    for path in sources(root.parent / 'rust'):
        if path.suffix == '.rs':
            walk(path.resolve(), 'shared')
    for directory in ('host', 'hosts'):
        for path in sources(root / directory):
            walk(path.resolve(), 'host')
    return sorted(set(failures)), sorted(dependencies)


def tree_violations(root):
    return analyze(root)[0]


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dependencies', action='store_true')
    args = parser.parse_args()
    failures, dependencies = analyze(Path(__file__).resolve().parent)
    if args.dependencies:
        print(';'.join(str(path) for path in dependencies), end='')
    elif failures:
        print('\n'.join(failures), file=sys.stderr)
        sys.exit(1)

#pragma once
#include <gui/interaction.hpp>
#include <limits>
#include <memory>
#include <string>
#include <vector>

namespace foundation::host {
// A three/five physical-key projection of declared, eligible actions. A press
// belongs to an explicitly committed presentation, never to a refreshed fallback.
class Bezel {
    struct Identity {};
    enum class Operation { activate, checked, choose, action };
    struct Action {
        gui::WidgetKey target;
        std::string id, label, value;
        Operation operation;
        bool checked=false;
        bool operator==(const Action&) const = default;
        gui::Input input() const {
            switch(operation) {
                case Operation::activate:return gui::Activate{};
                case Operation::checked:return gui::SetChecked{checked};
                case Operation::choose:return gui::ChooseOption{id};
                case Operation::action:return gui::InvokeAction{id};
            }
            throw std::logic_error("Unknown bezel operation");
        }
    };
    struct Binding {
        gui::ShortcutKey key;gui::WidgetKey target;bool control,shift,alt;
        bool operator==(const Binding&) const = default;
    };
    struct Context {
        enum class Mode { closed, ordinary, prompt, popup } mode=Mode::closed;
        std::vector<gui::Page> pages;
        std::optional<std::string> page;
        std::optional<gui::WidgetKey> modal;
        std::vector<Binding> bindings;
        std::vector<Action> actions;
        std::size_t selected=0;
        std::uint64_t prompt_id=0;
        gui::ServiceKind prompt_kind=gui::ServiceKind::prompt;
        std::string title,value;
        std::size_t limit=0;
        gui::WidgetKey popup_target;
        gui::Kind popup_kind=gui::Kind::label;
        std::vector<gui::Option> popup_options,declared_options;
        std::optional<std::string> declared_selection;
        bool popup_agrees=false;
        bool operator==(const Context&) const = default;
    };
public:
    // Owned, immutable through the public interface; copies retain one identity.
    class Token {
        friend class Bezel;
        std::shared_ptr<const Identity> owner_;
        std::uint64_t serial_=0,epoch_=0;
        Context context_;
        std::vector<std::string> labels_;
        Token(std::shared_ptr<const Identity> owner,std::uint64_t serial,std::uint64_t epoch,
              Context context,std::vector<std::string> labels)
            :owner_(owner),serial_(serial),epoch_(epoch),context_(std::move(context)),labels_(std::move(labels)) {}
    public:
        Token()=default;
        const std::vector<std::string>& labels() const noexcept {return labels_;}
        std::uint64_t input_epoch() const noexcept {return epoch_;}
    };
    explicit Bezel(unsigned buttons=3):buttons_(buttons) {
        if(buttons!=3&&buttons!=5)throw std::invalid_argument("Bezel requires three or five buttons");
    }
    Bezel(const Bezel&)=delete;
    Bezel& operator=(const Bezel&)=delete;
    template<class Adapter> std::vector<std::string> labels(Adapter& adapter) {
        return labels_for(capture(adapter,true)); // Observation cannot arm input.
    }
    template<class Adapter> Token prepare(Adapter& adapter,std::uint64_t epoch) {
        if(serial_==std::numeric_limits<std::uint64_t>::max())throw std::overflow_error("Bezel identity exhausted");
        auto context=capture(adapter,true);
        return Token(identity_,++serial_,epoch,context,labels_for(context));
    }
    bool candidate(const Token& token) const noexcept {
        return token.owner_==identity_&&token.serial_!=0&&token.serial_==serial_&&token.serial_!=consumed_;
    }
    template<class Adapter> bool commit(Adapter& adapter,std::uint64_t epoch,const Token& token) {
        if(!candidate(token)||!valid(adapter,epoch,token))return false;
        committed_=token;return true;
    }
    // Consume before settling touch/ticks/services: any nested press sees no
    // committed opportunity. Exceptions propagate and cannot retry this press.
    template<class Adapter,class Settle,class Epoch,class Pending>
    bool activate(Adapter& adapter,const Token& token,unsigned button,Settle settle,Epoch epoch,Pending pending) {
        if(!committed_||token.owner_!=identity_||token.serial_!=committed_->serial_)return false;
        auto shown=std::move(*committed_);committed_.reset();consumed_=serial_;
        settle();
        if(button<1||button>buttons_||pending()||!valid(adapter,epoch(),shown))return false;
        const auto& context=shown.context_;
        if(context.mode==Context::Mode::prompt) {
            if(button>2)return false;
            adapter.key(button==1?gui::Key::escape:gui::Key::enter);return true;
        }
        if(context.mode==Context::Mode::popup) {
            if(button==5)return false;
            adapter.key(button==1?gui::Key::up:button==2?gui::Key::down:button==3?gui::Key::enter:gui::Key::escape);return true;
        }
        if(button==4){adapter.key(gui::Key::escape);return true;}
        if(button==5){adapter.key(gui::Key::next_page);return true;}
        if(context.actions.empty())return false;
        if(button==1)selected_=(selected_+context.actions.size()-1)%context.actions.size();
        else if(button==2)selected_=(selected_+1)%context.actions.size();
        else {
            const auto action=context.actions[context.selected];
            return adapter.policy().send(gui::WidgetEvent{action.target,action.input()})==gui::Delivery::delivered;
        }
        return true;
    }
private:
    unsigned buttons_;
    const std::shared_ptr<const Identity> identity_=std::make_shared<const Identity>();
    std::size_t selected_=0;
    std::uint64_t serial_=0,consumed_=0;
    std::vector<Action> actions_;
    std::optional<Token> committed_;
    template<class Adapter> Context capture(Adapter& adapter,bool refresh) {
        Context context;
        if(adapter.closed())return context;
        const auto& view=adapter.snapshot();
        context.pages=view.pages;
        context.page=view.active_page;context.modal=view.modal_root;
        for(const auto& binding:view.key_bindings)
            context.bindings.push_back({binding.key,binding.target,binding.control,binding.shift,binding.alt});
        if(const auto& prompt=adapter.prompt()) {
            context.mode=Context::Mode::prompt;context.prompt_id=prompt->id;context.prompt_kind=prompt->kind;
            context.title=prompt->title;context.value=prompt->value;context.limit=prompt->byte_limit;
            return context;
        }
        if(const auto& popup=adapter.popup()) {
            context.mode=Context::Mode::popup;context.selected=popup->index;context.popup_options=popup->options;
            if(const auto* widget=gui::find_widget(view,popup->key)) {
                context.popup_target=widget->spec.key;context.popup_kind=widget->spec.kind;context.declared_selection=widget->state.selected;
                context.declared_options=widget->spec.kind==gui::Kind::bitmap?widget->state.actions:widget->state.options;
                const auto available=adapter.resolved_availability(popup->key);
                context.popup_agrees=available.visible&&available.enabled&&gui::in_modal_scope(view,popup->key)&&
                    context.popup_options==context.declared_options;
            }
            return context;
        }
        context.mode=Context::Mode::ordinary;
        for(const auto& widget:view.widgets) {
            const auto& key=widget.spec.key;const auto available=adapter.resolved_availability(key);
            if(!available.visible||!available.enabled||!gui::in_modal_scope(view,key))continue;
            const auto add=[&](Operation operation,std::string id,std::string label,std::string value={},bool checked=false) {
                context.actions.push_back({widget.spec.key,std::move(id),std::move(label),std::move(value),operation,checked});
            };
            if(widget.spec.kind==gui::Kind::button)add(Operation::activate,"",widget.state.label);
            else if(widget.spec.kind==gui::Kind::toggle)add(Operation::checked,"",widget.state.label,"",!widget.state.checked);
            else if(widget.spec.kind==gui::Kind::choice||widget.spec.kind==gui::Kind::menu) {
                for(const auto& option:widget.state.options)if(option.enabled)add(Operation::choose,option.id,option.label,option.value);
            } else if(widget.spec.kind==gui::Kind::bitmap) {
                for(const auto& action:widget.state.actions)if(action.enabled)add(Operation::action,action.id,action.label,action.value);
            }
        }
        if(refresh) {
            std::optional<std::pair<gui::WidgetKey,std::string>> old;
            if(selected_<actions_.size())old={{actions_[selected_].target,actions_[selected_].id}};
            selected_=0;
            if(old)for(std::size_t i=0;i<context.actions.size();++i)
                if(context.actions[i].target==old->first&&context.actions[i].id==old->second){selected_=i;break;}
            actions_=context.actions;
        }
        context.selected=selected_;
        return context;
    }
    std::vector<std::string> labels_for(const Context& context) const {
        if(context.mode==Context::Mode::closed)return std::vector<std::string>(buttons_);
        std::vector<std::string> result;
        if(context.mode==Context::Mode::prompt)result={"Cancel","Accept",""};
        else if(context.mode==Context::Mode::popup)result={"Previous","Next","Choose"};
        else result={context.actions.empty()?"":"Previous",context.actions.empty()?"":"Next",
            context.selected<context.actions.size()?context.actions[context.selected].label:""};
        if(buttons_==5){result.push_back(context.mode==Context::Mode::prompt?"":"Back");result.push_back(context.mode==Context::Mode::ordinary?"Next page":"");}
        return result;
    }
    template<class Adapter> bool valid(Adapter& adapter,std::uint64_t epoch,const Token& token) {
        if(token.owner_!=identity_||epoch==0||epoch==std::numeric_limits<std::uint64_t>::max()||epoch!=token.epoch_)return false;
        const auto current=capture(adapter,false);
        return current.mode!=Context::Mode::closed&&current==token.context_&&
            (current.mode!=Context::Mode::popup||current.popup_agrees);
    }
};
}

