#include <iostream>
#include <limits>
#include <stdexcept>
#include <string_view>

import Rev.Appearance;
import Rev.Core.DirtyFlag;

namespace {
void check(bool condition, const char* message) {
    if(!condition) throw std::runtime_error(message);
}
void equality() {
    using namespace Rev::Appearance;
    // Explicit aggregate initialization avoids GCC 15's module-import failure
    // for the implicit default constructor; the flag stays clean and lists empty.
    Rev::Core::DirtyFlag dirty{};
    auto distance=Px(12), same=Px(12);
    same.transition=250;same.dirty=&dirty;
    const auto fixed=Px(12);
    check(distance==same && same==distance && fixed==distance && distance==fixed,
          "distance equality must be symmetric and ignore notification/transition metadata");
    check(!(fixed==Px(13)) && !(fixed==Pct(12)), "distance equality lost its value or unit");
    check(Px(-0.f)==Px(0.f), "distance equality changed signed-zero semantics");
    auto nan=Px(std::numeric_limits<float>::quiet_NaN());
    check(!(nan==nan), "distance equality changed NaN semantics");
    same=distance;
    check(!dirty.isDirty() && same.dirty==&dirty && same.transition==250,
          "equal distance assignment changed existing notification/transition behavior");
    same=Px(13);
    check(dirty.isDirty() && same.dirty==&dirty && same.val==13,
          "changed distance assignment must retain and notify its owner");

    auto color=rgba(.1f,.2f,.3f,.4f), same_color=color;
    same_color.transition=100;same_color.dirty=&dirty;
    const auto fixed_color=color;
    check(color==same_color && same_color==color && fixed_color==color && color==fixed_color,
          "color equality must be symmetric and ignore notification/transition metadata");
    same_color.a=.5f;
    check(!(fixed_color==same_color), "color equality lost alpha");

    VisibilityStyle visible{Visibility::Visible}, same_visible{Visibility::Visible};
    same_visible.dirty=&dirty;
    const VisibilityStyle fixed_visible{Visibility::Visible};
    check(visible==same_visible && same_visible==visible && fixed_visible==visible && visible==fixed_visible,
          "visibility equality must be symmetric and ignore notification metadata");
    check(fixed_visible==Visibility::Visible && Visibility::Visible==fixed_visible &&
          !(fixed_visible==Visibility::Hidden), "visibility enum comparison changed");
}
void layout() {
    using namespace Rev::Appearance;
    auto before=Style::Null(), after=Style::Null();
    check(!after.layoutDiffers(before), "equal styles spuriously changed geometry");
    after.background.color=rgba(.1f,.2f,.3f,.4f);
    check(!after.layoutDiffers(before), "paint-only changes must not force relayout");
    after.size.width=Px(12);
    check(after.layoutDiffers(before), "a width change must force relayout");
    after.size.width=before.size.width;
    after.visibility=Visibility::Hidden;
    check(after.layoutDiffers(before), "a visibility change must force relayout");
}
}
int main(int argc, char** argv) {
    try {
        if(argc != 2) throw std::runtime_error("Choose equality or layout");
        const std::string_view which = argv[1];
        if(which == "equality") equality();
        else if(which == "layout") layout();
        else throw std::runtime_error("Unknown style scenario");
        std::cout << "Foundation Rev " << which << " assertions passed\n";
    }
    catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}

#include "foundation/store.hpp"
#include "text_validation.h"

#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>

namespace {
uint32_t injected_status = FOUNDATION_TEXT_OK;

void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}

template<class Error, class Function>
void rejects(Function function, const char* message) {
    try { function(); }
    catch (const Error& error) {
        require(std::string(error.what()) == message, "component status error changed");
        return;
    }
    throw std::runtime_error("component failure was accepted");
}
}

namespace foundation::detail {
// This executable substitutes a component result to test the caller's contract.
uint32_t validate_text(const uint8_t*, size_t) noexcept {
    return injected_status;
}
}

int main() {
    try {
        foundation::Store store(1);
        const auto id = store.add("Original");
        const auto before = store.snapshot();
        injected_status = FOUNDATION_TEXT_INVALID_LENGTH;
        rejects<std::invalid_argument>([&] { store.add("Input"); },
                                       "text must contain 1..256 bytes");
        injected_status = FOUNDATION_TEXT_INVALID_ASCII;
        rejects<std::invalid_argument>([&] { store.update(id, "Input"); },
                                       "text must contain printable ASCII only");
        for (const uint32_t status : {uint32_t{FOUNDATION_TEXT_INVALID_POINTER},
                                      uint32_t{4}, std::numeric_limits<uint32_t>::max()}) {
            injected_status = status;
            rejects<std::logic_error>([&] { store.add("Input"); },
                                      "text validation component failed");
            rejects<std::logic_error>([&] { store.update(id, "Input"); },
                                      "text validation component failed");
            rejects<std::logic_error>([&] { store.update(0, "Input"); },
                                      "text validation component failed");
        }
        require(store.snapshot() == before, "component failure changed records");
        injected_status = FOUNDATION_TEXT_OK;
        require(store.erase(id), "original record was lost");
        require(store.add("Next") == id + 1, "component failure consumed an ID");
        std::cout << "component failure translation passed\n";
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

#include "text_validation.h"

#include <array>
#include <iostream>
#include <limits>
#include <stdexcept>

namespace {
void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}
}

int main() {
    try {
#if defined(FOUNDATION_EXPECT_RUST) && FOUNDATION_EXPECT_RUST
        constexpr uint32_t expected_provider = FOUNDATION_TEXT_PROVIDER_RUST;
#else
        constexpr uint32_t expected_provider = FOUNDATION_TEXT_PROVIDER_CPP;
#endif
        require(foundation_text_provider_v1() == expected_provider,
                "linked text provider differs from configured provider");
        const uint8_t one = 'x';
        require(foundation::detail::validate_text(&one, 1) == FOUNDATION_TEXT_OK,
                "C++ validation bridge rejected valid text");
        for (const auto* pointer : {static_cast<const uint8_t*>(nullptr), &one}) {
            for (const size_t length : {size_t{0}, size_t{257},
                                       std::numeric_limits<size_t>::max()}) {
                require(foundation_text_validate_v1(pointer, length) == FOUNDATION_TEXT_INVALID_LENGTH,
                        "invalid length did not precede buffer access");
            }
        }
        for (const size_t length : {size_t{1}, size_t{256}}) {
            require(foundation_text_validate_v1(nullptr, length) == FOUNDATION_TEXT_INVALID_POINTER,
                    "nonnull buffer contract was not enforced");
        }
        for (unsigned value = 0; value <= 255; ++value) {
            const auto byte = static_cast<uint8_t>(value);
            const uint32_t expected = value >= 32 && value <= 126
                ? FOUNDATION_TEXT_OK : FOUNDATION_TEXT_INVALID_ASCII;
            require(foundation_text_validate_v1(&byte, 1) == expected,
                    "single byte acceptance differs from printable ASCII");
        }
        std::array<uint8_t, 256> bytes;
        bytes.fill('~');
        const auto valid_bytes = bytes;
        for (size_t length = 1; length <= bytes.size(); ++length) {
            require(foundation_text_validate_v1(bytes.data(), length) == FOUNDATION_TEXT_OK,
                    "allowed length rejected");
        }
        require(bytes == valid_bytes, "validation changed valid borrowed bytes");
        for (size_t position = 0; position < bytes.size(); ++position) {
            for (const uint8_t invalid : {uint8_t{0}, uint8_t{31}, uint8_t{127},
                                         uint8_t{128}, uint8_t{255}}) {
                bytes[position] = invalid;
                const auto input = bytes;
                require(foundation_text_validate_v1(bytes.data(), bytes.size()) == FOUNDATION_TEXT_INVALID_ASCII,
                        "invalid byte was missed within a bounded buffer");
                require(bytes == input, "validation changed invalid borrowed bytes");
            }
            bytes[position] = '~';
        }
        require(bytes == valid_bytes, "validation changed the borrowed buffer");
        std::cout << "text component ABI passed (provider="
                  << (expected_provider == FOUNDATION_TEXT_PROVIDER_RUST ? "Rust" : "C++")
                  << ")\n";
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

#include "foundation/store.hpp"

#include <iostream>
#include <stdexcept>
#include <string>

namespace {
void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}
template<class Error, class Function> void rejects(Function function) {
    try { function(); }
    catch (const Error&) { return; }
    throw std::runtime_error("expected rejection did not occur");
}
template<class Function> void rejects_text(Function function, const char* message) {
    try { function(); }
    catch (const std::invalid_argument& error) {
        require(std::string(error.what()) == message, "text error message changed");
        return;
    }
    throw std::runtime_error("expected text rejection did not occur");
}
}

int main() {
    try {
        rejects<std::invalid_argument>([] { foundation::Store store(0); });
        rejects<std::invalid_argument>([] { foundation::Store store(4097); });
        foundation::Store store(2);
        const auto a = store.add("Alpha");
        const auto b = store.add("Beta");
        require(a == 1 && b == 2, "initial IDs");
        const auto before = store.snapshot();
        rejects<std::length_error>([&] { store.add("Gamma"); });
        constexpr auto length_error = "text must contain 1..256 bytes";
        constexpr auto ascii_error = "text must contain printable ASCII only";
        rejects_text([&] { store.add(""); }, length_error);
        rejects_text([&] { store.add("bad\ntext"); }, ascii_error);
        rejects_text([&] { store.update(a, std::string_view{}); }, length_error);
        rejects_text([&] { store.update(a, std::string(257, 'x')); }, length_error);
        rejects_text([&] { store.update(a, std::string(257, '\n')); }, length_error);
        rejects_text([&] { store.update(a, "bad\ntext"); }, ascii_error);
        rejects_text([&] { store.update(a, std::string("a\0b", 3)); }, ascii_error);
        rejects_text([&] { store.update(0, ""); }, length_error);
        rejects_text([&] { store.update(0, "bad\ntext"); }, ascii_error);
        require(store.snapshot() == before, "failed operation changed state");
        require(!store.update(0, "Valid") && !store.erase(0), "missing ID accepted");
        require(store.update(a, std::string(256, 'x')), "maximum length rejected");
        auto copy = store.get(a);
        copy->text = "local";
        require(store.get(a)->text.size() == 256, "copy modified owned state");
        require(store.erase(a) && !store.get(a), "erase failed");
        require(store.add("Gamma") == 3, "ID reused or failure consumed ID");
        require(store.get(b)->text == "Beta", "unrelated record changed");
        foundation::Store bytes(1);
        for (unsigned value = 0; value < 256; ++value) {
            const auto text = std::string(1, static_cast<char>(value));
            if (value >= 32 && value <= 126) {
                const auto id = bytes.add(text);
                require(bytes.get(id)->text == text, "valid byte changed");
                bytes.erase(id);
            } else {
                rejects<std::invalid_argument>([&] { bytes.add(text); });
            }
        }
        std::cout << "store contract passed\n";
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

