#!/usr/bin/env python3
"""Assemble the reviewed renderer graph without a general JavaScript bundler.

The generated module contains data only. Its script is executed exclusively in
the opaque renderer document, under an exact hash and allow-scripts sandbox.
"""
import argparse
import base64
import hashlib
import json
from pathlib import Path
import re

CHILD_PROTOCOL = 'foundation-renderer-v1'
CHILD_SANDBOX = 'allow-scripts'
BUNDLE_NAME = 'renderer_child_bundle.mjs'
CHILD_MODULES = ('browser_limits.mjs', 'browser_presenter.mjs',
                 'renderer_channel.mjs', 'renderer_dom.mjs', 'renderer_frame.mjs')
CHILD_GRAPH = {
    'browser_limits.mjs': (),
    'browser_presenter.mjs': (),
    'renderer_channel.mjs': ('browser_limits.mjs',),
    'renderer_dom.mjs': ('browser_limits.mjs',),
    'renderer_frame.mjs': ('renderer_dom.mjs', 'browser_presenter.mjs',
                           'renderer_channel.mjs', 'browser_limits.mjs'),
}
CHILD_EXPORTS = {
    'browser_limits.mjs': ('MAX_OPERATION_BYTES', 'MAX_QUEUED_BYTES',
                           'MAX_CHANNEL_REQUESTS', 'MAX_STATE_BYTES', 'CHANNEL_PROTOCOL'),
    'browser_presenter.mjs': ('createBrowserPresenter',),
    'renderer_channel.mjs': ('clonePacket', 'validateRendererOperation',
                            'publicSnapshot', 'createRendererRequests', 'createHostChannel'),
    'renderer_dom.mjs': ('identity', 'byteOffset', 'utf16Offset', 'Renderer'),
    'renderer_frame.mjs': ('startRendererFrame',),
}
IDENTIFIER = r'[A-Za-z_$][A-Za-z0-9_$]*'
IMPORT = re.compile(r'import\s*\{([^{}]*)\}\s*from\s*([\'"])(\./[A-Za-z0-9_.-]+)\2\s*;')
EXPORT = re.compile(r'export\s+(?:(?:async\s+)?function|class|const|let)\s+(' + IDENTIFIER + r')\b')
DYNAMIC_IMPORT = re.compile(r'\bimport(?:\s|/\*[\s\S]*?\*/|//[^\r\n]*(?:\r?\n|$))*\(')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def child_csp(script):
    hash_value = base64.b64encode(hashlib.sha256(script.encode('utf-8')).digest()).decode('ascii')
    return ("default-src 'none'; script-src 'sha256-" + hash_value + "'; "
            "connect-src 'none'; worker-src 'none'; style-src 'unsafe-inline'; "
            "img-src data:; object-src 'none'; base-uri 'none'; form-action 'none'; "
            "frame-src 'none'; child-src 'none'")


def _keywords(source, all_tokens=False):
    """Find executable import/export tokens, including template expressions.

    This is deliberately a bounded lexical scanner, not a JavaScript parser.
    Unknown syntax is rejected by the reviewed declaration recognizers below.
    Regex literals are data; declaration recognition remains intentionally narrow.
    """
    size = len(source)
    found = []

    def quoted(index, quote):
        index += 1
        while index < size:
            if source[index] == '\\':
                index += 2
            elif source[index] == quote:
                return index + 1
            elif source[index] in '\r\n' and quote != '`':
                raise ValueError('Unterminated JavaScript string')
            else:
                index += 1
        raise ValueError('Unterminated JavaScript string')

    def template(index):
        index += 1
        while index < size:
            if source[index] == '\\':
                index += 2
            elif source[index] == '`':
                return index + 1
            elif source.startswith('${', index):
                index = code(index + 2, True)
            else:
                index += 1
        raise ValueError('Unterminated JavaScript template')

    def regexp(index):
        index += 1
        character_class = False
        while index < size:
            character = source[index]
            if character == '\\':
                index += 2
            elif character in '\r\n':
                raise ValueError('Unterminated JavaScript regular expression')
            elif character == '[':
                character_class = True
                index += 1
            elif character == ']':
                character_class = False
                index += 1
            elif character == '/' and not character_class:
                index += 1
                while index < size and source[index].isascii() and source[index].isalpha():
                    index += 1
                return index
            else:
                index += 1
        raise ValueError('Unterminated JavaScript regular expression')

    def code(index, expression=False):
        braces = 0
        can_regexp = True
        while index < size:
            character = source[index]
            if source.startswith('//', index):
                end = source.find('\n', index + 2)
                index = size if end < 0 else end + 1
            elif source.startswith('/*', index):
                end = source.find('*/', index + 2)
                if end < 0:
                    raise ValueError('Unterminated JavaScript comment')
                index = end + 2
            elif character in ('"', "'"):
                index = quoted(index, character)
                can_regexp = False
            elif character == '`':
                index = template(index)
                can_regexp = False
            elif character == '/' and can_regexp:
                index = regexp(index)
                can_regexp = False
            elif source.startswith(('++', '--'), index):
                if all_tokens:
                    found.append((index, source[index:index + 2]))
                # A prefix retains expression-start context; a postfix retains
                # operand context, so a subsequent division cannot hide code.
                index += 2
            elif character == '{':
                if all_tokens:
                    found.append((index, character))
                braces += 1
                index += 1
                can_regexp = True
            elif character == '}':
                if expression and braces == 0:
                    return index + 1
                if all_tokens:
                    found.append((index, character))
                braces -= 1
                index += 1
                can_regexp = False
            elif character.isascii() and (character.isalpha() or character in '_$'):
                match = re.match(IDENTIFIER, source[index:])
                word = match.group(0)
                if word in ('import', 'export') and (expression or braces != 0):
                    raise ValueError('Nested child module syntax is unsupported')
                if all_tokens or word in ('import', 'export'):
                    found.append((index, word))
                index += len(word)
                can_regexp = word in ('return', 'throw', 'case', 'delete', 'void', 'typeof', 'new', 'in', 'of', 'yield', 'await')
            else:
                if all_tokens and not character.isspace():
                    found.append((index, character))
                if not character.isspace():
                    can_regexp = character not in ')]' and not character.isdigit() and character != '.'
                index += 1
        if expression:
            raise ValueError('Unterminated JavaScript template expression')
        return index

    code(0)
    return found


def _single_binding(source, offset):
    depth = 0
    for _, token in _keywords(source[offset:], all_tokens=True):
        if token in ('(', '[', '{'):
            depth += 1
        elif token in (')', ']', '}'):
            depth -= 1
        elif depth == 0 and token == ',':
            raise ValueError('Unsupported multiple child export bindings')
        elif depth == 0 and token == ';':
            return
    raise ValueError('Child constant export requires a semicolon')


def _module(name, source, graph, exports):
    # The lexical scanner is deliberately smaller than JavaScript's grammar.
    # Conservatively reject dynamic-import spellings even in comments/data, so
    # slash ambiguity or an unfamiliar identifier can never admit such an edge.
    if DYNAMIC_IMPORT.search(source):
        raise ValueError('Unexpected or dynamic child import: ' + name)
    replacements = []
    actual_dependencies = []
    actual_exports = []
    for offset, kind in _keywords(source):
        if kind == 'import':
            match = IMPORT.match(source, offset)
            if not match:
                raise ValueError('Unexpected or dynamic child import: ' + name)
            dependency = match[3][2:]
            if dependency not in graph[name] or dependency in actual_dependencies:
                raise ValueError('Unexpected child dependency: ' + name + ' -> ' + dependency)
            bindings = []
            for binding in match[1].split(','):
                fields = binding.strip().split()
                if len(fields) == 1 and re.fullmatch(IDENTIFIER, fields[0]):
                    original = local = fields[0]
                elif len(fields) == 3 and fields[1] == 'as' and all(re.fullmatch(IDENTIFIER, field) for field in (fields[0], fields[2])):
                    original, local = fields[0], fields[2]
                else:
                    raise ValueError('Unexpected child import binding: ' + name)
                if original not in exports[dependency]:
                    raise ValueError('Unknown child export: ' + dependency + ' -> ' + original)
                bindings.append(original if local == original else original + ':' + local)
            if not bindings:
                raise ValueError('Empty child import: ' + name)
            actual_dependencies.append(dependency)
            replacements.append((offset, match.end(), 'const {' + ','.join(bindings) + '}=__modules[' + json.dumps(dependency) + '];'))
        else:
            match = EXPORT.match(source, offset)
            if not match or match[1] not in exports[name] or match[1] in actual_exports:
                raise ValueError('Unexpected child export or reexport: ' + name)
            if re.match(r'export\s+(?:const|let)\b', match[0]):
                _single_binding(source, match.end())
            actual_exports.append(match[1])
            replacements.append((offset, offset + len('export'), ''))
    if set(actual_dependencies) != set(graph[name]):
        raise ValueError('Child dependency inventory differs: ' + name)
    if set(actual_exports) != set(exports[name]):
        raise ValueError('Child export inventory differs: ' + name)
    for start, end, replacement in reversed(replacements):
        source = source[:start] + replacement + source[end:]
    return source


def assemble(blobs, graph=None, exports=None):
    """Return exact canonical data for the fixed, reviewed module closure."""
    graph = CHILD_GRAPH if graph is None else graph
    exports = CHILD_EXPORTS if exports is None else exports
    if set(graph) != set(exports) or set(blobs) != set(graph) | {'style.css'}:
        raise ValueError('Child bundle inventory differs')
    if any(name not in graph for dependencies in graph.values() for name in dependencies):
        raise ValueError('Unknown child dependency')
    state, ordered = {}, []

    def visit(name):
        if state.get(name) == 'active':
            raise ValueError('Cyclic child module graph')
        if state.get(name) == 'done':
            return
        state[name] = 'active'
        for dependency in graph[name]:
            visit(dependency)
        state[name] = 'done'
        ordered.append(name)

    for name in graph:
        visit(name)
    chunks = ['"use strict";\n(() => {\nconst __modules=Object.create(null);\n']
    for name in ordered:
        # HTML normalizes CR/CRLF in script text before applying a CSP hash.
        # Canonical LF script bytes keep the same policy on Windows checkouts.
        source = blobs[name].decode('utf-8').replace('\r\n', '\n').replace('\r', '\n')
        if any(terminator in source.lower() for terminator in ('</script', '<!--', '-->')) or '\x00' in source:
            raise ValueError('Unsafe child script terminator: ' + name)
        source = _module(name, source, graph, exports)
        chunks.append('__modules[' + json.dumps(name) + ']=(() => {\n' + source + '\nreturn Object.freeze({' + ','.join(exports[name]) + '});\n})();\n')
    chunks.append('})();\n')
    script = ''.join(chunks)
    style = blobs['style.css'].decode('utf-8')
    if '</style' in style.lower() or '</script' in style.lower() or '\x00' in style:
        raise ValueError('Unsafe child style terminator')
    return {'CHILD_SCRIPT': script, 'CHILD_SCRIPT_SHA256': base64.b64encode(hashlib.sha256(script.encode('utf-8')).digest()).decode('ascii'),
            'CHILD_CSP': child_csp(script), 'CHILD_SANDBOX': CHILD_SANDBOX,
            'CHILD_PROTOCOL': CHILD_PROTOCOL, 'CHILD_STYLE': style,
            'CHILD_INPUTS': {name: digest(data) for name, data in sorted(blobs.items())}}


def module_bytes(metadata):
    return ('// Generated renderer data; never evaluate this script in the parent.\n' +
            ''.join('export const ' + name + '=' + json.dumps(value, ensure_ascii=True, separators=(',', ':')) + ';\n'
                    for name, value in metadata.items())).encode('utf-8')


def parse_module(data):
    """Read only canonical pure-data output and verify its exact script policy."""
    names = ('CHILD_SCRIPT', 'CHILD_SCRIPT_SHA256', 'CHILD_CSP', 'CHILD_SANDBOX',
             'CHILD_PROTOCOL', 'CHILD_STYLE', 'CHILD_INPUTS')
    lines = data.decode('utf-8').splitlines()
    if len(lines) != len(names) + 1 or lines[0] != '// Generated renderer data; never evaluate this script in the parent.':
        raise ValueError('Invalid generated child data module')
    metadata = {}
    for name, line in zip(names, lines[1:]):
        prefix = 'export const ' + name + '='
        if not line.startswith(prefix) or not line.endswith(';'):
            raise ValueError('Invalid generated child data export')
        metadata[name] = json.loads(line[len(prefix):-1])
    if data != module_bytes(metadata) or any(not isinstance(metadata[name], str) for name in names[:-1]):
        raise ValueError('Noncanonical generated child data module')
    script = metadata['CHILD_SCRIPT']
    if (any(terminator in script.lower() for terminator in ('</script', '<!--', '-->')) or '\x00' in script or
            '</style' in metadata['CHILD_STYLE'].lower() or '</script' in metadata['CHILD_STYLE'].lower() or '\x00' in metadata['CHILD_STYLE']):
        raise ValueError('Unsafe generated child data terminator')
    if (metadata['CHILD_SCRIPT_SHA256'] != base64.b64encode(hashlib.sha256(script.encode('utf-8')).digest()).decode('ascii') or
            metadata['CHILD_CSP'] != child_csp(script) or metadata['CHILD_SANDBOX'] != CHILD_SANDBOX or
            metadata['CHILD_PROTOCOL'] != CHILD_PROTOCOL):
        raise ValueError('Generated child script policy mismatch')
    inputs = metadata['CHILD_INPUTS']
    if (not isinstance(inputs, dict) or set(inputs) != set(CHILD_MODULES + ('style.css',)) or
            any(not isinstance(value, str) or not re.fullmatch(r'[0-9a-f]{64}', value) for value in inputs.values())):
        raise ValueError('Generated child input metadata differs')
    if inputs['style.css'] != digest(metadata['CHILD_STYLE'].encode('utf-8')):
        raise ValueError('Generated child style metadata differs')
    return metadata


def generate(assets, output):
    root = Path(assets)
    blobs = {}
    for name in CHILD_MODULES + ('style.css',):
        path = root / name
        if path.is_symlink() or not path.is_file() or path.stat().st_size > 64 * 1024 * 1024:
            raise ValueError('Expected ordinary bounded child input: ' + str(path))
        blobs[name] = path.read_bytes()
    data = module_bytes(assemble(blobs))
    output = Path(output)
    if output.is_symlink():
        raise ValueError('Child bundle output must be ordinary')
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.exists() or output.read_bytes() != data:
        output.write_bytes(data)
    return data


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--assets', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    arguments = parser.parse_args(argv)
    generate(arguments.assets, arguments.output)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Select compile concurrency; stdout is a single positive job count.

Reserve one usable logical CPU and some available RAM. This is an admission
heuristic, not a per-process memory limit or a prediction of compiler RSS.
Only callers with no explicit job count should use this policy.
Testing uses the same resource admission limits with an independent four-job cap.
"""
import ctypes
import os
from pathlib import Path
import re
import subprocess
import sys

MIB = 1024 * 1024
MEMORY_PER_JOB = 768 * MIB


def read_text(path):
    try:
        return Path(path).read_text()
    except FileNotFoundError:
        return ""


def positive_int(value):
    try:
        number = int(value)
        return number if number > 0 else None
    except (ValueError, TypeError):
        return None


def cgroup_directories(proc=Path('/proc')):
    """Yield (controllers, leaf-to-mount-root paths), including visible parents."""
    membership_text = read_text(proc / 'self/cgroup')
    mount_text = read_text(proc / 'self/mountinfo')
    if not membership_text.strip() or not mount_text.strip():
        raise ValueError('cgroup visibility unknown')
    memberships = []
    for line in membership_text.splitlines():
        fields = line.split(':', 2)
        if len(fields) == 3:
            memberships.append((set(fields[1].split(',')), fields[2]))
    unescape = lambda text: re.sub(r'\\([0-7]{3})', lambda m: chr(int(m[1], 8)), text)
    found = False
    for line in mount_text.splitlines():
        before, sep, after = line.partition(' - ')
        fields, tail = before.split(), after.split()
        if not sep or len(fields) < 5 or len(tail) < 3 or tail[0] not in ('cgroup', 'cgroup2'):
            continue
        root, mount = Path(unescape(fields[3])), Path(unescape(fields[4]))
        controllers = set(tail[2].split(',')) if tail[0] == 'cgroup' else {''}
        for member_controllers, member in memberships:
            if not controllers.intersection(member_controllers):
                continue
            try:
                relative = Path(member).relative_to(root)
            except ValueError:
                continue
            if '..' in relative.parts:
                continue
            leaf = mount / relative
            found = True
            yield controllers, [leaf, *list(leaf.parents)[:len(relative.parts)]]
    if not found:
        raise ValueError('cgroup mount not visible')


def linux_limits(proc=Path('/proc')):
    """Return quota CPU counts and remaining physical-memory limits (bytes)."""
    cpus, memory = [], []
    for controllers, directories in cgroup_directories(proc):
        for directory in directories:
            if '' in controllers:
                quota = read_text(directory / 'cpu.max').split()
                limits = ['memory.high', 'memory.max']
                usage_name = 'memory.current'
            else:
                quota = [read_text(directory / 'cpu.cfs_quota_us'),
                         read_text(directory / 'cpu.cfs_period_us')] if 'cpu' in controllers else []
                limits = ['memory.limit_in_bytes'] if 'memory' in controllers else []
                usage_name = 'memory.usage_in_bytes'
            if any(part.strip() for part in quota):
                if len(quota) != 2:
                    raise ValueError('unrecognized cgroup CPU quota')
                amount, period = map(positive_int, quota)
                if period is None or (amount is None and quota[0].strip() not in ('max', '-1')):
                    raise ValueError('unrecognized cgroup CPU quota')
                if amount is not None:
                    cpus.append(max(1, amount // period))
            for name in limits:
                # Zero is a real exhausted limit, not missing information.
                value = read_text(directory / name).strip()
                if value in ('', 'max', '-1'):
                    continue
                limit = int(value)
                if 0 <= limit < (1 << 60):  # v1's effectively-unlimited sentinel
                    # A known finite limit without usage is indeterminate, not
                    # permission to use host-wide memory inside a container.
                    usage = int(read_text(directory / usage_name))
                    if usage < 0:
                        raise ValueError('invalid cgroup memory usage')
                    memory.append(max(0, limit - usage))
    return cpus, memory


def windows_memory():
    class MemoryStatus(ctypes.Structure):
        _fields_ = [('length', ctypes.c_uint32), ('load', ctypes.c_uint32)] + [
            (name, ctypes.c_uint64) for name in
            ('total_phys', 'avail_phys', 'total_page', 'avail_page',
             'total_virtual', 'avail_virtual', 'avail_extended')]
    status = MemoryStatus()
    status.length = ctypes.sizeof(status)
    try:
        if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
            return min(status.avail_phys, status.avail_page)
    except (AttributeError, OSError):
        pass
    return None


def macos_memory():
    try:
        output = subprocess.check_output(['/usr/bin/vm_stat'], text=True, timeout=2)
    except (OSError, subprocess.SubprocessError):
        return None
    page_size = re.search(r'page size of (\d+) bytes', output)
    pages = dict(re.findall(r'^(Pages [\w ]+):\s+(\d+)\.', output, re.M))
    names = ('Pages free', 'Pages inactive', 'Pages speculative')
    if not page_size or any(name not in pages for name in names):
        return None
    # vm_stat displays free minus speculative. Do not also count purgeable.
    return int(page_size[1]) * sum(int(pages[name]) for name in names)


def available_memory(proc=Path('/proc')):
    if sys.platform == 'win32':
        return windows_memory()
    if sys.platform == 'darwin':
        return macos_memory()
    if sys.platform.startswith('linux'):
        match = re.search(r'^MemAvailable:\s+(\d+)\s+kB$', read_text(proc / 'meminfo'), re.M)
        return int(match[1]) * 1024 if match else None
    return None


def usable_cpus():
    counts = [os.cpu_count() or 1]
    if hasattr(os, 'sched_getaffinity'):
        try:
            counts.append(len(os.sched_getaffinity(0)))
        except OSError:
            pass
    if sys.platform == 'win32' and counts[0] <= 64:
        # Above 64, GetProcessAffinityMask covers only the primary group.
        try:
            kernel = ctypes.windll.kernel32
            kernel.GetCurrentProcess.restype = ctypes.c_void_p
            kernel.GetProcessAffinityMask.argtypes = [ctypes.c_void_p,
                                                     ctypes.POINTER(ctypes.c_size_t),
                                                     ctypes.POINTER(ctypes.c_size_t)]
            process, system = ctypes.c_size_t(), ctypes.c_size_t()
            if kernel.GetProcessAffinityMask(kernel.GetCurrentProcess(),
                                             ctypes.byref(process), ctypes.byref(system)):
                counts.append(bin(process.value).count('1'))
        except (AttributeError, OSError):
            pass
    return max(1, min(counts))


def select_jobs(cpus, memory):
    cpu_jobs = max(1, cpus - 1)
    if memory is None:
        # Unknown RAM must not become an unbounded fan-out on large hosts.
        return min(cpu_jobs, 2)
    reserve = max(256 * MIB, memory // 10)
    return min(cpu_jobs, max(1, (memory - reserve) // MEMORY_PER_JOB))


def default_jobs():
    try:
        cpus, memory = usable_cpus(), available_memory()
        if sys.platform.startswith('linux'):
            quotas, headrooms = linux_limits()
            cpus = min([cpus, *quotas])
            if headrooms:
                memory = min(headrooms + ([] if memory is None else [memory]))
        return select_jobs(cpus, memory)
    except Exception:
        # Advisory detection must never prevent a build on an unfamiliar OS.
        # Explicit --jobs/--build-jobs remain available for such environments.
        return 1


def default_test_jobs():
    """Bound independent test workers without bypassing CPU or memory limits."""
    return min(4, default_jobs())


def compile_jobs(value=None):
    """Resolve a hosted/local compile limit; automatic selection is per machine."""
    if value is None or value in ("", "auto"):
        return default_jobs()
    if isinstance(value, bool) or not re.fullmatch(r"[0-9]+", str(value)) or int(value) < 1:
        raise ValueError("compile jobs must be auto or a positive integer")
    return int(value)


if __name__ == '__main__':
    if len(sys.argv) > 2:
        raise SystemExit("usage: build_capacity.py [auto|POSITIVE_JOBS]")
    print(compile_jobs(sys.argv[1] if len(sys.argv) == 2 else None))

#!/usr/bin/env python3
"""Qualify immutable local release bytes against a complete explicit policy."""
import argparse
import importlib.util
from pathlib import Path
import sys


def sibling(name):
    tools = str(Path(__file__).resolve().parent)
    if tools not in sys.path:
        sys.path.insert(0, tools)
    spec = importlib.util.spec_from_file_location("foundation_" + name, Path(__file__).with_name(name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


coverage = sibling("coverage")


def requirements(policy, profile):
    coverage.fields(policy, {"schema_version", "profiles"})
    if policy["schema_version"] != 1 or profile not in policy["profiles"]:
        raise ValueError("unknown release qualification profile")
    selected = policy["profiles"][profile]
    coverage.fields(selected, {"description", "targets", "checks"})
    if not selected["targets"] or not selected["checks"]:
        raise ValueError("empty release support contract")
    expected = set()
    for target, backends in selected["targets"].items():
        if not coverage.NAME.fullmatch(target) or not backends or len(backends) != len(set(backends)):
            raise ValueError("invalid target/backend contract")
        if any(not coverage.NAME.fullmatch(backend) for backend in backends):
            raise ValueError("invalid backend")
    for row in selected["checks"]:
        coverage.fields(row, {"target", "backend", "environment", "scope"})
        key = tuple(row[k] for k in ("target", "backend", "environment", "scope"))
        if (key in expected or row["target"] not in selected["targets"] or
                row["backend"] not in selected["targets"][row["target"]] or
                any(not isinstance(v, str) or not coverage.NAME.fullmatch(v) for v in row.values())):
            raise ValueError("duplicate or invalid required coverage")
        expected.add(key)
    for target, backends in selected["targets"].items():
        for backend in backends:
            kinds = {r[3] for r in expected if r[:2] == (target, backend)}
            if not {"source", "archive", "recovery"} <= kinds:
                raise ValueError("each delivered backend needs source, archive and recovery coverage")
    return selected, expected


def certify(directory, manifest, plan, reports, policy, profile, experiment=False, *, adoption=None):
    """verify_release must have verified manifest and file bytes before this call."""
    selected, expected = requirements(policy, profile)
    coverage.validate(plan)
    subject = {"source_sha256": manifest["source"]["sha256"],
               "inventory_sha256": coverage.sha(directory / "release.json"),
               "configuration_sha256": coverage.digest({"policy": policy, "profile": profile})}
    if plan["mode"] != "release" or plan["subject"] != subject:
        raise ValueError("diagnostic, different source, inventory or policy cannot certify these bytes")
    actual_targets = {}
    for artifact in manifest["artifacts"]:
        target = artifact["target"]
        actual_targets.setdefault(target, set())
        for backend in artifact["backends"] or ["core"]:
            if backend in actual_targets[target]:
                raise ValueError("duplicate delivered backend")
            actual_targets[target].add(backend)
    if actual_targets != {t: set(b) for t, b in selected["targets"].items()}:
        raise ValueError("delivered target/backend inventory differs from support contract")
    declared = set()
    for check in plan["checks"]:
        key = tuple(check[k] for k in ("target", "backend", "environment", "scope"))
        if key in declared:
            raise ValueError("duplicate qualification scope")
        declared.add(key)
        if key in expected and not check["required"]:
            raise ValueError("mandatory qualification scope marked optional")
        if key in expected and "qualification" not in check:
            raise ValueError("mandatory scope needs a bound qualification receipt")
    if not expected <= declared:
        raise ValueError("required qualification scope missing from plan")
    if not set(manifest["required_scopes"]) <= {r[3] for r in expected}:
        raise ValueError("release requirements absent from qualification policy")
    for leader in coverage.executions(plan):
        if "execution" in leader:
            covered = {x["backend"] for x in coverage.execution_members(plan, leader)}
            if covered != actual_targets[leader["target"]]:
                raise ValueError("grouped execution must cover every delivered backend")
    result = coverage.merge(plan, reports, adoption=adoption)
    report_paths = {coverage.load(path)["check"]: path for path in reports}
    for check in plan["checks"]:
        coverage.check_host(plan, check['id'], result['checks'][check['id']], report_paths[check['id']].parent)
    passed = result["status"] == "passed"
    # Neither an enclosing green workflow nor an advisory warning waives a check.
    warnings = {n: r["warnings"] for n, r in result["checks"].items() if r["warnings"]}
    return {"schema_version": 1, "subject": subject, "profile": profile, "plan": plan["id"],
            "status": ("passed_with_warnings" if warnings else "passed") if passed else "failed",
            "eligible_for_promotion": passed and not experiment, "experiment": experiment,
            "run_id": result["run_id"], "description": selected["description"],
            "warnings": warnings, "omitted": result["omitted"], "coverage": result["checks"],
            "reports": [{"name": str(p.name), "sha256": coverage.sha(p)} for p in reports],
            **({"adoption": result["adoption"]} if adoption is not None else {}),
            "limits": ["Evidence applies only to the named environments and exact bytes.",
                       "Containers do not qualify another kernel, physical device or desktop session.",
                       "This helper neither publishes a release nor changes a remote Latest pointer."]}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--release", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--profile", required=True)
    parser.add_argument("--plan", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--experiment", action="store_true")
    parser.add_argument("--adoption", type=Path, help="immutable explicit prior-receipt selection")
    parser.add_argument("reports", type=Path, nargs="+")
    args = parser.parse_args()
    directory = args.release.resolve(strict=True)
    if directory == args.output.resolve() or directory in args.output.resolve().parents:
        raise ValueError("certification evidence must not mutate the immutable release directory")
    release = sibling("release")
    manifest = release.verify_release(directory)
    initial = coverage.sha(directory / "release.json")
    result = certify(directory, manifest, coverage.load(args.plan), args.reports,
                     coverage.load(args.policy), args.profile, args.experiment,
                     adoption=coverage.load(args.adoption) if args.adoption else None)
    release.verify_release(directory)
    if initial != coverage.sha(directory / "release.json"):
        raise ValueError("release changed during certification")
    coverage.write_new(args.output, result)
    return 0 if result["status"] in ("passed", "passed_with_warnings") else 1


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError, TypeError) as error:
        print("certification: " + str(error), file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Read-only current-template session scan or proposed record-update check.

This is a reading/formatting aid, not a registry or ownership validator. It never
publishes, locks, reclaims or decides whether a path is free.
Legacy/freeform records still use the manual coordination workflow.
"""
import argparse
from datetime import datetime, timedelta
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import sys
import unicodedata


SECTIONS = ('Current checkpoint', 'Claims held', 'Blockers and handoff')
REQUIRED_FIELDS = (
    'State', 'Updated (UTC)', 'Last meaningful progress (UTC)',
    'Last inbox check (UTC)', 'Next check (UTC) / action',
    'Liveness mode / cadence', 'Last heartbeat (UTC), if supervised',
    'Run token / heartbeat file and writer, if used', 'Owner process',
    'Running jobs', 'Closed (UTC), if terminal', 'Delete after (UTC)',
    'Retention exception', 'Contact',
)
TERMINAL = {'done', 'failed', 'cancelled'}
PREAMBLE_FIELDS = (
    'Tool / host / local chat reference', 'Parent / read-only helpers',
    'Task and approach', 'Checkout / coordination root (absolute physical paths)',
    'Branch / starting HEAD / current HEAD',
    'Starting worktree and index changes (including work owned by others)',
)
SCAN_SECTIONS = ('Current checkpoint', 'Claims held', 'Baseline and dependencies',
                 'Progress and checks', 'Blockers and handoff')
SCAN_ADVISORY = ('Read-only observation, not an atomic snapshot or an ownership decision. '
                 'Recheck complete claims under the registry mutex before changing claims. '
                 'If incomplete, investigate every error; omitted records may hold claims.')
INSPECT_ADVISORY = (SCAN_ADVISORY + ' Targeted fallback is unvalidated extraction, not '
                    'legacy-format validation; resolve all errors by manual review.')
PRIVATE_FIELDS = ('Task and approach', PREAMBLE_FIELDS[-1])
SCOPE_KINDS = {'file', 'directory', 'resource'}
# Explicit aliases only: a substring match could expose unrelated progress prose.
LEGACY_METADATA_FIELDS = (
    'Closed (UTC)', 'Delete after', 'Liveness', 'Liveness mode', 'Owner process identity',
    'Closed / Updated / last meaningful progress (UTC)',
    'Closed / updated / last meaningful progress', 'Closed / updated / last progress',
    'Updated / last meaningful progress / Closed (UTC)',
)


class SnapshotChanged(ValueError):
    """A detected observation race; callers may restart the entire observation."""


def scan_error(path, error):
    detail = {'path': str(path), 'error': str(error)}
    if isinstance(error, SnapshotChanged):
        detail['code'] = 'snapshot_changed'
    return detail


def canonical_scope(kind, value):
    """Normalize an explicit scope, without deciding ownership or expanding globs."""
    if kind not in SCOPE_KINDS or not isinstance(value, str) or not value or value != value.strip():
        raise ValueError('scope needs file, directory or resource and a nonempty exact value')
    if any(ord(char) < 32 for char in value) or any(char in value for char in '*?[]`|;'):
        raise ValueError('scope contains control characters, a glob or ambiguous markup')
    if kind == 'resource':
        return {'kind': kind, 'value': value}
    path = Path(value)
    if not path.is_absolute():
        raise ValueError('file/directory scope must be an absolute path')
    # Reject portable aliases before resolving them: another host may treat a
    # trailing dot, stream suffix or device name as a different authority.
    for component in path.parts[1:]:
        stem = component.split('.', 1)[0].upper()
        if (component.rstrip('. ') != component or any(c in component for c in '<>:"|?*\\')
                or stem in {'CON', 'PRN', 'AUX', 'NUL'}
                or re.fullmatch(r'(?:COM|LPT)[1-9\u00b9\u00b2\u00b3]', stem)):
            raise ValueError('scope component is not portable; agree on a physical supported name')
    # Resolve existing ancestors too, including aliases of paths not created yet.
    try:
        try:
            physical = path.resolve(strict=True)
        except FileNotFoundError:
            physical = path.resolve(strict=False)
    except RuntimeError as exc:
        raise ValueError('scope alias cannot be resolved; inspect its symlink chain') from exc
    return {'kind': kind, 'value': os.path.normcase(str(physical))}


def validate_claim_scope(kind, value):
    """Validate an actual claim against the current filesystem, including its kind.

    Absent paths retain their declared kind; callers must repeat this check when
    reviewing/publishing claims, since materialization or replacement can change
    the answer. Prior scope discovery and query normalization deliberately
    keep using canonical_scope: an old file may now be a directory or absent.
    This observation does not freeze a path or enumerate hard-linked descendants.
    """
    scope = canonical_scope(kind, value)
    if kind == 'resource':
        return scope
    try:
        info = Path(scope['value']).stat()
    except FileNotFoundError:
        return scope
    matches = stat.S_ISREG(info.st_mode) if kind == 'file' else stat.S_ISDIR(info.st_mode)
    if not matches:
        raise ValueError('claim kind does not match the existing filesystem entry; '
                         'use file for a regular file and directory for a directory')
    if kind == 'file' and info.st_nlink > 1:
        raise ValueError('hard-linked file claim needs manual alias review; automatic scope checks cannot enumerate aliases')
    return scope


def scopes_overlap(left, right):
    """Component-aware overlap; extant hard-link aliases count as the same file."""
    left = canonical_scope(left['kind'], left['value'])
    right = canonical_scope(right['kind'], right['value'])
    if 'resource' in (left['kind'], right['kind']):
        return left['kind'] == right['kind'] and left['value'] == right['value']
    a, b = Path(left['value']), Path(right['value'])
    if a == b or (left['kind'] == 'directory' and a in b.parents) or (
            right['kind'] == 'directory' and b in a.parents):
        return True
    # Future paths cannot be compared with samefile. Conservatively fold spelling
    # even on case-sensitive hosts: macOS and mounted volumes need not follow the
    # host's normcase rules, and normalization-insensitive aliases can exist too.
    # A false positive needs explicit review/isolation, never an optimistic write.
    a_parts = tuple(unicodedata.normalize('NFC', part).casefold() for part in a.parts)
    b_parts = tuple(unicodedata.normalize('NFC', part).casefold() for part in b.parts)
    if (a_parts == b_parts or
            (left['kind'] == 'directory' and b_parts[:len(a_parts)] == a_parts) or
            (right['kind'] == 'directory' and a_parts[:len(b_parts)] == b_parts)):
        return True
    try:
        return os.path.samefile(a, b)
    except FileNotFoundError:
        return False


def parse_claims(text):
    """Parse only documented exact bullets/tables; never infer empty legacy claims.

    The ordinary scanner still returns opaque whole claims. Callers needing a
    machine decision must reject every unsupported row, including terminal ones.
    """
    if text.strip().lower() in ('none', 'none.'):
        return []
    result = []
    table_header = False
    for line in text.splitlines():
        line = line.strip()
        if not line or re.fullmatch(r'#{3,6}\s+.+', line):
            continue
        if line.startswith('|') and line.endswith('|'):
            cells = [cell.strip() for cell in line[1:-1].split('|')]
            if len(cells) != 4:
                raise ValueError('claim table needs exactly four cells; escaped pipes are unsupported')
            if cells[0] == 'Kind' and not table_header:
                table_header = True
                continue
            if table_header and all(re.fullmatch(r':?-{3,}:?', cell) for cell in cells):
                continue
            if not table_header:
                raise ValueError('claim table is missing its header')
            kind, value = cells[:2]
        else:
            match = re.fullmatch(r'- (file|directory|resource): (.+)', line)
            if not match:
                raise ValueError('unknown claim syntax; inspect the entire Claims held section')
            kind, value = match.groups()
        scope = validate_claim_scope(kind, value)
        if kind != 'resource':
            if os.path.normcase(value) != scope['value']:
                raise ValueError('recorded claims must use canonical physical paths; resolve aliases before publication')
        result.append(scope)
    if not result:
        raise ValueError('empty claim table/headings are not standalone None.')
    return result


def handoff_relevance(text, scopes):
    """Conservative discovery, never a selection of the most recent owner.

    Explicit typed rows preserve paths with spaces and resource IDs. The version-1
    ``- Scope inventory: complete`` producer assertion says those rows enumerate
    every prior scope in this section; it is not semantic proof. With that
    assertion explanatory prose is unrestricted and is never mined for paths.
    Unmarked non-neutral history needs manual review even beside some Scope rows:
    a partial inventory must not conceal another owner. Old records stay readable.
    """
    handoff = section_text(text, headings_in(text), 'Blockers and handoff')
    mentions = []
    declared_scopes = False
    declared_none = False
    inventories = []
    remaining = []
    for line in handoff.splitlines():
        line = line.strip()
        if re.match(r'- Scope inventory\b', line):
            inventories.append(line)
            continue
        declared = re.fullmatch(r'- (?:Scope|Release scope|Acquired scope|Retained scope): (.+)', line)
        if declared:
            declared_scopes = True
            body = declared[1]
            if body.lower() in ('none', 'none.'):
                declared_none = True
                continue
            typed = re.fullmatch(r'(file|directory|resource): (.+)', body)
            if not typed:
                raise ValueError('ambiguous handoff scope; use "- Scope: file|directory|resource: VALUE"')
            mentions.append(canonical_scope(*typed.groups()))
        else:
            if re.match(r'- (?:Scope|Release scope|Acquired scope|Retained scope)\b', line):
                raise ValueError('malformed handoff scope row; use "- Scope: file|directory|resource: VALUE"')
            remaining.append(line)
    if inventories and inventories != ['- Scope inventory: complete']:
        raise ValueError('need one exact "- Scope inventory: complete" assertion, not duplicate or unknown inventory markers')
    if inventories and not declared_scopes:
        raise ValueError('complete Scope inventory needs explicit typed Scope rows or standalone "- Scope: none"')
    if declared_none and mentions:
        raise ValueError('Scope: none contradicts a nonempty declared handoff scope')
    if not inventories:
        # A declaration beside legacy prose does not assert that it enumerates
        # all the prose's history. Never guess scopes from filenames or wording.
        neutral = all(not line or re.fullmatch(
            r'-?\s*(?:no pending handoffs?\.?|current request: none\.?|none\.?|'
            r'none; no pending requests\.?)', line, re.I) for line in remaining)
        if not neutral:
            raise ValueError('freeform handoff may omit scopes; inspect manually and preserve all relevant provenance; '
                             'assert Scope inventory: complete only after reviewing every prior scope')
    return any(scopes_overlap(scope, mention) for scope in scopes for mention in mentions)


def headings_in(text):
    return list(re.finditer(r'^(#{1,6})[ \t]+([^\n]+)$', text, re.MULTILINE))


def section_text(text, headings, name):
    found = [h for h in headings if h.group(2).strip() == name]
    if len(found) != 1 or found[0].group(1) != '##':
        raise ValueError(f'need exactly one ## {name} section')
    start = found[0]
    end = next((h.start() for h in headings
                if h.start() > start.start() and len(h.group(1)) <= 2), len(text))
    value = text[start.end():end].strip()
    if not value:
        raise ValueError(f'{name}: empty section; use explicit values or none')
    return value


def timestamp(value, field):
    if not re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|\+00:00)', value):
        raise ValueError(f'{field}: use an ISO UTC timestamp (YYYY-MM-DDTHH:MM:SSZ)')
    try:
        result = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError(f'{field}: invalid UTC timestamp') from exc
    assert result.utcoffset() == timedelta(0)
    return result


def event_timestamp(value, field):
    """An explicitly unobserved event must never be replaced with an invented time."""
    return None if value == 'unavailable' else timestamp(value, field)


def parse_record(text):
    """Require the documented headings/fields; keep the entire claims text opaque."""
    if re.search(r'^[ \t]*(?:`{3,}|~{3,})', text, re.MULTILINE):
        raise ValueError('fenced examples are unsupported; use the plain current record template')
    headings = headings_in(text)
    titles = [h.group(2).strip() for h in headings if h.group(1) == '#']
    if len(titles) != 1:
        raise ValueError('record needs exactly one # session-id heading')
    sections = {}
    for name in SECTIONS:
        sections[name] = section_text(text, headings, name)
    fields = {}
    for line in sections['Current checkpoint'].splitlines():
        if not line.strip():
            continue
        match = re.fullmatch(r'- ([^:]+):[ \t]*(.*)', line)
        if not match:
            raise ValueError('Current checkpoint: expected one nonempty "- Field: value" per line')
        key, value = (part.strip() for part in match.groups())
        if key not in REQUIRED_FIELDS:
            raise ValueError('unknown checkpoint field; use --fields for exact template labels')
        if key in fields:
            raise ValueError(f'duplicate checkpoint field: {key}')
        if not value:
            raise ValueError(f'{key}: empty field; use none when appropriate')
        fields[key] = value
    missing = [field for field in REQUIRED_FIELDS if field not in fields]
    if missing:
        raise ValueError('missing checkpoint fields: ' + ', '.join(missing))
    return titles[0], fields, sections['Claims held']


def check_transition(before, after):
    old_id, old, old_claims = parse_record(before)
    new_id, new, new_claims = parse_record(after)
    if new_id != old_id:
        raise ValueError('before/after session IDs differ')
    state = new['State']
    if state not in TERMINAL | {'active', 'waiting', 'paused'}:
        raise ValueError('State: choose one documented state')
    if old['State'] in TERMINAL and state not in TERMINAL:
        raise ValueError('terminal session cannot reopen under the same ID; register a fresh '
                         'session ID and reacquire claims')
    times = {}
    for field in ('Updated (UTC)', 'Last meaningful progress (UTC)', 'Last inbox check (UTC)'):
        parse = timestamp if field == 'Updated (UTC)' else event_timestamp
        times[field] = parse(new[field], field)
        previous = parse(old[field], 'before ' + field)
        if previous is not None and (times[field] is None or times[field] < previous):
            raise ValueError(f'{field}: moved backwards; investigate clock/history, do not invent times')
    updated = times['Updated (UTC)']
    if old_claims != new_claims and updated <= timestamp(old['Updated (UTC)'], 'before Updated'):
        raise ValueError('Claims held changed without advancing Updated (UTC) in the same candidate')
    for field in ('Last meaningful progress (UTC)', 'Last inbox check (UTC)'):
        if times[field] is not None and times[field] > updated:
            raise ValueError(f'{field}: later than Updated (UTC)')
    # Do not infer empty ownership from stage, age, table headers or release prose.
    empty_claims = new_claims.lower() in ('none', 'none.')
    if state in TERMINAL and not empty_claims:
        raise ValueError('terminal record retains Claims held text; inspect/release explicitly, '
                         'then use standalone None. and move disposition to Blockers and handoff')
    next_check, separator, action = new['Next check (UTC) / action'].partition(' / ')
    if not separator or not action.strip():
        raise ValueError('Next check (UTC) / action: expected timestamp (or none) / concrete action')
    if next_check.lower() == 'none':
        if state in {'active', 'waiting'}:
            raise ValueError('active/waiting record needs a concrete Next check (UTC)')
    elif timestamp(next_check, 'Next check') <= updated:
        raise ValueError('Next check must be later than Updated; replace the elapsed plan')
    closed = new['Closed (UTC), if terminal']
    deadline = new['Delete after (UTC)']
    if state in TERMINAL:
        closure = timestamp(closed, 'Closed')
        if closure > updated:
            raise ValueError('Closed must not be later than Updated')
        deletion = timestamp(deadline, 'Delete after')
        if deletion < closure:
            raise ValueError('Delete after must not precede Closed')
        if deletion > closure + timedelta(days=30) and new['Retention exception'].lower() in ('none', 'none.'):
            raise ValueError('Delete after beyond closure + 30 days requires an explicit '
                             'Retention exception with exact material, live dependency, '
                             'responsible owner, reason and review date')
        if new['Running jobs'].lower() not in ('none', 'none.'):
            raise ValueError('terminal Running jobs must be literal none (or None.); resolve jobs '
                             'first, then move completed-job details to Progress and checks '
                             'or Blockers and handoff')
    elif closed.lower() != 'none' or deadline.lower() != 'none':
        raise ValueError('nonterminal record needs none in closure/deletion fields')


def scan_record(text, path):
    """Extract named metadata and all claims; unknown layouts need manual review.

    This intentionally does not use check_transition: terminal claims, old next
    checks and unresolved jobs must remain visible rather than disappearing.
    """
    headings = headings_in(text)
    if not headings or headings[0].start() != 0 or headings[0].group(1) != '#':
        raise ValueError('expected current-template session heading at start of file')
    top = [h for h in headings if len(h.group(1)) <= 2]
    if ([h.group(1) for h in top] != ['#'] + ['##'] * len(SCAN_SECTIONS) or
            [h.group(2).strip() for h in top[1:]] != list(SCAN_SECTIONS)):
        raise ValueError('unknown, missing, duplicate or reordered top-level sections; review manually')
    if any(h.start() < top[1].start() for h in headings[1:]):
        raise ValueError('unexpected preamble heading; review manually')
    preamble = text[top[0].end():top[1].start()]
    identity = {}
    for line in preamble.splitlines():
        if not line.strip():
            continue
        match = re.fullmatch(r'- ([^:]+):[ \t]*(\S.*)', line)
        if not match or match[1] not in PREAMBLE_FIELDS or match[1] in identity:
            raise ValueError('unknown, duplicate or malformed preamble field; review manually')
        identity[match[1]] = match[2].strip()
    missing = [field for field in PREAMBLE_FIELDS if field not in identity]
    if missing:
        raise ValueError('missing current-template preamble fields: ' + ', '.join(missing))
    # Parser diagnostics name only known fields, never unknown labels or values.
    session_id, checkpoint, claims = parse_record(text)
    if not re.fullmatch(r'[A-Za-z0-9._-]+', session_id) or path.name != session_id + '.md':
        raise ValueError('session ID must use documented characters and match the record filename')
    if set(checkpoint) != set(REQUIRED_FIELDS):
        raise ValueError('unknown checkpoint fields; review manually')
    if checkpoint['State'] not in TERMINAL | {'active', 'waiting', 'paused'}:
        raise ValueError('unknown State; review manually')
    for field in ('Updated (UTC)', 'Last meaningful progress (UTC)', 'Last inbox check (UTC)'):
        (timestamp if field == 'Updated (UTC)' else event_timestamp)(checkpoint[field], field)
    next_check, separator, action = checkpoint['Next check (UTC) / action'].partition(' / ')
    if not separator or not action.strip():
        raise ValueError('Next check needs timestamp (or none) / action; review manually')
    for field, value in [('Next check (UTC)', next_check)] + [
            (key, checkpoint[key]) for key in ('Last heartbeat (UTC), if supervised',
                                              'Closed (UTC), if terminal', 'Delete after (UTC)')]:
        if value != 'none':
            timestamp(value, field)
    metadata = {key: identity[key] for key in PREAMBLE_FIELDS
                if key not in PRIVATE_FIELDS}
    metadata.update({key: value for key, value in checkpoint.items()
                     if key != 'Next check (UTC) / action'})
    metadata['Next check (UTC)'] = next_check
    return {'path': str(path), 'id': session_id, 'metadata': metadata, 'claims': claims}


def record_identity(info):
    # Reading may update atime; it is not evidence that the record changed.
    return tuple(getattr(info, key) for key in
                 ('st_dev', 'st_ino', 'st_mode', 'st_size', 'st_mtime_ns', 'st_ctime_ns'))


def read_scan_record(path, before, *, preserve_newlines=False):
    flags = os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_NONBLOCK', 0)
    with os.fdopen(os.open(path, flags), encoding='utf-8',
                   newline='' if preserve_newlines else None) as stream:
        opened = os.fstat(stream.fileno())
        if not stat.S_ISREG(opened.st_mode) or record_identity(opened) != record_identity(before):
            raise SnapshotChanged('record replaced before read; retry after publication settles')
        text = stream.read()
        if record_identity(os.fstat(stream.fileno())) != record_identity(opened):
            raise SnapshotChanged('record changed while being read; retry after publication settles')
        return text


def read_record(path):
    """Read a single stable direct regular record without following a leaf symlink."""
    before = path.lstat()
    if path.suffix != '.md' or not stat.S_ISREG(before.st_mode):
        raise ValueError('expected direct regular .md record; no symlinks or subdirectories')
    text = read_scan_record(path, before)
    if record_identity(path.lstat()) != record_identity(before):
        raise SnapshotChanged('record changed while being read; retry after publication settles')
    return text, before


def inspect_record(text, path, section='metadata-claims'):
    """Select complete named sections, reporting failed validation even on fallback.

    Metadata fallback reads only the preamble and an unambiguous checkpoint. It
    recognizes explicit old labels, never task/progress/handoff prose by keyword.
    Claims/handoff extraction stops at the next same-or-higher-level heading and
    preserves nested headings. Duplicate/misleveled sections and fences are unsafe.
    """
    if section not in ('metadata-claims', 'handoff'):
        raise ValueError('section must be metadata-claims or handoff')
    result = {'complete': False, 'path': str(path), 'section': section,
              'errors': [], 'advisory': INSPECT_ADVISORY}
    try:
        current = scan_record(text, path)
    except ValueError as exc:
        result['errors'].append({'path': str(path), 'error': str(exc)})
        current = None
    headings = headings_in(text)
    name = 'Claims held' if section == 'metadata-claims' else 'Blockers and handoff'
    key = 'claims' if section == 'metadata-claims' else 'handoff'
    try:
        if re.search(r'^[ \t]*(?:`{3,}|~{3,})', text, re.MULTILINE):
            raise ValueError('fenced examples make targeted section boundaries ambiguous; review manually')
        result[key] = section_text(text, headings, name)
    except ValueError as exc:
        error = {'path': str(path), 'error': str(exc)}
        if error not in result['errors']:
            result['errors'].append(error)
    if section == 'metadata-claims':
        if current is not None:
            result['id'] = current['id']
            result['metadata'] = [{'field': key, 'value': value}
                                  for key, value in current['metadata'].items()]
        else:
            # Do not infer a trusted ID, timestamps or empty ownership from this.
            first_section = headings[1].start() if len(headings) > 1 else len(text)
            chunks = [text[:first_section]]
            try:
                chunks.append(section_text(text, headings, 'Current checkpoint'))
            except ValueError:
                pass  # The strict validation error already makes this incomplete.
            if (not headings or headings[0].start() != 0 or headings[0][1] != '#' or
                    re.search(r'^[ \t]*(?:`{3,}|~{3,})', text, re.MULTILINE)):
                chunks = []
            known = (set(PREAMBLE_FIELDS) | set(REQUIRED_FIELDS) | set(LEGACY_METADATA_FIELDS)) - set(PRIVATE_FIELDS)
            fields = []
            for chunk in chunks:
                for line in chunk.splitlines():
                    match = re.fullmatch(r'- ([^:]+):[ \t]*(\S.*)', line)
                    if not match or match[1] not in known:
                        continue
                    label, value = match[1], match[2].strip()
                    if label == 'Next check (UTC) / action':
                        label = 'Next check (UTC)'
                        value = value.partition(' / ')[0]
                        if value != 'none':
                            try:
                                timestamp(value, label)
                            except ValueError:
                                continue  # Never leak an unrecognized action as a timestamp.
                    fields.append({'field': label, 'value': value})
            result['metadata'] = fields
    result['complete'] = not result['errors']
    return result


def inspect_path(path, section='metadata-claims'):
    path = path.absolute()
    try:
        text, _ = read_record(path)
        return inspect_record(text, path, section)
    except (OSError, UnicodeError, ValueError) as exc:
        return {'complete': False, 'path': str(path), 'section': section,
                'errors': [{'path': str(path), 'error': str(exc)}],
                'advisory': INSPECT_ADVISORY}


def scan_sessions(directory, scopes=None):
    """Read only direct regular .md entries; never silently skip a possible owner."""
    directory = directory.absolute()
    result = {'complete': False, 'records': [], 'errors': [], 'advisory': SCAN_ADVISORY}
    try:
        directory_before = directory.lstat()
        if not stat.S_ISDIR(directory_before.st_mode):
            raise ValueError('scan target must be a directory, not a symlink')
        entries = sorted(directory.iterdir())
    except (OSError, ValueError) as exc:
        result['errors'].append(scan_error(directory, exc))
        return result
    observed = {}
    fingerprint = hashlib.sha256()
    fingerprint.update(os.fsencode(directory))
    fingerprint.update(repr(record_identity(directory_before)).encode())
    for path in entries:
        try:
            # Include unreadable, malformed and unexpected entries in the page
            # identity too. Their errors still block a complete observation.
            before_entry = path.lstat()
            observed[path] = before_entry
            fingerprint.update(os.fsencode(path.name))
            fingerprint.update(repr(record_identity(before_entry)).encode())
            text, before = read_record(path)
            if record_identity(before) != record_identity(before_entry):
                raise SnapshotChanged('record changed before read during scan; retry after publication settles')
            observed[path] = before
            fingerprint.update(hashlib.sha256(text.encode()).digest())
            entry = scan_record(text, path)
            if scopes is None:
                result['records'].append(entry)
            else:
                claims = parse_claims(entry['claims'])
                uncertain = None
                try:
                    related = handoff_relevance(text, scopes)
                except ValueError as exc:
                    # An unscoped release cannot be ruled out as relevant. Return
                    # its whole section for explicit manual resolution, never a
                    # partial matching line or a silently absent former owner.
                    related, uncertain = True, str(exc)
                    result['errors'].append({'path': str(path), 'error': uncertain})
                if related or any(scopes_overlap(a, b) for a in scopes for b in claims):
                    selected = {
                        'path': str(path), 'id': entry['id'],
                        'state': entry['metadata']['State'], 'claims': entry['claims'],
                        'handoff': section_text(text, headings_in(text), 'Blockers and handoff'),
                    }
                    if uncertain:
                        selected['relevance_uncertain'] = True
                    result['records'].append(selected)
        except (OSError, UnicodeError, ValueError) as exc:
            result['errors'].append(scan_error(path, exc))
            fingerprint.update(os.fsencode(path.name))
            fingerprint.update(str(exc).encode('utf-8', errors='backslashreplace'))
    try:
        if (sorted(directory.iterdir()) != entries or
                record_identity(directory.lstat()) != record_identity(directory_before)):
            raise SnapshotChanged('directory entries changed during scan; retry after publication settles')
    except (OSError, ValueError) as exc:
        result['errors'].append(scan_error(directory, exc))
    for path, before in observed.items():
        try:
            if record_identity(path.lstat()) != record_identity(before):
                raise SnapshotChanged('record changed after read during scan; retry after publication settles')
        except (OSError, ValueError) as exc:
            result['errors'].append(scan_error(path, exc))
    result['complete'] = not result['errors']
    if scopes is not None:
        fingerprint.update(json.dumps(scopes, sort_keys=True).encode())
        result['scopes'] = scopes
        result['advisory'] += (' Scope results are discovery candidates, including closed owners and '
                               'covering paths, not a lineage decision. Inspect full relevant handoffs '
                               'and any unresolved legacy scope; never select by hash, timestamp or '
                               'message order. This scans sessions only, not archives or notes.')
    result['snapshot'] = fingerprint.hexdigest()
    return result


def page_result(result, offset=0, limit=None, snapshot=None):
    """Bound output by complete records/errors, while scanning all input every time."""
    if offset < 0 or (limit is not None and limit < 1):
        raise ValueError('offset must be nonnegative and limit must be positive')
    if offset and not snapshot:
        raise ValueError('later pages require --snapshot from the first page')
    if snapshot is not None and snapshot != result.get('snapshot'):
        raise ValueError('snapshot changed; restart at offset 0 and review the new observation')
    items = ([('record', entry) for entry in result['records']] +
             [('error', entry) for entry in result['errors']])
    if offset > len(items):
        raise ValueError('offset is beyond the end of this snapshot')
    end = len(items) if limit is None else min(len(items), offset + limit)
    result = dict(result)
    result.update(records=[entry for kind, entry in items[offset:end] if kind == 'record'],
                  errors=[entry for kind, entry in items[offset:end] if kind == 'error'],
                  total_records=len(result['records']), total_errors=len(result['errors']),
                  offset=offset, next_offset=end if end < len(items) else None,
                  all_returned=offset == 0 and end == len(items))
    result['advisory'] += (' A complete scan is not a complete page collection. Read every page with '
                           'the same snapshot, including all errors; never drop or truncate a record.')
    return result


def read_document(path, offset=0, limit=8000, snapshot=None):
    """Page one stable UTF-8 document by characters; never silently discard bytes."""
    if offset < 0 or limit < 1:
        raise ValueError('offset must be nonnegative and limit must be positive')
    path = path.absolute()
    before = path.lstat()
    if not stat.S_ISREG(before.st_mode):
        raise ValueError('document must be a direct regular file, not a symlink')
    text = read_scan_record(path, before, preserve_newlines=True)
    if record_identity(path.lstat()) != record_identity(before):
        raise ValueError('document changed while reading; restart at offset 0')
    digest = hashlib.sha256(os.fsencode(path) + repr(record_identity(before)).encode() + text.encode()).hexdigest()
    if offset and not snapshot:
        raise ValueError('later pages require --snapshot from the first page')
    if snapshot is not None and digest != snapshot:
        raise ValueError('snapshot changed; restart at offset 0')
    if offset > len(text):
        raise ValueError('offset is beyond the end of this document')
    end = min(len(text), offset + limit)
    return {'path': str(path), 'snapshot': digest, 'offset': offset, 'unit': 'characters',
            'total_characters': len(text), 'content': text[offset:end],
            'next_offset': end if end < len(text) else None,
            'advisory': 'Continue at next_offset with this snapshot until null; do not concatenate large outputs.'}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, epilog=(
        'Transition checking requires both files to use the current guide template '
        '(exact checkpoint field labels); scan requires its complete preamble and sections, '
        'with session ID matching the .md filename. '
        'Fenced examples are unsupported. '
        'Use ISO UTC timestamps; Next check uses "timestamp / action" ("none / action" '
        'only when paused or terminal). Empty claims use standalone "None.". '
        'Nonempty claims are opaque: paths, overlaps, blockers, receipts, real event times '
        'and stopped writers still require manual review. A pass never authorizes a write.'))
    parser.add_argument('--before', type=Path, help='saved current record')
    parser.add_argument('--after', type=Path, help='proposed complete replacement')
    parser.add_argument('--scan', type=Path, metavar='SESSIONS_DIRECTORY', help=(
        'emit JSON metadata and complete claims from direct current-template .md records; '
        'unknown/unreadable entries produce incomplete output and exit 1; never follow symlinks'))
    parser.add_argument('--compact', action='store_true', help=(
        'minify scan/inspection JSON formatting only; preserve every metadata field, whole '
        'claim and unresolved error; complete-claim review is still required'))
    parser.add_argument('--inspect', type=Path, metavar='RECORD', help=(
        'inspect only selected metadata/whole claims or handoff; legacy fallback stays '
        'incomplete (exit 1), with safe extraction and errors requiring manual review'))
    parser.add_argument('--section', choices=('metadata-claims', 'handoff'), help=(
        'selection for --inspect (default: metadata-claims); handoff omits all other sections'))
    parser.add_argument('--fields', action='store_true', help='list exact current-template field and section labels')
    parser.add_argument('--handoffs', type=Path, metavar='SESSIONS_DIRECTORY', help=(
        'scan every record; return complete scope-related handoffs including closed owners; '
        'unknown claims/provenance are errors, never select an owner automatically'))
    parser.add_argument('--scope', help='exact absolute path or agreed resource ID for --handoffs')
    parser.add_argument('--scope-kind', choices=sorted(SCOPE_KINDS), default=None)
    parser.add_argument('--read', type=Path, metavar='DOCUMENT', help='page one stable UTF-8 document (default 8000 characters)')
    parser.add_argument('--offset', type=int, default=0, help='page offset: whole entries for scans, characters for --read')
    parser.add_argument('--limit', type=int, help='maximum whole entries for scans or characters for --read')
    parser.add_argument('--snapshot', help='unchanged fingerprint from the first page; required at nonzero offsets')
    args = parser.parse_args(argv)
    new_modes = any((args.handoffs, args.read))
    paging = args.limit is not None or args.offset != 0 or args.snapshot is not None
    if sum(bool(mode) for mode in (args.fields, args.inspect, args.scan, args.handoffs, args.read,
                                  args.before or args.after)) > 1:
        parser.error('choose one mode: --fields, --inspect, --scan, --handoffs, --read, or --before/--after')
    if (args.scope or args.scope_kind) and not args.handoffs:
        parser.error('--scope/--scope-kind require --handoffs')
    if args.handoffs and not args.scope:
        parser.error('--handoffs requires --scope')
    if paging and not (args.scan or args.handoffs or args.read):
        parser.error('pagination requires --scan, --handoffs or --read')
    if args.fields:
        if any((args.before, args.after, args.scan, args.inspect, args.section, args.compact)):
            parser.error('--fields cannot be combined with other modes/options')
        print(json.dumps({'preamble': PREAMBLE_FIELDS, 'checkpoint': REQUIRED_FIELDS,
                          'sections': SCAN_SECTIONS}, indent=2))
        return 0
    if args.section and not args.inspect:
        parser.error('--section requires --inspect')
    if args.compact and not (args.scan or args.inspect or new_modes):
        parser.error('--compact requires a reading mode')
    if args.read is not None or args.handoffs is not None or (args.scan is not None and paging):
        try:
            if args.read is not None:
                result = read_document(args.read, args.offset,
                                       args.limit if args.limit is not None else 8000, args.snapshot)
            else:
                scopes = ([canonical_scope(args.scope_kind or 'file', args.scope)]
                          if args.handoffs else None)
                result = scan_sessions(args.handoffs or args.scan, scopes)
                result = page_result(result, args.offset, args.limit, args.snapshot)
        except (OSError, UnicodeError, ValueError) as exc:
            print(json.dumps({'complete': False, 'errors': [{'error': str(exc)}]}))
            return 1
        print(json.dumps(result, **({'separators': (',', ':')} if args.compact else {'indent': 2})))
        return 0 if result.get('complete', True) else 1
    if args.inspect is not None:
        if any((args.scan, args.before, args.after)):
            parser.error('--inspect cannot be combined with --scan, --before or --after')
        result = inspect_path(args.inspect, args.section or 'metadata-claims')
        print(json.dumps(result, **({'separators': (',', ':')} if args.compact else {'indent': 2})))
        return 0 if result['complete'] else 1
    if args.scan is not None:
        if args.before is not None or args.after is not None:
            parser.error('--scan cannot be combined with --before or --after')
        result = scan_sessions(args.scan)
        print(json.dumps(result, **({'separators': (',', ':')} if args.compact else {'indent': 2})))
        return 0 if result['complete'] else 1
    if args.before is None or args.after is None:
        parser.error('provide both --before and --after, or --scan, --inspect or --fields')
    try:
        if args.before.resolve() == args.after.resolve():
            raise ValueError('before and after must be distinct files')
        check_transition(args.before.read_text(encoding='utf-8'), args.after.read_text(encoding='utf-8'))
    except (OSError, UnicodeError, ValueError) as exc:
        print(f'agent record check: {exc}', file=sys.stderr)
        return 1
    print('Record format/timing checks passed; ownership, handoff and factual review still required.')
    return 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
"""Validate local Markdown destinations, required repository files and JSON."""
import json
import os
from pathlib import Path
import re
import sys
from urllib.parse import unquote, urlsplit

ROOT = Path(__file__).resolve().parents[1]
EXCLUDE = {".git", ".agent-work", "build", ".cache", "__pycache__"}
errors = []


def unique(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise ValueError("duplicate JSON key: " + key)
        value[key] = item
    return value


def headings(path):
    identifiers, seen = set(), {}
    content = re.sub(r"```.*?```", "", path.read_text(encoding="utf-8"), flags=re.S)
    for heading in re.findall(r"^#{1,6}\s+(.+?)\s*#*\s*$", content, re.M):
        anchor = re.sub(r"[^\w\- ]", "", heading.lower()).replace(" ", "-")
        count = seen.get(anchor, 0)
        seen[anchor] = count + 1
        identifiers.add(anchor + ("-" + str(count) if count else ""))
    identifiers.update(re.findall(r'(?:id|name)="([^"]+)"', content))
    return identifiers
required = ["README.md", "AGENTS.md", "COMPILE", "RELEASE", "LICENSE",
            "docs/README.md", "third_party/README.md", "CMakePresets.json"]
for name in required:
    if not (ROOT / name).is_file():
        errors.append("missing required file: " + name)
def repository_files():
    # Prune generated SDK/build trees before traversal: rejecting their files
    # afterward still walks millions of unrelated retained compiler inputs.
    for directory, children, files in os.walk(ROOT, followlinks=False):
        children[:] = [name for name in children if name not in EXCLUDE]
        for name in files:
            yield Path(directory) / name


for path in repository_files():
    relative = path.relative_to(ROOT)
    if any(part in EXCLUDE for part in relative.parts) or not path.is_file():
        continue
    if path.suffix == ".json":
        try:
            json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique,
                       parse_constant=lambda _: (_ for _ in ()).throw(ValueError("nonfinite JSON")))
        except (ValueError, UnicodeError) as error:
            errors.append(f"{relative}: {error}")
    if path.suffix != ".md":
        continue
    # Ignore code fences; template paths inside prose still need real destinations.
    content = re.sub(r"```.*?```", "", path.read_text(encoding="utf-8"), flags=re.S)
    for target in re.findall(r"\[[^\]]*\]\(([^)]+)\)", content):
        target = target.strip().split(" ", 1)[0].strip("<>")
        parsed = urlsplit(target)
        if parsed.scheme or parsed.netloc:
            continue
        destination = (path.parent / unquote(parsed.path)).resolve() if parsed.path else path
        if destination != ROOT and ROOT not in destination.parents:
            errors.append(f"{relative}: link escapes repository {target}")
        if not destination.exists():
            errors.append(f"{relative}: missing link {target}")
        elif parsed.fragment and destination.suffix == ".md" and unquote(parsed.fragment) not in headings(destination):
            errors.append(f"{relative}: missing heading {target}")

try:
    mapping = json.loads((ROOT / "docs/practice-map.json").read_text(encoding="utf-8"), object_pairs_hook=unique)
    seen = set()
    if mapping["schema_version"] != 1 or not mapping["practices"]:
        raise ValueError("empty or unsupported practice map")
    for entry in mapping["practices"]:
        if set(entry) != {"id", "requirement", "documents", "implementation", "checks"} or entry["id"] in seen:
            raise ValueError("invalid or duplicate practice entry")
        seen.add(entry["id"])
        for field in ("documents", "implementation", "checks"):
            if not entry[field] or len(entry[field]) != len(set(entry[field])):
                raise ValueError("empty or duplicate practice references")
            for name in entry[field]:
                destination = (ROOT / name).resolve()
                if ROOT not in destination.parents or not destination.exists():
                    raise ValueError("missing or unsafe practice reference: " + name)
except (OSError, ValueError, KeyError, TypeError) as error:
    errors.append("practice map: " + str(error))
if errors:
    print("\n".join(errors), file=sys.stderr)
    sys.exit(1)
print("Repository documentation links, headings, JSON and practice references are valid")

#!/usr/bin/env python3
"""Conservative local-Git selection for development feedback, never qualification."""
import argparse
import ast
from concurrent.futures import ThreadPoolExecutor
import json
import importlib.util
import os
from pathlib import Path
import re
import subprocess
import sys

# Only reviewed, non-installed narrative documents may omit compile/GUI work.
# New paths, manuals, release policies, schemas and installed text stay full.
DOCUMENTS = frozenset({
    'README.md', 'AGENTS.md', 'COMPILE', 'RELEASE',
    'docs/README.md', 'docs/architecture.md', 'docs/ci.md',
    'docs/development-speed.md', 'docs/testing.md', 'docs/validation.md',
    'docs/documentation.md', 'docs/maintenance.md',
    'docs/agent-coordination.md', 'docs/agent-recipes.md', 'docs/agent-lifecycle.md',
})
COMMIT = re.compile(r'[0-9a-f]{40}')
ROOT = Path(__file__).resolve().parents[1]
# Domains cover dependencies expressed through command lines, generated recipes,
# fixtures and retained inputs, in addition to the source-reference closure below.
TOOL_DOMAINS = (
    frozenset('agent_board agent_edit agent_migrate agent_publish agent_record agent_session agent_stress check_agent_record'.split()),
    frozenset('apt_repo artifact certification distribution_release distro_channel distro_check distro_client github_release latest_release legacy_artifacts package_notices portability release release_check verify_abi verify_legacy_preservation'.split()),
    frozenset('dependencies dependency_archive prepare_dependencies sdk sdk_paths sdk_retention windows_compiler windows_graphics'.split()),
    frozenset('gui_boundary gui_source_group gui_visual gallery_browser screenshots package_wasm rev_probe host_contracts'.split()),
    frozenset('build build_capacity ci_plan ci_changes coverage qualification_tasks run_tests source_identity test_plan'.split()),
    frozenset('ci_apt ci_artifacts ci_cleanup ci_cleanup_repository ci_retry ci_transport container_job workflow_storage'.split()),
    frozenset('rust_sdk rust_build rust_component rust_workflow build ci_plan source_identity test_plan release release_check offline_acceptance container_job'.split()),
)


def infrastructure_suites(paths, root=ROOT):
    """Select whole suites; unknown/deleted infrastructure requires every suite.

    Source references deliberately overapproximate Python imports: literal dynamic
    loader names and subprocess script names count too. Domain edges include
    non-Python coupling. Missing inventories or unreadable sources fail selection,
    never silently remove a suite from feedback.
    """
    suites = {p.stem[5:]: p for p in (root / 'tests').glob('test_*.py')}
    modules = {p.stem: p for p in (root / 'tools').glob('*.py')}
    if not suites or not modules:
        raise ValueError('complete tooling source and suite inventory required')
    all_suites = sorted(suites)
    if not paths:
        return all_suites
    changed, direct = set(), set()
    for path in paths:
        if path in DOCUMENTS:
            continue
        if path.startswith('tools/') and Path(path).suffix == '.py' and path.count('/') == 1:
            name = Path(path).stem
            if name not in modules or not any(name in domain for domain in TOOL_DOMAINS):
                return all_suites
            changed.add(name)
        elif path.startswith('tests/test_') and Path(path).suffix == '.py' and path.count('/') == 1:
            name = Path(path).stem[5:]
            if name not in suites:
                return all_suites
            direct.add(name)
            changed.add(name)
        elif path.startswith('gui/'):
            changed.update(TOOL_DOMAINS[3])
        elif path.startswith(('rust/', 'third_party/rust/')):
            changed.update(TOOL_DOMAINS[6])
        elif path.startswith(('src/', 'include/', 'tests/')) and Path(path).suffix in ('.cpp', '.hpp', '.h', '.c', '.cc'):
            continue  # Native application contracts remain in focused/shared-gui jobs.
        else:
            return all_suites
    if not changed:
        return sorted(direct)
    def referenced(file):
        result = set()
        for node in ast.walk(ast.parse(file.read_text(encoding='utf-8'))):
            if isinstance(node, ast.Import):
                result.update(alias.name.split('.')[0] for alias in node.names)
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    result.add(node.module.split('.')[0])
                result.update(alias.name for alias in node.names)
            elif isinstance(node, ast.Constant) and isinstance(node.value, str):
                # Exact literal dynamic-loader names and script paths count;
                # explanatory prose and selector tables do not create edges.
                if re.fullmatch(r'[a-z][a-z0-9_]*', node.value):
                    result.add(node.value)
                result.update(re.findall(r'(?<![A-Za-z0-9_])([a-z][a-z0-9_]*)\.py(?:$|[^A-Za-z0-9_])', node.value))
        return result | {name.removeprefix('test_') for name in result if name.startswith('test_')}
    references = {name: referenced(file) for name, file in modules.items()}
    tests = {name: referenced(file) for name, file in suites.items()}
    initial = set(changed)
    for domain in TOOL_DOMAINS:
        if domain & initial:
            changed.update(domain)
    previous = None
    while previous != changed:
        previous = set(changed)
        changed.update(name for name, dependencies in references.items() if dependencies & changed)
        changed.update(name for name, dependencies in tests.items() if dependencies & changed)
    return sorted(direct | (changed & suites.keys()) |
                  {name for name, dependencies in tests.items() if dependencies & changed})


def load_supervisor():
    spec = importlib.util.spec_from_file_location('feedback_process_tree', ROOT / 'tools/process_tree.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def run_tool_suites(suites, output, jobs=2, root=ROOT):
    """Bounded parallel whole-suite execution with the qualification runner policy."""
    if not suites or len(set(suites)) != len(suites) or jobs not in (1, 2):
        raise ValueError('nonempty unique suites and one or two workers required')
    known = {p.stem[5:] for p in (root / 'tests').glob('test_*.py')}
    if not set(suites) <= known:
        raise ValueError('unknown tooling suite')
    output.mkdir(parents=True, exist_ok=False)
    processes = load_supervisor()
    def execute(name):
        receipt = output / (name + '.json')
        with (output / (name + '.log')).open('wb') as log:
            owner = processes.launch([sys.executable, '-B', str(root / 'tools/run_tests.py'),
                                      '--suite', name, '--output', str(receipt)], root, log)
            try:
                owner.wait(timeout=900)
                code = owner.finish()
            except (subprocess.TimeoutExpired, processes.ProcessTreeError) as error:
                code = 1
                log.write(('\nSuite process ownership failed: ' + str(error) + '\n').encode())
            finally:
                owner.close()  # Join descendants before reading logs or publishing receipts.
        # run_tests rejects skips, expected failures, empty/duplicate inventories
        # and unrecorded cases. Never substitute unittest's weaker exit policy.
        passed = code == 0 and receipt.is_file()
        if passed:
            try:
                passed = json.loads(receipt.read_text())['status'] == 'passed'
            except (ValueError, KeyError):
                passed = False
        print(name + ': ' + ('passed' if passed else 'FAILED'), flush=True)
        if not passed:
            print((output / (name + '.log')).read_text(errors='replace'), flush=True)
        return {'suite': name, 'status': 'passed' if passed else 'failed'}
    with ThreadPoolExecutor(max_workers=jobs) as workers:
        results = list(workers.map(execute, suites))
    summary = {'schema_version': 1, 'scope': 'development-feedback', 'suites': results,
               'status': 'passed' if all(r['status'] == 'passed' for r in results) else 'failed'}
    (output / 'summary.json').write_text(json.dumps(summary, sort_keys=True, indent=2) + '\n')
    return summary


def classify(paths):
    """An absent/incomplete change inventory never authorizes omitted work."""
    paths = list(paths)
    docs_only = bool(paths) and all(path in DOCUMENTS for path in paths)
    return {'schema_version': 1, 'scope': 'documents' if docs_only else 'full',
            'build': not docs_only, 'gui': not docs_only, 'workflow_lint': not docs_only,
            'changed_paths': paths, 'tool_suites': infrastructure_suites(paths),
            'reason': 'Only reviewed narrative documents changed.' if docs_only
                      else 'Source, policy, unknown paths or an empty change set require full feedback.'}


def git(root, *args):
    return subprocess.run(['git', '-C', str(root), *args], check=True,
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=20).stdout


def commit(value):
    if not isinstance(value, str) or not COMMIT.fullmatch(value) or value == '0' * 40:
        raise ValueError('an exact nonzero commit is required')
    return value


def changed_paths(root, event_name, event, expected_head):
    """Compare the tested merge/tree with its exact event baseline, without APIs.

    Depth-two checkouts contain a PR merge's first parent. A multi-commit push
    may lack its previous tip; that condition deliberately selects full work.
    --no-renames makes moves include both deleted and added paths.
    """
    head = commit(expected_head)
    if git(root, 'rev-parse', 'HEAD').decode().strip() != head:
        raise ValueError('checked-out source differs from the event commit')
    if event_name == 'pull_request':
        base = commit(event['pull_request']['base']['sha'])
        if git(root, 'rev-parse', 'HEAD^1').decode().strip() != base:
            raise ValueError('the tested PR merge does not have the event base parent')
        commit(event['pull_request']['head']['sha'])
        if git(root, 'rev-parse', 'HEAD^2').decode().strip() != event['pull_request']['head']['sha']:
            raise ValueError('the tested PR merge does not have the event head parent')
    elif event_name == 'push':
        base = commit(event['before'])
        if commit(event['after']) != head or event.get('deleted'):
            raise ValueError('push event does not identify the checked-out live tip')
    else:
        raise ValueError('unsupported feedback event')
    raw = git(root, 'diff', '--name-only', '--no-renames', '-z', base, head, '--')
    if raw and not raw.endswith(b'\0'):
        raise ValueError('incomplete changed-path output')
    return [item.decode('utf-8', errors='strict') for item in raw.split(b'\0') if item]


def select(root, event_name, event, expected_head):
    try:
        return classify(changed_paths(root, event_name, event, expected_head))
    except (KeyError, TypeError, ValueError, OSError, subprocess.SubprocessError) as error:
        result = classify([])
        result['reason'] = 'Complete change inventory unavailable; full feedback selected (' + type(error).__name__ + ').'
        return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument('--event', type=Path, default=os.environ.get('GITHUB_EVENT_PATH'))
    parser.add_argument('--event-name', default=os.environ.get('GITHUB_EVENT_NAME', ''))
    parser.add_argument('--head', default=os.environ.get('GITHUB_SHA', ''))
    parser.add_argument('--github-output', type=Path, default=os.environ.get('GITHUB_OUTPUT'))
    parser.add_argument('--summary', type=Path, default=os.environ.get('GITHUB_STEP_SUMMARY'))
    parser.add_argument('--run-tool-suites', action='store_true')
    parser.add_argument('--tool-output', type=Path, default=Path('build/changed-tools'))
    parser.add_argument('--tool-jobs', type=int, choices=(1, 2), default=2)
    args = parser.parse_args(argv)
    try:
        event = json.loads(args.event.read_text(encoding='utf-8')) if args.event else {}
    except (OSError, ValueError):
        event = {}
    result = select(args.root, args.event_name, event, args.head)
    if args.github_output:
        with args.github_output.open('a', encoding='utf-8') as stream:
            for key in ('build', 'gui', 'workflow_lint'):
                stream.write(f'{key}={str(result[key]).lower()}\n')
            stream.write('tools=' + str(bool(result['tool_suites'])).lower() + '\n')
            stream.write('scope=' + result['scope'] + '\n')
    if args.summary:
        with args.summary.open('a', encoding='utf-8') as stream:
            stream.write('Development feedback: ' + result['scope'] + '. ' + result['reason'] + '\n')
            if result['scope'] == 'documents':
                stream.write('Documentation checks run; compile, GUI and workflow syntax work omitted.\n')
            stream.write('This selection does not qualify a candidate or release.\n')
    print(json.dumps(result, sort_keys=True))
    if args.run_tool_suites and result['tool_suites']:
        return 0 if run_tool_suites(result['tool_suites'], args.tool_output.resolve(), args.tool_jobs)['status'] == 'passed' else 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Delete explicit upload IDs supplied by their final workflow consumers.

The caller must obtain IDs from this workflow's trusted upload outputs and own
its final-consumer barrier and preservation option. No inventory is discovered.
One-day artifact expiry remains the fallback if cleanup cannot finish.
"""
import argparse
import json
import os
import re
import time

import github_release as delivery

IDS_ENV = 'FOUNDATION_CI_CLEANUP_ARTIFACT_IDS'
MAX_INPUT_BYTES = 32 * 1024
MAX_ARTIFACT_ID = 10 ** 20 - 1
MAX_DELETE = 512


class CleanupError(ValueError):
    pass


def current_context(environment=None):
    environment = os.environ if environment is None else environment
    if (environment.get('GITHUB_ACTIONS') != 'true' or
            environment.get('GITHUB_SERVER_URL') != 'https://github.com'):
        raise CleanupError('cleanup requires a native GitHub.com Actions context')
    repository = delivery.location(environment.get('GITHUB_REPOSITORY', ''))
    reference = environment.get('GITHUB_WORKFLOW_REF', '')
    prefix = repository + '/.github/workflows/'
    if (not reference.startswith(prefix) or
            not re.fullmatch(r'[A-Za-z0-9_-]+\.ya?ml@[^\r\n]+', reference[len(prefix):])):
        raise CleanupError('cleanup workflow must belong to the current repository')
    values = {}
    for field, variable in (('run_id', 'GITHUB_RUN_ID'), ('attempt', 'GITHUB_RUN_ATTEMPT'),
                            ('repository_id', 'GITHUB_REPOSITORY_ID')):
        value = environment.get(variable, '')
        if not isinstance(value, str) or not re.fullmatch(r'[1-9][0-9]{0,19}', value):
            raise CleanupError('cleanup requires a positive exact ' + field)
        values[field] = int(value)
    commit = environment.get('GITHUB_SHA', '')
    if not isinstance(commit, str) or not delivery.OID.fullmatch(commit):
        raise CleanupError('cleanup requires the exact current source commit')
    return dict(repository=repository, source_commit=commit, **values)


def selected_artifacts(raw):
    """Validate every explicit ID before returning a deduplicated immutable set."""
    if not isinstance(raw, str) or not raw.strip() or len(raw.encode('utf-8')) > MAX_INPUT_BYTES:
        raise CleanupError('cleanup requires a bounded explicit artifact-ids JSON array')
    try:
        values = delivery.parse(raw)
    except (ValueError, RecursionError):
        raise CleanupError('artifact-ids must be a complete JSON array') from None
    if not isinstance(values, list) or len(values) > MAX_DELETE:
        raise CleanupError('artifact-ids must be an array within the cleanup budget')
    selected, seen = [], set()
    for value in values:
        if isinstance(value, str) and re.fullmatch(r'[1-9][0-9]{0,19}', value):
            value = int(value)
        if type(value) is not int or not 0 < value <= MAX_ARTIFACT_ID:
            raise CleanupError('every artifact ID must be a canonical positive integer')
        if value not in seen:
            seen.add(value)
            selected.append(value)
    return tuple(selected)


def cleanup(*, environment=None, transport=None, sleep=time.sleep):
    environment = os.environ if environment is None else environment
    context = current_context(environment)
    selected = selected_artifacts(environment.get(IDS_ENV))
    if not selected:
        return dict(run_id=context['run_id'], attempt=context['attempt'], selected=0, deleted=0)
    if transport is None:
        transport = delivery.GitHub(context['repository'])
        # Cleanup is optional: never wait for quota or retry a partial mutation.
        transport.WRITE_HEADROOM = 0
        transport.REQUEST_DEADLINE = 30
        transport.COMMAND_TIMEOUT = 30
        transport.WAIT_BUDGET = 0
        transport.wait_remaining = 0.0
        transport.MAX_ATTEMPTS = 1
    deleted = 0
    for artifact_id in selected:
        if deleted:
            sleep(1.0)
        try:
            transport.json(f"repos/{context['repository']}/actions/artifacts/{artifact_id}", method='DELETE')
        except (ValueError, OSError) as error:
            raise CleanupError(f'cleanup stopped after {deleted} of {len(selected)} confirmed deletions; '
                               'remaining artifacts retain their expiry: ' + str(error)) from error
        deleted += 1
    return dict(run_id=context['run_id'], attempt=context['attempt'], selected=len(selected), deleted=deleted)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.parse_args(argv)
    print(json.dumps(cleanup(), sort_keys=True))


if __name__ == '__main__':
    delivery.enable_metrics()
    try:
        main()
    except (ValueError, OSError) as error:
        raise SystemExit('ci-cleanup: ' + str(error))

#!/usr/bin/env python3
"""Checked CI scheduling and package operations shared with local development."""
import argparse
import json
import os
from pathlib import Path
import platform
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]
STANDARD = {"linux-x86_64": "ubuntu-24.04", "linux-aarch64": "ubuntu-24.04-arm",
            "windows-x86_64": "windows-2022"}
RUST_RECIPES = {'linux-x86_64': 'third_party/rust/linux-x86_64.json',
                'linux-aarch64': 'third_party/rust/linux-aarch64.json',
                'windows-x86_64': 'third_party/rust/windows-x86_64.json',
                'browser-wasm32': 'third_party/rust/wasm32-emscripten.json'}


def plan(devfast=False, include_arm=True, pool="standard", configured="", configured_arm="", configured_windows=""):
    if pool not in ("standard", "faster"):
        raise ValueError("unknown runner pool")
    chosen = {"linux-x86_64": configured, "linux-aarch64": configured_arm, "windows-x86_64": configured_windows}
    prefixes = {"linux-x86_64": "linux", "linux-aarch64": "arm", "windows-x86_64": "windows"}
    if pool == "faster" and (not any(chosen.values()) or any(value and not re.fullmatch("foundation-" + prefixes[target] + "-[a-z0-9-]+", value) for target,value in chosen.items())):
        raise ValueError("explicit authorized larger-runner label required")
    targets = [x for x in STANDARD if include_arm or x != "linux-aarch64"]
    packages, checks = [], []
    for target in targets:
        runner = chosen[target] if pool == "faster" and chosen[target] else STANDARD[target]
        packages.append({"target": target, "runner": runner})
        for scope in (["core"] if devfast else ["core", "tools", "integration"]):
            checks.append({"target": target, "runner": runner, "scope": scope})
    return {"checks": {"include": checks}, "packages": {"include": packages}}


def assert_host(target):
    machine = platform.machine().lower()
    machine = {"amd64": "x86_64", "arm64": "aarch64"}.get(machine, machine)
    system = platform.system().lower()
    if target != system + "-" + machine:
        raise ValueError("actual host differs from selected execution target")
    return {"target": target, "system": system, "machine": machine, "release": platform.release(),
            "python": platform.python_version()}


def run(args):
    subprocess.run([str(a) for a in args], cwd=ROOT, check=True)


def archives(directory, recursive=True):
    find = directory.rglob if recursive else directory.glob
    values = sorted(list(find("*.tar.gz")) + list(find("*.zip")))
    if not values:
        raise ValueError("no application archives found")
    names = [x.name for x in values]
    if len(names) != len(set(names)):
        raise ValueError("duplicate application archive names")
    return values


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("plan")
    p.add_argument("--devfast", action="store_true")
    p.add_argument("--no-arm", action="store_true")
    p.add_argument("--pool", choices=("standard", "faster"), default="standard")
    p.add_argument("--configured", default="")
    p.add_argument("--configured-arm", default="")
    p.add_argument("--configured-windows", default="")
    p.add_argument("--github-output", type=Path)
    p = sub.add_parser("host")
    p.add_argument("target", choices=tuple(STANDARD))
    p = sub.add_parser("package")
    p.add_argument("--build", type=Path, required=True)
    p.add_argument("--jobs", type=module("build_capacity").compile_jobs, default="auto")
    p.add_argument("--core-provider", choices=("rust", "cpp"), default="rust")
    p.add_argument("--rust-sdk", type=Path)
    p = sub.add_parser("check-archives")
    p.add_argument("directory", type=Path)
    p.add_argument("--runtime-only", action="store_true")
    p = sub.add_parser("workflow-lint")
    p.add_argument("--retained-url", default="")
    p.add_argument("--executable", default="")
    p.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.command == "plan":
        result = plan(args.devfast, not args.no_arm, args.pool, args.configured, args.configured_arm, args.configured_windows)
        if args.github_output:
            with args.github_output.open("a", encoding="utf-8") as out:
                for key, value in result.items():
                    out.write(key + "=" + json.dumps(value, separators=(",", ":")) + "\n")
        print(json.dumps(result, indent=2))
    elif args.command == "workflow-lint":
        workflow_lint(args.output, retained_url=args.retained_url, executable=args.executable)
    elif args.command == "host":
        print(json.dumps(assert_host(args.target)))
    elif args.command == "package":
        if args.jobs < 1:
            raise ValueError("positive compile concurrency required")
        run([sys.executable, "tools/build.py", "package", "release", "--portable", "--build-dir", args.build,
             "--jobs", str(args.jobs), "--core-provider", args.core_provider,
             *(["--rust-sdk", str(args.rust_sdk)] if args.rust_sdk is not None else [])])
        for archive in archives(args.build / "packages", recursive=False):
            manifest = archive.with_name(archive.name + ".json")
            for operation in ("create", "verify"):
                run([sys.executable, "tools/artifact.py", operation, archive, "--manifest", manifest])
    else:
        for archive in archives(args.directory):
            run([sys.executable, "tools/artifact.py", "verify", archive,
                 "--manifest", archive.with_name(archive.name + ".json"),
                 *(["--runtime-only"] if args.runtime_only else [])])



# Lifecycle operations use the same validators as local release preparation.

ACTIONLINT_SHA256 = '8aca8db96f1b94770f1b0d72b6dddcb1ebb8123cb3712530b08cc387b349a3d8'


def workflow_lint(output, *, retained_url='', executable=''):
    """Require an installed validator or explicitly retained exact archive; no upstream fallback."""
    import io
    import shutil
    import tarfile
    import urllib.parse
    import urllib.request
    c = module('coverage')
    output = Path(output)
    tool = executable or shutil.which('actionlint')
    origin = 'installed'
    if not tool:
        def checked_url(url):
            parsed = urllib.parse.urlsplit(url)
            if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password or parsed.fragment:
                raise ValueError('retained validator requires credential-free HTTPS')
            return url
        checked_url(retained_url)
        class SecureRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, request, fp, code, msg, headers, newurl):
                checked_url(newurl)
                return super().redirect_request(request, fp, code, msg, headers, newurl)
        try:
            with urllib.request.build_opener(SecureRedirect()).open(retained_url, timeout=60) as response:
                data = response.read(32*1024*1024+1)
        except Exception as error:
            raise ValueError('retained validator transfer failed; inspect configured prerequisite') from error
        if len(data)>32*1024*1024 or __import__('hashlib').sha256(data).hexdigest()!=ACTIONLINT_SHA256:
            raise ValueError('retained validator archive differs from pinned identity')
        output.mkdir(parents=True,exist_ok=False)
        tool=output/'actionlint'
        with tarfile.open(fileobj=io.BytesIO(data)) as archive:
            members=[member for member in archive.getmembers() if member.name=='actionlint']
            if len(members)!=1 or not members[0].isfile() or members[0].size>32*1024*1024:
                raise ValueError('retained validator archive has invalid executable')
            with tool.open('xb') as stream: stream.write(archive.extractfile(members[0]).read())
        tool.chmod(0o755);origin='retained-exact-archive'
    else:
        tool=Path(tool).resolve(strict=True)
        output.mkdir(parents=True,exist_ok=False)
    version=subprocess.run([str(tool),'-version'],check=True,capture_output=True,text=True).stdout.splitlines()
    if not version or version[0].strip()!='1.7.12':
        raise ValueError('installed validator version differs from qualified prerequisite')
    files=sorted((ROOT/'.github/workflows').glob('*.yml'))
    if not files: raise ValueError('no workflow files')
    before = {'tool':c.sha(tool), 'workflows':{p.name:c.sha(p) for p in files}}
    subprocess.run([str(tool),'-shellcheck=','-pyflakes=',*map(str,files)],check=True)
    if before != {'tool':c.sha(tool), 'workflows':{p.name:c.sha(p) for p in files}}:
        raise ValueError('validator or workflow inputs changed during validation')
    result=dict(schema_version=1,status='passed',version=version[0],origin=origin,
                executable_sha256=c.sha(tool),workflows={p.name:c.sha(p) for p in files})
    c.write_new(output/'qualification.json',result)
    return result


def module(name):
    import importlib.util
    if str(ROOT / 'tools') not in sys.path: sys.path.insert(0, str(ROOT / 'tools'))
    spec = importlib.util.spec_from_file_location('ci_' + name, ROOT / 'tools' / (name + '.py'))
    value = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(value)
    return value


def exact_commit(value):
    if not isinstance(value, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', value):
        raise ValueError('complete source commit required')
    return value


def runner_selection(pool='standard', configured='', configured_arm='', configured_windows=''):
    return {row['target']: row['runner'] for row in plan(pool=pool, configured=configured, configured_arm=configured_arm, configured_windows=configured_windows)['packages']['include']}


def rust_recipe(target):
    if target not in RUST_RECIPES:
        raise ValueError('no qualified Rust recipe for target')
    rust = module('rust_sdk'); path = ROOT / RUST_RECIPES[target]
    rust.checked_recipe(path)
    return rust.recipe_identity(path)


def rust_base_names(recipe):
    return module('rust_sdk').group_names(recipe)


def release_matrix(recipes, profile='core', policy=None, *, runners=None, core_provider='rust'):
    if core_provider not in ('rust', 'cpp'):
        raise ValueError('unknown core provider')
    policy = policy or module('coverage').load(ROOT / 'docs/release-policy.json')
    selected, _ = module('certify_release').requirements(policy, profile)
    if not isinstance(recipes, dict) or set(recipes) != set(selected['targets']):
        raise ValueError('recipe map must cover exactly the selected target inventory')
    if any(not isinstance(v, str) or not re.fullmatch(r'[0-9a-f]{64}', v) for v in recipes.values()):
        raise ValueError('every target requires its complete prepared recipe')
    if profile == 'all-gui':
        lock = module('coverage').load(ROOT / 'third_party/gui-boundary.lock.json')
        if lock.get('redistribution', {}).get('approved') is not True:
            raise ValueError('GUI redistribution licensing must be resolved before producing release assets')
    runners = STANDARD if runners is None else runners
    if set(runners) != set(STANDARD): raise ValueError('complete runner selection required')
    rows = []
    for target, backends in selected['targets'].items():
        if target not in (*STANDARD, 'browser-wasm32'):
            raise ValueError('no qualified runner adapter for target')
        if core_provider == 'rust' and target == 'browser-wasm32':
            paired = module('rust_sdk').checked_recipe(ROOT / RUST_RECIPES[target])
            if paired['cpp_sdk_recipe_id'] != recipes[target]:
                raise ValueError('browser Rust recipe requires its exact matched C++ SDK recipe')
        rows.append({'target': target, 'runner': runners.get(target, runners['linux-x86_64']),
                     'recipe': recipes[target], 'backends': backends,
                     'container': 'debian:bookworm' if target.startswith('linux-') else '',
                     'core_provider': core_provider,
                     'rust_recipe': rust_recipe(target) if core_provider == 'rust' else ''})
    return {'include': rows}


def rust_qualification_matrix(recipes, *, runners=None):
    """An explicit complete optional-provider lane, with no publication adapter."""
    if not isinstance(recipes, dict) or set(recipes) != set(RUST_RECIPES):
        raise ValueError('Rust qualification requires every native and browser target')
    rows = release_matrix(recipes, 'all-gui', runners=runners)['include']
    rust = module('rust_sdk')
    for row in rows:
        path = ROOT / RUST_RECIPES[row['target']]
        rust.checked_recipe(path)
        row.update(core_provider='rust', rust_recipe=rust.recipe_identity(path),
                   rust_recipe_file=RUST_RECIPES[row['target']])
    return {'include': rows}


def source_archive(output, gui_source=None):
    module('source_identity').archive_source(ROOT, output, gui_source)
    return {'archive': str(output), 'sha256': module('coverage').sha(output)}


def rust_selection(core_provider, rust_group, rust_recipe):
    if core_provider not in ('cpp', 'rust'):
        raise ValueError('unknown core provider')
    if core_provider == 'cpp':
        if rust_group is not None or rust_recipe is not None:
            raise ValueError('C++ selection must omit Rust SDK inputs')
        return None
    if rust_group is None or not isinstance(rust_recipe, str) or not re.fullmatch(r'[0-9a-f]{64}', rust_recipe):
        raise ValueError('Rust selection requires one exact retained SDK group')
    return module('rust_sdk').verify_group(Path(rust_group), rust_recipe)


def install_rust_input(core_provider, rust_group, rust_recipe, output, cpp_sdk):
    if core_provider == 'cpp':
        return ['--core-provider', 'cpp'], {'core_provider': 'cpp'}
    rust = module('rust_sdk')
    rust.install(Path(rust_group), rust_recipe, output)
    metadata = rust.verify_rust_sdk(output, cpp_sdk=cpp_sdk, execute=True)
    identity = {'core_provider': 'rust', 'rust_sdk_recipe_id': rust_recipe,
                'rust_compiler_version': metadata['compiler']['version'],
                'rust_target': metadata['target']['triple'],
                'rust_sdk_manifest_sha256': module('coverage').sha(output / 'rust-sdk.json'),
                'rust_compiler_sha256': module('coverage').sha(output / metadata['compiler']['rustc'])}
    return ['--core-provider', 'rust', '--rust-sdk', str(output)], identity


def prepared_package(target, recipe, group, source, output, jobs=2, *, graphics_archive=None, expected_files=None,
                     core_provider='rust', rust_group=None, rust_recipe=None):
    import shutil
    from dependency_archive import extract
    from dependency_store import verify_group
    if target != 'browser-wasm32':
        assert_host(target)
    elif platform.system() != 'Linux':
        raise ValueError('prepared browser producer requires its declared Linux host')
    if graphics_archive is not None and target != 'windows-x86_64':
        raise ValueError('retained host graphics input applies only to Windows GUI production')
    if jobs < 1 or output.exists():
        raise ValueError('positive concurrency and new package output required')
    rust_files = rust_selection(core_provider, rust_group, rust_recipe)
    if expected_files is None: verify_group(group, recipe)
    else: module('dependency_store').verify_binary_group(group, recipe, expected_files)
    manifest = module('source_identity').verify_source_archive(source)
    output.mkdir(parents=True)
    work = output / 'work'
    extract(source, work / 'source')
    root = work / 'source'
    build = work / 'build'
    command = [sys.executable, str(root / 'tools/build.py'), 'test', 'release', '--full',
               '--portable', '--build-dir', str(build), '--build-jobs', str(jobs), '--test-jobs', '2', '--junit', str(output / 'source.junit.xml')]
    if target == 'windows-x86_64':
        version = module('windows_toolchain').inspect_selected_linker()['version']
        options = {} if expected_files is None else {'expected_files': expected_files}
        sdk_metadata = module('sdk_windows').install(group, recipe, work / 'dependencies', version, **options)
        command += ['--binary-dependency-group' if expected_files is not None else '--dependency-group',
                    str(group), '--windows-dependencies', str(work / 'dependencies')]
    else:
        options = {} if expected_files is None else {'expected_files': expected_files}
        sdk_metadata = module('sdk').install(group, recipe, work / 'sdk', production=True, **options)
        command += ['--sdk', str(work / 'sdk')]
    rust_flags, provider = install_rust_input(core_provider, rust_group, rust_recipe, work / 'rust-sdk',
                                            work / 'dependencies' if target == 'windows-x86_64' else work / 'sdk')
    command += rust_flags
    gui = root / 'third_party/retained/gui'
    if gui.is_dir():
        backends = ['wasm'] if target == 'browser-wasm32' else ['terminal', 'framebuffer', 'fltk', 'rev', 'sdl', 'hosted-web']
        capabilities = sdk_metadata.get('capabilities', ['wasm'] if target == 'browser-wasm32' else ['core', 'terminal', 'framebuffer', 'hosted-web'])
        if not set(backends) <= set(capabilities):
            raise ValueError('prepared SDK lacks required GUI capabilities; select the explicit GUI recipe')
        command += ['--gui-source', str(gui), '--gui-backends', ','.join(backends)]
        if target != 'browser-wasm32': command += ['--host-tests']
    else:
        backends = []
        if target == 'browser-wasm32': raise ValueError('browser target requires retained GUI source')
    graphics_needed = target == 'windows-x86_64' and 'rev' in backends
    if graphics_needed != (graphics_archive is not None):
        raise ValueError('Windows GUI production requires one explicit retained host graphics archive; core must omit it')
    graphics_evidence = None
    if graphics_needed:
        module('windows_graphics').verify_archive(Path(graphics_archive))
        graphics_evidence = windows_gui_qualification(command, Path(graphics_archive), build, output, jobs,
            protected_roots=(Path(group).resolve(), root, work / 'dependencies'), cwd=root)
    else:
        subprocess.run(command, cwd=root, check=True)
    # Host DLLs must already be removed before installation or package creation.
    package_command = command.copy()
    package_command[2] = 'package'
    package_command.remove('--full')
    index = package_command.index('--junit')
    del package_command[index:index + 2]
    subprocess.run(package_command, cwd=root, check=True)
    choices = sorted((build / 'packages').glob('*.zip' if target.startswith('windows-') else '*.tar.gz'))
    if len(choices) != 1:
        raise ValueError('producer needs one exact platform archive')
    archive = output / (target + ('.tar.gz' if choices[0].name.endswith('.tar.gz') else '.zip'))
    shutil.copyfile(choices[0], archive)
    a = module('artifact')
    descriptor = archive.with_name(archive.name + '.json')
    module('coverage').write_new(descriptor, a.describe(archive))
    a.verify(archive, descriptor, sdk=work / 'sdk' if (work / 'sdk/sdk.json').is_file() else None,
             abi=target.startswith('linux-'), processor=target.split('-', 1)[1])
    if module('source_identity').source_tree(root) != manifest:
        raise ValueError('source changed during prepared application production')
    entry = {'path': archive.name, 'sha256': module('coverage').sha(archive),
             'manifest_path': descriptor.name, 'target': target, 'backends': backends,
             'sdk_recipe': recipe, 'dependency_recipes': [recipe]}
    entry.update(provider)
    if rust_recipe:
        entry['dependency_recipes'].append(rust_recipe)
        if module('rust_sdk').verify_group(Path(rust_group), rust_recipe) != rust_files:
            raise ValueError('Rust SDK group changed during application production')
    if core_provider == 'rust':
        module('release').validate_package(archive, entry, manifest['tree_sha256'], module('coverage').load(descriptor))
    if graphics_evidence is not None:
        module('coverage').write_new(output / 'graphics-qualification.json',
            {'schema_version': 1, 'status': 'passed', 'target': target, 'backends': backends,
             'archive_sha256': entry['sha256'], 'evidence': graphics_evidence})
    module('coverage').write_new(output / 'artifact.json', entry)
    return entry


def assemble_release(source, packages, base, output, profile):
    c = module('coverage')
    selected, _ = module('certify_release').requirements(c.load(ROOT / 'docs/release-policy.json'), profile)
    entries = []
    for path in sorted(packages.glob('*/artifact.json')):
        value = c.load(path)
        for field in ('path', 'manifest_path'):
            # Transport descriptors contain names, never producer-host paths.
            # Validate instead of sanitizing a foreign path into a trusted name.
            name = module('github_release').valid_name(value[field])
            value[field] = str(module('dependency_archive').checked_file(path.parent, name).resolve())
        entries.append(value)
    observed = {x['target']: x['backends'] or ['core'] for x in entries}
    if len(entries) != len(observed) or observed != selected['targets']:
        raise ValueError('missing, duplicate or unexpected producer target/backend inventory')
    spec = {'schema_version': 1, 'source': {'path': str(source.resolve()), 'sha256': c.sha(source)},
            'artifacts': entries, 'required_scopes': sorted({x['scope'] for x in selected['checks']})}
    spec_path = output.parent / 'assembly.json'
    c.write_new(spec_path, spec)
    return module('release').assemble(spec_path, base, output)


def fetch_candidate(repository, tag, inventory, output, transport=None, *, metadata_only=False, planning=False, workflow_context=None):
    import tempfile
    g = module('github_release')
    c = module('coverage')
    g.location(repository, tag)
    if type(planning) is not bool or planning and not metadata_only:
        raise ValueError('planning requires metadata-only acquisition')
    if workflow_context is not None and (not planning or not g.workflow_context_matches(workflow_context) or workflow_context['repository'] != repository):
        raise ValueError('snapshot context must identify this exact planning workflow')
    if not re.fullmatch(r'[0-9a-f]{64}', inventory) or output.exists() or output.is_symlink():
        raise ValueError('exact inventory digest and new candidate destination required')
    remote = g.Remote(repository, transport)
    remote.visible()
    before = remote.published(tag)
    assets = remote.assets(before)
    if 'delivery.json' not in assets:
        raise ValueError('published delivery descriptor is absent')
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=output.parent) as temp:
        staged = Path(temp)
        remote.download(assets['delivery.json'], staged / 'delivery.json')
        delivery = c.load(staged / 'delivery.json')
        if delivery.get('repository') != repository or delivery.get('tag') != tag or delivery.get('inventory_sha256') != inventory:
            raise ValueError('candidate differs from requested identity')
        if not isinstance(delivery.get('files'), dict) or not delivery['files']:
            raise ValueError('missing complete delivery file map')
        candidate = staged / 'candidate'; candidate.mkdir()
        selections = []
        for name, entry in delivery['files'].items():
            if metadata_only and name != 'release.json': continue
            path = c.local(candidate, name); path.parent.mkdir(parents=True, exist_ok=True)
            selections.append((entry['asset'], path, entry['sha256']))
        g.download_files(remote, assets, selections)
        # The descriptor and selected bytes above already came from this exact
        # observed inventory. Validate it locally, then reconcile once after all
        # optional planning payloads finish; do not download the descriptor again.
        g.validate_delivery(delivery,candidate,metadata_only=metadata_only)
        g.validate_remote_inventory(delivery,before,assets)
        if remote.reference(tag) != delivery['tag_commit']:
            raise ValueError('tag commit differs from frozen delivery')
        info, verified_assets = before, assets
        if planning:
            manifest = module('release').verify_metadata(candidate)
            source = manifest['source']['archive']; item = delivery['files'][source]
            remote.download(verified_assets[item['asset']], candidate / source, item['sha256'])
            retained = module('source_identity').verify_source_archive(candidate / source)
            if retained['tree_sha256'] != manifest['source']['tree_sha256']:
                raise ValueError('retained source tree differs from frozen inventory')
            snapshot = dict(schema_version=1, repository=repository, tag=tag,
                inventory_sha256=inventory, delivery_sha256=g.sha(module('dependency_archive').encoded(delivery)),
                release={key: info[key] for key in ('id', 'tag_name', 'name', 'draft', 'prerelease')}, assets=verified_assets)
            if workflow_context is not None:
                snapshot.update(schema_version=2, workflow_context=dict(workflow_context), repository_private=remote.private)
            c.write_new(staged / 'candidate-remote.json', snapshot)
        remote.unchanged(tag, before, assets, delivery['tag_commit'])
        staged.rename(output)
    return delivery




def fetch_candidate_payloads(repository, tag, inventory, candidate, identity, frozen, plan, check_ids, *, transport=None, trusted_context=None):
    """Restore pinned bytes; authenticated same-run controls avoid remote rescans.

    Only pass trusted_context after restoring producer-validated workflow controls.
    Final attachment/promotion still reconciles the complete live release identity.
    """
    import tempfile
    g = module('github_release'); c = module('coverage'); a = module('dependency_archive')
    candidate = Path(candidate).absolute()
    g.location(repository, tag); g.validate_delivery(identity, candidate, metadata_only=True)
    version = frozen.get('schema_version') if isinstance(frozen,dict) else None
    fields = {'schema_version', 'repository', 'tag', 'inventory_sha256', 'delivery_sha256', 'release', 'assets'}
    if version == 2: fields |= {'workflow_context','repository_private'}
    c.fields(frozen,fields)
    trusted = trusted_context is not None
    if (version == 2 and type(frozen['repository_private']) is not bool or trusted and
            (version != 2 or not g.workflow_context_matches(trusted_context) or
             trusted_context != frozen['workflow_context'] or trusted_context['repository'] != repository or
             plan['inputs'].get('build/candidate-remote.json') != g.sha(a.encoded(frozen)) or
             plan['inputs'].get('build/delivery.json') != g.sha(a.encoded(identity)))):
        raise ValueError('trusted candidate snapshot differs from authenticated workflow controls')
    if (type(version) is not int or version not in (1,2) or frozen['repository'] != repository or frozen['tag'] != tag or
            frozen['inventory_sha256'] != inventory or identity['repository'] != repository or
            identity['tag'] != tag or identity['inventory_sha256'] != inventory or
            frozen['delivery_sha256'] != g.sha(a.encoded(identity)) or
            plan['subject']['inventory_sha256'] != inventory):
        raise ValueError('published qualification inputs differ from frozen candidate')
    c.validate(plan)
    g.Remote.info(frozen['release'], tag)
    if frozen['release']['draft'] or frozen['release']['name'] != ('experiment' if identity['experiment'] else tag):
        raise ValueError('qualification requires the frozen published candidate')
    manifest = module('release').verify_metadata(candidate)
    declared = {'build/candidate/' + name: digest for name, digest in manifest['files'].items()}
    if (any(plan['inputs'].get(name) != digest for name, digest in declared.items()) or
            {name for name in plan['inputs'] if name.startswith('build/candidate/')} != set(declared) | {'build/candidate/release.json'} or
            plan['inputs']['build/candidate/release.json'] != inventory):
        raise ValueError('frozen qualification inventory is incomplete')
    checks = {item['id']: item for item in c.executions(plan)}
    if not check_ids or len(set(check_ids)) != len(check_ids) or any(name not in checks for name in check_ids):
        raise ValueError('unknown or duplicate qualification execution')
    names = sorted({name for check in check_ids for name in module('release').required_files(manifest,
        checks[check]['target'], checks[check]['backend'], checks[check]['scope'],
        binary_source=checks[check].get('sdk_payload') == 'binary')})
    assets = frozen['assets']
    expected = {item['asset'] for item in identity['files'].values()} | {'delivery.json'}
    if not isinstance(assets, dict) or not expected <= assets.keys():
        raise ValueError('frozen candidate asset inventory is incomplete')
    g.evidence_pairs(set(assets) - expected)
    for item in identity['files'].values():
        row = assets[item['asset']]
        if row['digest'] != 'sha256:' + item['sha256'] or row['size'] != item['size']:
            raise ValueError('frozen asset differs from complete delivery')
    if assets['delivery.json']['digest'] != 'sha256:' + frozen['delivery_sha256']:
        raise ValueError('frozen delivery asset differs')
    for name in names:
        destination = candidate / a.relative(name)
        if destination.exists() or destination.is_symlink():
            raise ValueError('candidate payload restore refuses an existing file: ' + name)
        for parent in destination.parents:
            _bundle_directory(parent)
            if parent == candidate.parent: break
    remote = g.Remote(repository, transport)
    if trusted:
        remote.pin_published(frozen['release'],assets,frozen['repository_private'])
    else:
        remote.visible()
        remote.unchanged(tag, frozen['release'], assets, identity['tag_commit'])
    with tempfile.TemporaryDirectory(prefix='.qualification-payload-', dir=candidate.parent) as temporary:
        staged = Path(temporary); selections = []
        for name in names:
            path = staged / a.relative(name); path.parent.mkdir(parents=True, exist_ok=True)
            item = identity['files'][name]
            selections.append((item['asset'], path, item['sha256']))
        g.download_files(remote, assets, selections)
        if not trusted: remote.unchanged(tag, frozen['release'], assets, identity['tag_commit'])
        # Recheck all outputs after network work, then use exclusive creation so
        # an intervening writer cannot be replaced by a POSIX rename.
        for name in names:
            destination = candidate / a.relative(name)
            if destination.exists() or destination.is_symlink():
                raise ValueError('candidate payload restore refuses an existing file: ' + name)
            for parent in destination.parents:
                _bundle_directory(parent)
                if parent == candidate.parent: break
        # Publish only after every pinned byte passes; strict callers also recheck remote snapshots.
        import shutil
        for name in names:
            destination = candidate / a.relative(name); destination.parent.mkdir(parents=True, exist_ok=True)
            for parent in destination.parents:
                _bundle_directory(parent)
                if parent == candidate.parent: break
            with (staged / a.relative(name)).open('rb') as incoming, destination.open('xb') as outgoing:
                shutil.copyfileobj(incoming, outgoing)
    return {'schema_version': 1, 'repository': repository, 'tag': tag, 'inventory_sha256': inventory,
            'release_id': frozen['release']['id'], 'files': {name: identity['files'][name] for name in names}}


def needs_browser_prerequisite(backend, scope):
    return backend == 'hosted-web' and scope == 'archive' or backend == 'wasm' and scope in ('source', 'recovery', 'archive')


def browser_prerequisite(target, environment, backend):
    """Select external browser test prerequisites without changing the SDK."""
    if backend not in ('hosted-web', 'wasm'):
        raise ValueError('browser setup requires a browser backend')
    systems = {'debian-12': ('debian', '12', 'debian:bookworm'),
               'debian-13': ('debian', '13', 'debian:trixie'),
               'ubuntu-24.04': ('ubuntu', '24.04', 'ubuntu:24.04')}
    if target == 'browser-wasm32' and backend == 'wasm' and environment == 'chromium':
        # Use the maintained host installation and its namespace/AppArmor policy.
        # The browser remains an external prerequisite, never an SDK payload.
        return dict(distribution='ubuntu', version='24.04', image='', architecture='amd64',
                    engine='chromium', packages=['google-chrome', 'chromedriver'],
                    executable='/usr/bin/google-chrome', driver='/usr/bin/chromedriver',
                    repository='host-preinstalled')
    if target == 'browser-wasm32' and backend == 'wasm' and environment == 'firefox':
        distro, version, image = systems['debian-12']; architecture = 'amd64'; engine = environment
    elif target in ('linux-x86_64', 'linux-aarch64') and backend == 'hosted-web' and environment in systems:
        distro, version, image = systems[environment]
        architecture = 'amd64' if target == 'linux-x86_64' else 'arm64'; engine = 'firefox'
    else:
        raise ValueError('unsupported browser qualification environment')
    packages = ['firefox'] if distro == 'ubuntu' else ['firefox-esr'] if engine == 'firefox' else ['chromium', 'chromium-driver']
    return dict(distribution=distro, version=version, image=image, architecture=architecture,
                engine=engine, packages=packages, executable='/usr/bin/' + packages[0],
                repository='host-preinstalled' if distro == 'ubuntu' else 'distribution')


def browser_setup_preflight(selection):
    """No package/configuration writes before positive disposable-host checks."""
    if (platform.system() != 'Linux' or not hasattr(os, 'geteuid') or os.geteuid() != 0 or
            os.environ.get('FOUNDATION_DISPOSABLE_CHECK') != '1' or not Path('/.dockerenv').is_file()):
        raise ValueError('browser setup requires an explicitly disposable root Docker runtime')
    actual = platform.freedesktop_os_release()
    if (actual.get('ID'), actual.get('VERSION_ID')) != (selection['distribution'], selection['version']):
        raise ValueError('actual browser runtime distribution differs from selected environment')
    if os.environ.get('CHECK_IMAGE') != selection['image']:
        raise ValueError('browser runtime image differs from selected environment')
    expected = 'linux-x86_64' if selection['architecture'] == 'amd64' else 'linux-aarch64'
    assert_host(expected)
    architecture = subprocess.run(['dpkg', '--print-architecture'], check=True, capture_output=True, text=True).stdout.strip()
    if architecture != selection['architecture']:
        raise ValueError('actual package architecture differs from selected environment')


def inspect_host_firefox(selection):
    """Inspect an existing native host browser; never install or edit package sources."""
    if selection['repository'] != 'host-preinstalled' or platform.system() != 'Linux':
        raise ValueError('native hosted browser requires the selected Linux environment')
    actual = platform.freedesktop_os_release()
    if (actual.get('ID'), actual.get('VERSION_ID')) != (selection['distribution'], selection['version']):
        raise ValueError('host browser distribution differs')
    assert_host('linux-x86_64' if selection['architecture'] == 'amd64' else 'linux-aarch64')
    def version(path):
        result = subprocess.run([str(path), '--version'], check=True, capture_output=True, text=True,
                                timeout=30, env=dict(os.environ, LC_ALL='C', LANG='C'))
        if not re.fullmatch(r'Mozilla Firefox [0-9]+(?:\.[0-9]+){1,3}(?:esr)?', result.stdout.strip()):
            raise ValueError('unrecognized installed Firefox version')
        return result.stdout.strip()
    command = Path(selection['executable']).resolve(strict=True)
    with command.open('rb') as stream: header = stream.read(131072)
    native = command
    if not header.startswith(b'\x7fELF'):
        # Recognized distribution wrappers only. Execute the inspected real binary
        # for qualification so an unrelated same-version installation cannot satisfy it.
        choices = []
        if b'/usr/lib/firefox' in header: choices.append(Path('/usr/lib/firefox/firefox'))
        if b'snap' in header: choices.append(Path('/snap/firefox/current/usr/lib/firefox/firefox'))
        choices = [x.resolve(strict=True) for x in choices if x.is_file()]
        if len(choices) != 1:
            raise ValueError('installed Firefox wrapper has no unambiguous native executable')
        native = choices[0]
        with native.open('rb') as stream: header = stream.read(64)
    machine = 62 if selection['architecture'] == 'amd64' else 183
    if len(header) < 20 or header[:6] != b'\x7fELF\x02\x01' or int.from_bytes(header[18:20], 'little') != machine:
        raise ValueError('installed Firefox executable architecture differs')
    observed = version(native)
    if version(command) != observed:
        raise ValueError('Firefox wrapper and native executable versions differ')
    c = module('coverage')
    files = {str(path): c.sha(path) for path in {command,native}}
    return dict(package='firefox', version=observed, architecture=selection['architecture'],
                policy='preinstalled native host prerequisite; no package configuration changed',
                executable=str(native), files=files)


def inspect_host_chromium(selection):
    """Bind the installed Chromium-family browser and matching local driver."""
    if (selection['repository'] != 'host-preinstalled' or selection['engine'] != 'chromium' or
            platform.system() != 'Linux'):
        raise ValueError('native Chromium requires the selected Linux host')
    if not hasattr(os, 'geteuid') or os.geteuid() == 0:
        raise ValueError('native Chromium qualification requires an unprivileged host account')
    actual = platform.freedesktop_os_release()
    if (actual.get('ID'), actual.get('VERSION_ID')) != (selection['distribution'], selection['version']):
        raise ValueError('host browser distribution differs')
    assert_host('linux-x86_64')
    records = []
    versions = []
    for package, selected in zip(selection['packages'], (selection['executable'], selection['driver'])):
        command = Path(selected).resolve(strict=True)
        with command.open('rb') as stream: header = stream.read(131072)
        native = command
        if package == 'google-chrome' and not header.startswith(b'\x7fELF'):
            if b'"$HERE/chrome"' not in header or not (command.parent / 'chrome').is_file():
                raise ValueError('installed Chrome wrapper has no recognized native executable')
            native = (command.parent / 'chrome').resolve(strict=True)
            with native.open('rb') as stream: header = stream.read(64)
        if len(header) < 20 or header[:6] != b'\x7fELF\x02\x01' or int.from_bytes(header[18:20], 'little') != 62:
            raise ValueError('installed Chromium prerequisite architecture differs')
        def version(path):
            result = subprocess.run([str(path), '--version'], check=True, capture_output=True,
                                    text=True, timeout=30, env=dict(os.environ, LC_ALL='C', LANG='C'))
            value = result.stdout.strip()
            expression = (r'(?:Google Chrome(?: for Testing)?|Chromium) ([0-9]+(?:\.[0-9]+){3})' if package == 'google-chrome'
                          else r'ChromeDriver ([0-9]+(?:\.[0-9]+){3})(?: \([^\r\n]*\))?')
            match = re.fullmatch(expression, value)
            if not match: raise ValueError('unrecognized installed Chromium prerequisite version')
            return value, match[1]
        observed, number = version(native)
        if command != native and version(command)[0] != observed:
            raise ValueError('Chrome wrapper and native executable versions differ')
        versions.append(number)
        records.append(dict(package=package, version=observed, architecture=selection['architecture'],
            policy='preinstalled native host prerequisite; no package configuration changed',
            executable=str(native), files={str(path): module('coverage').sha(path) for path in {command,native}}))
    if versions[0].split('.')[0] != versions[1].split('.')[0]:
        raise ValueError('installed Chromium browser and driver major versions differ')
    return records


def install_browser_prerequisite(target, environment, backend, output):
    """Mutate only an explicitly disposable supported container, retaining facts."""
    selection = browser_prerequisite(target, environment, backend)
    if selection['repository'] == 'host-preinstalled':
        records = inspect_host_chromium(selection) if selection['engine'] == 'chromium' else [inspect_host_firefox(selection)]
        Path(output).mkdir(parents=True, exist_ok=False)
        return dict(schema_version=1, selection=selection, signing_key_fingerprint=None,
                    installed=records, browser_version=records[0]['version'])
    browser_setup_preflight(selection)
    output = Path(output); output.mkdir(parents=True, exist_ok=False)
    def capture(argv):
        return subprocess.run(argv, check=True, capture_output=True, text=True,
                              env=dict(os.environ, LC_ALL='C', LANG='C')).stdout.strip()
    subprocess.run(['apt-get', 'install', '-y', '--no-install-recommends', *selection['packages']], check=True)
    installed = []
    for package in selection['packages']:
        fields = capture(['dpkg-query', '-W', '-f=${Package}\t${Version}\t${Architecture}\t${db:Status-Status}\n', package]).split('\t')
        if len(fields) != 4 or fields[0] != package or fields[2] != selection['architecture'] or fields[3] != 'installed':
            raise ValueError('installed browser package differs from selected prerequisite')
        installed.append(dict(package=fields[0], version=fields[1], architecture=fields[2],
                              policy=capture(['apt-cache', 'policy', package])))
    return dict(schema_version=1, selection=selection, signing_key_fingerprint=None,
                installed=installed, browser_version=capture([selection['executable'], '--version']))


def needs_windows_graphics(target, backends, backend, scope):
    return target == 'windows-x86_64' and 'rev' in backends and (scope in ('source', 'recovery') or backend == 'rev' and scope == 'archive')


def qualification_row(item, runners=None):
    """Keep execution routing identical for individual checks and CI batches."""
    runners = STANDARD if runners is None else runners
    if set(runners) != set(STANDARD) or any(not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9.-]*', value) for value in runners.values()):
        raise ValueError('explicit complete runner selection required')
    target, environment, backend, scope = (item[key] for key in ('target', 'environment', 'backend', 'scope'))
    images = {'debian-12': 'debian:bookworm', 'debian-13': 'debian:trixie', 'ubuntu-24.04': 'ubuntu:24.04'}
    image = '' if (environment == 'ubuntu-24.04' and backend == 'hosted-web' and scope == 'archive' or
                   target == 'browser-wasm32' and backend == 'wasm' and environment == 'chromium') else images.get(environment, 'debian:bookworm' if environment in ('firefox', 'chromium') else '')
    return dict(id=item['id'], target=target, runner=runners.get(target, runners['linux-x86_64']),
                image=image, environment=environment, scope=scope, backend=backend,
                graphics='--windows-graphics-archive' in item['argv'])


def qualification_batches(plan, *, runners=None, manifest=None, attempt=None):
    """Keep independent scopes parallel and backend receipts complete.

    Whole-artifact source/recovery/ABI executions remain coalesced across
    backends; archive/client checks share only one same-scope transport batch.
    The 90-minute case and 240-minute hosted job limits are independent safety
    caps, not a promise that every member can exhaust its case allowance. Split
    future longer workloads here; this code is itself bound by the frozen plan.
    """
    c = module('coverage')
    rows = [qualification_row(item, runners) for item in c.executions(plan)]
    groups = {}
    for row in rows:
        groups.setdefault(tuple(row[key] for key in ('runner', 'image', 'target', 'environment', 'scope')), []).append(row)
    batches, identities = [], set()
    for members in groups.values():
        # Bound future policy growth without changing logical or execution IDs.
        for start in range(0, len(members), 16):
            selected = members[start:start + 16]
            first = selected[0]
            batch = {key: first[key] for key in ('runner', 'image', 'target', 'environment')}
            batch.update(checks=[row['id'] for row in selected],
                         graphics=any(row['graphics'] for row in selected),
                         browser=any(row['target'] != 'windows-x86_64' and needs_browser_prerequisite(row['backend'], row['scope']) for row in selected))
            # Transport labels have stricter characters and length than frozen
            # check IDs. Leave room for browser-prerequisite- and a 19-digit
            # attempt within ci_transport's 80-character bundle-name bound.
            slug = re.sub(r'[^a-z0-9_-]', '-', first['id'].lower())[:20]
            identity = 'batch-' + slug + '-' + c.digest(batch)[:12]
            if identity in identities:raise ValueError('colliding batch transport identity')
            identities.add(identity); batch['id'] = identity
            if manifest is not None:
                batch['payloads'] = qualification_payload_names(plan, batch, manifest, attempt)
            batches.append(batch)
    return {'include': batches}


def qualification_payload_names(plan, batch, manifest, attempt, *, include_inputs=True):
    """Derive a bounded exact projection from complete frozen qualification data."""
    if not isinstance(attempt, str) or not re.fullmatch(r'[1-9][0-9]*', attempt):
        raise ValueError('positive qualification attempt required')
    checks = {item['id']: item for item in module('coverage').executions(plan)}
    if not batch['checks'] or any(name not in checks for name in batch['checks']):
        raise ValueError('unknown qualification execution')
    items = [checks[name] for name in batch['checks']]
    if len({(item['target'], item['scope']) for item in items}) != 1:
        raise ValueError('one independent qualification scope required')
    item = items[0]
    entries = [entry for entry in manifest['artifacts'] if entry['target'] == item['target']]
    if len(entries) != 1: raise ValueError('selected target is absent or duplicate')
    names = ['qualification-inputs-' + attempt] if include_inputs else []
    names.append('qualification-' + item['target'] + '-' + attempt)
    if item['scope'] in ('source', 'recovery') or item['scope'] == 'archive' and any(row['backend'] in ('wasm', 'hosted-web') for row in items):
        names.append('qualification-source-' + attempt)
    if item['scope'] in ('source', 'recovery'):
        required = set(module('release').dependency_recipes(entries[0]))
        found = set()
        for index, group in enumerate(manifest['dependencies']):
            if group['recipe_id'] in required:
                found.add(group['recipe_id'])
                names.append('qualification-sdk-' + str(index) + '-' + attempt)
                if item['scope'] == 'recovery' or group.get('kind') == 'rust' or item.get('sdk_payload') != 'binary':
                    names.append('qualification-sdk-source-' + str(index) + '-' + attempt)
        if found != required: raise ValueError('qualification SDK closure is incomplete')
    if len(names) > 20 or len(names) != len(set(names)):
        raise ValueError('bounded distinct qualification payloads required')
    return names


def archived_binary_group_support(candidate, manifest):
    """Inspect the exact retained builder; old candidates keep complete SDKs."""
    import ast, tarfile
    source = candidate / manifest['source']['archive']
    with tarfile.open(source, 'r:*') as archive:
        members = [item for item in archive.getmembers() if item.name == 'tools/build.py']
        if not members: return False
        if len(members) != 1 or not members[0].isfile() or members[0].size > 8*1024**2:
            raise ValueError('invalid retained builder capability input')
        tree = ast.parse(archive.extractfile(members[0]).read().decode('utf-8'))
    return any(isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and
               node.func.attr == 'add_argument' and any(isinstance(arg, ast.Constant) and
               arg.value == '--binary-dependency-group' for arg in node.args) for node in ast.walk(tree))


def qualification_plan(candidate, profile, output, policy=None, *, runners=None, metadata_only=False):
    """Add hosted input bindings and runner routing to the local frozen plan."""
    from types import SimpleNamespace
    additional = {name: ROOT / name for name in
        ('.github/scripts/lifecycle.py', '.github/scripts/container_job.py', '.github/workflows/certify.yml')}
    if metadata_only:
        additional.update({'build/' + name: candidate.parent / name
                           for name in ('delivery.json', 'candidate-remote.json')})
    helpers = SimpleNamespace(module=module, needs_browser_prerequisite=needs_browser_prerequisite,
        browser_prerequisite=browser_prerequisite, needs_windows_graphics=needs_windows_graphics,
        archived_binary_group_support=archived_binary_group_support)
    value = module('qualification_plan').build_plan(ROOT, candidate, profile, policy,
        additional_inputs=additional, metadata_only=metadata_only, _helpers=helpers)
    c = module('coverage')
    matrix = [qualification_row(item, runners) for item in c.executions(value)]
    c.write_new(output, value)
    return {'include': matrix}


def _bundle_directory(path):
    import stat
    try: info=path.lstat()
    except FileNotFoundError: return
    if not stat.S_ISDIR(info.st_mode) or getattr(info,'st_file_attributes',0)&0x400:
        raise ValueError('bundle destination requires ordinary directories without links or reparse points')


def restore_run_bundle(repository, run_id, attempt, source_commit, workflow, name, output, *, allow_failed=False):
    """Verify into new staging before merging only absent files into an owned output."""
    import tempfile
    import shutil
    a=module('dependency_archive'); transport=module('ci_transport')
    output=Path(output).absolute()
    for parent in (output,*output.parents):
        _bundle_directory(parent)
    output.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.ci-bundle-',dir=output.parent) as temporary:
        staged=Path(temporary)/'payload'
        result=transport.fetch_bundle(repository,run_id,attempt,source_commit,workflow,name,staged,
                                      allow_failed=allow_failed)
        entries=result['manifest']['files']
        for relative in entries:
            destination=output/a.relative(relative)
            if destination.exists() or destination.is_symlink():
                raise ValueError('bundle restore refuses an existing file: '+relative)
            for parent in destination.parents:
                if parent==output.parent: break
                _bundle_directory(parent)
        output.mkdir(exist_ok=True)
        for relative,info in entries.items():
            source=staged/a.relative(relative);destination=output/a.relative(relative)
            destination.parent.mkdir(parents=True,exist_ok=True)
            with source.open('rb') as incoming,destination.open('xb') as outgoing:
                shutil.copyfileobj(incoming,outgoing)
            destination.chmod(info['mode'])
    return result


def restore_run_bundles(repository, run_id, attempt, source_commit, workflow, requests):
    """Fetch one authenticated batch before merging any selected payload files."""
    import tempfile, shutil
    a = module('dependency_archive'); transport = module('ci_transport')
    if not isinstance(requests, list) or not requests:
        raise ValueError('nonempty bundle restore batch required')
    outputs = []
    for request in requests:
        if not isinstance(request, dict) or not {'name', 'output'} <= request.keys():
            raise ValueError('bundle request requires exact name and output')
        output = Path(request['output']).absolute()
        for parent in (output, *output.parents): _bundle_directory(parent)
        outputs.append(output)
    outputs[0].parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.ci-batch-', dir=outputs[0].parent) as temporary:
        stages = [Path(temporary) / str(index) / 'payload' for index in range(len(requests))]
        selected = [dict(request, output=stage) for request, stage in zip(requests, stages)]
        results = transport.fetch_bundles(repository, run_id, attempt, source_commit, workflow, selected)
        if len(results) != len(requests): raise ValueError('bundle batch result inventory differs')
        files = []; destinations = set()
        for request, result, output, stage in zip(requests, results, outputs, stages):
            if result['manifest']['name'] != request['name']:
                raise ValueError('bundle batch result name differs')
            for relative, info in result['manifest']['files'].items():
                destination = output / a.relative(relative)
                key = str(destination).casefold()
                if key in destinations or destination.exists() or destination.is_symlink():
                    raise ValueError('bundle restore refuses an existing or colliding file: ' + relative)
                destinations.add(key)
                for parent in destination.parents: _bundle_directory(parent)
                files.append((stage / a.relative(relative), destination, info['mode']))
        if any(str(parent).casefold() in destinations for _, destination, _ in files for parent in destination.parents):
            raise ValueError('bundle restore file collides with another parent directory')
        # Complete collision/type checks precede every final write. Exclusive
        # creation rechecks later changes and never replaces an existing file.
        for source, destination, mode in files:
            for parent in destination.parents: _bundle_directory(parent)
            destination.parent.mkdir(parents=True, exist_ok=True)
            with source.open('rb') as incoming, destination.open('xb') as outgoing:
                shutil.copyfileobj(incoming, outgoing)
            destination.chmod(mode)
    return results


def download_run(repository, run_id, source_commit, workflow, name, output):
    g=module('github_release'); remote=g.Remote(repository);remote.visible()
    observed=remote.transport.json(remote.base+'/actions/runs/'+str(run_id))
    if observed.get('status')!='completed' or observed.get('conclusion')!='success':
        raise ValueError('bundle producer run must complete successfully')
    return restore_run_bundle(repository,run_id,observed['run_attempt'],source_commit,workflow,name,output)


def retained_sdk_request(request, repository, target, profile, recipe):
    fields={'schema_version','repository','target','profile','recipe_id','run_id','source_commit',
            'attempt','job_id','workflow','group','proof'}
    if not isinstance(request,dict) or set(request)!=fields or type(request['schema_version']) is not int or request['schema_version']!=2:
        raise ValueError('exact version-2 retained bundle request required; legacy storage requires explicit import')
    if request['workflow'] not in ('sdk-maintenance.yml','sdk-import.yml'):
        raise ValueError('retained SDK requires an allowed explicit producer workflow')
    legacy={key:value for key,value in request.items() if key!='workflow'}
    legacy['schema_version']=1
    for kind in ('group','proof'):
        entry=request[kind]
        if not isinstance(entry,dict) or set(entry)!={'manifest_id','manifest_sha256'}:
            raise ValueError('exact bundle manifest identity required')
        legacy[kind]={'id':entry['manifest_id'],'sha256':entry['manifest_sha256']}
    legacy_sdk_request(legacy,repository,target,profile,recipe)
    return request


def retained_sdk(repository,request,target,profile,recipe,output,*,transport=None):
    """Ordinary reuse accepts only complete run-scoped draft-release bundles."""
    import tempfile
    store=module('dependency_store');g=module('github_release');bundles=module('ci_transport')
    retained_sdk_request(request,repository,target,profile,recipe)
    output=Path(output).absolute()
    if output.exists() or output.is_symlink(): raise ValueError('retained SDK output must be new')
    output.parent.mkdir(parents=True,exist_ok=True)
    observed={}
    with tempfile.TemporaryDirectory(prefix='.retained-bundles-',dir=output.parent) as temporary:
        stage=Path(temporary)
        for kind in ('proof','group'):
            reference=request[kind]
            observed[kind]=bundles.fetch_bundle(repository,request['run_id'],request['attempt'],request['source_commit'],
                request['workflow'],f'sdk-{kind}-{target}-{request["attempt"]}',stage/kind,
                job_id=request['job_id'],manifest_id=reference['manifest_id'],
                manifest_sha256=reference['manifest_sha256'],allow_failed=True,transport=transport)
        proof=stage/'proof'
        for name in ('sdk-retention.json','sdk-origin.json'):
            path=proof/name
            if not path.is_file() or path.is_symlink() or path.stat().st_size>128*1024:
                raise ValueError('retained proof requires bounded retention and origin records')
        receipt=g.parse((proof/'sdk-retention.json').read_bytes());origin=g.parse((proof/'sdk-origin.json').read_bytes())
        expected=dict(schema_version=1,status='verified',qualification='unqualified',publication_approved=False,
            target=target,profile=profile,recipe_id=recipe,source_commit=request['source_commit'],
            run_id=str(request['run_id']),attempt=request['attempt'])
        if (not isinstance(receipt,dict) or set(receipt)!=set(expected)|{'files'} or
            any(type(receipt.get(k)) is not type(v) or receipt[k]!=v for k,v in expected.items()) or
            not isinstance(origin,dict) or origin.get('recipe')!=recipe or
            origin.get('origin') not in ('base','rebuild','absent-base','absent-recipe','retained')):
            raise ValueError('retained bundle receipt or origin differs from exact request')
        files=store.verify_group(stage/'group',recipe)
        if files!=receipt['files']: raise ValueError('retained SDK triplet differs from verified receipt')
        store.copy_group(stage/'group',output,recipe)
    return dict(origin='retained',recipe=recipe,qualification='unqualified',publication_approved=False,
                repository=repository,request=request,bundles=observed,retention=receipt,previous_origin=origin)


def retained_rust_request(request, repository, target, recipe):
