def install_portage(config, helper=Path(__file__)):
    """Install only the adapter, from an already operator-trusted retained tool tree."""
    if not hasattr(os, 'geteuid') or os.geteuid() != 0: raise ValueError('Portage installation requires root')
    import portage.sync.modules
    value = configuration(release.archive.read_json(config)); module = Path(portage.sync.modules.__path__[0])/'foundation_release'
    files = {module/'__init__.py': PORTAGE_ADAPTER,
        Path('/etc/portage/repos.conf/software-foundation-bin.conf'): native_config(value, 'gentoo', helper, config)}
    for path, text in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            if path.is_symlink() or path.read_text() != text: raise ValueError('preserve existing different Portage configuration')
        else:
            with path.open('x') as stream: stream.write(text)
            path.chmod(0o644)
    return {'adapter': str(module), 'config': str(Path(config).resolve())}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('operation', choices=('refresh', 'upgrade', 'config', 'install-portage'))
    parser.add_argument('--config', type=Path, required=True)
    parser.add_argument('--policy', type=Path, default=Path(__file__).resolve().parents[1]/'docs/release-policy.json')
    parser.add_argument('--kind', choices=('apt', 'arch', 'gentoo'))
    args = parser.parse_args(argv); value = configuration(release.archive.read_json(args.config))
    if args.operation == 'refresh': result = refresh(value, args.policy)
    elif args.operation == 'upgrade':
        if args.kind not in ('apt', 'arch'): parser.error('upgrade requires --kind apt or arch')
        result = native_upgrade(value, args.policy, args.kind)
    elif args.operation == 'install-portage': result = install_portage(args.config)
    else:
        if not args.kind: parser.error('--kind required')
        print(native_config(value, args.kind, Path(__file__), args.config), end=''); return
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, subprocess.SubprocessError) as error:
        raise SystemExit('distribution client: '+str(error)+'; preserve current state')

#!/usr/bin/env python3
"""Explicit pinned source SDK producer, with retained-input offline replay."""
import argparse
import hashlib
import os
from pathlib import Path, PurePosixPath
import platform
import re
import shutil
import subprocess
import tarfile
import tempfile
import urllib.request
from dependency_archive import sdk_temporary_directory, digest, encoded, file_inventory, read_json, relative, verify_inventory, write_json
from sdk import export_group, materialize, seal

TOOLS = ('distro_sdk.py', 'sdk.py', 'sdk_environment.py', 'sdk_manifest.py', 'dependency_archive.py', 'dependency_store.py', 'verify_abi.py')


def recipe_id(recipe):
    recipe = Path(recipe)
    inputs = {'recipe.json': digest(recipe)}
    for name in ('config', 'Config.in', 'external.desc', 'external.mk'):
        inputs[name] = digest(recipe.parent / name)
    for name in TOOLS:
        inputs['tools/' + name] = digest(Path(__file__).parent / name)
    return hashlib.sha256(encoded(inputs)).hexdigest()


def fetch_file(item, path, network):
    path = Path(path)
    if path.is_file():
        if digest(path) != item['sha256']: raise ValueError('changed pinned input: ' + path.name)
        return
    if not network: raise ValueError('missing pinned input; explicit fetch required: ' + path.name)
    if not item['url'].startswith('https://'): raise ValueError('source URL must use HTTPS')
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as stream: temporary = Path(stream.name)
    try:
        with urllib.request.urlopen(item['url'], timeout=60) as source, temporary.open('wb') as output:
            shutil.copyfileobj(source, output)
        if digest(temporary) != item['sha256']: raise ValueError('pinned source checksum mismatch')
        temporary.replace(path)
    finally:
        temporary.unlink(missing_ok=True)


def unpack_source(archive, output):
    """Upstream source links remain inert; no extraction can traverse any link."""
    if output.exists(): raise ValueError('source extraction destination must be new')
    with tarfile.open(archive) as source:
        members = source.getmembers()
        names, links = {}, set()
        for member in members:
            name = str(relative(member.name.rstrip('/')))
            if name in names:
                if member.isdir() and names[name]: continue
                raise ValueError('duplicate upstream source entry')
            if not (member.isfile() or member.isdir() or member.issym()):
                raise ValueError('unsupported upstream source entry')
            names[name] = member.isdir()
            if member.issym(): links.add(name)
            if member.mode & 0o7000: raise ValueError('privileged upstream source mode')
        for name in names:
            if any(str(parent) in links for parent in PurePosixPath(name).parents):
                raise ValueError('upstream source entry traverses a link')
        output.mkdir(parents=True)
        for member in members:
            path = output / member.name
            path.parent.mkdir(parents=True, exist_ok=True)
            if member.isdir(): path.mkdir(exist_ok=True)
            elif member.issym():
                # Buildroot contains target skeleton links to OS locations. They
                # are stored as inert entries; build commands never use skeletons
                # as their host source/build/output roots.
                path.symlink_to(member.linkname)
            else:
                with source.extractfile(member) as stream, path.open('xb') as target: shutil.copyfileobj(stream, target)
                path.chmod(member.mode & 0o777)


def overlay(source, manifest):
    if manifest['architecture'] == 'aarch64':
        architecture = source / 'arch/Config.in.arm'
        before = architecture.read_text()
        after, count = re.subn(r'default \"cortex-a53\"(\s+if BR2_cortex_a53)', r'default "generic"\1', before)
        if count != 1: raise ValueError('upstream generic ARM CPU context changed')
        architecture.write_text(after)
    item = manifest['glibc_source']
    path = source / 'package/glibc/glibc.mk'
    text = path.read_text()
    for name, value in {'VERSION': item['version'], 'SITE': item['site'], 'SITE_METHOD': 'wget'}.items():
        text, count = re.subn(r'^GLIBC_' + name + r' = .*$', 'GLIBC_' + name + ' = ' + value, text, flags=re.M)
        if count != 1: raise ValueError('upstream SDK overlay context changed')
    text = re.sub(r'^GLIBC_SOURCE = .*\n', '', text, flags=re.M)
    text, count = re.subn(r'^GLIBC_LICENSE = .*?\nGLIBC_LICENSE_FILES = .*?\n',
        'GLIBC_LICENSE = LGPL-2.1+, GPL-2.0+, BSD-3-Clause\nGLIBC_LICENSE_FILES = COPYING COPYING.LIB LICENSES\n', text, flags=re.M | re.S)
    if count != 1: raise ValueError('upstream license context changed')
    text = re.sub(r'^GLIBC_IGNORE_CVES.*\n', '', text, flags=re.M)
    marker = '$(eval $('
    if marker not in text: raise ValueError('upstream package evaluation context changed')
    text = text.replace(marker, 'GLIBC_SOURCE = ' + item['file'] + '\nGLIBC_EXTRA_CFLAGS += -std=gnu11\n' + marker, 1)
    path.write_text(text)
    (path.parent / 'glibc.hash').write_text('sha256  ' + item['sha256'] + '  ' + item['file'] + '\n' +
        ''.join('sha256  ' + value + '  ' + name + '\n' for name, value in item['licenses'].items()))


def host_check(recipe):
    target = read_json(recipe)['architecture']
    if target not in ('x86_64', 'aarch64'):
        raise ValueError('unsupported native SDK architecture')
    if platform.system() != 'Linux' or platform.machine() != target:
        raise ValueError('the source SDK recipe requires a native ' + target + ' Linux builder')
    info = dict(line.split('=', 1) for line in Path('/etc/os-release').read_text().splitlines() if '=' in line)
    if info.get('ID', '').strip('"') != 'debian' or info.get('VERSION_ID', '').strip('"') != '12':
        raise ValueError('production source SDK must be built on the declared Debian 12 host baseline')
    for name in ('make', 'gcc', 'g++', 'patch', 'tar', 'gzip', 'bzip2', 'xz', 'cpio', 'rsync', 'gawk', 'wget', 'python3'):
        if not shutil.which(name): raise ValueError('missing bootstrap tool: ' + name)
    return {'host': 'debian-12-' + target, 'status': 'passed'}


def prepare(recipe, cache, jobs, network):
    recipe, cache = Path(recipe).resolve(strict=True), Path(cache).absolute()
    manifest = read_json(recipe)
    if manifest['architecture'] not in ('x86_64', 'aarch64') or manifest['target'] != manifest['architecture'] + '-buildroot-linux-gnu':
        raise ValueError('unsupported native SDK target identity')
    identity = recipe_id(recipe)
    if any(not re.fullmatch(r'[A-Za-z0-9_./+-]+', str(path)) for path in (recipe, cache)):
        raise ValueError('upstream source preparation requires simple paths without spaces')
    bootstrap = cache / 'bootstrap' / manifest['buildroot']['file']
    fetch_file(manifest['buildroot'], bootstrap, network)
    fetch_file(manifest['glibc_source'], cache / 'downloads/glibc' / manifest['glibc_source']['file'], network)
    work = cache / 'work' / identity
    source = work / ('buildroot-' + manifest['buildroot']['version'])
    if not source.exists():
        work.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(dir=work) as temporary:
            extraction = Path(temporary) / 'source'
            unpack_source(bootstrap, extraction)
            candidate = extraction / source.name
            overlay(candidate, manifest)
            candidate.rename(source)
    output = work / 'output'
    command = ['make', '-C', str(source), 'O=' + str(output), 'BR2_DL_DIR=' + str(cache / 'downloads'), 'BR2_EXTERNAL=' + str(recipe.parent), 'BR2_JLEVEL=' + str(jobs)]
    if not network:
        command += ['BR2_' + name + '=/bin/false' for name in ('WGET', 'GIT', 'SVN', 'HG', 'CVS', 'BZR', 'SCP', 'SFTP')]
    else:
        command += ['BR2_WGET=wget --timeout=30 --tries=2 -nv']
    subprocess.run(command + ['BR2_DEFCONFIG=' + str(recipe.parent / 'config'), 'defconfig'], check=True)
    text = (output / '.config').read_text().splitlines()
    for required in ('BR2_GCC_VERSION_15_X=y', 'BR2_TOOLCHAIN_BUILDROOT_GLIBC=y', 'BR2_DOWNLOAD_FORCE_CHECK_HASHES=y', 'BR2_PACKAGE_HOST_CMAKE=y', 'BR2_' + manifest['architecture'] + '=y') + tuple(key + '=y' for key in manifest.get('required_packages', [])):
        if required not in text: raise ValueError('required source SDK configuration disappeared')
    return manifest, identity, command, output


def fetch(recipe, cache, jobs):
    manifest, identity, command, output = prepare(recipe, cache, jobs, True)
    subprocess.run(command + ['source'], check=True)
    resolution = subprocess.check_output(command + ['--no-print-directory', 'show-info'], text=True)
    packages = __import__('json').loads(resolution)
    files = {}
    for package in packages.values():
        for item in package.get('downloads', []):
            name = str(relative('downloads/' + package['dl_dir'] + '/' + item['source']))
            path = Path(cache) / name
            actual = path.resolve(strict=True)
            if Path(cache).resolve() not in actual.parents: raise ValueError('source download escapes cache')
            files[name] = digest(actual)
    bootstrap = 'bootstrap/' + manifest['buildroot']['file']
    files[bootstrap] = digest(Path(cache) / bootstrap)
    if len(files) < 2: raise ValueError('incomplete resolved source closure')
    write_json(Path(cache) / 'resolution.json', packages)
    write_json(Path(cache) / 'source-inputs.json', {'schema_version': 1, 'recipe_id': identity, 'files': files,
               'resolution_sha256': digest(Path(cache) / 'resolution.json')})
    return {'recipe_id': identity, 'input_count': len(files)}


def verify_inputs(recipe, cache):
    state = read_json(Path(cache) / 'source-inputs.json')
    if state.get('recipe_id') != recipe_id(recipe): raise ValueError('source cache belongs to another complete recipe')
    cache = Path(cache).resolve(strict=True)
    if state.get('schema_version') != 1 or not isinstance(state.get('files'), dict) or not state['files']:
        raise ValueError('missing complete offline source inventory')
    for name, value in state['files'].items():
        path = cache.joinpath(*relative(name).parts)
        if path.is_symlink() or not path.is_file() or cache not in path.resolve().parents or digest(path) != value:
            raise ValueError('missing or changed offline source input: ' + name)
    resolution = cache / 'resolution.json'
    if not resolution.is_file() or digest(resolution) != state.get('resolution_sha256'):
        raise ValueError('missing or changed retained dependency resolution')
    manifest = read_json(recipe)
    expected = {'bootstrap/' + manifest['buildroot']['file']}
    for package in read_json(resolution).values():
        for item in package.get('downloads', []):
            expected.add(str(relative('downloads/' + package['dl_dir'] + '/' + item['source'])))
    if set(state['files']) != expected or 'downloads/glibc/' + manifest['glibc_source']['file'] not in expected:
        raise ValueError('offline source inventory does not cover the complete resolved inputs')
    for item, name in ((manifest['buildroot'], 'bootstrap/' + manifest['buildroot']['file']),
                       (manifest['glibc_source'], 'downloads/glibc/' + manifest['glibc_source']['file'])):
        if state['files'].get(name) != item['sha256']:
            raise ValueError('offline source inventory differs from pinned bootstrap inputs')
    return state


def preserve_sources(recipe, cache, output):
    state = verify_inputs(recipe, cache)
    output = Path(output)
    if output.exists(): raise ValueError('source export destination must be new')
    (output / 'recipe').mkdir(parents=True)
    shutil.copyfile(recipe, output / 'recipe/recipe.json')
    for name in ('config', 'Config.in', 'external.desc', 'external.mk'):
        shutil.copyfile(Path(recipe).parent / name, output / 'recipe' / name)
    for name in TOOLS:
        (output / 'tools').mkdir(exist_ok=True)
        shutil.copyfile(Path(__file__).parent / name, output / 'tools' / name)
    for name in state['files']:
        target = output / 'cache' / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(Path(cache) / name, target)
    for name in ('source-inputs.json', 'resolution.json'):
        shutil.copyfile(Path(cache) / name, output / 'cache' / name)
    license_path = Path(__file__).resolve().parents[1] / 'LICENSE'
    if license_path.is_file(): shutil.copyfile(license_path, output / 'LICENSE')
    write_json(output / 'sources.json', {'schema_version': 1, 'recipe_id': state['recipe_id'], 'files': file_inventory(output)})
    return state['recipe_id']


def remove_host_compatibility_alias(host):
    """Omit Buildroot's exact historical host/usr -> . ancestor alias."""
    host = Path(host)
    if host.is_symlink() or not host.is_dir():
        raise ValueError('supplier host root must be an ordinary directory')
    alias = host / 'usr'
    if not alias.is_symlink():
        if alias.exists():
            raise ValueError("unexpected supplier host alias entry: usr (expected link '.')")
        return
    if os.readlink(alias) != '.' or alias.resolve(strict=True) != host.resolve(strict=True):
        raise ValueError("unexpected supplier host alias target: usr (expected '.')")
    # package/skeleton/skeleton.mk creates this build-time compatibility alias.
    # Tools now live directly in host; target sysroot/usr remains untouched.
    alias.unlink()


def remove_runtime_aliases(sysroot):
    """Omit exact target OS service links that have no meaning in a compiler SDK."""
    sysroot = Path(sysroot)
    expected = {'etc/mtab': '../proc/self/mounts', 'etc/resolv.conf': '../run/resolv.conf'}
    candidates = []
    for name, target in expected.items():
        path = sysroot / name
        if path.parent.is_symlink():
            raise ValueError('runtime alias parent must be an ordinary directory: ' + name)
        if not path.is_symlink():
            if path.exists():
                raise ValueError('unexpected runtime alias entry: ' + name)
            continue
        if os.readlink(path) != target:
            raise ValueError('unexpected runtime alias target: ' + name)
        candidates.append(path)
    # Validate both entries before removing either. Other dangling links still
    # fail the ordinary confined materialization check below.
    for path in candidates:
        path.unlink()


# Reviewed glibc install inventory: catgets, iconv, locale, posix, nss, nscd, elf and
# sysdeps/unix/sysv/linux Makefiles; iconvdata installs the gconv directory.
# These are target OS programs/modules, not host tools or linker inputs.
GLIBC_RUNTIME_SOURCE = '42458698e0f9956cf0a8529aa39c318b5130d15a20a40c87fa5cc0054ba19939'
GLIBC_TARGET_PROGRAMS = (
    'usr/bin/gencat', 'usr/bin/iconv', 'usr/bin/locale', 'usr/bin/localedef', 'usr/bin/getconf',
    'usr/bin/getent', 'usr/bin/makedb', 'usr/bin/pldd', 'usr/bin/sprof',
    'usr/sbin/iconvconfig', 'usr/sbin/nscd',
)
GLIBC_TARGET_DIRECTORIES = ('usr/lib/gconv', 'usr/lib64/gconv', 'usr/libexec/getconf')


def omit_target_runtime(root, sysroot_name, source_sha256):
    """Project a reviewed libc install into a compiler SDK after materialization."""
    if source_sha256 != GLIBC_RUNTIME_SOURCE:
        raise ValueError('target runtime omission needs a reviewed glibc source identity')
    root = Path(root).resolve(strict=True)
    sysroot = root.joinpath(*relative(sysroot_name).parts)
    if sysroot.is_symlink() or not sysroot.is_dir() or root not in sysroot.resolve().parents:
        raise ValueError('target runtime omission needs a contained ordinary sysroot')
    selected = []
    for name in GLIBC_TARGET_PROGRAMS + GLIBC_TARGET_DIRECTORIES:
        path = sysroot / name
        if any(parent.is_symlink() for parent in path.parents if parent != root and root in parent.parents):
            raise ValueError('target runtime omission parent must be an ordinary directory')
        if path.is_symlink():
            raise ValueError('target runtime omission requires materialized inputs')
        if not path.exists():
            continue
        directory = name in GLIBC_TARGET_DIRECTORIES
        if (directory and not path.is_dir()) or (not directory and not path.is_file()):
            raise ValueError('unexpected target runtime input type: ' + name)
        if directory:
            for child in path.rglob('*'):
                if child.is_symlink() or not (child.is_file() or child.is_dir()):
                    raise ValueError('target runtime directory contains an unsupported entry')
        selected.append(path)
    omitted = sorted(path.relative_to(root).as_posix() for path in selected)
    # Supplier relocation lists may name generated text inside an omitted tree.
    # Preserve every other entry and reject malformed paths before any removal.
    relocations = root / 'share/buildroot/sdk-relocs'
    if relocations.is_symlink() or not relocations.is_file():
        raise ValueError('target runtime omission requires its supplier relocation list')
    lines = relocations.read_text(encoding='utf-8').splitlines()
    normalized = []
    for name in lines:
        # Buildroot prepare-sdk emits './relative/path'. Accept that exact
        # prefix, validate the remainder, and preserve original retained text.
        item = name[2:] if name.startswith('./') else name
        if relative(item).as_posix() != item:
            raise ValueError('noncanonical supplier relocation entry')
        normalized.append(item)
    retained = [name for name, item in zip(lines, normalized)
                if not any(item == removed or item.startswith(removed + '/') for removed in omitted)]
    for path in selected:
        if path.is_dir(): shutil.rmtree(path)
        else: path.unlink()
    if retained != lines:
        relocations.write_text(''.join(name + '\n' for name in retained), encoding='utf-8')
    return {'source_sha256': source_sha256, 'paths': omitted}


def build(recipe, cache, destination, jobs):
    host_check(recipe)
    verify_inputs(recipe, cache)
    manifest, identity, command, output = prepare(recipe, cache, jobs, False)
    subprocess.run(command + ['sdk', 'legal-info'], check=True)
    verify_inputs(recipe, cache)
    destination = Path(destination).absolute()
    if destination.exists(): raise ValueError('SDK group destination must be new')
    destination.parent.mkdir(parents=True, exist_ok=True)
    with sdk_temporary_directory(dir=destination.parent, prefix='sdk-build-') as temporary:
        work = Path(temporary)
        supplier = output / 'host'
        remove_host_compatibility_alias(supplier)
        # Remove virtual filesystem aliases from the target sysroot. They are
        # runtime host services, never compiler inputs or application libraries.
        sysroot = supplier / manifest['target'] / 'sysroot'
        remove_runtime_aliases(sysroot)
        for name in ('dev', 'proc', 'sys', 'run', 'tmp', 'var'):
            path = sysroot / name
            if path.is_symlink(): path.unlink()
            elif path.is_dir(): shutil.rmtree(path)
        # Normalize SDK absolute aliases to their corresponding contained paths.
        for path in supplier.rglob('*'):
            if path.is_symlink() and os.readlink(path).startswith('/'):
                candidate = sysroot / os.readlink(path).lstrip('/')
                if candidate.exists():
                    path.unlink()
                    path.symlink_to(os.path.relpath(candidate, path.parent))
                else: raise ValueError('unresolved absolute SDK link: ' + str(path))
        tree = work / 'sdk'
        materialize(supplier, tree, path_policy='linux-case-sensitive-v1')
        omitted = omit_target_runtime(tree, manifest['target'] + '/sysroot', manifest['glibc_source']['sha256'])
        licenses = tree / 'share/sdk-licenses'
        shutil.copytree(output / 'legal-info', licenses, ignore=lambda directory, entries: set(entries) & {'sources', 'host-sources'})
        # Buildroot relocates selected generated text files on installation.
        sources = work / 'sources'
        preserve_sources(recipe, cache, sources)
        target = {'system': 'Linux', 'processor': manifest['architecture'], 'triple': manifest['target'],
                  'sysroot': manifest['target'] + '/sysroot', 'cxx_compiler': 'bin/' + manifest['target'] + '-g++',
                  'c_compiler': 'bin/' + manifest['target'] + '-gcc'}
        metadata = seal(tree, identity, target, digest(sources / 'sources.json'), licenses=['share/sdk-licenses'],
                        runtime_source_sha256=manifest['glibc_source']['sha256'], path_policy='linux-case-sensitive-v1',
                        host_tools={'cmake': 'bin/cmake', 'ctest': 'bin/ctest', 'cpack': 'bin/cpack', 'ninja': 'bin/ninja', 'python': 'bin/python3'})
        metadata['relocation'] = 'buildroot'
        metadata['omitted_target_runtime'] = omitted
        metadata['capabilities'] = manifest.get('capabilities', ['core', 'terminal', 'framebuffer', 'hosted-web'])
        metadata['runtime_host_services'] = manifest.get('runtime_host_services', [])
        write_json(tree / 'sdk.json', metadata)
        return export_group(tree, sources, destination, manifest['source_date_epoch'])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=('recipe-id', 'bootstrap', 'fetch', 'build', 'export-sources', 'verify-inputs'))
    parser.add_argument('--recipe', type=Path, default=Path(__file__).resolve().parents[1] / 'third_party/sdk/recipe.json')
    parser.add_argument('--cache', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--jobs', type=int, default=2)
    args = parser.parse_args()
    if args.jobs < 1: parser.error('jobs must be positive')
    if args.action == 'recipe-id': result = {'recipe_id': recipe_id(args.recipe)}
    elif args.action == 'bootstrap': result = {'distribution': 'Debian 12 Bookworm', 'packages': read_json(args.recipe)['bootstrap_packages'], 'install': 'apt-get install <listed packages>', 'check': host_check(args.recipe)}
    else:
        if not args.cache: parser.error('--cache is required')
        if args.action in ('build', 'export-sources') and not args.output: parser.error('--output is required')
        if args.action == 'fetch': result = fetch(args.recipe, args.cache.resolve(), args.jobs)
        elif args.action == 'build': result = build(args.recipe, args.cache.resolve(), args.output, args.jobs)
        elif args.action == 'export-sources': result = {'recipe_id': preserve_sources(args.recipe, args.cache.resolve(), args.output)}
        else: result = verify_inputs(args.recipe, args.cache.resolve())
    print(encoded(result).decode(), end='')


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, KeyError, subprocess.CalledProcessError) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Plan-first immutable GitHub delivery; remote mutation requires explicit execution.

Callers serialize publication and retain one reviewed input snapshot throughout
an operation. A failed mutation has an unknown remote outcome: reconcile exact
IDs and bytes before a new attempt. This helper never deletes or replaces assets.
"""
import argparse
import atexit
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
from email.utils import parsedate_to_datetime
import random
import re
import shutil
import subprocess
import sys
import tempfile
import threading
import time
from urllib.error import HTTPError, URLError
from urllib.parse import quote, urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

sys.dont_write_bytecode = True
TOOLS = str(Path(__file__).resolve().parent)
if TOOLS not in sys.path:
    sys.path.insert(0, TOOLS)
import dependency_archive as archive
import dependency_store as store
import rust_sdk
import release
import certify_release as certification
coverage = certification.coverage

NAME = re.compile(r'[A-Za-z0-9][A-Za-z0-9_.+-]{0,180}\Z')
OID = re.compile(r'(?:[0-9a-f]{40}|[0-9a-f]{64})\Z')
SHA = re.compile(r'[0-9a-f]{64}\Z')
# Dynamic adapters may load this file under several module names. Share one
# process-wide gate so nested four-worker pools still run at most four CLI
# requests at once; backoff and local hashing do not hold a request slot.
REQUEST_SLOTS = sys.__dict__.setdefault('_foundation_github_request_slots', threading.BoundedSemaphore(4))

class RequestMetrics:
    """Process totals only: no endpoints, credentials or response bodies retained."""
    def __init__(self):
        self.lock = threading.Lock()
        self.values = dict(cli_calls=0, api_responses=0, quota_probes=0,
                           cli_seconds=0., capacity_wait_seconds=0., retry_wait_seconds=0.,
                           downloaded_bytes=0, uploaded_bytes=0, public_downloads=0, public_download_seconds=0.)
        self.quota = None

    def add(self, **values):
        with self.lock:
            for key, value in values.items(): self.values[key] += value

    def observe(self, headers, *, quota_probe=False):
        with self.lock:
            self.values['quota_probes' if quota_probe else 'api_responses'] += 1
            numbers = {key: rate_integer(headers.get('x-ratelimit-' + key))
                       for key in ('limit', 'remaining', 'reset')}
            if (all(value is not None for value in numbers.values()) and
                    0 <= numbers['remaining'] <= numbers['limit']):
                # Responses can arrive out of order. Keep the lowest observed
                # allowance within the newest observed reset window.
                if (self.quota is None or numbers['reset'] > self.quota['reset'] or
                        numbers['reset'] == self.quota['reset'] and
                        numbers['remaining'] < self.quota['remaining']):
                    self.quota = numbers

    def snapshot(self):
        with self.lock:
            return dict(schema_version=1, **{k: round(v, 3) if isinstance(v, float) else v
                        for k, v in self.values.items()}, observed_quota=self.quota.copy() if self.quota else None)


REQUEST_METRICS = sys.__dict__.setdefault('_foundation_github_request_metrics', RequestMetrics())


def enable_metrics():
    """Opt-in sanitized per-process CI accounting, with no additional API calls."""
    if sys.__dict__.get('_foundation_github_metrics_reporter'): return
    sys.__dict__['_foundation_github_metrics_reporter'] = True
    def report():
        value = REQUEST_METRICS.snapshot()
        if value['cli_calls'] or value['public_downloads']:
            print('GitHub transport metrics: ' + json.dumps(value, sort_keys=True), file=sys.stderr, flush=True)
    atexit.register(report)


CERT = re.compile(r'certification-([A-Za-z0-9][A-Za-z0-9_.-]*)-attempt-([1-9][0-9]*)\.(json|tar.gz)\Z')


class DeliveryError(ValueError):
    def __init__(self, message, uncertain=False):
        super().__init__(message)
        self.uncertain = uncertain


def valid_name(value):
    if not isinstance(value, str) or not NAME.fullmatch(value) or value.endswith('.') or '..' in value:
        raise DeliveryError('expected one safe nonempty asset or tag name')
    stem = value.split('.', 1)[0].upper()
    if stem in {'CON', 'PRN', 'AUX', 'NUL'} or re.fullmatch(r'(?:COM|LPT)[1-9]', stem):
        raise DeliveryError('asset or tag name is reserved on a supported platform')
    return value


def location(repository, tag=None):
    if not isinstance(repository, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*', repository):
        raise DeliveryError('repository must be OWNER/REPO')
    for part in repository.split('/'):
        valid_name(part)
    if tag is not None:
        valid_name(tag)
    return repository


def sha(value):
    return hashlib.sha256(value).hexdigest()


def parse(raw):
    if isinstance(raw, bytes):
        raw = raw.decode('utf-8')
    if len(raw) > 16 * 1024 * 1024:
        raise DeliveryError('remote JSON exceeds supported inventory limit')
    return json.loads(raw, object_pairs_hook=coverage.object_pairs,
                      parse_constant=lambda _: (_ for _ in ()).throw(DeliveryError('nonfinite remote JSON')))


def positive(value):
    return type(value) is int and value > 0


HTTP_HEADER_LIMIT = 64 * 1024
HTTP_JSON_LIMIT = 16 * 1024 * 1024
RATE_HEADERS = {'retry-after', 'x-ratelimit-limit', 'x-ratelimit-remaining', 'x-ratelimit-reset', 'x-ratelimit-resource'}


def response_head(stream):
    """Read one bounded gh --include header; never normalize binary body bytes."""
    lines, size = [], 0
    while True:
        line = stream.readline(HTTP_HEADER_LIMIT + 1 - size)
        size += len(line)
        if not line or size > HTTP_HEADER_LIMIT:
            raise DeliveryError('missing or oversized GitHub response headers')
        if line in (b'\n', b'\r\n'):
            break
        lines.append(line.rstrip(b'\r\n'))
    status = re.fullmatch(rb'HTTP/\S+ ([0-9]{3})(?: [^\r\n]*)?', lines[0] if lines else b'')
    if not status:
        raise DeliveryError('invalid GitHub HTTP status')
    headers = {}
    for line in lines[1:]:
        key, separator, value = line.partition(b':')
        if not separator or not re.fullmatch(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+", key):
            raise DeliveryError('invalid GitHub response header')
        key = key.decode('ascii').lower()
        if key in RATE_HEADERS:
            if key in headers:
                raise DeliveryError('ambiguous GitHub rate-limit headers')
            try:headers[key] = value.decode('ascii').strip()
            except UnicodeError:raise DeliveryError('invalid GitHub rate-limit header') from None
    return int(status[1]), headers


def rate_integer(value):
    return int(value) if isinstance(value, str) and re.fullmatch(r'[0-9]{1,12}', value) else None


def rate_diagnostic(status, headers):
    # Only parsed status and bounded numeric quota fields may reach public logs.
    fields = ['HTTP ' + str(status)]
    for name in ('x-ratelimit-limit', 'x-ratelimit-remaining', 'x-ratelimit-reset'):
        number = rate_integer(headers.get(name))
        if number is not None:fields.append(name.removeprefix('x-ratelimit-') + '=' + str(number))
    return '; '.join(fields)


class HTTPFailure(DeliveryError):
    def __init__(self, status, headers, payload=b''):
        super().__init__('GitHub API request failed (' + rate_diagnostic(status, headers) + ')')
        self.status, self.headers, self.rate_message = status, headers, False
        # Some secondary 403 responses omit Retry-After. Recognize only GitHub's
        # explicit rate-limit messages, never arbitrary forbidden/error text.
        if status in (403, 429) and len(payload) <= 4096:
            try:
                value = parse(payload)
                message = value.get('message') if isinstance(value, dict) else None
                self.rate_message = isinstance(message, str) and (
                    message.startswith('API rate limit exceeded for ')
                    or message == 'API rate limit exceeded.'
                    or message.startswith('You have exceeded a secondary rate limit.')
                    or message.startswith('You have triggered an abuse detection mechanism.'))
            except (UnicodeError, ValueError):pass


class PublicReleaseRedirects(HTTPRedirectHandler):
    """Public bytes never carry credentials, including across CDN redirects."""
    max_redirections = 5
    max_repeats = 2

    def __init__(self, initial):
        self.initial = initial

    def validate(self, url):
        parsed = urlsplit(url)
        if (parsed.scheme != 'https' or parsed.netloc not in
                ('github.com', 'release-assets.githubusercontent.com', 'objects.githubusercontent.com') or
                parsed.fragment or not parsed.path.startswith('/') or
                parsed.netloc == 'github.com' and url != self.initial):
            raise DeliveryError('public asset redirect escaped the selected HTTPS release')
        return url

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self.validate(newurl)
        # Reconstruct instead of inheriting a caller's authentication headers.
        return Request(newurl, headers={'User-Agent': 'software-foundation-release/1'})


def workflow_context_matches(context):
    """An explicit caller snapshot must belong to this exact executing workflow."""
    if not isinstance(context, dict) or set(context) != {'repository','run_id','attempt','source_commit','workflow'}:
        return False
    return (os.environ.get('GITHUB_ACTIONS') == 'true' and
            os.environ.get('GITHUB_REPOSITORY') == context['repository'] and
            positive(context['run_id']) and positive(context['attempt']) and
            os.environ.get('GITHUB_RUN_ID') == str(context['run_id']) and
            os.environ.get('GITHUB_RUN_ATTEMPT') == str(context['attempt']) and
            os.environ.get('GITHUB_SHA') == context['source_commit'] and
            isinstance(context['source_commit'],str) and OID.fullmatch(context['source_commit']) is not None and
            isinstance(context['workflow'],str) and re.fullmatch(r'[a-zA-Z0-9_-]+\.yml',context['workflow']) is not None and
            os.environ.get('GITHUB_WORKFLOW_REF','').startswith(
                context['repository']+'/.github/workflows/'+context['workflow']+'@'))


class GitHub:
    """Bounded read retries; writes are never replayed after an ambiguous result."""
    WAIT_BUDGET = 180 * 60
    REQUEST_DEADLINE = 180 * 60
    COMMAND_TIMEOUT = 10 * 60
    MAX_ATTEMPTS = 8
    WRITE_HEADROOM = 128
    QUOTA_MAX_AGE = 30
    TRANSIENT_STATUS = frozenset((500, 502, 503, 504))

    def __init__(self, repository, *, metrics=None):
        self.metrics = metrics if metrics is not None else REQUEST_METRICS
        self.repository = location(repository)
        self.wait_remaining = float(self.WAIT_BUDGET)
        self._budget_lock = threading.Lock()
        self._quota_lock = threading.Lock()
        self._quota_probe_lock = threading.Lock()
        self._quota = None

    def _run(self, arguments, *, body=None, output=None, timeout=None):
        budget = self.COMMAND_TIMEOUT if timeout is None else timeout
        started = time.monotonic()
        if not REQUEST_SLOTS.acquire(timeout=budget):
            raise DeliveryError('GitHub request capacity wait exceeded its bounded deadline')
        call_started = None
        try:
            acquired = time.monotonic()
            self.metrics.add(capacity_wait_seconds=acquired - started)
            remaining = budget - (acquired - started)
            if remaining <= 0: raise DeliveryError('GitHub CLI request exceeded its bounded deadline')
            call_started = time.monotonic()
            self.metrics.add(cli_calls=1)
            return subprocess.run(['gh', *arguments], input=body,
                stdout=output if output is not None else subprocess.PIPE,
                stderr=subprocess.PIPE, check=False, timeout=remaining)
        except subprocess.TimeoutExpired:
            raise DeliveryError('GitHub CLI request exceeded its bounded deadline') from None
        except OSError:
            raise DeliveryError('GitHub CLI request could not complete') from None
        finally:
            if call_started is not None:
                self.metrics.add(cli_seconds=time.monotonic() - call_started)
            REQUEST_SLOTS.release()

    def _timeout(self, deadline):
        remaining = deadline - time.monotonic()
        if remaining <= 0:raise DeliveryError('GitHub request deadline exhausted')
        return min(self.COMMAND_TIMEOUT, remaining)

    def _wait(self, delay, diagnostic, deadline):
        delay += random.uniform(1, 5)
        if delay >= deadline - time.monotonic():
            raise DeliveryError('GitHub request deadline exhausted (' + diagnostic + ')')
        with self._budget_lock:
            if delay > self.wait_remaining:
                raise DeliveryError('GitHub read-retry wait budget exhausted (' + diagnostic + ')')
            self.wait_remaining -= delay
            remaining_budget = self.wait_remaining
        print(f'GitHub read retry ({diagnostic}); waiting {delay:.1f}s; '
              f'wait budget remaining {remaining_budget:.1f}s', file=sys.stderr, flush=True)
        remaining = delay; started = time.monotonic()
        try:
            while remaining > 0:
                self._timeout(deadline)
                step = min(60, remaining)
                time.sleep(step)  # Interrupts/cancellation propagate; no detached sleeper.
                remaining -= step
        finally:
            self.metrics.add(retry_wait_seconds=time.monotonic() - started)

    def _retry_delay(self, failure, attempt):
        if failure.status not in (403, 429) and failure.status not in self.TRANSIENT_STATUS:return None
        headers = failure.headers
        delays = []
        retry = headers.get('retry-after')
        seconds = rate_integer(retry)
        if seconds is not None:
            delays.append(seconds)
        elif isinstance(retry, str) and len(retry) <= 100:
            try:
                date = parsedate_to_datetime(retry)
                if date.tzinfo is not None:delays.append(max(0, date.timestamp() - time.time()))
            except (ValueError, TypeError, OverflowError):pass
        reset = rate_integer(headers.get('x-ratelimit-reset'))
        if rate_integer(headers.get('x-ratelimit-remaining')) == 0 and reset is not None:
            delays.append(max(1, reset - time.time()))
        if delays:return max(delays)
        if failure.status == 429 or failure.rate_message:
            return min(60 * 2 ** (attempt - 1), 15 * 60)
        if failure.status in self.TRANSIENT_STATUS:
            return min(2 * 2 ** (attempt - 1), 60)
        return None

    def _wait_after_failure(self, error, attempt, deadline):
        delay = self._retry_delay(error, attempt)
        if delay is None:raise error
        if attempt == self.MAX_ATTEMPTS:
            raise DeliveryError('GitHub read-retry attempt limit exhausted (' +
                                rate_diagnostic(error.status, error.headers) + ')') from None
        self._wait(delay, rate_diagnostic(error.status, error.headers), deadline)

    def _read(self, operation, *, deadline=None):
        deadline = deadline if deadline is not None else time.monotonic() + self.REQUEST_DEADLINE
        for attempt in range(1, self.MAX_ATTEMPTS + 1):
            self._timeout(deadline)
            try:return operation(deadline)
            except HTTPFailure as error:self._wait_after_failure(error, attempt, deadline)

    def _json_once(self, endpoint, method, body, missing, deadline):
        arguments = ['api', '--hostname', 'github.com', '--include', '--method', method, endpoint]
        if body is not None:arguments += ['--input', '-']
        result = self._run(arguments, body=body, timeout=self._timeout(deadline))
        if len(result.stdout) > HTTP_JSON_LIMIT:
            raise DeliveryError('remote JSON exceeds supported inventory limit')
        stream = io.BytesIO(result.stdout)
        status, headers = response_head(stream);payload = stream.read()
        self._observe(headers, quota_probe=endpoint == 'rate_limit')
        if missing and status == 404 and result.returncode:return None
        if not 200 <= status < 300:raise HTTPFailure(status, headers, payload)
        if result.returncode:raise DeliveryError('GitHub API response was incomplete')
        if status == 204:
            if payload: raise DeliveryError('HTTP 204 response must have an empty body')
            return None
        try:return parse(payload)
        except (UnicodeError, ValueError):raise DeliveryError('invalid complete GitHub JSON response') from None

    def _remember_core(self, numbers):
        # Per-client observations only, never a reservation against other jobs.
        # Out-of-order responses cannot replenish locally admitted writes.
        with self._quota_lock:
            before = self._quota
            if before is not None and numbers['reset'] < before['reset']:
                return
            remaining = numbers['remaining']
            if before is not None and numbers['reset'] == before['reset']:
                remaining = min(remaining, before['remaining'])
            self._quota = dict(numbers, remaining=remaining, observed=time.monotonic())

    def _observe(self, headers, *, quota_probe=False):
        self.metrics.observe(headers, quota_probe=quota_probe)
        if headers.get('x-ratelimit-resource') != 'core':
            return
        numbers = {key: rate_integer(headers.get('x-ratelimit-' + key))
                   for key in ('limit', 'remaining', 'reset')}
        if (positive(numbers['limit']) and positive(numbers['reset']) and
                numbers['remaining'] is not None and 0 <= numbers['remaining'] <= numbers['limit']):
            self._remember_core(numbers)

    def _reserve_headroom(self):
        with self._quota_lock:
            quota = self._quota
            if (quota is None or not 0 <= time.monotonic() - quota['observed'] < self.QUOTA_MAX_AGE or
                    quota['reset'] <= time.time() or
                    quota['remaining'] < min(self.WRITE_HEADROOM, quota['limit'])):
                return False
            quota['remaining'] -= 1
            return True

    def _headroom(self):
        if self.WRITE_HEADROOM <= 0 or self._reserve_headroom():
            return
        # One fallback probe can serve waiting upload workers as well. Network
        # and backoff never hold the observation lock used by response handlers.
        deadline = time.monotonic() + self.REQUEST_DEADLINE
        if not self._quota_probe_lock.acquire(timeout=self.REQUEST_DEADLINE):
            raise DeliveryError('GitHub quota observation wait exceeded request deadline')
        try:
            self._timeout(deadline)
            if self._reserve_headroom():
                return
            self._probe_headroom(deadline)
        finally:
            self._quota_probe_lock.release()

    def _probe_headroom(self, deadline):
        """Fallback only when fresh response headers cannot admit this write."""
        for attempt in range(1, self.MAX_ATTEMPTS + 1):
            try:value = self._json_once('rate_limit', 'GET', None, False, deadline)
            except HTTPFailure as error:
                self._wait_after_failure(error, attempt, deadline)
                continue
            resources = value.get('resources', {}) if isinstance(value, dict) else {}
            core = resources.get('core', {}) if isinstance(resources, dict) else {}
            if (not isinstance(core, dict) or not positive(core.get('limit'))
                    or type(core.get('remaining')) is not int or not 0 <= core['remaining'] <= core['limit']
                    or not positive(core.get('reset'))):
                raise DeliveryError('GitHub primary quota preflight returned invalid core limits')
            self._remember_core({key: core[key] for key in ('limit', 'remaining', 'reset')})
            if self._reserve_headroom():return
            if core['remaining'] >= min(self.WRITE_HEADROOM, core['limit']) and core['reset'] > time.time():
                # Local reservations are deliberately conservative. A fresh
                # successful probe still admits this write just as before;
                # do not wait an hour only because cached estimates were lower.
                # Keep the cache conservative for other concurrent admissions.
                with self._quota_lock:
                    self._quota['remaining'] = max(0, self._quota['remaining'] - 1)
                return
            diagnostic = rate_diagnostic(200, {'x-ratelimit-' + k:str(core[k]) for k in ('limit','remaining','reset')})
            if attempt == self.MAX_ATTEMPTS:
                raise DeliveryError('GitHub quota preflight attempt limit exhausted (' + diagnostic + ')')
            self._wait(max(1, core['reset'] - time.time()), diagnostic, deadline)

    def json(self, endpoint, *, method='GET', body=None, missing=False):
        encoded = archive.encoded(body) if body is not None else None
        if method == 'GET':
            return self._read(lambda end: self._json_once(endpoint, method, encoded, missing, end))
        if self.WRITE_HEADROOM > 0: self._headroom()
        try:return self._json_once(endpoint, method, encoded, missing, time.monotonic() + self.REQUEST_DEADLINE)
        except DeliveryError as error:
            raise DeliveryError(str(error) + '; remote outcome requires reconciliation', True) from None

    def pages(self, endpoint):
        # gh2.23 (bookworm) supports --include/--paginate, but not --slurp.
        # Each attempt restarts the complete inventory; no prefix survives a retry.
        def attempt(deadline):
            result = self._run(['api', '--hostname', 'github.com', '--include', '--paginate',
                                '--method', 'GET', endpoint], timeout=self._timeout(deadline))
            raw = result.stdout
            if len(raw) > HTTP_JSON_LIMIT:
                raise DeliveryError('remote pagination exceeds supported inventory limit')
            stream = io.BytesIO(raw)
            decoder = json.JSONDecoder(object_pairs_hook=coverage.object_pairs,
                parse_constant=lambda _: (_ for _ in ()).throw(DeliveryError('nonfinite remote JSON')))
            pages = []
            try:
                while stream.tell() < len(raw):
                    # gh inserts a newline between included page responses.
                    while stream.tell() < len(raw) and raw[stream.tell()] in b' \r\n\t':stream.seek(1, 1)
                    if stream.tell() == len(raw):break
                    status, headers = response_head(stream)
                    self._observe(headers)
                    if not 200 <= status < 300:raise HTTPFailure(status, headers, stream.read(4097))
                    # A later error body is opaque, even if it is not UTF-8.
                    # Strictly re-encode only this successful JSON page below.
                    offset = stream.tell();tail = raw[offset:].decode('utf-8', errors='surrogateescape')
                    leading = len(tail) - len(tail.lstrip())
                    page, end = decoder.raw_decode(tail, leading)
                    if not isinstance(page, list):raise DeliveryError('expected every page of a remote array')
                    pages.append(page);stream.seek(offset + len(tail[:end].encode('utf-8')))
                if result.returncode or not pages:raise DeliveryError('incomplete remote page inventory')
            except HTTPFailure:raise
            except (UnicodeError, ValueError):
                raise DeliveryError('complete remote pagination failed; invalid or incomplete response stream') from None
            return [item for page in pages for item in page]
        return self._read(attempt)

    def upload(self, tag, path):
        self._headroom()
        try:
            result = self._run(['release', 'upload', tag, '--repo', 'github.com/' + self.repository, str(path)])
        except DeliveryError as error:
            raise DeliveryError(str(error) + '; remote outcome requires reconciliation', True) from None
        if result.returncode:
            raise DeliveryError('asset upload failed; remote outcome requires reconciliation', True)

    def upload_to(self, release_id, path):
        """Upload once to a known immutable release ID, with no tag lookup."""
        from urllib.parse import quote
        if not positive(release_id): raise DeliveryError('positive upload release ID required')
        path = Path(path).absolute(); name = valid_name(path.name)
        if path.is_symlink() or not path.is_file(): raise DeliveryError('upload requires an ordinary payload file')
        before = path.stat(); expected = archive.digest(path)
        self._headroom()
        endpoint = f'https://uploads.github.com/repos/{self.repository}/releases/{release_id}/assets?name=' + quote(name, safe='')
        try:
            result = self._run(['api', '--hostname', 'github.com', '--include', '--method', 'POST', endpoint,
                '--input', str(path), '-H', 'Content-Type: application/octet-stream',
                '-H', 'Content-Length: ' + str(before.st_size), '-H', 'Accept: application/vnd.github+json'])
            response = io.BytesIO(result.stdout); status, headers = response_head(response)
            self._observe(headers)
            if result.returncode or status != 201:
                raise DeliveryError('asset upload failed; remote outcome requires reconciliation', True)
            body = response.read(HTTP_JSON_LIMIT + 1)
            if len(body) > HTTP_JSON_LIMIT: raise DeliveryError('upload response exceeds inventory limit', True)
            row = parse(body); after = path.stat()
            if (not isinstance(row, dict) or not positive(row.get('id')) or row.get('name') != name or
                    row.get('state') != 'uploaded' or row.get('size') != before.st_size or
                    row.get('digest') != 'sha256:' + expected or archive.digest(path) != expected or
                    (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) !=
                    (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)):
                raise DeliveryError('uploaded asset or local payload identity differs', True)
            self.metrics.add(uploaded_bytes=before.st_size)
        except (DeliveryError, OSError, ValueError) as error:
            raise DeliveryError('asset upload could not be confirmed; remote outcome requires reconciliation', True) from error

    def download(self, asset_id, path):
        path = Path(path)
        if path.exists() or path.is_symlink():raise DeliveryError('asset download destination must be new')
        def attempt(deadline):
            # Each failed attempt closes and removes its complete private response
            # before any wait. Header bytes and partial payloads never reach path.
            with tempfile.TemporaryDirectory(prefix='.github-download-', dir=path.parent) as temporary:
                raw = Path(temporary) / 'response'
                with raw.open('xb') as stream:
                    result = self._run(['api', '--hostname', 'github.com', '--include', '--method', 'GET',
                        f'repos/{self.repository}/releases/assets/{asset_id}',
                        '-H', 'Accept:application/octet-stream'], output=stream, timeout=self._timeout(deadline))
                with raw.open('rb') as stream:
                    status, headers = response_head(stream)
                    self._observe(headers)
                    if not 200 <= status < 300:raise HTTPFailure(status, headers, stream.read(4097))
                    if result.returncode or status != 200:
                        raise DeliveryError('asset download failed; incomplete response must not be reused')
                    with path.open('xb') as destination:shutil.copyfileobj(stream, destination)
                    self.metrics.add(downloaded_bytes=path.stat().st_size)
        return self._read(attempt)

    def download_public(self, url, path, size, digest):
        """Fetch hash-pinned public bytes without an authenticated REST request."""
        parsed = urlsplit(url)
        prefix = '/' + self.repository + '/releases/download/'
        if (parsed.scheme != 'https' or parsed.netloc != 'github.com' or parsed.query or parsed.fragment or
                not parsed.path.startswith(prefix) or len(parsed.path[len(prefix):].split('/')) != 2 or
                type(size) is not int or not 0 <= size < 2*1024**3 or not isinstance(digest,str) or not SHA.fullmatch(digest)):
            raise DeliveryError('public download requires an exact release URL, size and digest')
        path = Path(path)
        if path.exists() or path.is_symlink(): raise DeliveryError('asset download destination must be new')
        deadline = time.monotonic() + 10*60
        def attempt(end):
            started = time.monotonic()
            if not REQUEST_SLOTS.acquire(timeout=self._timeout(end)):
                raise DeliveryError('public download capacity deadline exhausted')
            acquired = time.monotonic(); self.metrics.add(capacity_wait_seconds=acquired-started, public_downloads=1)
            try:
                redirects = PublicReleaseRedirects(url)
                request = Request(redirects.validate(url), headers={'User-Agent':'software-foundation-release/1'})
                with tempfile.TemporaryDirectory(prefix='.github-public-',dir=path.parent) as temporary:
                    staged = Path(temporary)/'payload'; total=0; hashed=hashlib.sha256()
                    try:
                        with build_opener(redirects).open(request,timeout=min(60,self._timeout(end))) as response, staged.open('xb') as output:
                            redirects.validate(response.url)
                            if response.status != 200: raise DeliveryError('public asset response was incomplete')
                            while True:
                                self._timeout(end)
                                data=response.read1(min(1024*1024,size-total+1))
                                self._timeout(end)
                                if not data: break
                                total+=len(data)
                                if total>size: raise DeliveryError('public asset exceeds declared size')
                                hashed.update(data);output.write(data)
                    except HTTPError as error:
                        with error:
                            headers={key:error.headers.get(key) for key in RATE_HEADERS if error.headers.get(key) is not None}
                            raise HTTPFailure(error.code,headers,b'') from None
                    except (OSError,URLError):
                        raise DeliveryError('public asset transfer failed; incomplete bytes discarded') from None
                    if total!=size or hashed.hexdigest()!=digest:
                        raise DeliveryError('public asset bytes differ from complete inventory')
                    with staged.open('rb') as incoming,path.open('xb') as output: shutil.copyfileobj(incoming,output)
                    self.metrics.add(downloaded_bytes=total)
            finally:
                self.metrics.add(public_download_seconds=time.monotonic()-acquired)
                REQUEST_SLOTS.release()
        return self._read(attempt,deadline=deadline)


class Remote:
    def __init__(self, repository, transport=None):
        self.repository = location(repository)
        self.transport = transport or GitHub(repository)
        self.base = f'repos/{repository}'
        self.mutated = False
        self.private = None
        self._public_assets = {}

    def visible(self):
        value = self.transport.json(self.base)
        if (not isinstance(value, dict) or not isinstance(value.get('full_name'), str)
                or value['full_name'].casefold() != self.repository.casefold() or type(value.get('private')) is not bool):
            raise DeliveryError('repository visibility or identity is unconfirmed')
        self.private = value['private']
        return self.private

    def published(self, tag, required=True):
        """Use GitHub's exact published-tag endpoint, independent of release history."""
        valid_name(tag)
        value = self.transport.json(self.base + '/releases/tags/' + quote(tag,safe=''), missing=True)
        if value is None:
            if required: raise DeliveryError('required published release is absent; no implicit fallback')
            return None
        self.info(value,tag)
        if value['draft']: raise DeliveryError('published release endpoint returned a draft')
        return value

    def by_id(self, identity, tag):
        if not positive(identity): raise DeliveryError('positive release identity required')
        value = self.info(self.transport.json(self.base + '/releases/' + str(identity)),tag)
        if value['id'] != identity: raise DeliveryError('release identity changed during operation')
        return value

    def pin_published(self, info, assets, private):
        """Bind local immutable download inputs from an authenticated snapshot."""
        self.info(info,info.get('tag_name'))
        if info['draft'] or type(private) is not bool: raise DeliveryError('published repository visibility is required')
        self.private = private
        if not private:
            for name,row in assets.items():
                valid_name(name)
                if not positive(row.get('id')) or row.get('name') != name:
                    raise DeliveryError('public asset identity differs')
                url='https://github.com/'+self.repository+'/releases/download/'+quote(info['tag_name'],safe='')+'/'+quote(name,safe='')
                self._public_assets[row['id']] = url

    def find(self, tag, required=True):
        rows = self.transport.pages(self.base + '/releases?per_page=100')
        seen = set()
        matches = []
        for row in rows:
            if not isinstance(row, dict) or not positive(row.get('id')) or row['id'] in seen:
                raise DeliveryError('invalid or duplicate release inventory entry')
            seen.add(row['id'])
            if not isinstance(row.get('tag_name'), str):
                raise DeliveryError('incomplete release inventory')
            if row['tag_name'] == tag:
                self.info(row, tag)
                matches.append(row)
        if len(matches) > 1:
            raise DeliveryError('duplicate release tags require inspection')
        if not matches:
            if required:
                raise DeliveryError('required release is absent; no implicit build or publication')
            return None
        return matches[0]

    def wait_find(self, tag, *, release_id=None):
        """Bounded observation after initialization; never repeat a mutation."""
        if release_id is not None and not positive(release_id):
            raise DeliveryError('positive release identity required')
        for delay in (0, .25, .5, 1, 2, 4, 8):
            if delay: time.sleep(delay)
            if release_id is None:
                found = self.find(tag, required=False)
            else:
                # A confirmed creation response already identifies the resource.
                # Unrelated draft inserts must not shift its observation pages.
                found = self.transport.json(self.base + '/releases/' + str(release_id), missing=True)
                if found is not None:
                    self.info(found, tag)
                    if found['id'] != release_id:
                        raise DeliveryError('observed release ID differs from creation response')
            if found is not None:
                return found
        raise DeliveryError('release is not visible; preserve initialization state and reconcile')

    @staticmethod
    def info(value, tag):
        if (not isinstance(value, dict) or not positive(value.get('id')) or value.get('tag_name') != tag
                or type(value.get('draft')) is not bool or type(value.get('prerelease')) is not bool
                or not isinstance(value.get('name'), str)):
            raise DeliveryError('invalid release identity or lifecycle fields')
        return value

    def assets(self, info):
        rows = self.transport.pages(self.base + f'/releases/{info["id"]}/assets?per_page=100')
        assets, ids, folded = {}, set(), set()
        for row in rows:
            if not isinstance(row, dict):
                raise DeliveryError('invalid asset entry')
            name = valid_name(row.get('name'))
            if (name.casefold() in folded or not positive(row.get('id')) or row['id'] in ids
                    or row.get('state') != 'uploaded' or type(row.get('size')) is not int or row['size'] < 0
                    or not isinstance(row.get('digest'), str) or not re.fullmatch(r'sha256:[0-9a-f]{64}', row['digest'])):
                raise DeliveryError('duplicate, incomplete or unbound asset inventory')
            assets[name] = {key: row[key] for key in ('id', 'name', 'state', 'size', 'digest')}
            ids.add(row['id']); folded.add(name.casefold())
        if self.private is not None and info['draft'] is False: self.pin_published(info,assets,self.private)
        return assets

    def reference(self, tag, missing=False):
        value = self.transport.json(self.base + '/git/ref/tags/' + tag, missing=missing)
        if value is None:
            return None
        obj = value.get('object', {}) if isinstance(value, dict) else {}
        if (not isinstance(obj, dict) or obj.get('type') != 'commit'
                or not isinstance(obj.get('sha'), str) or not OID.fullmatch(obj['sha'])):
            raise DeliveryError('tag must directly identify the frozen commit')
        return obj['sha']

    def change(self, endpoint, *, method='POST', body=None):
        self.mutated = True
        return self.transport.json(self.base + endpoint, method=method, body=body)

    def upload(self, tag, path):
        self.mutated = True
        self.transport.upload(tag, path)

    def upload_to(self, info, path):
        # Callers retain this validated release snapshot through their final
        # complete asset reconciliation; no response-loss mutation is replayed.
        self.info(info, info.get('tag_name'))
        self.mutated = True
        if hasattr(self.transport, 'upload_to'):
            return self.transport.upload_to(info['id'], path)
        return self.transport.upload(info['tag_name'], path)

    def download(self, row, path, expected=None):
        expected = expected or row['digest'][7:]
        if row['digest'] != 'sha256:' + expected:
            raise DeliveryError('remote asset differs from expected bytes')
        public_url = self._public_assets.get(row['id'])
        if self.private is False and public_url is not None and hasattr(self.transport,'download_public'):
            self.transport.download_public(public_url,path,row['size'],expected)
        else:
            self.transport.download(row['id'], path)
        if Path(path).stat().st_size != row['size'] or archive.digest(path) != expected:
            raise DeliveryError('downloaded asset bytes differ from complete inventory')

    def unchanged(self, tag, before, assets, expected_ref=None):
        after = self.by_id(before['id'],tag) if before['draft'] is False else self.find(tag)
        for key in ('id', 'tag_name', 'name', 'draft', 'prerelease'):
            if after[key] != before[key]:
                raise DeliveryError('release identity or lifecycle changed during operation')
        if self.assets(after) != assets:
            raise DeliveryError('remote asset identities changed during operation')
        if expected_ref is not None and self.reference(tag) != expected_ref:
            raise DeliveryError('tag identity changed during operation')

    def not_latest(self, info):
        value = self.transport.json(self.base + '/releases/latest', missing=True)
        if value is not None:
            self.info(value, value.get('tag_name'))
            if value['id'] == info['id']:
                raise DeliveryError('candidate or base was unexpectedly selected as Latest')


def plan(operation, repository, **details):
    value = dict(operation=operation, repository=location(repository), execute=False, **details)
    value['plan_sha256'] = coverage.digest(value)
    return value


def run_mutation(remote, action):
    try:
        return action()
    except BaseException as error:
        if remote.mutated:
            raise DeliveryError('remote outcome uncertain; reconcile tag, release ID, inventory and bytes before retry: '
                                + str(error), True) from error
        raise


def candidate_identity(directory, repository, tag, source_commit, packager_commit, publication_id, experiment=False):
    location(repository, tag)
    if tag == 'base' or not OID.fullmatch(source_commit) or not OID.fullmatch(packager_commit):
        raise DeliveryError('candidate needs a distinct tag and complete source/packager commits')
    valid_name(publication_id)
    if type(experiment) is not bool or (not experiment and source_commit != packager_commit):
        raise DeliveryError('different packaging revision requires an experiment')
    directory = Path(directory)
    manifest = release.verify_release(directory)
    mapping, seen = {}, {'delivery.json'}
    for name in sorted([*manifest['files'], 'release.json']):
        path = archive.checked_file(directory, name)
        asset = valid_name(path.name)
        if asset.casefold() in seen or CERT.fullmatch(asset):
            raise DeliveryError('flattened asset names collide with another asset or evidence namespace')
        seen.add(asset.casefold())
        mapping[name] = {'asset': asset, 'sha256': archive.digest(path), 'size': path.stat().st_size}
        if name != 'release.json' and mapping[name]['sha256'] != manifest['files'][name]:
            raise DeliveryError('local release changed while freezing delivery identity')
    archive.verify_inventory(directory, manifest['files'], exclude=('release.json',))
    if (coverage.load(directory / 'release.json') != manifest or
            archive.digest(directory / 'release.json') != mapping['release.json']['sha256']):
        raise DeliveryError('local release changed while freezing delivery identity')
    return {'schema_version': 1, 'repository': repository, 'tag': tag, 'source_commit': source_commit,
            'packager_commit': packager_commit, 'tag_commit': packager_commit,
            'publication_id': publication_id, 'experiment': experiment,
            'source_sha256': manifest['source']['sha256'], 'inventory_sha256': archive.digest(directory / 'release.json'),
            'files': mapping}


def validate_delivery(delivery, directory, *, metadata_only=False):
    if not isinstance(delivery, dict):
        raise DeliveryError('delivery identity must be an object')
    if metadata_only:
        metadata = release.verify_metadata(directory)
        coverage.fields(delivery, {'schema_version', 'repository', 'tag', 'source_commit', 'packager_commit', 'tag_commit',
            'publication_id', 'experiment', 'source_sha256', 'inventory_sha256', 'files'})
        location(delivery['repository'], delivery['tag']); valid_name(delivery['publication_id'])
        if (delivery['schema_version'] != 1 or type(delivery['experiment']) is not bool or
                not OID.fullmatch(delivery['source_commit']) or not OID.fullmatch(delivery['packager_commit']) or
                delivery['tag_commit'] != delivery['packager_commit'] or
                not delivery['experiment'] and delivery['source_commit'] != delivery['packager_commit'] or
                delivery['source_sha256'] != metadata['source']['sha256'] or
                delivery['inventory_sha256'] != archive.digest(Path(directory) / 'release.json')):
            raise DeliveryError('delivery identity differs from complete release metadata')
        expected = dict(metadata['files'], **{'release.json': delivery['inventory_sha256']})
        if set(delivery['files']) != set(expected): raise DeliveryError('delivery file inventory differs')
        seen = {'delivery.json'}
        for name, digest in expected.items():
            item = delivery['files'][name]; coverage.fields(item, {'asset', 'sha256', 'size'})
            asset = valid_name(Path(name).name)
            if (item['asset'] != asset or item['sha256'] != digest or asset.casefold() in seen or
                    CERT.fullmatch(asset) or type(item['size']) is not int or item['size'] < 0):
                raise DeliveryError('delivery asset identity differs from complete metadata')
            seen.add(asset.casefold())
        return sha(archive.encoded(delivery))
    expected = candidate_identity(directory, **{key: delivery[key] for key in
        ('repository', 'tag', 'source_commit', 'packager_commit', 'publication_id', 'experiment')})
    if expected != delivery:
        raise DeliveryError('delivery identity differs from complete local release')
    return sha(archive.encoded(delivery))


def evidence_pairs(names):
    groups = {}
    for name in names:
        match = CERT.fullmatch(name)
        if not match:
            raise DeliveryError('unexpected asset outside immutable delivery and certificate attempts')
        groups.setdefault((match[1], match[2]), set()).add(match[3])
    if any(parts != {'json', 'tar.gz'} for parts in groups.values()):
        raise DeliveryError('partial certificate attempt requires reconciliation')


def validate_remote_inventory(delivery, info, assets, *, draft=False, prerelease=None):
    """Reconcile a complete observed inventory without fetching it repeatedly."""
    if prerelease is not None and type(prerelease) is not bool:
        raise DeliveryError('prerelease pin must be a boolean or None')
    tag = delivery['tag']; Remote.info(info,tag)
    title = 'experiment' if delivery['experiment'] else tag
    # Ordinary candidates are prereleases until certification permits promotion.
    # Experiment identity remains immutable and can never become an ordinary release.
    if (info['draft'] != draft or info['name'] != title
            or (delivery['experiment'] and not info['prerelease'])
            or (prerelease is not None and info['prerelease'] != prerelease)):
        raise DeliveryError('release lifecycle does not match frozen delivery')
    expected = {item['asset'] for item in delivery['files'].values()} | {'delivery.json'}
    if not expected <= assets.keys():
        raise DeliveryError('published delivery is missing required assets')
    extras = set(assets) - expected
    if draft and extras:
        raise DeliveryError('unexpected draft assets')
    evidence_pairs(extras)
    for item in delivery['files'].values():
        row = assets[item['asset']]
        if row['digest'] != 'sha256:' + item['sha256'] or row['size'] != item['size']:
            raise DeliveryError('remote asset differs from complete frozen inventory')
    descriptor = archive.encoded(delivery)
    if assets['delivery.json']['digest'] != 'sha256:' + sha(descriptor) or assets['delivery.json']['size'] != len(descriptor):
        raise DeliveryError('remote frozen delivery differs')


def verified_remote(remote, delivery, directory, *, draft=False, prerelease=None, readback=True, metadata_only=False):
    validate_delivery(delivery, directory, metadata_only=metadata_only)
    tag = delivery['tag']; info = remote.find(tag) if draft else remote.published(tag)
    assets = remote.assets(info)
    validate_remote_inventory(delivery,info,assets,draft=draft,prerelease=prerelease)
    if remote.reference(tag) != delivery['tag_commit']:
        raise DeliveryError('tag commit differs from frozen delivery')
    with tempfile.TemporaryDirectory(prefix='delivery-verify-') as temporary:
        staged = Path(temporary)
        descriptor = staged / 'delivery.json'
        remote.download(assets['delivery.json'], descriptor, sha(archive.encoded(delivery)))
        if coverage.load(descriptor) != delivery:
            raise DeliveryError('remote frozen delivery differs')
        restored = staged / 'release'; restored.mkdir()
        selections = []
        for name, item in (delivery['files'].items() if readback else ()):
            path = restored.joinpath(*archive.relative(name).parts); path.parent.mkdir(parents=True, exist_ok=True)
            selections.append((item['asset'], path, item['sha256']))
        download_files(remote, assets, selections)
        if readback: release.verify_release(restored)
    remote.unchanged(tag, info, assets, delivery['tag_commit'])
    return info, assets


def upload_files(remote, tag, paths, *, release_info=None):
    """Bound independent payload uploads and join a failed batch before stopping.

    Control descriptors and lifecycle transitions belong to the caller, after
    every payload finishes. A response loss retains the outer mutation's sticky
    uncertainty; queued later batches never launch after the first failure.
    """
    paths = [Path(path) for path in paths]
    if len({path.name.casefold() for path in paths}) != len(paths):
        raise DeliveryError('upload payload names must be distinct')
    with ThreadPoolExecutor(max_workers=4) as pool:
        for start in range(0, len(paths), 4):
            futures = [pool.submit(remote.upload_to, release_info, path) if release_info is not None else
                       pool.submit(remote.upload, tag, path) for path in paths[start:start + 4]]
            for future in futures: future.result()


def download_files(remote, assets, selections, *, _completed=None):
    """Bounded independent immutable transfers; all workers join before return."""
    selections = list(selections)
    destinations = [str(Path(path).absolute()) for _, path, _ in selections]
    if len(destinations) != len(set(destinations)):
        raise DeliveryError('download destinations must be distinct')
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures = {pool.submit(remote.download, assets[name], path, digest): name
                   for name, path, digest in selections}
        for future in as_completed(futures) if _completed is not None else futures:
            future.result()
            if _completed is not None:
                _completed(futures[future])  # Coordinator only; never a transfer worker.


def _fetch_base_groups(repository, recipes, output, *, transport, binary_only, single,
                       group_store=store):
    if type(binary_only) is not bool: raise DeliveryError('binary-only selection must be boolean')
    if (not isinstance(recipes, (list, tuple)) or not recipes or
            any(not isinstance(recipe, str) for recipe in recipes) or len(set(recipes)) != len(recipes)):
        raise DeliveryError('expected distinct nonempty SDK recipe identities')
    expected = {recipe: group_store.names(recipe) for recipe in recipes}
    output = Path(output)
    if output.exists() or output.is_symlink():
        raise DeliveryError('fetch destination must be new')
    remote = Remote(repository, transport); remote.visible()
    info = remote.published('base')
    if info['draft'] or not info['prerelease'] or info['name'] != 'base':
        raise DeliveryError('base must be a published prerelease')
    assets = remote.assets(info)
    reference = remote.reference('base')
    if any(not set(names) <= assets.keys() for names in expected.values()):
        raise DeliveryError('exact complete dependency group is absent; no cold build fallback')
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.base-fetch-', dir=output.parent) as temporary:
        stage = Path(temporary) / 'group'; stage.mkdir()
        groups, selections, remaining, owners = {}, [], {}, {}
        for recipe, names in expected.items():
            group = stage if single else stage / recipe
            if not single: group.mkdir()
            groups[recipe] = group
            binary, source, checksum = names
            selected = (binary, checksum) if binary_only else names
            selections.extend((name, group / name, None) for name in selected)
            remaining[recipe] = len(selected)
            owners.update((name, recipe) for name in selected)
        def verify(recipe):
            group = groups[recipe]
            files = (group_store.verify_binary_group(group, recipe) if binary_only else
                     group_store.verify_group(group, recipe))
            if any(assets[name]['digest'] != 'sha256:' + files[name] for name in expected[recipe]):
                raise DeliveryError('base assets differ from complete checksum inventory')
            return dict(fetched=True, recipe=recipe, files=files,
                        payload='binary' if binary_only else 'complete')
        # A recipe can verify while other recipes still download. Separate
        # bounded pools avoid verification occupying transfer slots or waiting
        # on unfinished files. Both pools join before failed staging is removed.
        with ThreadPoolExecutor(max_workers=4) as pool:
            pending = {}
            def downloaded(name):
                recipe = owners[name]
                remaining[recipe] -= 1
                if remaining[recipe] == 0:
                    pending[recipe] = pool.submit(verify, recipe)
            download_files(remote, assets, selections, _completed=downloaded)
            results = {recipe: pending[recipe].result() for recipe in groups}
        # All consumers retain full byte checks; one fresh reconciliation covers
        # the whole immutable snapshot before any output becomes available.
        remote.unchanged('base', info, assets, reference)
        stage.rename(output)
    return results


def fetch_base(repository, recipe, output, *, transport=None, binary_only=False):
    return _fetch_base_groups(repository, [recipe], output, transport=transport,
                              binary_only=binary_only, single=True)[recipe]


def fetch_bases(repository, recipes, output, *, transport=None, binary_only=False):
    """Fetch recipe subdirectories together using one in-memory base inventory."""
    return _fetch_base_groups(repository, recipes, output, transport=transport,
                              binary_only=binary_only, single=False)


def fetch_rust_base(repository, recipe, output, *, transport=None):
    """Fetch and verify the exact complete retained Rust extension group."""
    return _fetch_base_groups(repository, [recipe], output, transport=transport,
                              binary_only=False, single=True, group_store=rust_sdk)[recipe]


def fetch_rust_bases(repository, recipes, output, *, transport=None):
    """Fetch complete Rust recipe subdirectories using one base inventory."""
    return _fetch_base_groups(repository, recipes, output, transport=transport,
                              binary_only=False, single=False, group_store=rust_sdk)


def _publish_base_group(repository, recipe, group, source_commit, *, execute, transport,
                        group_store, operation):
    files = group_store.verify_group(group, recipe)
    if not OID.fullmatch(source_commit):
        raise DeliveryError('complete source commit required')
    result = plan(operation, repository, recipe=recipe, source_commit=source_commit, files=files,
                  lifecycle='prerelease; never Latest; immutable complete group')
    if not execute:return result
    remote = Remote(repository, transport)
    def act():
        remote.visible(); info = remote.find('base', False)
        before = remote.assets(info) if info else {}
        reference = remote.reference('base') if info else source_commit
        present = set(files) & before.keys()
        if present and present != set(files):
            raise DeliveryError('partial existing dependency group requires reconciliation')
        if info and (info['draft'] or not info['prerelease'] or info['name'] != 'base'):
            raise DeliveryError('existing base has incompatible lifecycle')
        if present:
            # The local complete group was verified above. Existing published
            # immutable assets must match every exact size and SHA-256; their
            # first publication already required complete byte readback.
            if any(before[name]['digest'] != 'sha256:' + digest or
                   before[name]['size'] != (Path(group) / name).stat().st_size
                   for name, digest in files.items()):
                raise DeliveryError('immutable group conflicts: remote asset differs')
            remote.unchanged('base', info, before, reference); remote.not_latest(info)
            return dict(result, execute=True, reused=True)
        if info is None:
            if remote.reference('base', True) is not None:raise DeliveryError('base tag already exists without its release')
            remote.change('/git/refs', body={'ref':'refs/tags/base','sha':source_commit})
            info = remote.info(remote.change('/releases', body={'tag_name':'base','target_commitish':source_commit,
                'name':'base','body':'Complete reusable dependency groups indexed by recipe identity.',
                'draft':True,'prerelease':True,'make_latest':'false'}), 'base')
            if not info['draft'] or not info['prerelease'] or info['name']!='base':
                raise DeliveryError('created base does not match requested draft lifecycle')
            remote.wait_find('base', release_id=info['id'])
        binary, source, checksum = group_store.names(recipe)
        upload_files(remote, 'base', [Path(group) / name for name in (binary, source)], release_info=info)
        remote.upload_to(info, Path(group) / checksum)  # Complete group marker follows joined payloads.
        current = remote.find('base'); assets = remote.assets(current)
        if any(current[key]!=info[key] for key in ('id','name','draft','prerelease')):
            raise DeliveryError('base release identity changed during upload')
        if set(assets) != set(before) | set(files) or any(assets[n] != v for n,v in before.items()):
            raise DeliveryError('base inventory changed unexpectedly')
        with tempfile.TemporaryDirectory(prefix='base-confirm-') as temporary:
            download_files(remote, assets, [(name, Path(temporary) / name, files[name]) for name in files])
            if group_store.verify_group(temporary, recipe) != files:raise DeliveryError('uploaded group differs')
        if group_store.verify_group(group, recipe) != files:raise DeliveryError('local dependency group changed')
        remote.unchanged('base', current, assets, reference)
        if current['draft']:
            remote.change(f'/releases/{current["id"]}', method='PATCH', body={'draft':False,'prerelease':True,'make_latest':'false'})
        final = remote.find('base')
        if (final['id'] != current['id'] or final['name']!='base' or final['draft']
                or not final['prerelease'] or remote.assets(final) != assets):
            raise DeliveryError('base finalization could not be verified')
        remote.not_latest(final)
        if remote.reference('base') != reference:raise DeliveryError('base tag identity changed')
        return dict(result, execute=True, reused=False, release_id=final['id'])
    return run_mutation(remote, act)


def publish_base(repository, recipe, group, source_commit, *, execute=False, transport=None):
    return _publish_base_group(repository, recipe, group, source_commit, execute=execute,
                               transport=transport, group_store=store, operation='publish-base')


def publish_rust_base(repository, recipe, group, source_commit, *, execute=False, transport=None):
    """Plan or append an immutable complete retained Rust extension group."""
    return _publish_base_group(repository, recipe, group, source_commit, execute=execute,
                               transport=transport, group_store=rust_sdk, operation='publish-rust-base')


def publish_candidate(repository, tag, directory, source_commit, packager_commit, publication_id,
                      experiment=False, *, execute=False, transport=None):
    delivery = candidate_identity(directory, repository, tag, source_commit, packager_commit, publication_id, experiment)
    result = plan('publish-candidate', repository, delivery=delivery, lifecycle='draft upload, verify every byte, publish prerelease until certified promotion; never Latest')
    if not execute:return result
    remote = Remote(repository, transport)
    def act():
        remote.visible()
        if remote.find(tag, False) is not None or remote.reference(tag, True) is not None:
            raise DeliveryError('release or tag already exists; no overwrite or implicit resume')
        remote.change('/git/refs', body={'ref':'refs/tags/'+tag,'sha':delivery['tag_commit']})
        info = remote.info(remote.change('/releases', body={'tag_name':tag,'target_commitish':delivery['tag_commit'],
            'name':'experiment' if experiment else tag,'body':'Certification pending. Immutable application assets.',
            'draft':True,'prerelease':True,'make_latest':'false'}), tag)
        remote.wait_find(tag, release_id=info['id'])
        upload_files(remote, tag, [Path(directory) / name for name in delivery['files']], release_info=info)
        with tempfile.TemporaryDirectory(prefix='delivery-metadata-') as temporary:
            path=Path(temporary)/'delivery.json';path.write_bytes(archive.encoded(delivery));remote.upload_to(info,path)
        current, assets = verified_remote(remote, delivery, directory, draft=True, prerelease=True, metadata_only=True)
        if current['id'] != info['id']:raise DeliveryError('draft release identity changed')
        remote.change(f'/releases/{info["id"]}', method='PATCH', body={'draft':False,'prerelease':True,'make_latest':'false'})
        final, final_assets = verified_remote(remote, delivery, directory, prerelease=True, readback=False, metadata_only=True)
        if final['id'] != info['id'] or final_assets != assets:raise DeliveryError('publication identity changed')
        remote.not_latest(final)
        return dict(result, execute=True, release_id=final['id'])
    return run_mutation(remote, act)


def retain_reports(reports, retain):
    """Keep every logical report beside one copy of shared physical evidence."""
    report_paths, parents = {}, {}
    for path in reports:
        path = Path(path); report = coverage.load(path); check = valid_name(report['check'])
        if check in report_paths: raise DeliveryError('duplicate evidence check')
        parent = path.parent.resolve(strict=True)
        prefix = parents.setdefault(parent, 'reports/' + check)
        relative = prefix + '/' + valid_name(path.name)
        report_paths[check] = relative; retain(path, relative)
        for name in report['evidence']:
            retain(coverage.local(path.parent, name), prefix + '/' + name)
    return report_paths


def bundle_certificate(directory, delivery, certificate, check_plan, policy, profile, reports, attempt, destination, *, metadata_only=False):
    validate_delivery(delivery, directory, metadata_only=metadata_only)
    manifest = release.verify_metadata(directory) if metadata_only else release.verify_release(directory)
    if not positive(attempt):raise DeliveryError('certificate attempt must be positive')
    certificate = Path(certificate); reports = [Path(p) for p in reports]
    document = coverage.load(certificate)
    frozen = coverage.load(check_plan); rules = coverage.load(policy)
    adoption = document.get('adoption')
    if adoption is not None and (not isinstance(adoption, dict) or adoption.get('attempt') != attempt or
                                 adoption.get('run_id') != document.get('run_id')):
        raise DeliveryError('certificate adoption belongs to another run or attempt')
    expected = certification.certify(Path(directory), manifest, frozen, reports,
                                     rules, profile, delivery['experiment'], adoption=adoption)
    if document != expected:raise DeliveryError('certificate does not match current complete policy and evidence')
    run_id = document['run_id']
    if not isinstance(run_id, str) or not coverage.NAME.fullmatch(run_id):raise DeliveryError('invalid certification run')
    stem = valid_name(f'certification-{run_id}-attempt-{attempt}')
    tree = Path(destination) / 'contents'; tree.mkdir()
    retained = {}
    def retain(source, name):
        source = Path(source)
        if source.is_symlink() or not source.is_file():raise DeliveryError('evidence must be an ordinary file')
        current = source.stat(); identity = (current.st_dev, current.st_ino, current.st_size, current.st_mtime_ns)
        digest = archive.digest(source)
        target = tree.joinpath(*archive.relative(name).parts)
        if name in retained:
            if retained[name] != (source.resolve(), identity, digest) or archive.digest(target) != digest:
                raise DeliveryError('shared evidence changed during retention')
            return
        target.parent.mkdir(parents=True,exist_ok=True)
        with source.open('rb') as incoming, target.open('xb') as outgoing:shutil.copyfileobj(incoming,outgoing)
        after = source.stat()
        if (identity != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns) or
                archive.digest(source) != digest or archive.digest(target) != digest):
            raise DeliveryError('local evidence changed during retention')
        retained[name] = (source.resolve(), identity, digest)
    for source,name in ((certificate,'certificate.json'),(check_plan,'plan.json'),(policy,'policy.json')):retain(source,name)
    report_paths = retain_reports(reports, retain)
    copied_reports = [tree / name for name in report_paths.values()]
    copied_certificate = coverage.load(tree / 'certificate.json')
    if (copied_certificate != document or coverage.load(tree / 'plan.json') != frozen
            or coverage.load(tree / 'policy.json') != rules
            or certification.certify(Path(directory), manifest, frozen,
                                     copied_reports, rules, profile, delivery['experiment'],
                                     adoption=copied_certificate.get('adoption')) != document):
        raise DeliveryError('certificate evidence changed while creating the complete bundle')
    metadata={'schema_version':1,'delivery_sha256':sha(archive.encoded(delivery)), 'run_id':run_id,
              'attempt':attempt,'profile':profile,'reports':report_paths,
              'report_order':list(report_paths),'files':archive.file_inventory(tree)}
    (tree/'bundle.json').write_bytes(archive.encoded(metadata))
    bundled=Path(destination)/(stem+'.tar.gz');archive.archive_tree(tree,bundled)
    envelope={'schema_version':1,'delivery_sha256':metadata['delivery_sha256'],'run_id':run_id,'attempt':attempt,
              'bundle':bundled.name,'bundle_sha256':archive.digest(bundled),
              'certificate_sha256':archive.digest(tree/'certificate.json'),'subject':document['subject'],
              'status':document['status'],'eligible_for_promotion':document['eligible_for_promotion'],
              'experiment':document['experiment']}
    path=Path(destination)/(stem+'.json');path.write_bytes(archive.encoded(envelope))
    return envelope,path,bundled


def attach_certificate(repository, tag, directory, delivery, certificate, check_plan, policy, profile,
                       reports, attempt, *, execute=False, transport=None, metadata_only=False):
    location(repository,tag)
    if (repository,tag)!=(delivery.get('repository'),delivery.get('tag')):raise DeliveryError('delivery belongs to another location')
    with tempfile.TemporaryDirectory(prefix='certificate-package-') as temporary:
        envelope,report,bundle=bundle_certificate(directory,delivery,certificate,check_plan,policy,profile,reports,attempt,temporary,metadata_only=metadata_only)
        files={p.name:archive.digest(p) for p in (report,bundle)}
        result=plan('attach-certificate',repository,tag=tag,files=files,certificate=envelope,
                    lifecycle='append one immutable attempt; preserve every previous asset; no promotion')
        if not execute:return result
        remote=Remote(repository,transport)
        def act():
            remote.visible();info,before=verified_remote(remote,delivery,directory,readback=not metadata_only,metadata_only=metadata_only)
            if set(files)&before.keys():raise DeliveryError('certificate attempt already exists; inspect it, never overwrite')
            remote.upload_to(info,bundle);remote.upload_to(info,report)
            current=remote.by_id(info['id'],tag);after=remote.assets(current)
            if (any(current[key]!=info[key] for key in ('id','tag_name','name','draft','prerelease')) or
                    remote.reference(tag)!=delivery['tag_commit'] or set(after)!=set(before)|set(files) or any(after[n]!=v for n,v in before.items())):
                raise DeliveryError('certificate attachment changed lifecycle or an existing asset')
            with tempfile.TemporaryDirectory(prefix='certificate-confirm-') as check:
                for name,digest in files.items():remote.download(after[name],Path(check)/name,digest)
            remote.unchanged(tag,current,after,delivery['tag_commit'])
            return dict(result,execute=True,release_id=info['id'])
        return run_mutation(remote,act)


def verify_certificate(remote, assets, delivery, directory, policy, profile, run_id, attempt, certificate_sha256, *, metadata_only=False):
    if not positive(attempt) or not coverage.NAME.fullmatch(run_id) or not SHA.fullmatch(certificate_sha256):
        raise DeliveryError('exact certificate run, attempt and digest are required')
    stem=valid_name(f'certification-{run_id}-attempt-{attempt}')
    names={stem+'.json',stem+'.tar.gz'}
    if not names<=assets.keys():raise DeliveryError('complete certificate attempt is missing')
    with tempfile.TemporaryDirectory(prefix='certificate-review-') as temporary:
        temporary=Path(temporary);path=temporary/(stem+'.json');remote.download(assets[path.name],path)
        envelope=coverage.load(path)
        expected_fields={'schema_version','delivery_sha256','run_id','attempt','bundle','bundle_sha256',
                         'certificate_sha256','subject','status','eligible_for_promotion','experiment'}
        coverage.fields(envelope,expected_fields)
        if (envelope['schema_version']!=1 or envelope['delivery_sha256']!=sha(archive.encoded(delivery))
                or envelope['run_id']!=run_id or envelope['attempt']!=attempt
                or envelope['certificate_sha256']!=certificate_sha256 or envelope['bundle']!=stem+'.tar.gz'
                or not isinstance(envelope['bundle_sha256'],str) or not SHA.fullmatch(envelope['bundle_sha256'])):
            raise DeliveryError('certificate attempt is stale or belongs to another delivery')
        bundled=temporary/envelope['bundle'];remote.download(assets[bundled.name],bundled,envelope['bundle_sha256'])
        tree=archive.extract(bundled,temporary/'contents',max_bytes=4*1024**3)
        metadata=coverage.load(tree/'bundle.json')
        coverage.fields(metadata,{'schema_version','delivery_sha256','run_id','attempt','profile','reports','report_order','files'})
        if (metadata['schema_version']!=1 or metadata['delivery_sha256']!=envelope['delivery_sha256']
                or metadata['run_id']!=run_id or metadata['attempt']!=attempt or metadata['profile']!=profile):
            raise DeliveryError('bundled evidence identity differs')
        archive.verify_inventory(tree,metadata['files'],exclude=('bundle.json',))
        if archive.digest(tree/'certificate.json')!=certificate_sha256:raise DeliveryError('certificate bytes changed')
        rules=coverage.load(policy)
        if coverage.load(tree/'policy.json')!=rules:raise DeliveryError('current promotion policy differs from tested policy')
        reports=[]
        if not isinstance(metadata['reports'],dict) or not metadata['reports']:raise DeliveryError('complete reports required')
        if (not isinstance(metadata['report_order'],list) or len(set(metadata['report_order']))!=len(metadata['report_order'])
                or set(metadata['report_order'])!=set(metadata['reports'])):
            raise DeliveryError('complete original report order required')
        for check in metadata['report_order']:
            name=metadata['reports'][check]
            valid_name(check);path=archive.checked_file(tree,name)
            if coverage.load(path)['check']!=check:raise DeliveryError('report identity mismatch')
            reports.append(path)
        # Preserve original caller order when comparing the certifier's report list.
        frozen=coverage.load(tree/'plan.json')
        saved=coverage.load(tree/'certificate.json')
        adoption=saved.get('adoption')
        if adoption is not None and (not isinstance(adoption,dict) or adoption.get('attempt')!=attempt or
                                     adoption.get('run_id')!=run_id):
            raise DeliveryError('certificate adoption belongs to another run or attempt')
        result=certification.certify(Path(directory),release.verify_metadata(directory) if metadata_only else release.verify_release(directory),frozen,reports,rules,profile,False,adoption=adoption)
        if result!=saved or result['subject']!=envelope['subject']:
            raise DeliveryError('saved certificate does not reproduce from complete retained evidence')
        if (result['status'] not in ('passed','passed_with_warnings') or result['eligible_for_promotion'] is not True
                or result['experiment'] is not False or envelope['eligible_for_promotion'] is not True
                or envelope['experiment'] is not False or envelope['status']!=result['status']):
            raise DeliveryError('certificate does not qualify this ordinary release')
        return {'certificate_sha256':certificate_sha256,'run_id':run_id,'attempt':attempt,'status':result['status']}


def promote(repository,tag,directory,delivery,policy,profile,run_id,attempt,certificate_sha256,*,execute=False,transport=None,metadata_only=False):
    location(repository,tag);validate_delivery(delivery,directory,metadata_only=metadata_only)
    if (repository,tag)!=(delivery['repository'],delivery['tag']) or delivery['experiment'] or tag=='base':
        raise DeliveryError('only this ordinary application release can be promoted')
    if not positive(attempt) or not coverage.NAME.fullmatch(run_id) or not SHA.fullmatch(certificate_sha256):
        raise DeliveryError('exact certificate run, attempt and digest are required')
    certification.requirements(coverage.load(policy),profile)
    result=plan('promote',repository,tag=tag,delivery_sha256=sha(archive.encoded(delivery)),
                policy_sha256=archive.digest(policy),profile=profile,run_id=run_id,attempt=attempt,
                certificate_sha256=certificate_sha256,lifecycle='verify exact certificate and every remote asset, change Latest, verify pointer')
    if not execute:return result
    remote=Remote(repository,transport)
    def act():
        remote.visible();info,assets=verified_remote(remote,delivery,directory,readback=not metadata_only,metadata_only=metadata_only)
        evidence=verify_certificate(remote,assets,delivery,directory,policy,profile,run_id,attempt,certificate_sha256,metadata_only=metadata_only)
        # Reconcile IDs, sizes, hashes and tag after certificate reproduction;
        # this operation already downloaded and verified the immutable bytes.
        remote.unchanged(tag,info,assets,delivery['tag_commit'])
        if archive.digest(policy)!=result['policy_sha256']:raise DeliveryError('promotion policy changed')
        remote.change(f'/releases/{info["id"]}',method='PATCH',body={'draft':False,'prerelease':False,'make_latest':'true'})
        final=remote.by_id(info['id'],tag);after=remote.assets(final)
        if (final['draft'] or final['prerelease'] or final['name']!=info['name'] or after!=assets or
                remote.reference(tag)!=delivery['tag_commit']):raise DeliveryError('promoted lifecycle or assets changed')
        latest=remote.transport.json(remote.base+'/releases/latest')
        remote.info(latest,tag)
        if latest['id']!=info['id'] or latest['draft'] or latest['prerelease']:
            raise DeliveryError('Latest pointer does not identify the exact certified release')
        return dict(result,execute=True,release_id=info['id'],latest=True,evidence=evidence)
    return run_mutation(remote,act)


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('operation',choices=('fetch-base','fetch-rust-base','publish-base',
        'publish-rust-base','publish-candidate','attach-certificate','promote'))
    parser.add_argument('--input',default='-',help='strict JSON request file or stdin')
    parser.add_argument('--execute',action='store_true',help='explicitly execute planned remote mutations')
    args=parser.parse_args(argv)
    request=parse(sys.stdin.buffer.read() if args.input=='-' else Path(args.input).read_bytes())
    if not isinstance(request,dict) or 'execute' in request or 'transport' in request:
        raise DeliveryError('request must be an object; execution is a separate explicit CLI option')
    operation=globals()[args.operation.replace('-','_')]
    fetching=args.operation in ('fetch-base','fetch-rust-base')
    result=operation(**request,**({} if fetching else {'execute':args.execute}))
    try:
        print(json.dumps(result,sort_keys=True,indent=2),flush=True)
    except (OSError,ValueError) as error:
        if args.execute and not fetching:
            raise DeliveryError('execution completed but its receipt could not be delivered; reconcile remote before retry',True) from error
        raise
    return 0


if __name__=='__main__':
    enable_metrics()
    try:sys.exit(main())
    except (OSError,ValueError,RuntimeError,KeyError,TypeError) as error:
        print(json.dumps({'ok':False,'uncertain':getattr(error,'uncertain',False),
                          'error':str(error),'action':'reconcile remote before retry' if getattr(error,'uncertain',False)
                          else 'correct the request or inspect read-only state'}),file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Build/package the application inside a prepared, disconnected Bookworm boundary.

No input acquisition or compiler reconstruction is performed. A plan contains
structured paths and exact recipes, never shell fragments. Each native target
uses one tree for core/CLI and all six native GUI hosts; Wasm uses its own tree.
"""
import argparse
import errno
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import socket
import subprocess
import sys
import time
import xml.etree.ElementTree as ET

from dependency_archive import digest, encoded, inspect_manifest_archive, read_json
from dependency_store import names, verify_group
from sdk_environment import require_clean

ROOT = Path(__file__).resolve().parents[1]
INVENTORY = Path(__file__).with_name('offline_inputs.json')
SHA = re.compile(r'[0-9a-f]{64}')


def write_new(path, value):
    with Path(path).open('xb') as output:
        output.write(encoded(value))


def processor(value=None):
    value = platform.machine() if value is None else value
    return {'AMD64': 'x86_64', 'amd64': 'x86_64', 'arm64': 'aarch64', 'ARM64': 'aarch64'}.get(value, value)


def inventory(path=INVENTORY):
    value = read_json(path)
    native = ['terminal', 'framebuffer', 'fltk', 'rev', 'sdl', 'hosted-web']
    if (value.get('schema_version') != 1 or value.get('native_backends') != native
            or not isinstance(value.get('targets'), list)):
        raise ValueError('unsupported offline input inventory')
    targets = {item.get('target'): item for item in value['targets']}
    if (len(targets) != len(value['targets']) or set(targets) !=
            {'linux-x86_64', 'linux-aarch64', 'browser-wasm32', 'windows-x86_64'}):
        raise ValueError('offline inventory must preserve the complete supported matrix')
    for name, item in targets.items():
        if item.get('backends') != (['wasm'] if name == 'browser-wasm32' else native) or item.get('core_cli') is not True:
            raise ValueError('offline inventory must preserve core/CLI and every GUI backend')
    return value


def absolute(value, *, exists=True):
    if not isinstance(value, str) or not value or not Path(value).is_absolute() or '\n' in value or '\0' in value:
        raise ValueError('offline input/output paths must be absolute ordinary paths')
    path = Path(value)
    if path.is_symlink():
        raise ValueError('offline input/output root cannot be a symlink')
    try:
        resolved = path.resolve(strict=exists)
    except FileNotFoundError as error:
        raise ValueError('missing declared offline input: ' + str(path)) from error
    if resolved != path:
        raise ValueError('offline input/output paths must be canonical')
    return path


def validate_plan(value, *, system=None, machine=None):
    contract = inventory()
    if (not isinstance(value, dict) or set(value) != {'schema_version', 'isolation', 'cases'}
            or type(value['schema_version']) is not int or value['schema_version'] not in (1, 2)):
        raise ValueError('exact schema-2 offline plan or explicit-provider schema-1 plan required')
    boundary = value['isolation']
    if not isinstance(boundary, dict):
        raise ValueError('an explicit prepared isolation boundary is required')
    if boundary.get('kind') == 'docker':
        if set(boundary) != {'kind', 'image'} or not re.fullmatch(r'sha256:[0-9a-f]{64}', boundary.get('image', '')):
            raise ValueError('Docker acceptance requires an immutable locally prepared image ID')
    elif boundary.get('kind') == 'namespace':
        if set(boundary) != {'kind', 'rootfs', 'manifest', 'manifest_sha256'} or not SHA.fullmatch(boundary.get('manifest_sha256', '')):
            raise ValueError('namespace acceptance requires an exact prepared rootfs inventory')
        absolute(boundary['rootfs']); absolute(boundary['manifest'])
    else:
        raise ValueError('unsupported isolation; no online or unisolated fallback')
    cases = value['cases']
    if not isinstance(cases, list) or not cases:
        raise ValueError('offline plan needs explicit retained groups')
    supported = {item['target']: item for item in contract['targets']}
    seen = set()
    for case in cases:
        if not isinstance(case, dict):
            raise ValueError('offline cases need structured provider and retained group fields')
        if value['schema_version'] == 1 and 'core_provider' not in case:
            raise ValueError('schema-1 offline plans require an explicit core_provider; select cpp to preserve '
                             'the historical request, or migrate to schema 2 with complete retained Rust inputs')
        provider = case.get('core_provider', 'rust')
        required = {'target', 'group', 'recipe'}
        allowed = required | {'core_provider'}
        if provider == 'rust':
            if not {'rust_group', 'rust_recipe'} <= set(case):
                raise ValueError('Rust offline cases need their complete retained Rust group and recipe identity')
            required |= {'rust_group', 'rust_recipe'}
            allowed = required | {'core_provider'}
        if (provider not in ('cpp', 'rust') or not required <= set(case) or not set(case) <= allowed
                or case['target'] not in supported or case['target'] in seen or not SHA.fullmatch(case.get('recipe', ''))):
            raise ValueError('offline cases need unique supported targets and complete recipe identities')
        seen.add(case['target']); absolute(case['group'])
        if provider == 'rust':
            if not SHA.fullmatch(case.get('rust_recipe', '')):
                raise ValueError('Rust offline cases need a complete paired Rust recipe identity')
            absolute(case['rust_group'])
    current_system = platform.system() if system is None else system
    current_machine = processor(machine)
    applicable = [item['target'] for item in contract['targets']
                  if item['host_system'] == current_system and item['host_processor'] == current_machine]
    if not applicable or current_system != 'Linux':
        raise ValueError('this Bookworm launcher requires a supported native Linux host; Windows acceptance remains separate')
    foreign = seen - set(applicable)
    if foreign:
        raise ValueError('offline plan requests unavailable/foreign host targets: ' + ', '.join(sorted(foreign)))
    return applicable


def verify_case(case):
    provider = case.get('core_provider', 'rust')
    if provider not in ('cpp', 'rust'):
        raise ValueError('unsupported explicit core provider')
    if provider == 'rust' and (not isinstance(case.get('rust_group'), str)
                               or not isinstance(case.get('rust_recipe'), str)
                               or not SHA.fullmatch(case['rust_recipe'])):
        raise ValueError('Rust offline cases need their complete retained Rust group and recipe identity')
    target = next(item for item in inventory()['targets'] if item['target'] == case['target'])
    group = absolute(case['group'])
    hashes = verify_group(group, case['recipe'])
    metadata, _ = inspect_manifest_archive(group / names(case['recipe'])[0], 'sdk.json', sdk_archive=True)
    if (metadata['target']['system'] != target['sdk_target_system']
            or metadata['target']['processor'] != target['sdk_processor']):
        raise ValueError('retained SDK target/architecture differs from requested application target')
    host = metadata.get('host', {})
    if (host.get('system') != target['host_system'] or not isinstance(host.get('processor'), str)
            or not host['processor'] or processor(host['processor']) != target['host_processor']):
        raise ValueError('retained SDK host tools require a different native host')
    capabilities = metadata.get('capabilities', ['wasm'] if case['target'] == 'browser-wasm32' else ['core', 'terminal', 'framebuffer', 'hosted-web'])
    if not set(target['backends']) <= set(capabilities):
        raise ValueError('retained SDK lacks required GUI capabilities; select a complete matching all-GUI group')
    result = {'files': hashes, 'recipe': case['recipe'], 'target': case['target'], 'metadata': metadata,
              'core_provider': provider}
    if result['core_provider'] == 'rust':
        from rust_sdk import names as rust_names, verify_group as verify_rust_group, verify_pair
        rust_group = absolute(case['rust_group'])
        rust_hashes = verify_rust_group(rust_group, case['rust_recipe'])
        rust_metadata, _ = inspect_manifest_archive(rust_group / rust_names(case['rust_recipe'])[0], 'rust-sdk.json')
        verify_pair(rust_metadata, metadata)
        if (rust_metadata['host']['system'] != target['host_system']
                or processor(rust_metadata['host']['processor']) != target['host_processor']):
            raise ValueError('retained Rust SDK host tools require a different native host')
        result['rust'] = {'files': rust_hashes, 'recipe': case['rust_recipe'], 'metadata': rust_metadata}
    return result


def snapshot(root, destination):
    from source_identity import selected_files, source_tree
    before = source_tree(root)
    destination.mkdir()
    for name, path in selected_files(root).items():
        output = destination / name
        output.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(path, output)
        output.chmod(0o755 if name in before['executables'] else 0o644)
    write_new(destination / 'source.json', before)
    if source_tree(destination) != before or source_tree(root) != before:
        raise ValueError('source changed while freezing offline acceptance inputs')
    return before


def os_release(path=Path('/etc/os-release')):
    result = {}
    for line in path.read_text().splitlines():
        if '=' in line:
            key, value = line.split('=', 1)
            result[key] = value.strip('"')
    if result.get('ID') != 'debian' or result.get('VERSION_ID') != '12':
        raise ValueError('offline acceptance requires the prepared Debian 12 Bookworm runtime')
    return result


def isolation_probe(*, child=False):
    interfaces = sorted(path.name for path in Path('/sys/class/net').iterdir()) if Path('/sys/class/net').is_dir() else sorted(name for _, name in socket.if_nameindex())
    if interfaces != ['lo']:
        raise ValueError('offline boundary has a non-loopback interface')
    if Path('/sys/class/net/lo/flags').is_file() and not int(Path('/sys/class/net/lo/flags').read_text().strip(), 16) & 1:
        raise ValueError('offline network namespace loopback is not enabled')
    readonly = {}
    for name, path in (('rootfs', Path('/')), ('source', ROOT), ('retained_group', Path('/inputs/group'))):
        readonly[name] = bool(os.statvfs(path).f_flag & os.ST_RDONLY)
    if Path('/inputs/rust-group').is_dir() and any(Path('/inputs/rust-group').iterdir()):
        readonly['retained_rust_group'] = bool(os.statvfs('/inputs/rust-group').f_flag & os.ST_RDONLY)
    if not all(readonly.values()):
        raise ValueError('offline rootfs/source/retained inputs must be read-only mounts')
    # A numeric TEST-NET address avoids DNS and must be unreachable in this netns.
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
        probe.settimeout(1)
        try:
            probe.connect(('198.51.100.1', 9))
        except OSError as error:
            if error.errno not in (errno.ENETUNREACH, errno.EHOSTUNREACH):
                raise ValueError('network rejection does not establish a disconnected route') from error
            rejection = error.errno
        else:
            raise ValueError('offline boundary unexpectedly reached a non-loopback address')
    capabilities = {}
    for line in Path('/proc/self/status').read_text().splitlines():
        if line.startswith(('CapEff:', 'CapBnd:')):
            key, value = line.split(':', 1); capabilities[key] = int(value.strip(), 16)
    if capabilities != {'CapEff': 0, 'CapBnd': 0}:
        raise ValueError('offline application processes must have no effective/bounding capabilities')
    mapping = Path('/proc/self/uid_map').read_text().strip()
    if os.getuid() == 0:
        rows = [tuple(map(int, row.split())) for row in mapping.splitlines()]
        if rows != [(0, os.environ.get('FOUNDATION_OUTER_UID') and int(os.environ['FOUNDATION_OUTER_UID']), 1)] or rows[0][1] == 0:
            raise ValueError('offline application must run as an ordinary host user')
    result = {'interfaces': interfaces, 'external_connect_errno': rejection,
              'network_namespace': os.readlink('/proc/self/ns/net'), 'capabilities': capabilities,
              'uid': os.getuid(), 'uid_map': mapping, 'readonly_mounts': readonly,
              'host_home_present': Path('/home/user').exists()}
    if not child:
        completed = subprocess.run([sys.executable, '-B', str(Path(__file__).resolve()), '--probe'],
                                   check=True, text=True, capture_output=True, env=os.environ.copy())
        result['child'] = json.loads(completed.stdout)
        if result['child']['network_namespace'] != result['network_namespace']:
            raise ValueError('build child did not inherit the verified network boundary')
    return result


def tool_identity(name, executable, version_args=('--version',)):
    lexical = Path(shutil.which(executable) or executable).absolute()
    try:
        path = lexical.resolve(strict=True)
    except OSError as error:
        raise ValueError('missing declared offline host tool: ' + name + ' (' + executable + ')') from error
    if not path.is_file() or not os.access(path, os.X_OK):
        raise ValueError('missing declared offline host tool: ' + name)
    completed = subprocess.run([str(path), *version_args], check=True, text=True, capture_output=True, timeout=30)
    value = {'selected_path': str(lexical), 'path': str(path), 'sha256': digest(path),
             'version': (completed.stdout + completed.stderr)[:4096].strip()}
    if str(path).startswith(('/usr/', '/bin/')):
        ownership = distribution_owner(path, lexical)
        value['distribution_owner_path'] = ownership.args[-1]
        packages = sorted(set(line.split(': ', 1)[0] for line in ownership.stdout.splitlines()))
        versions = subprocess.run(['dpkg-query', '-W', '-f=${Package}\t${Version}\t${Architecture}\n', *packages],
                                  check=True, text=True, capture_output=True)
        value['distribution_packages'] = versions.stdout.splitlines()
    return value


def distribution_owner(physical, lexical):
    """Bookworm usrmerge may retain /bin package names for /usr/bin bytes."""
    candidates = [physical]
    if lexical != physical:
        candidates.append(lexical)
    for first, second in (('/usr/bin/', '/bin/'), ('/usr/sbin/', '/sbin/'), ('/bin/', '/usr/bin/'), ('/sbin/', '/usr/sbin/')):
        if str(physical).startswith(first):
            candidates.append(Path(second + str(physical)[len(first):]))
    for candidate in dict.fromkeys(candidates):
        if not candidate.exists() or not candidate.samefile(physical):
            continue
        completed = subprocess.run(['dpkg-query', '-S', str(candidate)], text=True, capture_output=True)
        if completed.returncode == 0:
            return completed
        if completed.returncode != 1:
            raise ValueError('distribution package ownership lookup failed for declared host tool: ' + str(candidate))
    raise ValueError('declared host tool lacks distribution package ownership: ' + str(physical))


def host_tools(sdk, target):
    from build import host_programs
    programs = host_programs(sdk)
    metadata = read_json(sdk / 'sdk.json')
    selected = {'python3': sys.executable, 'git': 'git', 'cmake': programs['cmake'], 'ninja': programs['ninja'],
                'ctest': programs['ctest'], 'cpack': programs['cpack'],
                'retained-cxx': str(sdk / metadata['target']['cxx_compiler'])}
    if 'python' in programs:
        selected['retained-python'] = programs['python']
    if target.startswith('linux-'):
        selected['readelf'] = 'readelf'
        selected['pkg-config'] = str(sdk / 'bin/pkg-config') if (sdk / 'bin/pkg-config').is_file() else 'pkg-config'
    tools = {name: tool_identity(name, path) for name, path in selected.items()}
    minimum = (3, 10) if target == 'browser-wasm32' else (3, 9)
    if sys.version_info[:2] < minimum:
        raise ValueError('host Python is older than the declared offline prerequisite')
    if target == 'browser-wasm32':
        tools['node'] = tool_identity('node', str(sdk / 'node/bin/node'))
    return tools


def rust_host_tools(rust_sdk, cpp_sdk):
    from rust_sdk import verify_rust_sdk
    metadata = verify_rust_sdk(rust_sdk, cpp_sdk=cpp_sdk, execute=True)
    return {name: tool_identity('retained-' + name, str(rust_sdk / metadata['compiler'][name]))
            for name in ('rustc', 'cargo')}


def rust_environment(output, environment=None):
    result = dict(os.environ if environment is None else environment)
    for name in list(result):
        if name.startswith(('CARGO_', 'RUST')):
            del result[name]
    result.update(CARGO_HOME=str(output / 'cargo-home'), CARGO_NET_OFFLINE='true',
                  RUSTUP_HOME=str(output / 'rustup-home'))
    return result


def readonly_sdk(root):
    import uuid
    root = Path(root)
    if not os.statvfs(root).f_flag & os.ST_RDONLY:
        raise ValueError('execution must consume the restored Rust SDK through a read-only mount')
    path = root / ('.offline-write-probe-' + uuid.uuid4().hex)
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except OSError as error:
        if error.errno != errno.EROFS:
            raise ValueError('restored Rust SDK did not reject writing as a read-only filesystem') from error
        return {'mount_readonly': True, 'write_rejection_errno': error.errno}
    else:
        os.close(descriptor)
        path.unlink()
        raise ValueError('restored Rust SDK unexpectedly allowed writing')


def checked_command(argv, commands, *, cwd=ROOT, environment=None):
    row = {'argv': [str(value) for value in argv], 'status': 'running'}
    commands.append(row)
    print('+ ' + subprocess.list2cmdline(row['argv']), flush=True)
    started = time.monotonic()
    try:
        completed = subprocess.run(row['argv'], cwd=cwd, env=environment, check=True)
        row.update(status='passed', returncode=completed.returncode)
    except subprocess.CalledProcessError as error:
        row.update(status='failed', returncode=error.returncode)
        raise
    finally:
        row['seconds'] = time.monotonic() - started


def build_arguments(target, sdk, output, jobs, action, *, core_provider='rust', rust_sdk=None):
    contract = next(item for item in inventory()['targets'] if item['target'] == target)
    arguments = [sys.executable, '-B', str(ROOT / 'tools/build.py'), action, 'release',
                 '--sdk', str(sdk), '--gui', '--gui-backends', ','.join(contract['backends']),
                 '--build-dir', str(output / 'build'), '--build-jobs', str(jobs), '--test-jobs', '2']
    if core_provider not in ('cpp', 'rust') or (core_provider == 'rust') != (rust_sdk is not None):
        raise ValueError('offline Rust commands require their exact retained SDK')
    arguments += ['--core-provider', core_provider]
    if core_provider == 'rust':
        arguments += ['--rust-sdk', str(rust_sdk)]
    if target.startswith('linux-'):
        arguments.append('--portable')
    if action == 'test':
        arguments += ['--label', 'core', '--junit', str(output / 'core.junit.xml')]
    return arguments


def verify_core_junit(path, required=('core.store', 'core.cli')):
    path = Path(path)
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 8 * 1024 * 1024:
        raise ValueError('missing or invalid offline core JUnit evidence')
    try:
        root = ET.parse(path).getroot()
    except ET.ParseError as error:
        raise ValueError('invalid offline core JUnit XML') from error
    cases = list(root.iter('testcase'))
    names = [case.get('name') for case in cases]
    if len(names) != len(required) or set(names) != set(required):
        raise ValueError('offline core evidence must execute the complete required core inventory')
    for case in cases:
        if (case.get('status') not in (None, 'run', 'passed', 'pass')
                or any(case.find(name) is not None for name in ('skipped', 'failure', 'error'))):
            raise ValueError('offline core evidence contains skipped/unexecuted/failed assertions')
    for suite in root.iter('testsuite'):
        for name in ('failures', 'errors', 'skipped', 'disabled'):
            if suite.get(name) not in (None, '0'):
                raise ValueError('offline core evidence declares incomplete/failed tests')
    return {'status': 'passed', 'tests': sorted(names), 'count': len(names), 'sha256': digest(path)}


def inside(phase, request_path):
    request = read_json(request_path)
    output = Path('/output')
    case = {**request['case'], 'group': '/inputs/group'}
    sdk = output / 'sdk'
    if 'core_provider' not in case:
        raise ValueError('projected offline requests require an explicit core_provider; recreate the request '
                         'from a migrated plan')
    provider = case['core_provider']
    rust_sdk = output / 'rust-sdk' if provider == 'rust' else None
    if rust_sdk:
        case['rust_group'] = '/inputs/rust-group'
    result = {'schema_version': 1, 'phase': phase, 'target': case['target'], 'status': 'failed', 'commands': [],
              'core_provider': provider,
              'source_tree_sha256': request['source_tree_sha256'], 'inventory_sha256': digest(INVENTORY),
              'requested_backends': next(item['backends'] for item in inventory()['targets'] if item['target'] == case['target']),
              'browser_security': 'separate real-browser qualification required'}
    try:
        from source_identity import source_tree
        result['os'] = os_release()
        result['isolation'] = isolation_probe()
        require_clean()
        if source_tree(ROOT)['tree_sha256'] != request['source_tree_sha256']:
            raise ValueError('offline source differs from the frozen request')
        verified = verify_case(case)
        if verified['files'] != request['group_files']:
            raise ValueError('retained group changed across the isolated boundary')
        result['group'] = {key: verified[key] for key in ('files', 'recipe', 'target')}
        if rust_sdk:
            if verified['rust']['files'] != request.get('rust_group_files'):
                raise ValueError('retained Rust group changed across the isolated boundary')
            if not os.statvfs('/inputs/rust-group').f_flag & os.ST_RDONLY:
                raise ValueError('retained Rust inputs must be a read-only mount')
            result['rust_group'] = {key: verified['rust'][key] for key in ('files', 'recipe')}
        if phase == 'stage':
            required = ['sh', 'bash', 'git', 'sed', 'find', 'grep', 'xargs', 'dirname', 'readlink', 'dpkg-query']
            if case['target'].startswith('linux-'):
                required += ['readelf', 'xvfb-run', 'xauth']
                if 'bin/pkg-config' not in verified['metadata']['files']:
                    required.append('pkg-config')
            for name in required:
                if not shutil.which(name):
                    raise ValueError('missing declared offline host prerequisite: ' + name)
            result['restoration_tools'] = {name: tool_identity(name, name, ('-c', ':') if name == 'sh' else ('--version',))
                                           for name in required if name not in ('xvfb-run', 'xauth')}
            if case['target'].startswith('linux-'):
                result['display_tools'] = {name: tool_identity(name, name, ('-h',) if name == 'xvfb-run' else ('-V',))
                                           for name in ('xvfb-run', 'xauth')}
            directories = ['home', 'tmp', 'cache', 'stage-home', 'stage-tmp', 'stage-cache']
            if rust_sdk:
                directories += ['cargo-home', 'rustup-home']
            for name in directories:
                directory = output / name
                if directory.exists() and any(directory.iterdir()):
                    raise ValueError('offline HOME/temp/cache must start empty')
                directory.mkdir(exist_ok=True)
            from sdk import install
            result['restoration'] = {'status': 'running', 'source': 'complete retained group',
                                     'helper': 'tools/sdk.py', 'operation': 'install', 'production': True,
                                     'group': case['group'], 'recipe': case['recipe'], 'output': str(sdk)}
            metadata = install(Path(case['group']), case['recipe'], sdk, production=True)
            result['restoration']['status'] = 'passed'
            result['sdk_manifest_sha256'] = digest(sdk / 'sdk.json')
            result['host_tools'] = host_tools(sdk, case['target'])
            if rust_sdk:
                from rust_sdk import restore
                result['rust_restoration'] = {'status': 'running', 'source': 'complete retained Rust group',
                                             'helper': 'tools/rust_sdk.py', 'operation': 'restore',
                                             'group': case['rust_group'], 'recipe': case['rust_recipe'], 'output': str(rust_sdk)}
                restore(Path(case['rust_group']), case['rust_recipe'], rust_sdk, cpp_sdk=sdk, execute=True)
                result['rust_restoration']['status'] = 'passed'
                result['rust_sdk_manifest_sha256'] = digest(rust_sdk / 'rust-sdk.json')
                result['rust_host_tools'] = rust_host_tools(rust_sdk, sdk)
            if case['target'] == 'browser-wasm32':
                if not (sdk / 'cache').is_dir() or not any((sdk / 'cache').iterdir()) or not (sdk / '.emscripten').is_file():
                    raise ValueError('prepared Wasm cache/configuration is missing; preparation must be explicit')
                result['wasm_cache'] = {'root': str(sdk / 'cache'), 'frozen': True,
                                        'files': {name: value for name, value in metadata['files'].items() if name.startswith('cache/')}}
        elif phase == 'execute':
            from sdk_manifest import verify_sdk
            if not os.statvfs(sdk).f_flag & os.ST_RDONLY:
                raise ValueError('execution must consume the restored SDK through a read-only mount')
            fresh_directories = ['home', 'tmp', 'cache'] + (['cargo-home', 'rustup-home'] if rust_sdk else [])
            for name in fresh_directories:
                if any((output / name).iterdir()):
                    raise ValueError('application acceptance HOME/temp/cache must be fresh after SDK restoration')
            result['fresh_outputs'] = {'home': True, 'temporary': True, 'cache': True, 'build': not (output / 'build').exists()}
            before = verify_sdk(sdk, release=True)
            stage = read_json(output / 'stage.json')
            if stage['status'] != 'passed' or stage['sdk_manifest_sha256'] != before:
                raise ValueError('installed SDK differs from its isolated restoration receipt')
            result['host_tools'] = host_tools(sdk, case['target'])
            if result['host_tools'] != stage['host_tools']:
                raise ValueError('selected host tools differ from their isolated restoration receipt')
            result['sdk_manifest_sha256'] = before
            if rust_sdk:
                from rust_sdk import verify_rust_sdk
                result['rust_sdk_readonly'] = readonly_sdk(rust_sdk)
                verify_rust_sdk(rust_sdk, cpp_sdk=sdk, execute=True)
                rust_before = digest(rust_sdk / 'rust-sdk.json')
                if stage.get('rust_sdk_manifest_sha256') != rust_before:
                    raise ValueError('installed Rust SDK differs from its isolated restoration receipt')
                result['rust_sdk_manifest_sha256'] = rust_before
                result['rust_host_tools'] = rust_host_tools(rust_sdk, sdk)
                if result['rust_host_tools'] != stage.get('rust_host_tools'):
                    raise ValueError('selected Rust tools differ from their isolated restoration receipt')
                result['fresh_outputs'].update(cargo_home=True, rustup_home=True)
            if (output / 'build').exists():
                raise ValueError('offline application build directory must be fresh')
            environment = os.environ.copy()
            environment.update(CCACHE_DISABLE='1', CCACHE_DIR='/output/cache/ccache', EM_FROZEN_CACHE='1')
            if rust_sdk:
                environment = rust_environment(output, environment)
                result['cargo_environment'] = {name: environment[name] for name in ('CARGO_HOME', 'RUSTUP_HOME', 'CARGO_NET_OFFLINE')}
            if case['target'] == 'browser-wasm32':
                environment['EM_CACHE'] = str(sdk / 'cache')
            for action in ('build', 'test', 'package'):
                checked_command(build_arguments(case['target'], sdk, output, request['jobs'], action,
                                                core_provider=provider, rust_sdk=rust_sdk), result['commands'], environment=environment)
                if action == 'test':
                    result['core_tests'] = verify_core_junit(output / 'core.junit.xml',
                        ('core.store', 'core.cli', 'core.text_validation', 'core.text_status'))
            choices = sorted((output / 'build/packages').glob('*.tar.gz'))
            if len(choices) != 1:
                raise ValueError('offline acceptance needs one exact platform application archive')
            archive = choices[0]
            manifest = archive.with_name(archive.name + '.json')
            base = [sys.executable, '-B', str(ROOT / 'tools/artifact.py')]
            checked_command([*base, 'create', str(archive), '--manifest', str(manifest)], result['commands'], environment=environment)
            verify = [*base, 'verify', str(archive), '--manifest', str(manifest), '--sdk', str(sdk)]
            if case['target'].startswith('linux-'):
                verify += ['--abi', '--processor', case['target'].split('-', 1)[1]]
            checked_command(verify, result['commands'], environment=environment)
            result['package'] = {'path': str(archive.relative_to(output)), 'sha256': digest(archive),
                                 'manifest_sha256': digest(manifest), 'installed_consumer': 'passed',
                                 'bookworm_abi': 'passed' if case['target'].startswith('linux-') else 'not-applicable'}
            if case['target'].startswith('linux-'):
                for backend in result['requested_backends']:
                    checked_command([*base, 'verify', str(archive), '--manifest', str(manifest), '--sdk', str(sdk),
                                     '--runtime-only', '--backend', backend], result['commands'], environment=environment)
                result['native_gui_package_smoke'] = 'passed'
            else:
                result['wasm_cache'] = stage['wasm_cache']
            if verify_sdk(sdk, release=True) != before or verify_group(case['group'], case['recipe']) != request['group_files']:
                raise ValueError('prepared SDK/retained group changed during offline acceptance')
            result['host_tools_after'] = host_tools(sdk, case['target'])
            if result['host_tools_after'] != result['host_tools']:
                raise ValueError('selected host tools changed during offline acceptance')
            if rust_sdk:
                from rust_sdk import verify_group as verify_rust_group
                verify_rust_sdk(rust_sdk, cpp_sdk=sdk, execute=True)
                if (digest(rust_sdk / 'rust-sdk.json') != rust_before
                        or verify_rust_group(case['rust_group'], case['rust_recipe']) != request['rust_group_files']):
                    raise ValueError('prepared Rust SDK/retained group changed during offline acceptance')
                result['rust_host_tools_after'] = rust_host_tools(rust_sdk, sdk)
                if result['rust_host_tools_after'] != result['rust_host_tools']:
                    raise ValueError('selected Rust tools changed during offline acceptance')
            if source_tree(ROOT)['tree_sha256'] != request['source_tree_sha256']:
                raise ValueError('source changed during offline acceptance')
        else:
            raise ValueError('unsupported offline phase')
        result['status'] = 'passed'
    except BaseException as error:
        result['error'] = str(error)[:4096]
        raise
    finally:
        write_new(output / (phase + '.json'), result)


def docker_phase(boundary, source, output, group, uid, gid, phase, *, rust_group=None):
    import importlib.util
    spec = importlib.util.spec_from_file_location('offline_container_adapter', ROOT / '.github/scripts/container_job.py')
    adapter = importlib.util.module_from_spec(spec); spec.loader.exec_module(adapter)
    optional = {'rust_group': rust_group} if rust_group is not None else {}
    return adapter.offline_command(source, output, group, uid, gid, boundary['image'], phase,
                                   target=read_json(output / 'request.json')['case']['target'], **optional)


def run(plan_path, output, cases=None, jobs=2, root=ROOT):
    plan_path = absolute(str(plan_path))
    plan = read_json(plan_path)
    applicable = validate_plan(plan)
    selected = list(cases) if cases else applicable
    if len(selected) != len(set(selected)) or not set(selected) <= set(applicable):
        raise ValueError('focused selection must name unique host-applicable targets')
    planned = {case['target']: {**case, 'core_provider': case.get('core_provider', 'rust')}
               for case in plan['cases']}
    missing = set(selected) - set(planned)
    if missing:
        raise ValueError('missing retained inputs for required offline targets: ' + ', '.join(sorted(missing)))
    if type(jobs) is not int or jobs < 1:
        raise ValueError('offline build concurrency must be positive')
    output = absolute(str(output), exists=False)
    if output.exists() or output.is_symlink():
        raise ValueError('offline acceptance output must be new')
    root = Path(root).resolve(strict=True)
    if root in output.parents and output.relative_to(root).parts[0] not in ('build', '.agent-work'):
        raise ValueError('offline output must not enter nonignored application source inputs')
    boundary = plan['isolation']
    if boundary['kind'] == 'namespace':
        rootfs = Path(boundary['rootfs'])
        if output == rootfs or rootfs in output.parents or output in rootfs.parents:
            raise ValueError('offline output and prepared rootfs must be disjoint')
    for target in selected:
        groups = [planned[target]['group']]
        if planned[target]['core_provider'] == 'rust':
            groups.append(planned[target]['rust_group'])
        for retained in groups:
            group = Path(retained)
            if group == output or group in output.parents or output in group.parents:
                raise ValueError('offline output and retained input roots must be disjoint')
    # Freeze inputs before launching any expensive work.
    verified = {target: verify_case(planned[target]) for target in selected}
    rust_groups = [Path(planned[target]['rust_group']) for target in selected
                   if planned[target]['core_provider'] == 'rust']
    rootfs_options = {'rust_group': rust_groups[0]} if rust_groups else {}
    if boundary['kind'] == 'docker':
        completed = subprocess.run(['docker', 'image', 'inspect', '--format', '{{.Id}}', boundary['image']],
                                   check=True, text=True, capture_output=True)
        if completed.stdout.strip() != boundary['image']:
            raise ValueError('prepared Docker image identity differs; pulling is forbidden')
    else:
        from offline_namespace import verify_rootfs
        prepared_rootfs = verify_rootfs(boundary, **rootfs_options)
    output.mkdir(parents=True)
    summary = {'schema_version': 1, 'status': 'failed', 'plan_sha256': digest(plan_path), 'isolation': boundary,
               'inventory_sha256': digest(INVENTORY), 'requested_targets': selected,
               'requested_providers': {target: planned[target]['core_provider'] for target in selected},
               'required_host_targets': applicable, 'complete_host_inventory': set(selected) == set(applicable),
               'unavailable_targets': sorted({item['target'] for item in inventory()['targets']} - set(applicable)),
               'cases': [], 'coverage': 'offline application build, core tests, package/installed consumer and native GUI smoke; browser security and full regressions separate'}
    try:
        if boundary['kind'] == 'namespace':
            write_new(output / 'prepared-rootfs.json', prepared_rootfs)
            shutil.copyfile(Path(boundary['manifest']).parent / prepared_rootfs['inventory'], output / 'prepared-rootfs-inventory.json')
            from offline_namespace import setup_program
            summary['namespace_setup_tools'] = {name: tool_identity(name, setup_program(name),
                                                                    ('-Version',) if name == 'ip' else ('--version',))
                                                 for name in ('unshare', 'mount', 'chroot', 'ip')}
            summary['namespace_setup_tools']['python'] = tool_identity('python', sys.executable)
        source = output / 'source'
        source_identity = snapshot(root, source)
        summary['source_tree_sha256'] = source_identity['tree_sha256']
        if (Path(root) / '.git').exists():
            summary['source_commit'] = subprocess.check_output(['git', '-C', str(root), 'rev-parse', 'HEAD'], text=True).strip()
            summary['source_diff_sha256'] = hashlib.sha256(subprocess.check_output(['git', '-C', str(root), 'diff', '--binary', 'HEAD'])).hexdigest()
        write_new(output / 'plan.json', plan)
        for target in selected:
            case_output = output / target
            case_output.mkdir()
            request = {'schema_version': 1, 'case': planned[target], 'group_files': verified[target]['files'],
                       'source_tree_sha256': source_identity['tree_sha256'], 'jobs': jobs}
            rust_group = None
            if 'rust' in verified[target]:
                request['rust_group_files'] = verified[target]['rust']['files']
                rust_group = Path(planned[target]['rust_group'])
            write_new(case_output / 'request.json', request)
            row = {'target': target, 'core_provider': planned[target]['core_provider'], 'status': 'failed'}
            summary['cases'].append(row)
            with (case_output / 'acceptance.log').open('xb') as log:
                if boundary['kind'] == 'docker':
                    for phase in ('stage', 'execute'):
                        argv = docker_phase(boundary, source, case_output, Path(planned[target]['group']), os.getuid(), os.getgid(), phase,
                                            **({'rust_group': rust_group} if rust_group is not None else {}))
                        subprocess.run(argv, check=True, stdout=log, stderr=subprocess.STDOUT)
                else:
                    from offline_namespace import command, setup_environment
                    argv = command(boundary, source, case_output, Path(planned[target]['group']),
                                   **({'rust_group': rust_group} if rust_group is not None else {}))
                    subprocess.run(argv, check=True, stdout=log, stderr=subprocess.STDOUT, env=setup_environment())
            result = read_json(case_output / 'execute.json')
            if result['status'] != 'passed':
                raise ValueError('isolated offline acceptance did not pass')
            row.update(status='passed', evidence=str((case_output / 'execute.json').relative_to(output)))
        if boundary['kind'] == 'namespace':
            # A read-only bind protects the child, not a separate host writer.
            # Refuse success if prepared bytes changed outside the namespace.
            verify_rootfs(boundary, **rootfs_options)
            summary['rootfs_recheck'] = 'passed'
        for target in selected:
            retained_groups = [(Path(planned[target]['group']), verified[target]['files'])]
            if 'rust' in verified[target]:
                retained_groups.append((Path(planned[target]['rust_group']), verified[target]['rust']['files']))
            for group, expected in retained_groups:
                if (group.is_symlink() or not group.is_dir() or {path.name for path in group.iterdir()} != set(expected)
                        or any((group / name).is_symlink() or not (group / name).is_file() for name in expected)
                        or {name: digest(group / name) for name in expected} != expected):
                    raise ValueError('retained group changed outside the boundary before acceptance completion')
        from source_identity import source_tree
        if source_tree(source) != source_identity:
            raise ValueError('frozen source changed before acceptance completion')
        summary['input_recheck'] = 'passed'
        summary['status'] = 'passed'
        return summary
    except BaseException as error:
        summary['error'] = str(error)[:4096]
        raise
    finally:
        write_new(output / 'acceptance.json', summary)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', nargs='?', choices=('run',), default='run')
    parser.add_argument('--plan', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--case', action='append', dest='cases')
    parser.add_argument('--jobs', type=int, default=2)
    parser.add_argument('--inside', choices=('stage', 'execute'), help=argparse.SUPPRESS)
    parser.add_argument('--request', type=Path, help=argparse.SUPPRESS)
    parser.add_argument('--probe', action='store_true', help=argparse.SUPPRESS)
    args = parser.parse_args(argv)
    if args.probe:
        print(json.dumps(isolation_probe(child=True)))
    elif args.inside:
        if args.request != Path('/output/request.json'):
            raise ValueError('isolated acceptance needs its explicit projected request')
        inside(args.inside, args.request)
    else:
        if not args.plan or not args.output:
            parser.error('run requires --plan and --output absolute paths')
        print(json.dumps(run(args.plan, args.output, args.cases, args.jobs), indent=2))
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError, subprocess.CalledProcessError) as error:
        print('offline acceptance: ' + str(error), file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Install complete, locally verified dependency notices beside application files."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import tempfile


# Existing retained SDK manifests authenticate these bytes but older license
# inventories list only the top-level tool and Node notices. Include the complete
# target runtime terms without changing or rebuilding the immutable SDK.
WASM_RUNTIME_NOTICES = (
    'upstream/emscripten/AUTHORS',
    'upstream/emscripten/system/lib/libc/musl/COPYRIGHT',
    'upstream/emscripten/system/lib/libcxx/LICENSE.TXT',
    'upstream/emscripten/system/lib/libcxxabi/LICENSE.TXT',
    'upstream/emscripten/system/lib/compiler-rt/LICENSE.TXT',
    'upstream/emscripten/system/lib/libunwind/LICENSE.TXT',
    # This source file contains its dedication; there is no separate license file.
    'upstream/emscripten/system/lib/dlmalloc.c',
)


def sha(path):
    result = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            result.update(block)
    return result.hexdigest()


def regular(path, root=None):
    path = Path(path)
    actual = path.resolve(strict=True)
    if not actual.is_file() or (root is not None and Path(root).resolve() not in actual.parents):
        raise ValueError('notice input is not a contained regular file: ' + str(path))
    return actual


def command(*args):
    return subprocess.check_output(args, text=True, encoding='utf-8', errors='strict').strip()


def distro_notice(library, share=Path('/usr/share'), query=command):
    library = regular(library)
    try:
        owner = query('dpkg-query', '-S', str(library))
    except subprocess.CalledProcessError:
        if not str(library).startswith('/usr/'):
            owner = query('dpkg-query', '-S', '/usr' + str(library))
        else:
            raise ValueError('dependency has no local notice provider; supply an explicit manifest')
    rows = owner.splitlines()
    if len(rows) != 1 or ': ' not in rows[0]:
        raise ValueError('dependency package ownership is ambiguous')
    package, owned = rows[0].rsplit(': ', 1)
    if not re.fullmatch(r'[a-z0-9][a-z0-9+.-]*(?::[a-z0-9]+)?', package):
        raise ValueError('unrecognized dependency package identity')
    if Path(owned).resolve(strict=True) != library:
        raise ValueError('package ownership names a different dependency')
    version = query('dpkg-query', '-W', '-f=${Version}', package)
    if not version or '\n' in version:
        raise ValueError('dependency package version is unavailable')
    name = package.split(':')[0]
    return {'provider': 'debian-package', 'package': package, 'version': version,
            'input': {'name': library.name, 'sha256': sha(library)}}, regular(Path(share) / 'doc' / name / 'copyright')


def notice_files(path):
    path = Path(path)
    if path.is_file():
        return [regular(path)]
    if not path.is_dir() or path.is_symlink():
        raise ValueError('dependency notice tree is unavailable')
    result = []
    for entry in sorted(path.rglob('*')):
        if entry.is_symlink():
            # SDK producers materialize links; a changed tree must not leak host files.
            raise ValueError('dependency notice tree contains a link')
        if entry.is_file(): result.append(regular(entry, path))
        elif not entry.is_dir(): raise ValueError('dependency notice tree contains a special entry')
    if not result: raise ValueError('dependency notice tree is empty')
    return result


def manual_components(path):
    if path is None: return {}
    data = json.loads(Path(path).read_text(encoding='utf-8'))
    if set(data) != {'schema_version', 'components'} or data['schema_version'] != 1:
        raise ValueError('invalid explicit dependency notice manifest')
    result = {}
    for item in data['components']:
        if set(item) != {'name', 'inputs', 'notices'} or not item['name'] or not item['inputs'] or not item['notices']:
            raise ValueError('incomplete explicit dependency notice component')
        files = []
        for relative, expected in item['notices'].items():
            source = Path(path).resolve().parent / relative
            if source.is_absolute() and Path(relative).is_absolute():
                raise ValueError('explicit notices use contained relative paths')
            source = regular(source, Path(path).resolve().parent)
            if sha(source) != expected: raise ValueError('explicit notice digest differs')
            files.append(source)
        for identity in item['inputs']:
            if not re.fullmatch('[0-9a-f]{64}', identity) or identity in result:
                raise ValueError('invalid or duplicate explicit dependency identity')
            result[identity] = (item['name'], files)
    return result


def collect(destination, *, sdk=None, windows_dependencies=None, libraries=(), files=(), manifest=None,
            share=Path('/usr/share'), query=command, runtime_inventory=None, runtime_roots=()):
    destination = Path(destination).absolute()
    if destination.is_symlink() or (destination.exists() and not destination.is_dir()):
        raise ValueError('dependency notice destination must be an ordinary directory')
    libraries = list(libraries)
    if runtime_inventory and not (sdk or windows_dependencies):
        runtime = json.loads(Path(runtime_inventory).read_text(encoding='utf-8'))
        for name, expected in runtime['files'].items():
            if Path(name).name != name: raise ValueError('invalid runtime notice inventory name')
            candidates = []
            for root in map(Path, runtime_roots):
                for path in root.rglob(name):
                    actual = regular(path, root)
                    if sha(actual) == expected: candidates.append(actual)
            if not candidates: raise ValueError('copied runtime notice input is unavailable: ' + name)
            libraries.append(sorted(set(candidates))[0])
    manual = manual_components(manifest)
    inputs, providers = [], []
    common_roots = [Path(share) / 'common-licenses']
    if sdk or windows_dependencies:
        from sdk_manifest import verify_sdk
        root = Path(sdk or windows_dependencies).resolve(strict=True)
        verify_sdk(root, release=True)
        data = json.loads((root / 'sdk.json').read_text(encoding='utf-8'))
        if windows_dependencies:
            inputs += sorted((root / 'prefix').glob('installed/*/share/*/copyright'))
            inputs += sorted((root / 'prefix').glob('share/*/copyright'))
            ports = data.get('provenance', {}).get('ports', [])
            triplet = data.get('provenance', {}).get('triplet', '')
            for port in ports:
                name = port.split('[', 1)[0]
                notice = root / 'prefix/installed' / triplet / 'share' / name / 'copyright'
                if not notice.is_file(): raise ValueError('prepared dependency lacks its exported port notice: ' + name)
            inputs = [regular(path, root) for path in inputs]
            common_roots = [root / 'prefix/share/common-licenses']
        else:
            for relative in data['licenses']:
                tree = root / relative
                if root not in tree.resolve(strict=True).parents:
                    raise ValueError('SDK notice tree escapes its retained root')
                inputs += notice_files(tree)
            if data['target'].get('system') == 'Emscripten':
                for relative in WASM_RUNTIME_NOTICES:
                    path = regular(root / relative, root)
                    if relative not in data['files'] or sha(path) != data['files'][relative]:
                        raise ValueError('Wasm runtime notice differs from retained inventory: ' + relative)
                    inputs.append(path)
            common_roots = [root / data['target']['sysroot'] / 'usr/share/common-licenses']
        providers.append({'provider': 'retained-sdk', 'recipe_id': data['recipe_id'],
                          'manifest_sha256': sha(root / 'sdk.json')})
    else:
        for library in sorted(set(map(str, libraries))):
            library = regular(library)
            identity = sha(library)
            if identity in manual:
                name, paths = manual[identity]
                providers.append({'provider': 'explicit', 'name': name, 'input': {'name': library.name, 'sha256': identity}})
                inputs += paths
            else:
                provider, path = distro_notice(library, share, query)
                providers.append(provider)
                inputs.append(path)
    for path, expected in files:
        path = regular(path)
        if sha(path) != expected: raise ValueError('configured dependency notice changed')
        inputs.append(path)
    # Distro notices reference shared complete texts; never leave such references dangling.
    queue, resolved = list(inputs), {}
    while queue:
        path = regular(queue.pop())
        data = path.read_bytes()
        identity = hashlib.sha256(data).hexdigest()
        key = identity + '-' + re.sub(r'[^A-Za-z0-9._+-]', '_', path.name)
        if key in resolved: continue
        resolved[key] = (path, data)
        for name in re.findall(rb'/usr/share/common-licenses/([A-Za-z0-9](?:[A-Za-z0-9.+-]*[A-Za-z0-9+])?)', data):
            candidates = [base / name.decode('ascii') for base in common_roots]
            found = [regular(candidate, base) for candidate, base in zip(candidates, common_roots) if candidate.exists()]
            if len(found) != 1: raise ValueError('referenced common license is unavailable: ' + name.decode('ascii'))
            queue += found
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.notices-', dir=destination.parent) as temporary:
        stage = Path(temporary) / 'notices'; stage.mkdir(); stage.chmod(0o755)
        inventory = {}
        for name, (path, data) in sorted(resolved.items()):
            if path.read_bytes() != data: raise ValueError('dependency notice changed while copying')
            target = stage / name
            target.write_bytes(data); target.chmod(0o644)
            inventory[name] = {'sha256': hashlib.sha256(data).hexdigest(), 'size': len(data)}
        report = {'schema_version': 1, 'providers': providers, 'files': inventory}
        (stage / 'index.json').write_text(json.dumps(report, sort_keys=True, indent=2) + '\n', encoding='utf-8')
        (stage / 'index.json').chmod(0o644)
        if destination.exists():
            current = {p.name: p.read_bytes() for p in destination.iterdir() if p.is_file() and not p.is_symlink()}
            intended = {p.name: p.read_bytes() for p in stage.iterdir()}
            permissions_match = os.name != 'posix' or (
                destination.stat().st_mode & 0o777 == 0o755 and
                all(path.stat().st_mode & 0o777 == 0o644 for path in destination.iterdir()))
            if not permissions_match or len(current) != len(list(destination.iterdir())) or current != intended:
                raise ValueError('existing dependency notices differ; use a fresh installation prefix')
        else:
            stage.rename(destination)
    return report


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--output', required=True, type=Path)
    inputs = p.add_mutually_exclusive_group()
    inputs.add_argument('--sdk', type=Path)
    inputs.add_argument('--windows-dependencies', type=Path)
    p.add_argument('--library', action='append', default=[])
    p.add_argument('--file', nargs=2, action='append', default=[])
    p.add_argument('--manifest', type=Path)
    p.add_argument('--runtime-inventory', type=Path)
    p.add_argument('--runtime-root', type=Path, action='append', default=[])
    a = p.parse_args()
    print(json.dumps(collect(a.output, sdk=a.sdk, windows_dependencies=a.windows_dependencies,
                            libraries=a.library, files=a.file, manifest=a.manifest,
                            runtime_inventory=a.runtime_inventory, runtime_roots=a.runtime_root), sort_keys=True))


if __name__ == '__main__':
    try: main()
    except (OSError, ValueError, KeyError, subprocess.SubprocessError) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Package the generated, patched browser assets as one offline HTML application."""
import argparse
import base64
import hashlib
from html import escape
import json
from pathlib import Path
import re
import sys

TOOLS = Path(__file__).resolve().parent
if str(TOOLS) not in sys.path:
    sys.path.insert(0, str(TOOLS))
from package_notices import WASM_RUNTIME_NOTICES, notice_files
from sdk_manifest import verify_sdk
import browser_bundle

LEGACY_ASSETS = ('boot.mjs', 'renderer.mjs', 'browser_lifecycle.mjs', 'wasm_transport.mjs',
          'wasm_worker.mjs', 'browser_presenter.mjs', 'file_services.mjs', 'style.css', 'index.html', 'gui_web_wasm.js', 'gui_web_wasm.wasm')
MAX_ASSET = 64 * 1024 * 1024
MAX_TOTAL = 96 * 1024 * 1024
HTML_NAME = 'software-foundation-wasm.html'
LEGACY_CSP = ("default-src 'none'; script-src 'unsafe-inline' 'wasm-unsafe-eval' blob:; "
       "worker-src blob:; connect-src 'none'; style-src 'unsafe-inline'; "
       "img-src data: blob:; object-src 'none'; base-uri 'none'; form-action 'none'")
# Static module imports are rewritten only at these exact reviewed dependency edges.
LEGACY_IMPORTS = {'boot.mjs': ('renderer.mjs', 'browser_lifecycle.mjs', 'browser_presenter.mjs', 'wasm_transport.mjs'),
           'renderer.mjs': ('file_services.mjs',)}

# Schemas 1/2 retain their original inventory and policy. The schema-3 document
# adds an isolated renderer composition while preserving the standalone entry.
ASSETS = LEGACY_ASSETS + ('browser_limits.mjs', 'browser_client.mjs', 'browser_services.mjs', 'browser_composition.mjs',
                         'renderer_dom.mjs', 'renderer_channel.mjs', 'renderer_frame.mjs',
                         'browser_embedding.mjs', browser_bundle.BUNDLE_NAME)
CSP = LEGACY_CSP + "; frame-src 'self' blob:"
IMPORTS = {
    'boot.mjs': ('browser_embedding.mjs', 'browser_services.mjs', 'browser_composition.mjs', 'renderer.mjs', 'browser_lifecycle.mjs',
                 'browser_presenter.mjs', 'wasm_transport.mjs'),
    'renderer.mjs': ('renderer_dom.mjs', 'browser_client.mjs', 'browser_services.mjs'),
    'browser_client.mjs': ('browser_limits.mjs', 'browser_limits.mjs'),
    'browser_services.mjs': ('file_services.mjs',),
    'browser_embedding.mjs': ('browser_client.mjs', 'browser_services.mjs', 'browser_lifecycle.mjs',
                             'renderer_channel.mjs', 'browser_limits.mjs', browser_bundle.BUNDLE_NAME),
    **browser_bundle.CHILD_GRAPH,
}


def child_metadata(blobs):
    metadata = browser_bundle.assemble({name: blobs[name] for name in browser_bundle.CHILD_MODULES + ('style.css',)})
    if blobs[browser_bundle.BUNDLE_NAME] != browser_bundle.module_bytes(metadata):
        raise ValueError('Generated child bundle differs from reviewed renderer inputs')
    return {'protocol': metadata['CHILD_PROTOCOL'], 'sandbox': metadata['CHILD_SANDBOX'],
            'csp': metadata['CHILD_CSP'], 'script_sha256': digest(metadata['CHILD_SCRIPT'].encode('utf-8')),
            'script_csp_sha256': metadata['CHILD_SCRIPT_SHA256'], 'inputs': metadata['CHILD_INPUTS']}


def classic_worker_source(data):
    """Adapt only the reviewed self-installing Worker entry for local files.

    Chromium rejects a module Blob Worker created by a file document before its
    entry point runs. A classic entry retains the existing Worker-owned dynamic
    factory import. No general module transform or runtime fallback is allowed.
    """
    source = data.decode('utf-8')
    declaration = 'export function installWasmWorker(scope,loadModule=url=>import(url))'
    if (source.count(declaration) != 1 or len(re.findall(r'\bexport\b', source)) != 1 or
            len(re.findall(r'\bimport\b', source)) != 1):
        raise ValueError('Unexpected embedded Worker module syntax')
    declaration_offset = source.index(declaration)
    import_offset = declaration_offset + declaration.index('import(url)')
    if browser_bundle._keywords(source) != [(declaration_offset, 'export'), (import_offset, 'import')]:
        raise ValueError('Unexpected embedded Worker module syntax')
    # Modules are implicitly strict. Preserve that semantic mode in the classic
    # entry instead of relying on the current body to avoid sloppy behavior.
    return '"use strict";\n' + source[:declaration_offset] + source[declaration_offset:].replace('export ', '', 1)


def make_html(blobs, notices):
    if set(blobs) != set(ASSETS) or sum(map(len, blobs.values())) > MAX_TOTAL:
        raise ValueError('Invalid browser asset inventory or size')
    if not blobs['gui_web_wasm.wasm'].startswith(b'\0asm\x01\0\0\0'):
        raise ValueError('Invalid Wasm module header')
    for name in ASSETS:
        if name.endswith(('.mjs', '.js', '.css', '.html')):
            blobs[name].decode('utf-8')
    child_metadata(blobs)
    worker_source = classic_worker_source(blobs['wasm_worker.mjs'])
    for module, dependencies in IMPORTS.items():
        source = blobs[module].decode('utf-8')
        discovered = re.findall(r"['\"]\./([A-Za-z0-9_.-]+\.mjs)['\"]", source)
        if sorted(discovered) != sorted(dependencies):
            raise ValueError('Generated module dependency changed: ' + module)
    shell = blobs['index.html'].decode('utf-8')
    style_link = '<link rel="stylesheet" href="/style.css">'
    script_link = '<script type="module" src="/boot.mjs"></script>'
    if shell.count(style_link) != 1 or shell.count(script_link) != 1 or shell.count('<meta charset="utf-8">') != 1:
        raise ValueError('Generated HTML entry point changed')
    if len(re.findall(r'<script\b', shell, re.I)) != 1:
        raise ValueError('Generated HTML has an unexpected script entry point')
    style = blobs['style.css'].decode('utf-8')
    if '</style' in style.lower():
        raise ValueError('Unsafe style terminator')
    # Include original shell/style bytes too, so verification can regenerate and
    # compare the complete canonical document instead of trusting outer hashes.
    payload = {name: base64.b64encode(data).decode('ascii') for name, data in sorted(blobs.items())}
    bootstrap = '''
const assets=JSON.parse(document.querySelector('#foundation-assets').textContent);
const bytes=name=>Uint8Array.from(atob(assets[name]),c=>c.charCodeAt(0));
const text=name=>new TextDecoder('utf-8',{fatal:true}).decode(bytes(name));
const urls=[];
const local=source=>{const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));urls.push(url);return url;};
try{
  const dependencies=DEPENDENCY_GRAPH;
  const modules=new Map();
  const moduleURL=name=>{
    if(modules.has(name))return modules.get(name);
    let source=text(name);
    for(const dependency of dependencies[name]||[]){
      const target=JSON.stringify(moduleURL(dependency));
      source=source.replace("'./"+dependency+"'",target).replace('"./'+dependency+'"',target);
    }
    const url=local(source);modules.set(name,url);return url;
  };
  const workerSource=new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(CLASSIC_WORKER_SOURCE),c=>c.charCodeAt(0)));
  globalThis.foundationWasmAssets={workerURL:local(workerSource),workerFactory:url=>new Worker(url,{type:'classic'}),moduleURL:'embedded',
    factorySource:text('gui_web_wasm.js'),wasmBinary:bytes('gui_web_wasm.wasm')};
  await import(moduleURL('boot.mjs'));
}catch(error){document.querySelector('#status').textContent='Could not start: '+error.message;}
finally{delete globalThis.foundationWasmAssets;for(const url of urls)URL.revokeObjectURL(url);}
'''.replace('DEPENDENCY_GRAPH', json.dumps(IMPORTS, separators=(',', ':'))).replace(
        'CLASSIC_WORKER_SOURCE', json.dumps(base64.b64encode(worker_source.encode('utf-8')).decode('ascii')))
    content = ('<script type="application/json" id="foundation-assets">' + json.dumps(payload, separators=(',', ':')) + '</script>' +
               '<script type="application/json" id="foundation-notices">' +
               json.dumps({name: base64.b64encode(data).decode('ascii') for name, data in sorted(notices.items())}, separators=(',', ':')) + '</script>' +
               '<details id="foundation-notices-text"><summary>Software licenses and notices</summary><pre>' +
               escape('\n\n'.join(name + '\n' + data.decode('utf-8') for name, data in sorted(notices.items()))) +
               '</pre></details><script type="module">' + bootstrap + '</script>')
    return (shell.replace('<meta charset="utf-8">', '<meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="' + escape(CSP, quote=True) + '">')
            .replace(style_link, '<style>' + style + '</style>').replace(script_link, content)).encode('utf-8')


def read_file(path, limit=MAX_ASSET):
    if path.is_symlink() or not path.is_file():
        raise ValueError('Expected ordinary asset: ' + str(path))
    if path.stat().st_size > limit:
        raise ValueError('Asset exceeds limit: ' + str(path))
    return path.read_bytes()


def digest(data):
    return hashlib.sha256(data).hexdigest()


def make_legacy_html(blobs, notices):
    if set(blobs) != set(LEGACY_ASSETS) or sum(map(len, blobs.values())) > MAX_TOTAL:
        raise ValueError('Invalid browser asset inventory or size')
    if not blobs['gui_web_wasm.wasm'].startswith(b'\0asm\x01\0\0\0'):
        raise ValueError('Invalid Wasm module header')
    for name in LEGACY_ASSETS:
        if name.endswith(('.mjs', '.js', '.css', '.html')):
            blobs[name].decode('utf-8')
    for module, dependencies in LEGACY_IMPORTS.items():
        source = blobs[module].decode('utf-8')
        for name in dependencies:
            if source.count("'./" + name + "'") != 1:
                raise ValueError('Generated module dependency changed: ' + module + ' -> ' + name)
    shell = blobs['index.html'].decode('utf-8')
    style_link = '<link rel="stylesheet" href="/style.css">'
    script_link = '<script type="module" src="/boot.mjs"></script>'
    if shell.count(style_link) != 1 or shell.count(script_link) != 1 or shell.count('<meta charset="utf-8">') != 1:
        raise ValueError('Generated HTML entry point changed')
    style = blobs['style.css'].decode('utf-8')
    if '</style' in style.lower():
        raise ValueError('Unsafe style terminator')
    payload = {name: base64.b64encode(data).decode('ascii') for name, data in blobs.items()
               if name not in ('index.html', 'style.css')}
    bootstrap = '''
const assets=JSON.parse(document.querySelector('#foundation-assets').textContent);
const bytes=name=>Uint8Array.from(atob(assets[name]),c=>c.charCodeAt(0));
const text=name=>new TextDecoder('utf-8',{fatal:true}).decode(bytes(name));
const urls=[];
const local=source=>{const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));urls.push(url);return url;};
try{
  const dependencies=DEPENDENCY_GRAPH;
  const modules=new Map();
  const moduleURL=name=>{
    if(modules.has(name))return modules.get(name);
    let source=text(name);
    for(const dependency of dependencies[name]||[])
      source=source.replace("'./"+dependency+"'",JSON.stringify(moduleURL(dependency)));
    const url=local(source);modules.set(name,url);return url;
  };
  globalThis.foundationWasmAssets={workerURL:local(text('wasm_worker.mjs')),moduleURL:'embedded',
    factorySource:text('gui_web_wasm.js'),wasmBinary:bytes('gui_web_wasm.wasm')};
  await import(moduleURL('boot.mjs'));
}catch(error){document.querySelector('#status').textContent='Could not start: '+error.message;}
finally{delete globalThis.foundationWasmAssets;for(const url of urls)URL.revokeObjectURL(url);}
'''
    bootstrap = bootstrap.replace('DEPENDENCY_GRAPH', json.dumps(LEGACY_IMPORTS, separators=(',', ':')))
    content = ('<script type="application/json" id="foundation-assets">' +
               json.dumps(payload, separators=(',', ':')) + '</script>' +
               '<script type="application/json" id="foundation-notices">' +
               json.dumps({name: base64.b64encode(data).decode('ascii') for name, data in sorted(notices.items())}, separators=(',', ':')) + '</script>' +
               '<details id="foundation-notices-text"><summary>Software licenses and notices</summary><pre>' +
               escape('\n\n'.join(name + '\n' + data.decode('utf-8') for name, data in sorted(notices.items()))) +
               '</pre></details><script type="module">' + bootstrap + '</script>')
    return (shell.replace('<meta charset="utf-8">', '<meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="' + escape(LEGACY_CSP, quote=True) + '">')
            .replace(style_link, '<style>' + style + '</style>').replace(script_link, content)).encode('utf-8')


def sdk_notices(root):
    root = Path(root).resolve(strict=True)
    verify_sdk(root, release=True)
    manifest = json.loads(read_file(root / 'sdk.json'))
    if manifest['target']['system'] != 'Emscripten':
        raise ValueError('Offline Wasm package requires an Emscripten SDK')
    inputs = []
    for relative in manifest['licenses']:
        tree = root / relative
        if root not in tree.resolve(strict=True).parents:
            raise ValueError('SDK notice escapes retained root')
        inputs.extend(notice_files(tree))
    inputs.extend(root / name for name in WASM_RUNTIME_NOTICES)
    paths = sorted(set(inputs))
    for path in paths:
        relative = path.relative_to(root).as_posix()
        if manifest['files'].get(relative) != digest(read_file(path)):
            raise ValueError('SDK runtime notice differs from retained inventory: ' + relative)
    return ['sdk-' + str(index) + '=' + str(path) for index, path in enumerate(paths)], {
        'manifest_sha256': digest(read_file(root / 'sdk.json')), 'recipe_id': manifest['recipe_id']}


def package(assets, output, notice_paths, module_dir=None, sdk=None, source_root=None):
    assets, output = Path(assets), Path(output)
    if not notice_paths:
        raise ValueError('At least one applicable license notice is required')
    notice_paths = list(notice_paths)
    sdk_identity = None
    if sdk is not None:
        extra, sdk_identity = sdk_notices(sdk)
        notice_paths.extend(extra)
    notices = {}
    for item in notice_paths:
        label, raw = str(item).split('=', 1) if '=' in str(item) else (Path(item).name, str(item))
        if not re.fullmatch(r'[A-Za-z0-9_.-]+', label) or label in ('.', '..'):
            raise ValueError('Invalid notice label')
        if label in notices:
            raise ValueError('Duplicate notice label: ' + label)
        notices[label] = read_file(Path(raw))
    if sum(map(len, notices.values())) > 4 * 1024 * 1024:
        raise ValueError('Notices exceed limit')
    blobs = {name: read_file((Path(module_dir) if module_dir and name.startswith('gui_web_wasm.') else assets) / name) for name in ASSETS}
    html = make_html(blobs, notices)
    manifest = {'schema': 3, 'runtime': 'dedicated-worker', 'transport': 'ordered-local-messages',
                'network': 'disabled-by-csp', 'csp': CSP,
                'renderer_modes': ['standalone', 'isolated'], 'child': child_metadata(blobs),
                'inputs': {name: digest(data) for name, data in sorted(blobs.items())},
                'notices': {name: digest(data) for name, data in sorted(notices.items())},
                'html_sha256': digest(html)}
    if source_root is not None:
        from source_identity import source_tree
        manifest['source_tree_sha256'] = source_tree(source_root)['tree_sha256']
    if sdk_identity is not None:
        manifest['sdk'] = sdk_identity
    if output.is_symlink():
        raise ValueError('Output must be an ordinary directory')
    output.mkdir(parents=True, exist_ok=True)
    expected = {HTML_NAME, 'web-manifest.json', 'manifest.sha256'}
    if any(p.name not in expected or not p.is_file() or p.is_symlink() for p in output.iterdir()):
        raise ValueError('Output contains unexpected entries')
    (output / HTML_NAME).write_bytes(html)
    # These files have byte identities; host text-mode newline translation must
    # not change either the metadata or the portable checksum grammar.
    (output / 'web-manifest.json').write_bytes((json.dumps(manifest, indent=2, sort_keys=True) + '\n').encode('utf-8'))
    (output / 'manifest.sha256').write_bytes(''.join(digest(read_file(output / name, 256 * 1024 * 1024)) + '  ' + name + '\n'
                                                for name in sorted(expected - {'manifest.sha256'})).encode('utf-8'))
    verify(output)
    return manifest


def verify(output):
    output = Path(output)
    if output.is_symlink() or set(p.name for p in output.iterdir()) != {HTML_NAME, 'web-manifest.json', 'manifest.sha256'}:
        raise ValueError('Incomplete or unexpected package inventory')
    manifest = json.loads(read_file(output / 'web-manifest.json'))
    schema = manifest.get('schema')
    if type(schema) is not int or schema not in (1, 2, 3):
        raise ValueError('Package manifest mismatch')
    if schema in (1, 2):
        return verify_legacy(output)
    html = read_file(output / HTML_NAME, 256 * 1024 * 1024)
    if manifest.get('csp') != CSP or manifest.get('html_sha256') != digest(html):
        raise ValueError('Package manifest mismatch')
    source_identity = manifest.get('source_tree_sha256')
    if 'source_tree_sha256' in manifest and (not isinstance(source_identity, str) or not re.fullmatch(r'[0-9a-f]{64}', source_identity)):
        raise ValueError('Package source identity missing or invalid')
    expected = ''.join(digest(read_file(output / name, 256 * 1024 * 1024)) + '  ' + name + '\n'
                       for name in sorted((HTML_NAME, 'web-manifest.json')))
    if read_file(output / 'manifest.sha256').decode('utf-8') != expected:
        raise ValueError('Package checksum mismatch')
    text = html.decode('utf-8')
    if re.search(r'<script\b[^>]*\bsrc\s*=', text, re.I):
        raise ValueError('Package has an external entry point')
    payloads = re.findall(r'<script type="application/json" id="foundation-assets">([^<]*)</script>', text)
    if len(payloads) != 1:
        raise ValueError('Missing embedded asset inventory')
    payload = json.loads(payloads[0])
    if not isinstance(payload, dict) or set(payload) != set(ASSETS) or set(manifest.get('inputs', {})) != set(ASSETS):
        raise ValueError('Embedded asset inventory mismatch')
    blobs = {}
    for name, encoded in payload.items():
        if not isinstance(encoded, str):
            raise ValueError('Invalid embedded asset encoding')
        blobs[name] = base64.b64decode(encoded, validate=True)
        if len(blobs[name]) > MAX_ASSET or digest(blobs[name]) != manifest['inputs'][name]:
            raise ValueError('Embedded asset digest mismatch: ' + name)
    notice_payloads = re.findall(r'<script type="application/json" id="foundation-notices">([^<]*)</script>', text)
    if len(notice_payloads) != 1:
        raise ValueError('Missing embedded notices')
    encoded_notices = json.loads(notice_payloads[0])
    if not isinstance(encoded_notices, dict) or not encoded_notices or set(encoded_notices) != set(manifest.get('notices', {})):
        raise ValueError('Embedded notice inventory mismatch')
    notices = {}
    for name, encoded in encoded_notices.items():
        if not re.fullmatch(r'[A-Za-z0-9_.-]+', name) or name in ('.', '..') or not isinstance(encoded, str):
            raise ValueError('Invalid embedded notice label or encoding')
        notices[name] = base64.b64decode(encoded, validate=True)
        if digest(notices[name]) != manifest['notices'][name]:
            raise ValueError('Embedded notice digest mismatch')
    if sum(map(len, notices.values())) > 4 * 1024 * 1024:
        raise ValueError('Embedded notices exceed limit')
    if (manifest.get('runtime') != 'dedicated-worker' or manifest.get('transport') != 'ordered-local-messages' or
            manifest.get('network') != 'disabled-by-csp' or manifest.get('renderer_modes') != ['standalone', 'isolated']):
        raise ValueError('Package runtime/renderer metadata mismatch')
    if manifest.get('child') != child_metadata(blobs):
        raise ValueError('Package child isolation metadata mismatch')
    if html != make_html(blobs, notices):
        raise ValueError('Package document differs from canonical embedded inputs')
    return manifest


def verify_legacy(output):
    output = Path(output)
    if output.is_symlink() or set(p.name for p in output.iterdir()) != {HTML_NAME, 'web-manifest.json', 'manifest.sha256'}:
        raise ValueError('Incomplete or unexpected package inventory')
    html = read_file(output / HTML_NAME, 256 * 1024 * 1024)
    manifest = json.loads(read_file(output / 'web-manifest.json'))
    if manifest.get('schema') not in (1, 2) or manifest.get('csp') != LEGACY_CSP or manifest.get('html_sha256') != digest(html):
        raise ValueError('Package manifest mismatch')
    if manifest['schema'] == 2 and not re.fullmatch(r'[0-9a-f]{64}', manifest.get('source_tree_sha256', '')):
        raise ValueError('Package source identity missing or invalid')
    expected = ''.join(digest(read_file(output / name, 256 * 1024 * 1024)) + '  ' + name + '\n' for name in sorted((HTML_NAME, 'web-manifest.json')))
    if read_file(output / 'manifest.sha256').decode('utf-8') != expected:
        raise ValueError('Package checksum mismatch')
    text = html.decode('utf-8')
    if escape(LEGACY_CSP, quote=True) not in text or re.search(r'<script\b[^>]*\bsrc\s*=', text, re.I):
        raise ValueError('Package has an external entry point')
    payloads = re.findall(r'<script type="application/json" id="foundation-assets">([^<]*)</script>', text)
    if len(payloads) != 1:
        raise ValueError('Missing embedded asset inventory')
    payload = json.loads(payloads[0])
    expected_names = set(LEGACY_ASSETS) - {'index.html', 'style.css'}
    if set(payload) != expected_names or set(manifest.get('inputs', {})) != set(LEGACY_ASSETS):
        raise ValueError('Embedded asset inventory mismatch')
    for name, encoded in payload.items():
        data = base64.b64decode(encoded, validate=True)
        if len(data) > MAX_ASSET or digest(data) != manifest['inputs'][name]:
            raise ValueError('Embedded asset digest mismatch: ' + name)
    styles = re.findall(r'<style>(.*?)</style>', text, re.S)
    if len(styles) != 1 or digest(styles[0].encode('utf-8')) != manifest['inputs']['style.css']:
        raise ValueError('Embedded style digest mismatch')
    notice_payloads = re.findall(r'<script type="application/json" id="foundation-notices">([^<]*)</script>', text)
    if len(notice_payloads) != 1:
        raise ValueError('Missing embedded notices')
    encoded_notices = json.loads(notice_payloads[0])
    if not isinstance(encoded_notices, dict) or not encoded_notices or set(encoded_notices) != set(manifest.get('notices', {})):
        raise ValueError('Embedded notice inventory mismatch')
    notices = {}
    for name, encoded in encoded_notices.items():
        if not re.fullmatch(r'[A-Za-z0-9_.-]+', name) or name in ('.', '..'):
            raise ValueError('Invalid embedded notice label')
        notices[name] = base64.b64decode(encoded, validate=True)
        if digest(notices[name]) != manifest['notices'][name]:
            raise ValueError('Embedded notice digest mismatch')
    if sum(map(len, notices.values())) > 4 * 1024 * 1024:
        raise ValueError('Embedded notices exceed limit')
    visible_notices = ('<details id="foundation-notices-text"><summary>Software licenses and notices</summary><pre>' +
                       escape('\n\n'.join(name + '\n' + data.decode('utf-8') for name, data in sorted(notices.items()))) + '</pre></details>')
    if text.count(visible_notices) != 1:
        raise ValueError('Visible notice content differs')
    if not manifest.get('notices') or manifest.get('runtime') != 'dedicated-worker' or manifest.get('transport') != 'ordered-local-messages' or manifest.get('network') != 'disabled-by-csp':
        raise ValueError('Package runtime/notice metadata mismatch')
    return manifest


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--assets', type=Path)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--notice', action='append', default=[], help='Applicable notice path or unique-label=path')
    parser.add_argument('--module-dir', type=Path, help='Directory containing compiled gui_web_wasm.js/.wasm')
    parser.add_argument('--sdk', type=Path, help='Verified retained Emscripten SDK including complete runtime notices')
    parser.add_argument('--verify', action='store_true')
    parser.add_argument('--source-root', type=Path, help='Bind the package to the complete application source tree')
    args = parser.parse_args(argv)
    if args.verify:
        verify(args.output)
    elif args.assets:
        package(args.assets, args.output, args.notice, args.module_dir, args.sdk, args.source_root)
    else:
        parser.error('--assets is required for packaging')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Prepare an offline native development prefix from explicit retained Debian inputs."""
import argparse
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import subprocess
import tarfile
import tempfile
import urllib.request


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''): h.update(block)
    return h.hexdigest()


def run(*args):
    return subprocess.check_output(args, text=True, encoding='utf-8').strip()


def relative(name):
    p = PurePosixPath(name)
    if not name or p.is_absolute() or str(p) != name or any(x in ('', '.', '..') for x in p.parts) or '\\' in name:
        raise ValueError('invalid retained development path')
    return p


def runtimes(data):
    if run('dpkg', '--print-architecture') != data['architecture']:
        raise ValueError('native development prefix architecture differs from host')
    versions = {p['package']: p['version'] for p in data['packages']}
    found = {}
    for item in data['runtime_libraries']:
        package = item['package'] + ':' + data['architecture']
        version = run('dpkg-query', '-W', '-f=${Version}', package)
        if version != versions[item['development']]: raise ValueError('installed runtime and development package versions differ')
        candidates = [Path(p).resolve(strict=True) for p in run('dpkg-query', '-L', package).splitlines()
                      if Path(p).name == item['soname'] and Path(p).is_file()]
        if len(set(candidates)) != 1: raise ValueError('runtime provider is absent or ambiguous')
        link = str(relative(item['link']));source = candidates[0]
        if link in found: raise ValueError('duplicate runtime link')
        found[link] = {'package': package, 'version': version, 'path': str(source), 'sha256': digest(source)}
    return found


def inventory(root, runtime):
    result = {}
    for path in sorted(Path(root).rglob('*')):
        name = path.relative_to(root).as_posix()
        if name == 'prepared.json': continue
        if path.is_symlink():
            actual = path.resolve(strict=True)
            if name in runtime:
                if str(actual) != runtime[name]['path'] or digest(actual) != runtime[name]['sha256']:
                    raise ValueError('prepared runtime alias changed')
            elif Path(root).resolve() not in actual.parents:
                raise ValueError('development alias escapes its prepared tree')
            result[name] = {'link': os.readlink(path)}
        elif path.is_file(): result[name] = {'sha256': digest(path)}
        elif not path.is_dir(): raise ValueError('unsupported development prefix entry')
    return result


def extract_deb(archive, stage):
    # Read metadata before extraction; never ask dpkg to follow archive paths.
    raw = subprocess.check_output(['dpkg-deb', '--fsys-tarfile', str(archive)])
    with tarfile.open(fileobj=io.BytesIO(raw)) as tar:
        members, entries = [], {}
        for member in tar:
            name = member.name.removeprefix('./').rstrip('/')
            if not name: continue
            name = str(relative(name)); member.name = name
            if name.split('/',1)[0] in ('prepared.json','inputs.json','retained-packages'):
                raise ValueError('development archive collides with preparation metadata')
            if member.mode & 0o7000 or not (member.isdir() or member.isfile() or member.issym()):
                raise ValueError('unsupported development archive entry')
            if name in entries and not (member.isdir() and entries[name].isdir()):
                raise ValueError('duplicate development archive member')
            entries[name] = member; members.append(member)
        for name, member in entries.items():
            for parent in PurePosixPath(name).parents:
                if str(parent) in entries and not entries[str(parent)].isdir():
                    raise ValueError('development archive traverses a non-directory')
            target = stage / name
            if any(p.is_symlink() for p in (target,*target.parents) if p != stage and stage in p.parents):
                raise ValueError('development archive traverses a previous alias')
            if target.exists() and not (target.is_dir() and member.isdir()):
                if member.isfile() and target.is_file() and target.read_bytes() == tar.extractfile(member).read(): continue
                raise ValueError('development archives conflict')
            target.parent.mkdir(parents=True, exist_ok=True)
            if member.isdir(): target.mkdir(exist_ok=True)
            elif member.issym(): target.symlink_to(member.linkname)
            else:
                with tar.extractfile(member) as source, target.open('xb') as out: shutil.copyfileobj(source, out)
                target.chmod(0o755 if member.mode & 0o111 else 0o644)


def prepare(manifest, packages, output, download=False):
    manifest, packages, output = Path(manifest).resolve(strict=True), Path(packages).absolute(), Path(output).absolute()
    data = json.loads(manifest.read_text(encoding='utf-8'))
    if data.get('schema_version') != 1 or not data.get('packages') or not re.fullmatch('[a-z0-9]+', data.get('architecture','')):
        raise ValueError('invalid pinned development manifest')
    if output.exists() or output.is_symlink(): raise ValueError('prepared development destination must be new')
    runtime = runtimes(data)
    packages.mkdir(parents=True, exist_ok=True)
    names, identities = set(), set()
    for item in data['packages']:
        name = item['file']
        if Path(name).name != name or not name.endswith('.deb') or name in names or not re.fullmatch('[0-9a-f]{64}', item['sha256']):
            raise ValueError('invalid pinned development archive')
        if item['package'] in identities or not re.fullmatch('[a-z0-9][a-z0-9+.-]*',item['package']):
            raise ValueError('duplicate or invalid development package identity')
        identities.add(item['package'])
        if item.get('architecture',data['architecture']) not in ('all',data['architecture']):
            raise ValueError('development package architecture differs from selected host')
        names.add(name);archive = packages / name
        if not archive.exists() and download:
            if not item['url'].startswith('https://deb.debian.org/debian/'):
                raise ValueError('unapproved development archive origin')
            with tempfile.NamedTemporaryFile(dir=packages, delete=False) as f: partial = Path(f.name)
            try:
                with urllib.request.urlopen(item['url'], timeout=60) as source, partial.open('wb') as out: shutil.copyfileobj(source,out)
                if digest(partial) != item['sha256']: raise ValueError('downloaded development checksum differs')
                if archive.exists(): raise ValueError('development archive appeared during fetch')
                partial.rename(archive)
            finally: partial.unlink(missing_ok=True)
        if not archive.is_file() or digest(archive) != item['sha256']: raise ValueError('missing or changed retained development archive')
        for field, expected in [('Package',item['package']),('Version',item['version']),('Architecture',item.get('architecture',data['architecture']))]:
            if run('dpkg-deb','-f',str(archive),field) != expected: raise ValueError('development package metadata differs: '+field)
        source = run('dpkg-deb','-f',str(archive),'Source').split(' ',1)[0] or item['package']
        if source != item['source_package']: raise ValueError('development source package identity differs')
    output.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='.development-',dir=output.parent) as temporary:
        stage=Path(temporary)/'prefix';stage.mkdir()
        for item in data['packages']: extract_deb(packages/item['file'],stage)
        if not (stage/'usr/include').is_dir(): raise ValueError('development prefix has no headers')
        for name, provider in runtime.items():
            path=stage/name
            if not path.is_symlink(): raise ValueError('declared runtime linker alias is missing')
            if any(parent.is_symlink() for parent in path.parents if stage in parent.parents): raise ValueError('runtime alias parent is a link')
            path.unlink();path.symlink_to(provider['path'])
        retained=stage/'retained-packages';retained.mkdir()
        for item in data['packages']: shutil.copyfile(packages/item['file'],retained/item['file'])
        shutil.copyfile(manifest,stage/'inputs.json')
        state={'schema_version':1,'manifest_sha256':digest(stage/'inputs.json'),'runtime_libraries':runtime,'files':inventory(stage,runtime)}
        (stage/'prepared.json').write_text(json.dumps(state,sort_keys=True,indent=2)+'\n',encoding='utf-8')
        verify(stage)
        stage.rename(output)
    return state


def verify(root, expected=None):
    root=Path(root).resolve(strict=True)
    if expected is not None and digest(root/'prepared.json') != expected:
        raise ValueError('configured development prefix identity changed')
    state=json.loads((root/'prepared.json').read_text(encoding='utf-8'))
    data=json.loads((root/'inputs.json').read_text(encoding='utf-8'))
    if state.get('schema_version')!=1 or state['manifest_sha256']!=digest(root/'inputs.json'):
        raise ValueError('prepared development manifest changed')
    if runtimes(data)!=state['runtime_libraries'] or inventory(root,state['runtime_libraries'])!=state['files']:
        raise ValueError('prepared development inputs or host runtime changed')
    return {'sha256':digest(root/'prepared.json'),'prefix':str(root/'usr')}


def main():
    p=argparse.ArgumentParser(description=__doc__);sub=p.add_subparsers(dest='action',required=True)
    a=sub.add_parser('prepare');a.add_argument('--manifest',type=Path,required=True);a.add_argument('--packages',type=Path,required=True);a.add_argument('--output',type=Path,required=True);a.add_argument('--download',action='store_true')
    a=sub.add_parser('verify');a.add_argument('root',type=Path);a.add_argument('--expected-sha256')
    a=p.parse_args();print(json.dumps(verify(a.root,a.expected_sha256) if a.action=='verify' else prepare(a.manifest,a.packages,a.output,a.download),sort_keys=True))


if __name__=='__main__':
    try:main()
    except (ValueError,OSError,KeyError,subprocess.SubprocessError) as error:raise SystemExit(str(error))

#!/usr/bin/env python3
"""Supervise one command and finish its inherited output writers before evidence.

Linux uses a private child-subreaper process, including nested sessions and groups.
Commands must not transfer writable handles or ask another service to keep writing;
such workloads require a qualified container/service supervisor. This is lifetime
supervision of cooperating programs, not hostile-process confinement. Other POSIX
systems fail closed until an equivalent descendant owner is supplied.
Windows starts suspended and assigns a no-breakaway, kill-on-close Job Object
before resuming the initial thread; assignment failure never runs child code.
Windows termination pins verified Job member handles before requesting exit and
joins them under one deadline; changed cumulative assignments fail closed.
Normal completion checks signaled member handles and a fresh complete Job list
before waiting for accounting retirement; a running descendant fails immediately.
Native qualification is required for each supported platform and environment.
"""
import ctypes
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time


class ProcessTreeError(RuntimeError):
    pass


def _remaining(deadline):
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise ProcessTreeError('descendant exit deadline exhausted; retain output ownership')
    return remaining


def _direct_children():
    """The private supervisor has one thread and is its children's only reaper."""
    text = Path('/proc/self/task/' + str(os.getpid()) + '/children').read_text()
    values = text.split()
    if any(not value.isdecimal() or int(value) <= 0 for value in values):
        raise ProcessTreeError('invalid private supervisor child inventory')
    return [int(value) for value in values]


def _linux_supervise(parent, report_fd, control_fd, argv):
    """Run only in a dedicated process, never inside the calling Python harness.

    Reaping all children to ECHILD proves no descendant can still create writers.
    During cleanup, killing direct children makes their descendants direct adopted
    children of this subreaper. Repeat until the kernel reports no children. PID
    identity cannot be reused between inventory and kill: this single-threaded
    process performs no wait/reap between those operations.
    """
    stopping = False
    primary = None
    code = None
    outlived = False
    error = None
    reaped = 0
    def stop(_signum, _frame):
        nonlocal stopping
        stopping = True
    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    signal.signal(signal.SIGCHLD, signal.SIG_DFL)
    os.set_blocking(control_fd, False)
    def requested():
        try:
            # Data requests termination; EOF means the caller disappeared.
            os.read(control_fd, 1)
            return True
        except BlockingIOError:
            return False
    try:
        api = ctypes.CDLL(None, use_errno=True)
        api.prctl.argtypes = [ctypes.c_int, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_ulong]
        api.prctl.restype = ctypes.c_int
        if api.prctl(36, 1, 0, 0, 0) != 0:  # PR_SET_CHILD_SUBREAPER
            raise ProcessTreeError('private Linux child-subreaper setup failed')
        if api.prctl(1, signal.SIGTERM, 0, 0, 0) != 0:  # PR_SET_PDEATHSIG
            raise ProcessTreeError('private Linux parent-death notification failed')
        if os.getppid() != parent:
            raise ProcessTreeError('command owner exited before launch')
        _direct_children()  # Require the cleanup primitive before any command code.
        if stopping or requested():
            stopping = True
            code = -signal.SIGTERM
        else:
            child = subprocess.Popen(argv, stdin=subprocess.DEVNULL, close_fds=True)
            primary = child.pid
    except BaseException as failure:
        error = 'supervisor launch failed: ' + str(failure)[:1024]
        stopping = True
    # Even a failed inspection keeps this owner alive while children remain. The
    # caller times out and retains ownership instead of claiming uncertain cleanup.
    while True:
        empty = False
        try:
            stopping = stopping or requested()
            while True:
                try:
                    pid, status = os.waitpid(-1, os.WNOHANG)
                except ChildProcessError:
                    empty = True
                    break
                if not pid:
                    break
                reaped += 1
                if pid == primary:
                    code = os.waitstatus_to_exitcode(status)
                    child.returncode = code
            if empty:
                break
            if code is not None and not stopping:
                outlived = True
            if stopping or outlived:
                for pid in _direct_children():
                    try:
                        os.kill(pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
        except BaseException as failure:
            error = 'descendant cleanup inspection failed: ' + str(failure)[:1024]
            stopping = True
        time.sleep(0.01)
    report = {'schema_version': 1, 'primary_returncode': code, 'descendants_outlived': outlived,
              'terminated': stopping, 'error': error, 'reaped': reaped}
    data = (json.dumps(report, sort_keys=True) + '\n').encode()
    if len(data) > 4096:
        report['error'] = 'supervisor failure exceeded the bounded diagnostic size'
        data = (json.dumps(report, sort_keys=True) + '\n').encode()
    # The pipe is private, has one small final record, and is not inherited by the
    # command. A lost receipt remains uncertain to the caller, even after cleanup.
    try:
        os.write(report_fd, data)
    finally:
        os.close(report_fd)
        os.close(control_fd)


class _LinuxProcess:
    """Popen-compatible observation of a privately supervised primary command."""
    def __init__(self, supervisor, report_fd, argv, control_fd=None):
        self.supervisor, self.report_fd, self.args = supervisor, report_fd, argv
        self.control_fd = control_fd
        self.pid = supervisor.pid
        self.returncode = None
        self.report = None
        self.failure = None

    def _collect(self):
        if self.failure is not None:
            raise ProcessTreeError(self.failure)
        if self.report is not None:
            return self.returncode
        try:
            raw = os.read(self.report_fd, 8193)
            if len(raw) > 8192 or self.supervisor.returncode != 0:
                raise ValueError('private supervisor failed or excessive receipt')
            report = json.loads(raw)
            required = {'schema_version', 'primary_returncode', 'descendants_outlived', 'terminated', 'error', 'reaped'}
            if (not isinstance(report, dict) or set(report) != required or report['schema_version'] != 1
                    or type(report['descendants_outlived']) is not bool or type(report['terminated']) is not bool
                    or type(report['reaped']) is not int or report['reaped'] < 0
                    or (report['error'] is not None and not isinstance(report['error'], str))
                    or (report['primary_returncode'] is not None and type(report['primary_returncode']) is not int)):
                raise ValueError('invalid private supervisor receipt')
            if report['primary_returncode'] is None and not report['error']:
                raise ValueError('primary completion missing from supervisor receipt')
            self.report = report
            self.returncode = report['primary_returncode'] if report['primary_returncode'] is not None else 125
        except (OSError, ValueError) as failure:
            self.failure = 'private supervisor completion uncertain; retain output ownership'
            raise ProcessTreeError(self.failure) from failure
        finally:
            if self.report_fd is not None:
                os.close(self.report_fd)
                self.report_fd = None
            if self.control_fd is not None:
                os.close(self.control_fd)
                self.control_fd = None
        return self.returncode

    def poll(self):
        return None if self.supervisor.poll() is None else self._collect()

    def wait(self, timeout=None):
        self.supervisor.wait(timeout=timeout)
        return self._collect()

    def terminate(self):
        if self.supervisor.poll() is None:
            # A pipe request is safe before the private interpreter has installed
            # handlers; an immediate signal could otherwise kill it at startup.
            try:
                os.write(self.control_fd, b'T')
            except BrokenPipeError:
                pass


def _linux_launch(argv, cwd, stream, *, env=None):
    incoming, outgoing = os.pipe()
    try:
        control_incoming, control_outgoing = os.pipe()
    except BaseException:
        os.close(incoming)
        os.close(outgoing)
        raise
    try:
        process = subprocess.Popen([sys.executable, '-B', str(Path(__file__).resolve()),
                                    '--supervise-linux', str(os.getpid()), str(outgoing), str(control_incoming), *argv],
                                   cwd=cwd, stdin=subprocess.DEVNULL, stdout=stream,
                                   stderr=subprocess.STDOUT, start_new_session=True, pass_fds=(outgoing,control_incoming), env=env)
    except BaseException:
        os.close(incoming)
        os.close(control_outgoing)
        raise
    finally:
        os.close(outgoing)
        os.close(control_incoming)
    return ProcessTree(_LinuxProcess(process, incoming, argv,control_outgoing))


class _WindowsJob:
    """Native handle owner; constructed only on Windows."""
    def __init__(self):
        from ctypes import wintypes as w
        self.api = ctypes.WinDLL('kernel32', use_last_error=True)
        self.handle = None
        self.completion_observation = None
        self.w = w
        class BasicLimits(ctypes.Structure):
            _fields_ = [('process_time', ctypes.c_longlong), ('job_time', ctypes.c_longlong),
                        ('flags', w.DWORD), ('min_working_set', ctypes.c_size_t),
                        ('max_working_set', ctypes.c_size_t), ('active_limit', w.DWORD),
                        ('affinity', ctypes.c_size_t), ('priority', w.DWORD), ('scheduling', w.DWORD)]
        class IoCounters(ctypes.Structure):
            _fields_ = [(name, ctypes.c_ulonglong) for name in
                        ('read_ops', 'write_ops', 'other_ops', 'read_bytes', 'write_bytes', 'other_bytes')]
        class ExtendedLimits(ctypes.Structure):
            _fields_ = [('basic', BasicLimits), ('io', IoCounters),
                        ('process_memory', ctypes.c_size_t), ('job_memory', ctypes.c_size_t),
                        ('peak_process_memory', ctypes.c_size_t), ('peak_job_memory', ctypes.c_size_t)]
        class Accounting(ctypes.Structure):
            _fields_ = [('user_time', ctypes.c_longlong), ('kernel_time', ctypes.c_longlong),
                        ('period_user', ctypes.c_longlong), ('period_kernel', ctypes.c_longlong),
                        ('page_faults', w.DWORD), ('total', w.DWORD), ('active', w.DWORD),
                        ('terminated', w.DWORD)]
        class ThreadEntry(ctypes.Structure):
            _fields_ = [('size', w.DWORD), ('usage', w.DWORD), ('thread', w.DWORD),
                        ('owner', w.DWORD), ('base_priority', w.LONG), ('delta_priority', w.LONG),
                        ('flags', w.DWORD)]
        self.Accounting, self.ThreadEntry = Accounting, ThreadEntry
        signatures = {
            'CreateJobObjectW': ([ctypes.c_void_p, w.LPCWSTR], w.HANDLE),
            'SetInformationJobObject': ([w.HANDLE, ctypes.c_int, ctypes.c_void_p, w.DWORD], w.BOOL),
            'QueryInformationJobObject': ([w.HANDLE, ctypes.c_int, ctypes.c_void_p, w.DWORD, ctypes.c_void_p], w.BOOL),
            'AssignProcessToJobObject': ([w.HANDLE, w.HANDLE], w.BOOL),
            'TerminateJobObject': ([w.HANDLE, w.UINT], w.BOOL),
            'CloseHandle': ([w.HANDLE], w.BOOL),
            'CreateToolhelp32Snapshot': ([w.DWORD, w.DWORD], w.HANDLE),
            'Thread32First': ([w.HANDLE, ctypes.POINTER(ThreadEntry)], w.BOOL),
            'Thread32Next': ([w.HANDLE, ctypes.POINTER(ThreadEntry)], w.BOOL),
            'OpenThread': ([w.DWORD, w.BOOL, w.DWORD], w.HANDLE),
            'ResumeThread': ([w.HANDLE], w.DWORD),
            'OpenProcess': ([w.DWORD, w.BOOL, w.DWORD], w.HANDLE),
            'IsProcessInJob': ([w.HANDLE, w.HANDLE, ctypes.POINTER(w.BOOL)], w.BOOL),
            'WaitForSingleObject': ([w.HANDLE, w.DWORD], w.DWORD),
            'QueryFullProcessImageNameW': ([w.HANDLE, w.DWORD, w.LPWSTR, ctypes.POINTER(w.DWORD)], w.BOOL),
        }
        for name, (arguments, result) in signatures.items():
            function = getattr(self.api, name)
            function.argtypes, function.restype = arguments, result
        self.handle = self.api.CreateJobObjectW(None, None)
        if not self.handle:
            self.fail('create job')
        try:
            limits = ExtendedLimits()
            limits.basic.flags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE; no breakaway flags.
            if not self.api.SetInformationJobObject(self.handle, 9, ctypes.byref(limits), ctypes.sizeof(limits)):
                self.fail('configure non-breakaway job')
        except BaseException:
            self.close()
            raise

    def fail(self, operation):
        raise ProcessTreeError(operation + ' failed: ' + str(ctypes.WinError(ctypes.get_last_error())))

    def assign(self, process):
        if not self.api.AssignProcessToJobObject(self.handle, self.w.HANDLE(int(process._handle))):
            self.fail('assign suspended process to job')

    def resume(self, process):
        snapshot = self.api.CreateToolhelp32Snapshot(0x4, 0)  # TH32CS_SNAPTHREAD
        if snapshot == ctypes.c_void_p(-1).value:
            self.fail('inspect suspended process thread')
        matches = []
        try:
            entry = self.ThreadEntry()
            entry.size = ctypes.sizeof(entry)
            found = self.api.Thread32First(snapshot, ctypes.byref(entry))
            while found:
                if entry.owner == process.pid:
                    matches.append(entry.thread)
                entry.size = ctypes.sizeof(entry)
                found = self.api.Thread32Next(snapshot, ctypes.byref(entry))
            if ctypes.get_last_error() != 18:  # ERROR_NO_MORE_FILES
                self.fail('enumerate suspended process thread')
        finally:
            if not self.api.CloseHandle(snapshot):
                self.fail('close thread snapshot')
        if len(matches) != 1:
            raise ProcessTreeError('expected exactly one suspended initial thread')
        thread = self.api.OpenThread(0x2, False, matches[0])  # THREAD_SUSPEND_RESUME
        if not thread:
            self.fail('open suspended initial thread')
        try:
            count = self.api.ResumeThread(thread)
            if count == 0xffffffff:
                self.fail('resume initial thread')
            if count != 1:
                raise ProcessTreeError('unexpected initial thread suspension count')
        finally:
            if not self.api.CloseHandle(thread):
                self.fail('close initial thread handle')

    def accounting(self):
        accounting = self.Accounting()
        if not self.api.QueryInformationJobObject(self.handle, 1, ctypes.byref(accounting),
                                                  ctypes.sizeof(accounting), None):
            self.fail('inspect job membership')
        return accounting

    def active(self):
        return self.accounting().active

    def total(self):
        return self.accounting().total

    def process_ids(self):
        """Take a complete, bounded Job snapshot, including nested members."""
        capacity = 32
        for _ in range(8):
            class ProcessIds(ctypes.Structure):
                _fields_ = [('assigned', self.w.DWORD), ('count', self.w.DWORD),
                            ('ids', ctypes.c_size_t * capacity)]
            members = ProcessIds()
            ok = self.api.QueryInformationJobObject(self.handle, 3, ctypes.byref(members),
                                                    ctypes.sizeof(members), None)
            if not ok and ctypes.get_last_error() != 234:  # ERROR_MORE_DATA
                self.fail('inspect job process list')
            if members.count > capacity or members.count > members.assigned:
                raise ProcessTreeError('invalid job process list counts')
            if ok and members.count == members.assigned:
                result = list(members.ids[:members.count])
                if len(set(result)) != len(result) or any(not 0 < pid <= 0xffffffff for pid in result):
                    raise ProcessTreeError('invalid job process identifiers')
                return result
            capacity = max(capacity * 2, members.assigned)
            if capacity > 65536:
                break
        raise ProcessTreeError('job process inventory remains incomplete; retain output ownership')

    def observe_running_process(self, pid, handle, members, state):
        """Retain the first rejected handle observation, never a later substitute.

        These bounded diagnostics cannot grant completion. Query the image through
        the already pinned, verified member handle; do not log argv or environment.
        Accounting is explicitly a later observation, not an atomic snapshot.
        """
        if getattr(self, 'completion_observation', None) is not None:
            return
        observation = {'pid': pid, 'member_verified': True, 'wait_state': state,
                       'snapshot_count': len(members), 'snapshot_pids': members[:32],
                       'snapshot_truncated': len(members) > 32}
        self.completion_observation = observation
        image = ctypes.create_unicode_buffer(32768)
        size = self.w.DWORD(len(image))
        if self.api.QueryFullProcessImageNameW(handle, 0, image, ctypes.byref(size)):
            observation['image'] = image.value[:4096]
            observation['image_truncated'] = len(image.value) > 4096
        else:
            observation['image_query_error'] = ctypes.get_last_error()
        try:
            accounting = self.accounting()
            observation['accounting_after_observation'] = {
                key: int(getattr(accounting, key)) for key in ('active', 'total', 'terminated')}
        except (OSError, ProcessTreeError):
            observation['accounting_query_error'] = ctypes.get_last_error()

    def has_running_process(self):
        """Separate executable members from already-signaled process objects.

        Job accounting and process-handle completion are separate observations.
        Never give a running descendant a grace period to finish successfully.
        Open handles pin identity; membership rejects a reused foreign PID.
        """
        observed = {}
        try:
            pending = self.process_ids()
            for _ in range(8):
                disappeared = set()
                for pid in pending:
                    if pid in observed:
                        continue  # The retained signaled handle pins this identity.
                    # SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION; no inheritance.
                    handle = self.api.OpenProcess(0x101000, False, pid)
                    if not handle:
                        error = ctypes.get_last_error()
                        if error == 87:  # Possibly retired since the snapshot.
                            disappeared.add(pid)
                            continue
                        raise ProcessTreeError('open job member failed: ' + str(error) +
                                               '; retain output ownership')
                    observed[pid] = handle
                    member = self.w.BOOL()
                    if not self.api.IsProcessInJob(handle, self.handle, ctypes.byref(member)):
                        self.fail('confirm job process identity')
                    if not member.value:
                        raise ProcessTreeError('job process identity changed; retain output ownership')
                    state = self.api.WaitForSingleObject(handle, 0)
                    if state == 0x102:  # WAIT_TIMEOUT: still executable now.
                        self.observe_running_process(pid, handle, pending, state)
                        return True
                    if state != 0:  # Only WAIT_OBJECT_0 establishes termination.
                        self.fail('inspect job process completion')
                # A member could have created another member before terminating.
                # Inspect every newly found process before permitting any sleep.
                pending = self.process_ids()
                if disappeared.intersection(pending):
                    raise ProcessTreeError('job member lookup remains ambiguous; retain output ownership')
                if all(pid in observed for pid in pending):
                    return False
            raise ProcessTreeError('job membership did not settle; retain output ownership')
        finally:
            failed = False
            for handle in observed.values():
                if not self.api.CloseHandle(handle):
                    failed = True
            if failed:
                self.fail('close job process observation')

    def terminate(self):
        if not self.api.TerminateJobObject(self.handle, 1):
            self.fail('terminate job')

    def terminate_and_wait(self, deadline, *, validate_live=None):
        """Pin identities before termination; accounting alone is not a join.

        A cumulative assignment change can hide a new child that disappeared from
        the active list before it was pinned. Reject that uncertainty, even when
        the final list and active count are empty. This is not a creation freeze.
        """
        observed, requested, failure = {}, False, None
        try:
            _remaining(deadline)
            total = self.total()
            for pid in self.process_ids():
                _remaining(deadline)
                handle = self.api.OpenProcess(0x101000, False, pid)
                if not handle:
                    # Even ERROR_INVALID_PARAMETER cannot prove completion of an
                    # observed identity that we never managed to pin.
                    raise ProcessTreeError('cannot pin observed job member; retain output ownership')
                observed[pid] = handle
                member = self.w.BOOL()
                if not self.api.IsProcessInJob(handle, self.handle, ctypes.byref(member)):
                    self.fail('confirm termination member identity')
                if not member.value:
                    raise ProcessTreeError('termination member identity changed; retain output ownership')
            if validate_live is not None:
                # Pin the entire snapshot before classifying any live member.
                # A caller-specific helper policy never uses the first-member
                # diagnostic as proof about the remainder of the Job.
                live = []
                for pid, handle in observed.items():
                    _remaining(deadline)
                    state = self.api.WaitForSingleObject(handle, 0)
                    if state == 0x102:
                        live.append((pid, handle))
                    elif state != 0:
                        self.fail('inspect helper process completion')
                # Preserve every live observation before any caller policy work;
                # a later natural exit cannot exempt an already observed member.
                for pid, handle in live:
                    _remaining(deadline)
                    image = ctypes.create_unicode_buffer(32768)
                    size = self.w.DWORD(len(image))
                    if not self.api.QueryFullProcessImageNameW(handle, 0, image, ctypes.byref(size)):
                        self.fail('identify live helper image')
                    if not 0 < size.value < len(image) or size.value != len(image.value):
                        raise ProcessTreeError('invalid live helper image identity; retain output ownership')
                    if validate_live(pid, image.value) is not True:
                        raise ProcessTreeError('live member is not an accepted command helper; retain output ownership')
                    _remaining(deadline)
            def reconcile():
                _remaining(deadline)
                members = self.process_ids()
                if any(pid not in observed for pid in members) or self.total() != total:
                    raise ProcessTreeError('job assignments changed during termination; retain output ownership')
            reconcile()
            requested = True
            self.terminate()
            for handle in observed.values():
                milliseconds = max(1, min(int(_remaining(deadline) * 1000), 0xfffffffe))
                state = self.api.WaitForSingleObject(handle, milliseconds)
                if state == 0x102:
                    raise ProcessTreeError('descendant exit deadline exhausted; retain output ownership')
                if state != 0:
                    self.fail('join terminated job member')
            reconcile()
        except BaseException as error:
            failure = error
            raise
        finally:
            cleanup_errors = []
            if not requested:
                # Capture failed, but still stop executable members. This is a
                # best-effort stop, never a substitute for the failed join proof.
                try:
                    self.terminate()
                except BaseException as error:
                    cleanup_errors.append('stop after failed capture: ' + str(error))
            for handle in observed.values():
                if not self.api.CloseHandle(handle):
                    cleanup_errors.append('close termination observation failed')
            if cleanup_errors:
                message = '; '.join(cleanup_errors) + '; retain output ownership'
                if failure is not None:
                    raise ProcessTreeError(str(failure) + '; ' + message) from failure
                raise ProcessTreeError(message)
        return total

    def close(self):
        if self.handle is not None:
            if not self.api.CloseHandle(self.handle):
                self.fail('close job')
            self.handle = None


class ProcessTree:
    def __init__(self, process, job=None):
        self.process, self.job = process, job
        self.closed = False
        self.termination_joined = False
        self.termination_failure = None

    def poll(self):
        return self.process.poll()

    def wait(self, timeout=None):
        return self.process.wait(timeout=timeout)

    def _live(self):
        if isinstance(self.process, _LinuxProcess):
            return self.process.poll() is None
        return bool(self.job.active())

    def terminate(self, timeout=5, *, validate_live=None):
        """Stop and join every member; optional helper validation precedes stopping.

        A caller-specific helper policy requires an already successful Windows
        parent and validates every live pinned identity. It does not alter finish.
        """
        if self.closed:
            return
        if self.termination_failure is not None:
            raise ProcessTreeError(self.termination_failure)
        if validate_live is not None:
            if (not callable(validate_live) or self.job is None or self.process.poll() != 0
                    or self.termination_joined):
                raise ProcessTreeError('helper completion requires a successful unjoined Windows command')
        if self.termination_joined:
            return
        deadline = time.monotonic() + timeout
        try:
            if isinstance(self.process, _LinuxProcess):
                self.process.terminate()
            elif self.job is not None:
                total = (self.job.terminate_and_wait(deadline) if validate_live is None else
                         self.job.terminate_and_wait(deadline, validate_live=validate_live))
            self.process.wait(timeout=_remaining(deadline))
            while self._live():
                time.sleep(min(0.01, _remaining(deadline)))
            _remaining(deadline)
            if self.job is not None and self.job.total() != total:
                raise ProcessTreeError('job assignments changed during termination; retain output ownership')
            self.termination_joined = True
        except BaseException as error:
            if self.job is not None:
                self.termination_failure = 'Windows termination remains unconfirmed: ' + str(error)
            raise

    def finish(self):
        """A successful parent with surviving writers is an incomplete command."""
        if self.closed:
            raise ProcessTreeError('process owner already closed')
        if self.termination_failure is not None:
            raise ProcessTreeError(self.termination_failure)
        if self.process.poll() is None:
            raise ProcessTreeError('parent has not exited')
        if isinstance(self.process, _LinuxProcess):
            report = self.process.report
            if report['error']:
                raise ProcessTreeError(report['error'])
            if report['descendants_outlived']:
                raise ProcessTreeError('descendants outlived the command; output completion was not valid')
        deadline = time.monotonic() + 5
        while self._live():
            if self.job is None or self.job.has_running_process():
                message = 'descendants outlived the command; output completion was not valid'
                observation = getattr(self.job, 'completion_observation', None)
                if isinstance(observation, dict):
                    message += '; windows_completion=' + json.dumps(observation, sort_keys=True)
                try:
                    self.terminate()
                except BaseException as error:
                    raise ProcessTreeError(message + '; descendant cleanup failed: ' + str(error)) from error
                raise ProcessTreeError(message)
            # All observed members have terminated. Wait only for accounting to
            # retire them, rechecking for any actual live member on every turn.
            if time.monotonic() >= deadline:
                raise ProcessTreeError('job retirement remains unconfirmed; retain output ownership')
            time.sleep(0.01)
        return self.process.returncode

    def close(self):
        if not self.closed:
            try:
                if self.termination_failure is not None:
                    raise ProcessTreeError(self.termination_failure)
                if self.job is not None or self.process.poll() is None or self._live():
                    # Windows must not skip a required join merely because its
                    # primary and aggregate counters already look completed.
                    self.terminate()
            finally:
                if self.job is not None:
                    self.job.close()
            self.closed = True


def launch(argv, cwd, stream, *, env=None):
    """Own descendants before execution; env affects only the supervised tree."""
    if os.name == 'posix' and sys.platform.startswith('linux'):
        return _linux_launch(argv, cwd, stream, env=env)
    if os.name != 'nt':
        raise ProcessTreeError('no qualified process supervisor for this operating system')
    job = _WindowsJob() if os.name == 'nt' else None
    process = None
    try:
        process = subprocess.Popen(argv, cwd=cwd, stdin=subprocess.DEVNULL,
                                   stdout=stream, stderr=subprocess.STDOUT,
                                   start_new_session=os.name == 'posix',
                                   creationflags=0x4 if job is not None else 0, env=env)
        if job is not None:
            job.assign(process)
            job.resume(process)
        return ProcessTree(process, job)
    except BaseException as original:
        # Assignment failure leaves the child suspended; no child code ran.
        cleanup_errors = []
        actions = []
        deadline = time.monotonic() + 5
        if process is not None:
            if job is not None:
                # Resume can fail after the initial thread already ran (for
                # example while closing its handle), so descendants need joining.
                actions.append(lambda: job.terminate_and_wait(deadline))
            actions.extend((lambda: process.kill() if process.poll() is None else None,
                            lambda: process.wait(timeout=_remaining(deadline))))
        if job is not None:
            actions.append(job.close)
        for action in actions:
            try:
                action()
            except BaseException as error:
                cleanup_errors.append(str(error))
        if cleanup_errors:
            raise ProcessTreeError('launch failed and writer cleanup is uncertain: '
                                   + '; '.join(cleanup_errors)) from original
        raise


if __name__ == '__main__':
    if len(sys.argv) < 6 or sys.argv[1] != '--supervise-linux' or not sys.platform.startswith('linux'):
        raise SystemExit('private supervisor requires its complete internal invocation')
    _linux_supervise(int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4]), sys.argv[5:])

#!/usr/bin/env python3
"""File-based qualification tasks for a prepared workspace on any CI runner.

The scheduler selects the actual host and supplies trusted inputs. This module
neither downloads release assets nor publishes or authenticates a CI producer.
"""
import argparse
import json
from pathlib import Path
import sys

TOOLS = Path(__file__).resolve().parent
if str(TOOLS) not in sys.path:
    sys.path.insert(0, str(TOOLS))
import ci_plan
import coverage as evidence


def load_plan(root):
    root = Path(root).resolve(strict=True)
    plan = evidence.load(root / 'build/check-plan.json')
    evidence.validate(plan)
    return root, plan


def executions(root):
    """Return host requirements; scheduling and runner names belong to the CI."""
    _, plan = load_plan(root)
    return dict(plan=plan['id'], mode=plan['mode'], executions=[
        dict(id=item['id'], target=item['target'], environment=item['environment'],
             scope=item['scope'], backends=[row['backend'] for row in evidence.execution_members(plan, item)],
             checks=[row['id'] for row in evidence.execution_members(plan, item)],
             reports=[evidence.result_path(plan, row['id'], 'build/evidence').as_posix()
                      for row in evidence.execution_members(plan, item)])
        for item in evidence.executions(plan)])


def _execution(root, check_id, run_id, attempt):
    if not isinstance(run_id, str) or not evidence.NAME.fullmatch(run_id) or type(attempt) is not int or attempt < 1:
        raise ValueError('explicit run ID and positive attempt required')
    root, plan = load_plan(root)
    matches = [item for item in evidence.executions(plan) if item['id'] == check_id]
    if len(matches) != 1:
        raise ValueError('only a frozen physical execution leader can launch')
    evidence.check_inputs(plan, root, check_ids=[check_id])
    return root, plan, matches[0]


def _needs_browser(item):
    return ci_plan.platform.system() == 'Linux' and ci_plan.needs_browser_prerequisite(item['backend'], item['scope'])


def prepare(root, check_id, run_id, attempt):
    """Explicit prerequisite stage; existing disposable-host guards still apply."""
    root, plan, item = _execution(root, check_id, run_id, attempt)
    result = dict(plan=plan['id'], check=check_id, run_id=run_id, attempt=attempt)
    if not _needs_browser(item):
        return dict(result, status='not_required')
    directory = root / 'build/prerequisites' / check_id
    receipt = ci_plan.install_browser_prerequisite(item['target'], item['environment'], item['backend'], directory)
    receipt.update(result)
    directory.mkdir(parents=True, exist_ok=True)
    evidence.write_new(directory / 'browser.json', receipt)
    return dict(result, status='prepared', receipt=str(directory / 'browser.json'))


def run(root, check_id, run_id, attempt):
    """Run one physical execution, retaining every existing logical receipt."""
    root, plan, item = _execution(root, check_id, run_id, attempt)
    if _needs_browser(item) and not (root / 'build/prerequisites' / check_id / 'browser.json').is_file():
        raise ValueError('run explicit browser prerequisite setup before unprivileged qualification')
    return evidence.run_execution(plan, check_id, root, root / 'build/evidence' / check_id, run_id, attempt)



def adopt(root, run_id, attempt, reports, output):
    """Create an immutable explicit selection of trusted earlier receipts."""
    root, plan = load_plan(root)
    output = Path(output)
    if output.exists() or output.is_symlink():
        raise ValueError('adoption must name a new immutable output')
    result = evidence.adopt(plan, reports, root, run_id, attempt)
    evidence.write_new(output, result)
    return result

def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='operation', required=True)
    for name in ('plan', 'list', 'prepare', 'run', 'adopt'):
        command = commands.add_parser(name)
        command.add_argument('--root', type=Path, default=Path.cwd())
        if name == 'plan':
            command.add_argument('--profile', required=True)
            command.add_argument('--policy', type=Path)
        if name in ('prepare', 'run'):
            command.add_argument('--check', required=True)
        if name in ('prepare', 'run', 'adopt'):
            command.add_argument('--run-id', required=True)
            command.add_argument('--attempt', type=int, required=True)
        if name == 'adopt':
            command.add_argument('--output', type=Path, required=True)
            command.add_argument('reports', type=Path, nargs='+')
    args = parser.parse_args(argv)
    try:
        if args.operation == 'plan':
            import qualification_plan
            root = args.root.resolve(strict=True)
            policy = evidence.load(args.policy) if args.policy else None
            qualification_plan.create_plan(root, root / 'build/candidate', args.profile,
                                           root / 'build/check-plan.json', policy)
            result = executions(root)
        elif args.operation == 'adopt':
            result = adopt(args.root, args.run_id, args.attempt, args.reports, args.output)
        elif args.operation == 'list':
            result = executions(args.root)
        else:
            result = globals()[args.operation](args.root, args.check, args.run_id, args.attempt)
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(json.dumps(dict(status='failed', operation=args.operation, error=str(error))), file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True, indent=2))
    return 1 if args.operation == 'run' and result['status'] != 'passed' else 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
"""Assemble and recover complete local releases. Never publishes remotely."""
import argparse
from pathlib import Path
import re
import shutil
import tempfile
import artifact
from dependency_archive import digest, encoded, file_inventory, read_json, relative, verify_inventory, write_json
from dependency_store import copy_group, verify_group
from source_identity import verify_source_archive

RUST_IDENTITY_FIELDS = ('rust_sdk_recipe_id', 'rust_compiler_version', 'rust_target',
                        'rust_sdk_manifest_sha256', 'rust_compiler_sha256')


def provider_identity(entry):
    # An omitted field belongs to a historical C++ artifact, not a new build request.
    provider = entry.get('core_provider', 'cpp')
    if provider not in ('cpp', 'rust'):
        raise ValueError('unknown core provider')
    result = {'core_provider': provider}
    if provider == 'rust':
        for field in RUST_IDENTITY_FIELDS:
            value = entry.get(field)
            if not isinstance(value, str) or not value.strip() or value == 'none':
                raise ValueError('Rust artifact needs its complete compiler and SDK identity')
            if (field.endswith('sha256') or field == 'rust_sdk_recipe_id') and not re.fullmatch(r'[0-9a-f]{64}', value):
                raise ValueError('invalid Rust compiler or SDK identity')
            result[field] = value
    elif any(entry.get(field) not in (None, 'none') for field in RUST_IDENTITY_FIELDS):
        raise ValueError('C++ artifact cannot declare a Rust compiler or SDK')
    return result


def dependency_kinds(artifacts):
    kinds = {}
    for entry in artifacts:
        identity = provider_identity(entry)
        for recipe in dependency_recipes(entry):
            kind = 'rust' if recipe == identity.get('rust_sdk_recipe_id') else 'sdk'
            if recipe in kinds and kinds[recipe] != kind:
                raise ValueError('dependency recipe has conflicting SDK kinds')
            kinds[recipe] = kind
    return kinds


def dependency_names(recipe, kind='sdk'):
    if kind == 'sdk':
        from dependency_store import names
        return names(recipe)
    if kind == 'rust':
        from rust_sdk import group_names
        return group_names(recipe)
    raise ValueError('unknown dependency group kind')


def verify_dependency_group(directory, recipe, kind='sdk', expected_files=None, *, binary=False):
    if kind == 'rust':
        from rust_sdk import verify_group as verify_rust_group
        actual = verify_rust_group(directory, recipe)
    elif kind == 'sdk':
        if binary:
            from dependency_store import verify_binary_group
            return verify_binary_group(directory, recipe, expected_files)
        actual = verify_group(directory, recipe)
    else:
        raise ValueError('unknown dependency group kind')
    if expected_files is not None and actual != expected_files:
        raise ValueError('release dependency identity mismatch')
    return actual


def copy_dependency_group(source, destination, recipe, kind='sdk'):
    if kind == 'sdk':
        return copy_group(source, destination, recipe)
    files = verify_dependency_group(source, recipe, kind)
    source, destination = Path(source), Path(destination).absolute()
    if destination.exists() or destination.is_symlink():
        raise ValueError('refusing to overwrite retained dependency destination')
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=destination.parent, prefix='.group-') as temporary:
        staged = Path(temporary) / 'group'; staged.mkdir()
        for name in files:
            shutil.copyfile(source / name, staged / name)
        verify_dependency_group(staged, recipe, kind, files)
        staged.rename(destination)
    return files


def safe_name(name):
    if len(relative(name).parts) != 1:
        raise ValueError('release asset names must be simple filenames')
    return name


def dependency_recipes(entry):
    recipes = entry.get('dependency_recipes', [entry['sdk_recipe']])
    if not recipes or len(recipes) != len(set(recipes)) or entry['sdk_recipe'] not in recipes:
        raise ValueError('artifact dependency recipes must be complete, unique and include its primary SDK')
    if any(not re.fullmatch(r'[0-9a-f]{64}', value) for value in recipes):
        raise ValueError('invalid dependency recipe identity')
    identity = provider_identity(entry)
    if identity['core_provider'] == 'rust' and (identity['rust_sdk_recipe_id'] not in recipes
            or identity['rust_sdk_recipe_id'] == entry['sdk_recipe']):
        raise ValueError('Rust artifact must retain its distinct Rust SDK dependency group')
    return sorted(recipes)


def validate_package(archive, entry, source_identity, expected):
    # Read the small build record while validating every archive member. No full
    # temporary extraction is needed for this metadata-only package check.
    records = [name for name in expected["files"] if Path(name).name == "build-info.txt"]
    if len(records) != 1:
        raise ValueError('application archive requires one build information record')
    contents = {records[0]: None}
    if artifact.describe(archive, contents=contents) != expected:
        raise ValueError('release application archive inventory mismatch')
    info = {}
    for line in contents[records[0]].decode('utf-8').splitlines():
        if '=' in line:
            key, value = line.split('=', 1)
            if key in info: raise ValueError('duplicate packaged build information field')
            info[key] = value
    if info.get('sdk_recipe_id') != entry['sdk_recipe']:
        raise ValueError('packaged SDK recipe differs from release specification')
    if info.get('source_tree_sha256') != source_identity:
        raise ValueError('packaged source tree differs from retained source archive')
    if info.get('target') != entry['target']:
        raise ValueError('packaged target differs from release specification')
    identity = provider_identity(entry)
    if provider_identity(info) != identity:
        raise ValueError('packaged core provider or Rust toolchain differs from release specification')
    backends = [value for value in info.get('gui_backends', '').split(',') if value]
    if len(backends) != len(set(backends)) or sorted(backends) != sorted(entry.get('backends', [])):
        raise ValueError('packaged backends differ from release specification')
    declared = info.get('dependency_recipes', '').split(',')
    if sorted(declared) != dependency_recipes(entry):
        raise ValueError('packaged dependency list differs from release specification')


def verify_metadata(directory):
    """Validate the complete frozen inventory without reading absent payloads.

    This is for evidence aggregation and authenticated remote reconciliation;
    producer publication and physical qualification still verify payload bytes.
    """
    directory = Path(directory).resolve(strict=True)
    data = read_json(directory / 'release.json')
    if data.get('schema_version') != 1 or data.get('qualification') != 'candidate':
        raise ValueError('unsupported local release manifest')
    files = data.get('files')
    if not isinstance(files, dict) or not files or any(not isinstance(v, str) or not re.fullmatch(r'[0-9a-f]{64}', v) for v in files.values()):
        raise ValueError('invalid complete release inventory')
    source = data['source']; safe_name(source['archive'])
    if files.get(source['archive']) != source['sha256'] or not re.fullmatch(r'[0-9a-f]{64}', source.get('tree_sha256', '')):
        raise ValueError('release source identity mismatch')
    referenced = {source['archive']}; wanted = set(); targets = set()
    if not data['artifacts']: raise ValueError('release needs application artifacts')
    for entry in data['artifacts']:
        if entry['target'] in targets: raise ValueError('duplicate release target')
        targets.add(entry['target'])
        for key, checksum in (('archive', 'sha256'), ('manifest', 'manifest_sha256')):
            safe_name(entry[key])
            if entry[key] in referenced or files.get(entry[key]) != entry[checksum]:
                raise ValueError('release application identity mismatch')
            referenced.add(entry[key])
        wanted.update(dependency_recipes(entry))
        backends = entry.get('backends', [])
        if not isinstance(backends, list) or len(backends) != len(set(backends)):
            raise ValueError('duplicate release backend')
    observed = set()
    kinds = dependency_kinds(data['artifacts'])
    for entry in data['dependencies']:
        recipe = entry['recipe_id']
        kind = entry.get('kind', 'sdk')
        if (kind != kinds.get(recipe) or recipe in observed
                or set(entry['files']) != set(dependency_names(recipe, kind))):
            raise ValueError('duplicate or incomplete dependency group')
        observed.add(recipe)
        for name, value in entry['files'].items():
            path = 'dependencies/' + recipe + '/' + name
            if files.get(path) != value: raise ValueError('release dependency identity mismatch')
            referenced.add(path)
    if not wanted or wanted != observed or set(files) != referenced:
        raise ValueError('unexpected or omitted release asset')
    scopes = data['required_scopes']
    if not scopes or len(scopes) != len(set(scopes)):
        raise ValueError('release scopes must be nonempty and unique')
    return data


def required_files(metadata, target, backend, scope, *, binary_source=True):
    """Derive physical-check inputs from the complete target/backend inventory."""
    if scope not in ('source', 'recovery', 'archive', 'abi', 'apt'):
        raise ValueError('unsupported qualification operation')
    choices = [item for item in metadata['artifacts'] if item['target'] == target and backend in (item['backends'] or ['core'])]
    if len(choices) != 1: raise ValueError('unknown or ambiguous target/backend')
    entry = choices[0]; selected = {entry['archive'], entry['manifest']}
    if scope in ('source', 'recovery') or scope == 'archive' and backend in ('wasm', 'hosted-web'):
        selected.add(metadata['source']['archive'])
    if scope in ('source', 'recovery'):
        recipes = dependency_recipes(entry)
        for group in metadata['dependencies']:
            if group['recipe_id'] in recipes:
                selected.update('dependencies/' + group['recipe_id'] + '/' + name for name in group['files']
                    if scope == 'recovery' or group.get('kind') == 'rust' or not binary_source or not name.endswith('-sources.tar.gz'))
    return sorted(selected)


def verify_selection(directory, target, backend, scope):
    """Verify every selected byte; reject additional or missing scope payloads."""
    directory = Path(directory).resolve(strict=True); data = verify_metadata(directory)
    names = required_files(data, target, backend, scope)
    actual = file_inventory(directory, exclude=('release.json',))
    if not set(names) <= set(actual) or not set(actual) <= set(data['files']):
        raise ValueError('missing or unexpected physical qualification input')
    if actual != {name: data['files'][name] for name in actual}:
        raise ValueError('retained file inventory or checksum mismatch')
    entry = next(item for item in data['artifacts'] if item['target'] == target)
    if data['source']['archive'] in names:
        source = verify_source_archive(directory / data['source']['archive'])
        if source['tree_sha256'] != data['source']['tree_sha256']:
            raise ValueError('release source tree binding mismatch')
    validate_package(directory / entry['archive'], entry, data['source']['tree_sha256'],
                     read_json(directory / entry['manifest']))
    if scope in ('source', 'recovery'):
        for group in data['dependencies']:
            if group['recipe_id'] in dependency_recipes(entry):
                binary = scope == 'source' and not any((directory / 'dependencies' / group['recipe_id'] / name).exists() for name in group['files'] if name.endswith('-sources.tar.gz'))
                verify_dependency_group(directory / 'dependencies' / group['recipe_id'], group['recipe_id'],
                                        group.get('kind', 'sdk'), group['files'], binary=binary)
    return data


def verify_release(directory):
    directory = Path(directory).resolve(strict=True)
    metadata = verify_metadata(directory)
    if metadata.get('schema_version') != 1 or metadata.get('qualification') != 'candidate':
        raise ValueError('unsupported local release manifest')
    verify_inventory(directory, metadata['files'], exclude=('release.json',))
    source = metadata['source']
    safe_name(source['archive'])
    if digest(directory / source['archive']) != source['sha256']:
        raise ValueError('release source identity mismatch')
    source_manifest = verify_source_archive(directory / source['archive'])
    if source.get('tree_sha256') != source_manifest['tree_sha256']:
        raise ValueError('release source tree binding mismatch')
    wanted = set()
    for entry in metadata['artifacts']:
        for name in ('archive', 'manifest'):
            safe_name(entry[name])
        if digest(directory / entry['archive']) != entry['sha256'] or digest(directory / entry['manifest']) != entry['manifest_sha256']:
            raise ValueError('release application identity mismatch')
        validate_package(directory / entry['archive'], entry, source_manifest['tree_sha256'],
                         read_json(directory / entry['manifest']))
        wanted.update(dependency_recipes(entry))
    observed = set()
    for entry in metadata['dependencies']:
        recipe = entry['recipe_id']
        if recipe in observed: raise ValueError('duplicate dependency recipe')
        observed.add(recipe)
        verify_dependency_group(directory / 'dependencies' / recipe, recipe, entry.get('kind', 'sdk'), entry['files'])
    if not wanted or wanted != observed:
        raise ValueError('release must retain exactly every required SDK group')
    if not metadata['required_scopes'] or len(metadata['required_scopes']) != len(set(metadata['required_scopes'])):
        raise ValueError('release scopes must be nonempty and unique')
    referenced = {source['archive']}
    for entry in metadata['artifacts']:
        referenced.update((entry['archive'], entry['manifest']))
    for entry in metadata['dependencies']:
        referenced.update('dependencies/' + entry['recipe_id'] + '/' + name for name in entry['files'])
    if set(metadata['files']) != referenced:
        raise ValueError('unexpected or omitted release asset')
    return metadata


def assemble(spec_path, base, output):
    spec_path, output = Path(spec_path).resolve(), Path(output).absolute()
    spec = read_json(spec_path)
    if spec.get('schema_version') != 1 or not spec.get('artifacts'):
        raise ValueError('release spec must list application archives')
    if output.exists() or output.is_symlink():
        raise ValueError('release output must be new')
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=output.parent, prefix='.release-') as temporary:
        staged = Path(temporary) / 'release'
        staged.mkdir()
        seen = {'release.json', 'dependencies'}
        def retain(name):
            path = Path(name)
            if not path.is_absolute(): path = spec_path.parent / path
            path = path.resolve(strict=True)
            filename = safe_name(path.name)
            if filename in seen: raise ValueError('duplicate release asset filename')
            seen.add(filename)
            shutil.copyfile(path, staged / filename)
            if digest(path) != digest(staged / filename): raise ValueError('input changed during release assembly')
            return filename
        source = retain(spec['source']['path'])
        source_hash = digest(staged / source)
        if source_hash != spec['source']['sha256']:
            raise ValueError('source archive differs from frozen specification')
        source_manifest = verify_source_archive(staged / source)
        metadata = {'schema_version': 1, 'qualification': 'candidate',
                    'source': {'archive': source, 'sha256': source_hash, 'tree_sha256': source_manifest['tree_sha256']}, 'artifacts': [],
                    'dependencies': [], 'required_scopes': spec['required_scopes']}
        recipes = set()
        kinds = dependency_kinds(spec['artifacts'])
        for entry in spec['artifacts']:
            archive = retain(entry['path'])
            manifest = retain(entry['manifest_path'])
            if digest(staged / archive) != entry['sha256']:
                raise ValueError('application archive differs from frozen specification')
            recipe = entry['sdk_recipe']
            validate_package(staged / archive, entry, source_manifest['tree_sha256'], read_json(staged / manifest))
            recipes.update(dependency_recipes(entry))
            frozen = {'archive': archive, 'sha256': digest(staged / archive),
                'manifest': manifest, 'manifest_sha256': digest(staged / manifest),
                'target': entry['target'], 'backends': entry.get('backends', []), 'sdk_recipe': recipe,
                'dependency_recipes': dependency_recipes(entry)}
            if entry.get('core_provider') is not None:
                frozen.update(provider_identity(entry))
            metadata['artifacts'].append(frozen)
        for recipe in sorted(recipes):
            files = copy_dependency_group(Path(base) / recipe, staged / 'dependencies' / recipe, recipe, kinds[recipe])
            group = {'recipe_id': recipe, 'files': files}
            if kinds[recipe] == 'rust': group['kind'] = 'rust'
            metadata['dependencies'].append(group)
        metadata['files'] = file_inventory(staged)
        write_json(staged / 'release.json', metadata)
        verify_release(staged)
        staged.rename(output)
    return metadata


def verify_recovery(directory, expected_release_sha256=None):
    """Verify a standalone recovery kit without the original release or base.

    A caller-supplied release digest is the trust anchor. Without it, this checks
    local integrity and completeness, not publisher identity or qualification.
    """
    directory = Path(directory).absolute()
    if directory.is_symlink() or not directory.is_dir():
        raise ValueError('recovery kit must be an ordinary directory')
    directory = directory.resolve(strict=True)
    receipt_path = directory / 'recovery.json'
    if receipt_path.is_symlink() or not receipt_path.is_file():
        raise ValueError('recovery kit needs an ordinary recovery.json')
    receipt_hash = digest(receipt_path)
    receipt = read_json(receipt_path)
    if not isinstance(receipt, dict) or 'schema_version' not in receipt:
        raise ValueError('legacy recovery kit lacks retained release metadata; re-export from the verified release')
    if (type(receipt['schema_version']) is not int or receipt['schema_version'] != 1 or
            set(receipt) != {'schema_version', 'release_sha256', 'source', 'dependencies'}):
        raise ValueError('unsupported recovery manifest')
    release_hash = receipt['release_sha256']
    if not isinstance(release_hash, str) or not re.fullmatch(r'[0-9a-f]{64}', release_hash):
        raise ValueError('invalid recovery release identity')
    if expected_release_sha256 is not None:
        if (not isinstance(expected_release_sha256, str) or
                not re.fullmatch(r'[0-9a-f]{64}', expected_release_sha256)):
            raise ValueError('expected release identity must be a complete SHA-256')
        if release_hash != expected_release_sha256:
            raise ValueError('recovery release differs from trusted release identity')
    manifest_path = directory / 'release.json'
    if manifest_path.is_symlink() or not manifest_path.is_file() or digest(manifest_path) != release_hash:
        raise ValueError('retained release metadata is missing or changed')
    data = verify_metadata(directory)
    if receipt['source'] != data['source'] or receipt['dependencies'] != data['dependencies']:
        raise ValueError('recovery declarations differ from retained release metadata')
    source = data['source']
    if source['archive'] in ('release.json', 'recovery.json', 'dependencies'):
        raise ValueError('source archive collides with recovery metadata')
    expected = {'release.json': release_hash, 'recovery.json': receipt_hash,
                source['archive']: source['sha256']}
    for entry in data['dependencies']:
        recipe = entry['recipe_id']
        expected.update(('dependencies/' + recipe + '/' + name, value)
                        for name, value in entry['files'].items())
    # Check ordinary entries and frozen hashes before parsing any payload. Inner
    # inventories then bind the source tree and each compiled SDK to its sources.
    verify_inventory(directory, expected)
    if verify_source_archive(directory / source['archive'])['tree_sha256'] != source['tree_sha256']:
        raise ValueError('recovery source tree binding mismatch')
    for entry in data['dependencies']:
        verify_dependency_group(directory / 'dependencies' / entry['recipe_id'], entry['recipe_id'],
                                entry.get('kind', 'sdk'), entry['files'])
    expected_directories = {str(parent) for name in expected for parent in relative(name).parents if str(parent) != '.'}
    if {path.relative_to(directory).as_posix() for path in directory.rglob('*') if path.is_dir()} != expected_directories:
        raise ValueError('unexpected recovery directory')
    # Recheck after archive inspection: concurrent mutation cannot leave a success
    # receipt describing bytes that failed the frozen inventory at completion.
    verify_inventory(directory, expected)
    return {'schema_version': 1, 'status': 'passed', 'scope': 'retained-recovery-inputs',
            'release_sha256': release_hash, 'release_pin_verified': expected_release_sha256 is not None,
            'source': source, 'dependencies': data['dependencies'], 'artifacts': data['artifacts']}


def recover(directory, output):
    directory, output = Path(directory).resolve(strict=True), Path(output).absolute()
    if output == directory or directory in output.resolve().parents:
        raise ValueError('recovery output must be outside the release tree')
    if output.exists() or output.is_symlink(): raise ValueError('recovery output must be new')
    release_hash = digest(directory / 'release.json')
    data = verify_release(directory)
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=output.parent, prefix='.recover-') as temporary:
        staged = Path(temporary) / 'recovered'
        staged.mkdir()
        shutil.copyfile(directory / data['source']['archive'], staged / data['source']['archive'])
        for entry in data['dependencies']:
            recipe = entry['recipe_id']
            copy_dependency_group(directory / 'dependencies' / recipe, staged / 'dependencies' / recipe,
                                  recipe, entry.get('kind', 'sdk'))
        shutil.copyfile(directory / 'release.json', staged / 'release.json')
        write_json(staged / 'recovery.json', {'schema_version': 1, 'release_sha256': release_hash,
                   'source': data['source'], 'dependencies': data['dependencies']})
        verify_recovery(staged, release_hash)
        staged.rename(output)
    return data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='action', required=True)
    create = sub.add_parser('assemble')
    create.add_argument('--spec', type=Path, required=True)
    create.add_argument('--base', type=Path, required=True)
    create.add_argument('--output', type=Path, required=True)
    for action in ('verify', 'recover', 'verify-recovery'):
        command = sub.add_parser(action)
        command.add_argument('directory', type=Path)
        if action == 'recover': command.add_argument('--output', type=Path, required=True)
        if action == 'verify-recovery':
            command.add_argument('--expected-release-sha256', help='independently trusted SHA-256 of the original release.json')
    args = parser.parse_args()
    if args.action == 'assemble': result = assemble(args.spec, args.base, args.output)
    elif args.action == 'verify': result = verify_release(args.directory)
    elif args.action == 'verify-recovery': result = verify_recovery(args.directory, args.expected_release_sha256)
    else: result = recover(args.directory, args.output)
    print(encoded(result).decode(), end='')


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, KeyError) as error: raise SystemExit(str(error))

# Explicit one-time bootstrap from already-retained ZIPs. No downloads or tool execution.
[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$PythonArchive,
    [Parameter(Mandatory=$true)][ValidatePattern('^[a-fA-F0-9]{64}$')][string]$PythonSha256,
    [Parameter(Mandatory=$true)][string]$CmakeArchive,
    [Parameter(Mandatory=$true)][ValidatePattern('^[a-fA-F0-9]{64}$')][string]$CmakeSha256,
    [Parameter(Mandatory=$true)][string]$NinjaArchive,
    [Parameter(Mandatory=$true)][ValidatePattern('^[a-fA-F0-9]{64}$')][string]$NinjaSha256,
    [Parameter(Mandatory=$true)][string]$Output
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if ($env:OS -ne 'Windows_NT') { throw 'This bootstrap requires native Windows.' }
# .NET's process working directory can differ from PowerShell Set-Location.
# Restrict this bootstrap to fully qualified local paths, including the output.
foreach ($path in @($PythonArchive, $CmakeArchive, $NinjaArchive, $Output)) {
    if ($path -notmatch '^[A-Za-z]:[\\/]') { throw 'Use absolute local Windows paths (for example C:\owned\tools).' }
}
Add-Type -AssemblyName System.IO.Compression.FileSystem

function Assert-OrdinaryPath([string]$Path) {
    $item = Get-Item -LiteralPath $Path -Force
    while ($null -ne $item) {
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Linked bootstrap paths are unsupported.' }
        if ($item -is [IO.DirectoryInfo]) { $item = $item.Parent } else { $item = $item.Directory }
    }
}

function Expand-CheckedZip([string]$Archive, [string]$Expected, [string]$Destination) {
    Assert-OrdinaryPath $Archive
    # Keep the exact checked input open without permitting writes or deletion.
    $stream = [IO.File]::Open($Archive, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    $zip = $null
    try {
        $sha = [Security.Cryptography.SHA256]::Create()
        try { $actual = ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-', '').ToLowerInvariant() }
        finally { $sha.Dispose() }
        if ($actual -cne $Expected.ToLowerInvariant()) { throw 'Retained ZIP SHA256 mismatch.' }
        $stream.Position = 0
        $zip = [IO.Compression.ZipArchive]::new($stream, [IO.Compression.ZipArchiveMode]::Read, $true)
        $entries = [Collections.Generic.Dictionary[string,bool]]::new([StringComparer]::OrdinalIgnoreCase)
        $spellings = [Collections.Generic.Dictionary[string,string]]::new([StringComparer]::OrdinalIgnoreCase)
        if ($zip.Entries.Count -gt 50000) { throw 'Bootstrap ZIP has too many entries.' }
        [long]$expanded = 0
        foreach ($entry in $zip.Entries) {
            $expanded += $entry.Length
            if ($expanded -gt 2GB) { throw 'Bootstrap ZIP expanded size exceeds 2 GiB.' }
            $name = $entry.FullName
            $directory = $name.EndsWith('/')
            $path = $name.TrimEnd('/')
            $mode = ($entry.ExternalAttributes -shr 16) -band 0xffff
            if (-not $path -or $name.Contains('\') -or $name.EndsWith('//') -or
                (($mode -band 0xf000) -notin @(0, 0x8000, 0x4000)) -or ($mode -band 0xe00) -or
                ($entry.ExternalAttributes -band 0x400) -or
                (($mode -band 0xf000) -eq 0x4000 -and -not $directory)) {
                throw 'Unsafe or linked ZIP member.'
            }
            $prefix = ''
            foreach ($part in $path.Split('/')) {
                if (-not $part -or $part -in @('.', '..') -or $part -match '[\x00-\x1f\x7f<>:"|?*]' -or
                    $part -match '[. ]$' -or $part -match '^(?i:con|prn|aux|nul|com[1-9\u00b9\u00b2\u00b3]|lpt[1-9\u00b9\u00b2\u00b3])(?:\.|$)') {
                    throw 'Unsafe Windows ZIP path.'
                }
                if ($prefix) { $prefix += '/' }
                $prefix += $part
                if ($spellings.ContainsKey($prefix) -and $spellings[$prefix] -cne $prefix) {
                    throw 'Inconsistent explicit or implicit ZIP path spelling.'
                }
                $spellings[$prefix] = $prefix
            }
            if ($entries.ContainsKey($path)) { throw 'Duplicate or case-colliding ZIP member.' }
            $entries.Add($path, $directory)
        }
        if (-not $entries.Count) { throw 'Empty bootstrap ZIP.' }
        foreach ($path in $entries.Keys) {
            $parent = $path
            while ($parent.Contains('/')) {
                $parent = $parent.Substring(0, $parent.LastIndexOf('/'))
                if ($entries.ContainsKey($parent) -and -not $entries[$parent]) { throw 'ZIP file is an ancestor.' }
            }
        }
        [IO.Directory]::CreateDirectory($Destination) | Out-Null
        foreach ($entry in $zip.Entries) {
            $target = Join-Path $Destination $entry.FullName.TrimEnd('/')
            if ($entry.FullName.EndsWith('/')) { [IO.Directory]::CreateDirectory($target) | Out-Null; continue }
            [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target)) | Out-Null
            $inputStream = $entry.Open()
            try {
                $outputStream = [IO.File]::Open($target, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write)
                try {
                    $buffer = [byte[]]::new(65536)
                    [long]$written = 0
                    while (($count = $inputStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
                        $written += $count
                        if ($written -gt $entry.Length) { throw 'ZIP member exceeds declared size.' }
                        $outputStream.Write($buffer, 0, $count)
                    }
                    if ($written -ne $entry.Length) { throw 'ZIP member size mismatch.' }
                } finally { $outputStream.Dispose() }
            } finally { $inputStream.Dispose() }
        }
    } finally {
        if ($null -ne $zip) { $zip.Dispose() }
        $stream.Dispose()
    }
}

$outputPath = [IO.Path]::GetFullPath($Output)
if (Test-Path -LiteralPath $outputPath) { throw 'Bootstrap output must be new.' }
$parent = [IO.Path]::GetDirectoryName($outputPath)
if (-not (Test-Path -LiteralPath $parent -PathType Container)) { throw 'Create and exclusively own the bootstrap parent directory first.' }
Assert-OrdinaryPath $parent
$stage = Join-Path $parent ('.windows-tools-' + [Guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($stage) | Out-Null
try {
    Expand-CheckedZip ([IO.Path]::GetFullPath($PythonArchive)) $PythonSha256 (Join-Path $stage 'python')
    Expand-CheckedZip ([IO.Path]::GetFullPath($CmakeArchive)) $CmakeSha256 (Join-Path $stage 'cmake')
    Expand-CheckedZip ([IO.Path]::GetFullPath($NinjaArchive)) $NinjaSha256 (Join-Path $stage 'ninja')
    $policies = @(Get-ChildItem -LiteralPath (Join-Path $stage 'python') -Filter 'python*._pth' -File)
    $cmakeRoots = @(Get-ChildItem -LiteralPath (Join-Path $stage 'cmake') -Directory |
        Where-Object { $_.Name -match '^cmake-[0-9]+\.[0-9]+\.[0-9]+-windows-x86_64$' })
    if ($policies.Count -ne 1 -or $policies[0].Name -notmatch '^python[0-9]+\._pth$' -or $cmakeRoots.Count -ne 1) {
        throw 'Unexpected retained Python or CMake layout.'
    }
    $cmakeRelative = 'cmake/' + $cmakeRoots[0].Name + '/bin'
    foreach ($name in @('python/python.exe', 'ninja/ninja.exe', "$cmakeRelative/cmake.exe", "$cmakeRelative/ctest.exe", "$cmakeRelative/cpack.exe")) {
        if (-not (Test-Path -LiteralPath (Join-Path $stage $name) -PathType Leaf)) { throw "Missing retained host tool: $name" }
    }
    $policy = $policies[0]
    $stem = [IO.Path]::GetFileNameWithoutExtension($policy.Name)
    $searchPaths = @([IO.File]::ReadAllLines($policy.FullName) | Where-Object { $_.Trim() -and -not $_.Trim().StartsWith('#') })
    if ($searchPaths.Count -ne 2 -or $searchPaths[0] -cne ($stem + '.zip') -or $searchPaths[1] -cne '.' -or
        -not (Test-Path -LiteralPath (Join-Path $stage ('python/' + $stem + '.zip')) -PathType Leaf) -or
        -not (Test-Path -LiteralPath (Join-Path $stage ('python/' + $stem + '.dll')) -PathType Leaf)) {
        throw 'Unexpected embedded Python search policy or standard-library layout.'
    }
    # Retain the exact isolated policy but restore normal Python initialization,
    # including the invoked script directory needed for local helper imports.
    # The embedded standard-library ZIP and DLL are preserved unchanged.
    [IO.File]::Move($policies[0].FullName, $policies[0].FullName + '.retained-disabled')
    $receipt = [ordered]@{ schema_version = 1; scope = 'host-tool-bootstrap'; qualification = 'not-executed';
        archives = @{ python = $PythonSha256.ToLowerInvariant(); cmake = $CmakeSha256.ToLowerInvariant(); ninja = $NinjaSha256.ToLowerInvariant() };
        python = 'python/python.exe'; cmake_bin = $cmakeRelative; ninja_bin = 'ninja';
        separate_prerequisites = @('Microsoft compiler and Windows SDK', 'Git for checkout and Git-dependent tests') }
    [IO.File]::WriteAllText((Join-Path $stage 'bootstrap.json'), ($receipt | ConvertTo-Json -Depth 4), [Text.UTF8Encoding]::new($false))
    [IO.Directory]::Move($stage, $outputPath)
    $receipt | ConvertTo-Json -Depth 4
} finally {
    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Recurse -Force }
}

#!/usr/bin/env python3
"""Run a complete registered unit suite and expose every case and exclusion."""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import platform
import re
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]


def flatten(suite):
    for item in suite:
        if isinstance(item, unittest.TestSuite):
            yield from flatten(item)
        else:
            yield item


def inapplicable(case, system):
    """Only platform facts exclude cases; missing tools/permissions are failures."""
    name = case.id()
    if system != 'Windows' and name == 'test_agent_board.CoordinationTests.test_windows_delete_pending_mutex_requires_new_exclusive_creation':
        return 'Native Windows delete-pending directory handle semantics belong to Windows runners.'
    if system != 'Windows' and name == 'test_build.BuildTests.test_native_windows_selected_linker_file_identity':
        return 'Native Win32 linker file identity inspection belongs to Windows runners.'
    if system != 'Linux' and name.startswith('test_sdk.NativeLinuxToolchainTests.'):
        return 'Native Linux retained C/C++ compiler fixture belongs to Linux runners.'
    if system != 'Linux' and name in {
            'test_rust_build.RustBuildTests.test_native_distro_links_bind_owners_versions_link_and_runtime_notices',
            'test_rust_build.RustBuildTests.test_retained_target_libraries_still_reject_native_distro_links',
            'test_rust_build.RustBuildTests.test_native_distro_bad_dangling_escaping_chained_and_special_link_targets',
            'test_rust_build.RustBuildTests.test_native_distro_directory_links_and_other_library_names_are_not_allowed',
            'test_rust_build.RustBuildTests.test_native_distro_package_ambiguity_unowned_wrong_owner_and_versions_fail',
            'test_rust_build.RustBuildTests.test_native_distro_changed_target_and_retargeted_link_block_all_operations',
            'test_rust_build.RustBuildTests.test_native_distro_ownership_changes_and_missing_harness_family_invalidate_inputs',
            'test_rust_build.RustBuildTests.test_native_distro_target_replacement_during_ownership_queries_is_rejected',
            'test_rust_build.RustBuildTests.test_native_distro_link_text_cannot_hide_intermediate_symlink_traversal'}:
        return 'Native Debian Rust symlink and package-ownership fixtures belong to Linux runners; retained SDK and Windows ownership checks remain required.'
    if system != 'Linux' and name == 'test_release_check.ReleaseCheckTests.test_apt_timeout_stops_descendant_before_cleanup':
        return 'Native Linux APT descendant fixture belongs to Linux runners.'
    if system != 'Linux' and name.startswith('test_process_tree.LinuxSubreaper.'):
        return 'Native Linux descendant supervision belongs to the Linux runner.'
    if system != 'Windows' and name == 'test_process_tree.NativeProcessTree.test_windows_child_cannot_break_out_of_its_job':
        return 'Native Windows Job Object check belongs to the Windows runner.'
    if system == 'Windows':
        if name in {
                'test_import_wasm.ImportWasmTests.test_pinned_same_source_staging_and_relocated_exact_document_launch',
                'test_import_wasm.ImportWasmTests.test_windows_gui_entry_preserves_arguments_and_console_target_kind'}:
            return 'Unix opener/compiler fixtures; portable import identity checks and native Windows GUI linking remain required.'
        if name == 'test_coverage.CoverageTests.test_parent_success_with_inherited_log_child_is_rejected':
            return 'POSIX process-group fixture; Windows Job Object cases remain required.'
        if name.startswith('test_portability.Portability.') or name.startswith('test_portability.PortabilityTests.'):
            return 'ELF runtime qualification belongs to Linux runners; PE checks remain required.'
        if name == 'test_source_identity.SourceIdentityTests.test_executable_mode_changes_identity':
            return 'POSIX executable metadata belongs to POSIX runners.'
        if name == 'test_source_identity.SourceIdentityTests.test_source_links_rejected_in_plain_and_restored_trees':
            return 'POSIX source symlink fixture; portable source inventory checks remain required.'
    return None


class Recorded(unittest.TextTestResult):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.outcomes = {}

    def addSuccess(self, test):
        super().addSuccess(test)
        self.outcomes[test.id()] = {'status': 'passed'}

    def addError(self, test, error):
        super().addError(test, error)
        self.outcomes[test.id()] = {'status': 'failed', 'reason': 'error'}

    def addFailure(self, test, error):
        super().addFailure(test, error)
        self.outcomes[test.id()] = {'status': 'failed', 'reason': 'assertion'}

    def addSkip(self, test, reason):
        super().addSkip(test, reason)
        self.outcomes[test.id()] = {'status': 'incomplete', 'reason': reason}

    def addExpectedFailure(self, test, error):
        super().addExpectedFailure(test, error)
        self.outcomes[test.id()] = {'status': 'incomplete', 'reason': 'expected failure'}

    def addUnexpectedSuccess(self, test):
        super().addUnexpectedSuccess(test)
        self.outcomes[test.id()] = {'status': 'failed', 'reason': 'unexpected success'}

    def addSubTest(self, test, subtest, error):
        super().addSubTest(test, subtest, error)
        if error is not None:
            self.outcomes[test.id()] = {'status': 'failed', 'reason': 'subtest'}


def execute(suite, system=None, stream=None):
    tests = list(flatten(suite))
    names = [test.id() for test in tests]
    if not names or len(set(names)) != len(names):
        raise ValueError('empty or duplicate test inventory')
    system = system or platform.system()
    excluded, selected = {}, []
    for test in tests:
        reason = inapplicable(test, system)
        if reason:
            excluded[test.id()] = reason
        else:
            selected.append(test)
    if not selected:
        raise ValueError('no applicable checks; do not schedule this suite on this host')
    result = unittest.TextTestRunner(stream=stream or sys.stderr, verbosity=2, resultclass=Recorded).run(unittest.TestSuite(selected))
    required = {test.id() for test in selected}
    complete = (result.wasSuccessful() and set(result.outcomes) == required and
                all(item['status'] == 'passed' for item in result.outcomes.values()))
    return {'schema_version': 1, 'system': system, 'status': 'passed' if complete else 'failed',
            'inventory': names, 'excluded': excluded, 'results': result.outcomes}


def publish(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix=path.name + '-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'w') as stream:
            json.dump(value, stream, sort_keys=True, indent=2)
            stream.write('\n')
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        Path(temporary).unlink(missing_ok=True)


# Opt-in host diagnostics are deliberately outside normal test_*.py discovery.
DIAGNOSTICS = {'windows_hosts': ('tests/diagnostics/windows_hosts.py', 'Windows')}


def suite_source(suite, system=None):
    if not re.fullmatch(r'[a-z][a-z0-9_]*', suite):
        raise ValueError('invalid registered suite')
    if suite in DIAGNOSTICS:
        relative, required = DIAGNOSTICS[suite]
        if (system or platform.system()) != required:
            raise ValueError(suite + ' requires its native Windows host')
        name, path = 'diagnostic_' + suite, ROOT / relative
    else:
        name = 'test_' + suite
        path = ROOT / 'tests' / (name + '.py')
    if not path.is_file():
        raise ValueError('missing registered suite')
    return name, path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--suite', required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    name, path = suite_source(args.suite)
    args.output.unlink(missing_ok=True)
    # Test modules can import local fixtures and maintained tools explicitly.
    sys.path.insert(0, str(ROOT / 'tests'))
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    result = execute(unittest.defaultTestLoader.loadTestsFromModule(module))
    publish(args.output, result)
    return 0 if result['status'] == 'passed' else 1


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, ValueError, ImportError) as error:
        print('unit runner: ' + str(error), file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Build the private dependency-free Rust archive with identified offline inputs."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time

import package_notices
import process_tree
import sdk_environment
import windows_compiler


TARGETS = {
    'x86_64-unknown-linux-gnu': 'Linux',
    'aarch64-unknown-linux-gnu': 'Linux',
    'x86_64-pc-windows-msvc': 'Windows',
    'wasm32-unknown-emscripten': 'Emscripten',
}
NATIVE_LIBRARIES = {
    'Linux': {'gcc_s', 'gcc', 'util', 'rt', 'pthread', 'm', 'dl', 'c'},
    'Windows': {'advapi32', 'bcrypt', 'comdlg32', 'dbghelp', 'gdi32', 'kernel32',
                'ntdll', 'ole32', 'oleaut32', 'shell32', 'user32', 'userenv',
                'uuid', 'ws2_32', 'legacy_stdio_definitions', 'libcmt',
                'libvcruntime', 'libucrt', 'libcmtd', 'libvcruntimed', 'libucrtd'},
    'Emscripten': set(),
}
MAX_OUTPUT = 16 * 1024 * 1024
DISTRO_USR = Path('/usr')
DISTRO_TARGETS = {'x86_64-unknown-linux-gnu': ('x86_64-linux-gnu', 'amd64'),
                  'aarch64-unknown-linux-gnu': ('aarch64-linux-gnu', 'arm64')}
CONFIG_FIELDS = {'schema_version', 'source_root', 'build_dir', 'target', 'system',
                 'profile', 'tools', 'sysroot', 'target_libdir', 'target_libraries',
                 'source_inputs', 'sources', 'flags', 'artifact_path', 'receipt_path',
                 'native_static_libs', 'notice_files', 'notices', 'sdk_root',
                 'cpp_sdk_root', 'sdk_manifest', 'cpp_sdk_manifest', 'metadata'}


def _file_identity(value):
    return [value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_ctime_ns]


def _snapshot(path):
    path = Path(path)
    if not path.is_absolute():
        raise ValueError('Rust inputs require absolute paths: ' + str(path))
    path = path.resolve(strict=True)
    before = path.stat()
    if not stat.S_ISREG(before.st_mode):
        raise ValueError('Rust input must be a regular file: ' + str(path))
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    if _file_identity(path.stat()) != _file_identity(before):
        raise ValueError('Rust input changed while identified: ' + str(path))
    return {'path': str(path), 'sha256': digest.hexdigest(), 'identity': _file_identity(before)}


def native_tool_identity(cargo, rustc):
    """Bind explicitly selected tools without executing them or discovering Rust."""
    result = {'cargo': _snapshot(cargo), 'rustc': _snapshot(rustc)}
    if (result['cargo']['identity'][:2] == result['rustc']['identity'][:2]
            or result['cargo']['sha256'] == result['rustc']['sha256']):
        raise ValueError('Rust proxies are unsupported; Cargo and rustc must be distinct actual tools')
    for name, row in result.items():
        if Path(row['path']).stem.lower() == 'rustup':
            raise ValueError('Rust proxies are unsupported; select the actual ' + name + ' executable')
        if os.name != 'nt' and not os.access(row['path'], os.X_OK):
            raise ValueError('selected Rust tool is not executable: ' + row['path'])
        for proxy_name in ('rustup', 'rustup.exe'):
            proxy = Path(row['path']).parent / proxy_name
            if proxy.is_file():
                identity = _snapshot(proxy)
                if identity['identity'][:2] == row['identity'][:2] or identity['sha256'] == row['sha256']:
                    raise ValueError('Rust proxies are unsupported; select the actual ' + name + ' executable')
    return result


def select_native_tools():
    if not sys.platform.startswith('linux'):
        raise ValueError('native Rust discovery requires Linux; prepare a retained Rust SDK')
    result = {}
    for name in ('cargo', 'rustc'):
        selected = shutil.which(name)
        if not selected:
            raise ValueError('missing ' + name + '; explicitly prepare Rust tools before building')
        result[name] = str(Path(selected).resolve(strict=True))
    native_tool_identity(**result)
    return result


def _absolute(value, label, *, existing=False):
    path = Path(value)
    if not path.is_absolute():
        raise ValueError(label + ' must be an absolute path')
    if path.is_symlink():
        raise ValueError(label + ' must not be a symlink')
    return path.resolve(strict=existing)


def _configs_absent(*directories):
    checked = set()
    for directory in directories:
        directory = Path(directory)
        for ancestor in (directory, *directory.parents):
            if ancestor in checked:
                continue
            checked.add(ancestor)
            for name in ('config', 'config.toml'):
                candidate = ancestor / '.cargo' / name
                if candidate.exists() or candidate.is_symlink():
                    raise ValueError('ambient Cargo configuration is unsupported: ' + str(candidate))


def child_environment(build_dir, cargo, rustc, flags, environment=None):
    inherited = dict(os.environ if environment is None else environment)
    sdk_environment.require_clean({name: inherited.get(name) for name in sdk_environment.HOST_OVERRIDES
                                   if name.startswith('LD_')})
    for key, value in inherited.items():
        upper = key.upper()
        permitted = upper in ('CARGO_HOME', 'CARGO_TARGET_DIR', 'CARGO_MAKEFLAGS', 'RUSTUP_HOME',
                              'RUST_LOG', 'RUST_BACKTRACE', 'RUST_LIB_BACKTRACE')
        permitted = permitted or (upper == 'CARGO_NET_OFFLINE' and value == 'true')
        if (upper.startswith(('RUST', 'CARGO_')) and not permitted) or upper == 'LD_PRELOAD':
            if value:
                raise ValueError('ambient Rust setting is unsupported: ' + key)
    home = Path(build_dir) / 'cargo-home'
    target = Path(build_dir) / 'target'
    _configs_absent(build_dir, home)
    if home.is_symlink() or target.is_symlink():
        raise ValueError('private Cargo home and output must not be symlinks')
    for name in ('config', 'config.toml'):
        if (home / name).exists() or (home / name).is_symlink():
            raise ValueError('private Cargo home contains unapproved configuration')
    home.mkdir(parents=True, exist_ok=True)
    target.mkdir(parents=True, exist_ok=True)
    result = {key: value for key, value in inherited.items()
              if not key.upper().startswith(('RUST', 'CARGO_'))
              and key.upper() not in ('MAKEFLAGS', 'MFLAGS', 'MAKELEVEL', 'JOBSERVERS', 'JOBSERVER_FDS')}
    result.update({'CARGO_HOME': str(home), 'CARGO_TARGET_DIR': str(target),
                   'RUSTC': str(rustc), 'CARGO_ENCODED_RUSTFLAGS': '\x1f'.join(flags),
                   'CARGO_NET_OFFLINE': 'true', 'CARGO_BUILD_JOBS': '1',
                   'CARGO_INCREMENTAL': '0', 'CARGO_TERM_COLOR': 'never',
                   'CARGO_PROFILE_DEV_PANIC': 'abort', 'CARGO_PROFILE_RELEASE_PANIC': 'abort',
                   'CARGO_PROFILE_DEV_LTO': 'false', 'CARGO_PROFILE_RELEASE_LTO': 'false',
                   'CARGO_PROFILE_DEV_CODEGEN_UNITS': '1', 'CARGO_PROFILE_RELEASE_CODEGEN_UNITS': '1'})
    # Rust tools are absolute; PATH still supplies the selected native C++ tools.
    result['PATH'] = os.pathsep.join(dict.fromkeys((str(Path(cargo).parent), str(Path(rustc).parent),
                                                  inherited.get('PATH', ''))))
    return result


def _run(argv, *, cwd, environment, compiler=False, timeout=180):
    session = windows_compiler.BuildSession(environment) if compiler and os.name == 'nt' else None
    environment = session.environment if session else environment
    with tempfile.TemporaryFile(dir=cwd) as output:
        owner = process_tree.launch(argv, cwd=cwd, stream=output, env=environment)
        try:
            deadline = time.monotonic() + timeout
            while owner.poll() is None:
                if time.monotonic() >= deadline or os.fstat(output.fileno()).st_size > MAX_OUTPUT:
                    owner.terminate()
                    raise ValueError('Rust command exceeded its time or output bound')
                time.sleep(0.01)
            code = owner.process.returncode
            if code:
                owner.terminate()
                owner.finish()
            elif session:
                session.finish(owner)
            else:
                owner.finish()
            if os.fstat(output.fileno()).st_size > MAX_OUTPUT:
                raise ValueError('Rust command exceeded its output bound')
            output.seek(0)
            raw = output.read(MAX_OUTPUT + 1).decode('utf-8', errors='strict')
            if code:
                raise ValueError('Rust command failed (' + str(code) + '): ' + raw[-8192:])
            return raw
        finally:
            owner.close()


def _flags(target, sysroot):
    result = ['--sysroot', str(sysroot), '-Cpanic=abort', '-Ccodegen-units=1',
              '-Clto=no', '-Cembed-bitcode=no', '-Crelocation-model=pic']
    if TARGETS[target] == 'Windows':
        result += ['-Ctarget-feature=+crt-static']
    return result


def _sources(root, sdk=False):
    rust = root / 'rust'
    paths = []
    if not rust.is_dir() or rust.is_symlink():
        raise ValueError('missing Rust workspace; expected rust/Cargo.toml')
    for path in sorted(rust.rglob('*')):
        if path.is_symlink():
            raise ValueError('Rust source tree must not contain links: ' + str(path))
        if path.is_file():
            if path.suffix in ('.rs', '.toml') or path.name == 'Cargo.lock':
                paths.append(path)
            elif path.name == 'build.rs':
                raise ValueError('Rust build scripts are unsupported')
        elif not path.is_dir():
            raise ValueError('Rust source tree contains a special entry')
    required = (rust / 'Cargo.toml', rust / 'Cargo.lock',
                rust / 'text_validation/Cargo.toml', rust / 'text_validation/src/lib.rs')
    if any(path not in paths for path in required):
        raise ValueError('missing Rust workspace manifest, frozen lockfile or component source')
    lock = (rust / 'Cargo.lock').read_text(encoding='utf-8').split('[[package]]', 1)[0]
    if not re.search(r'^version\s*=\s*3\s*$', lock, re.MULTILINE):
        raise ValueError('Rust requires Cargo.lock format 3 readable by baseline Cargo 1.63')
    if any(path.name == 'build.rs' for path in paths):
        raise ValueError('Rust build scripts are unsupported')
    producers = [Path(__file__), Path(process_tree.__file__), Path(windows_compiler.__file__),
                 Path(windows_compiler.windows_toolchain.__file__), Path(package_notices.__file__),
                 Path(sdk_environment.__file__)]
    if sdk:
        producers.extend(Path(__file__).parent / name for name in
                         ('rust_sdk.py', 'dependency_archive.py', 'sdk_manifest.py'))
    paths.extend(path.resolve(strict=True) for path in producers)
    return {str(path): _snapshot(path) for path in paths}


def _distro_package(path):
    query = str(DISTRO_USR / 'bin/dpkg-query')
    try:
        rows = package_notices.command(query, '-S', str(path)).splitlines()
        if len(rows) != 1 or ': ' not in rows[0]:
            raise ValueError('ambiguous package ownership')
        package, owned = rows[0].rsplit(': ', 1)
        if (not re.fullmatch(r'[a-z0-9][a-z0-9+.-]*(?::[a-z0-9]+)?', package)
                or owned != str(path)):
            raise ValueError('package ownership names a different input')
        status = package_notices.command(query, '-W', '-f=${db:Status-Abbrev}\n${Version}', package)
        lines = status.splitlines()
        if len(lines) != 2 or lines[0] != 'ii ' or not lines[1] or lines[1].strip() != lines[1]:
            raise ValueError('package is not installed with one identified version')
        return {'package': package, 'version': lines[1]}
    except (ValueError, subprocess.SubprocessError, OSError) as error:
        raise ValueError('native Rust package ownership is unavailable: ' + str(path)
                         + '; prepare a retained Rust SDK (' + str(error) + ')') from error


def _distro_library_link(path, directory, target, rustc, compiler_version):
    if target not in DISTRO_TARGETS:
        raise ValueError('unsupported native Rust library link layout; prepare a retained Rust SDK')
    multiarch, architecture = DISTRO_TARGETS[target]
    expected_directory = DISTRO_USR / 'lib/rustlib' / target / 'lib'
    if (directory != expected_directory or path.parent != directory
            or expected_directory.resolve(strict=True) != expected_directory
            or Path(rustc) != DISTRO_USR / 'bin/rustc'
            or not re.fullmatch(r'lib(?:std|test)-[0-9a-f]+\.so', path.name)):
        raise ValueError('unsupported native Rust library link layout; prepare a retained Rust SDK')
    before = path.lstat()
    if not stat.S_ISLNK(before.st_mode):
        raise ValueError('native Rust library input stopped being a link')
    text = os.readlink(path)
    expected = DISTRO_USR / 'lib' / multiarch / path.name
    try:
        target_before = expected.lstat()
        if (text not in ('../../../' + multiarch + '/' + path.name, str(expected))
                or path.resolve(strict=True) != expected or expected.resolve(strict=True) != expected
                or not stat.S_ISREG(target_before.st_mode)):
            raise ValueError('link must name the matched ordinary distro runtime file')
    except (ValueError, OSError, RuntimeError) as error:
        raise ValueError('invalid native Rust library link: ' + str(path)
                         + '; prepare a retained Rust SDK (' + str(error) + ')') from error
    ownership_tool = _snapshot(_absolute(DISTRO_USR / 'bin/dpkg-query',
                                        'native Rust package ownership tool', existing=True))
    compiler = _distro_package(Path(rustc))
    link = _distro_package(path)
    runtime = _distro_package(expected)
    runtime_name = 'libstd-rust-' + '.'.join(compiler_version.split('.')[:2])
    if (compiler['package'] not in ('rustc', 'rustc:' + architecture)
            or link['package'] != 'libstd-rust-dev:' + architecture
            or runtime['package'] != runtime_name + ':' + architecture
            or compiler['version'] != link['version'] or compiler['version'] != runtime['version']):
        raise ValueError('native Rust compiler and library package owners or versions differ; '
                         'prepare a retained Rust SDK')
    result = {'path': str(path), 'link': text, 'identity': _file_identity(before),
              'target': _snapshot(expected), 'compiler_package': compiler,
              'link_package': link, 'target_package': runtime,
              'ownership_tool': ownership_tool}
    link_after, target_after = path.lstat(), expected.lstat()
    if (not stat.S_ISLNK(link_after.st_mode) or _file_identity(link_after) != result['identity']
            or os.readlink(path) != text or path.resolve(strict=True) != expected
            or not stat.S_ISREG(target_after.st_mode)
            or expected.resolve(strict=True) != expected or result['target']['path'] != str(expected)
            or _file_identity(target_after) != _file_identity(target_before)
            or _file_identity(target_after) != result['target']['identity']
            or _snapshot(ownership_tool['path']) != ownership_tool):
        raise ValueError('native Rust library link or target changed while identified')
    return result


def _target_libraries(directory, native_target=None, native_rustc=None, compiler_version=None):
    directory = _absolute(directory, 'Rust target library directory', existing=True)
    result = {}
    for path in sorted(directory.rglob('*')):
        if path.is_symlink():
            if native_target is None:
                raise ValueError('Rust target libraries must not contain symlinks')
            result[str(path)] = _distro_library_link(path, directory, native_target,
                                                    native_rustc, compiler_version)
        elif path.is_file():
            result[str(path)] = _snapshot(path)
        elif not path.is_dir():
            raise ValueError('Rust target libraries contain a special entry')
    required = ('libcore-', 'libcompiler_builtins-')
    if native_target:
        required += ('libstd-', 'libtest-')
    for prefix in required:
        if not any(Path(path).name.startswith(prefix) and path.endswith('.rlib') for path in result):
            raise ValueError('missing matched ' + prefix[:-1] + ' target library; prepare the exact target')
    links = [row for row in result.values() if 'link' in row]
    if links:
        families = [Path(row['path']).name.split('-', 1)[0] for row in links]
        if sorted(families) != ['libstd', 'libtest'] or any(
                str(Path(row['path']).with_suffix('.rlib')) not in result for row in links):
            raise ValueError('incomplete native Rust distro runtime library family; prepare a retained Rust SDK')
    return result


def _metadata(root, cargo, environment, build):
    raw = _run([cargo, 'metadata', '--frozen', '--no-deps', '--format-version', '1',
                '--manifest-path', str(root / 'rust/Cargo.toml')],
               cwd=build, environment=environment)
    data = json.loads(raw)
    packages = data.get('packages', [])
    if (len(packages) != 1 or len(data.get('workspace_members', [])) != 1
            or Path(data.get('workspace_root', '')).resolve() != root / 'rust'):
        raise ValueError('Rust pilot requires its one dependency-free workspace member')
    package = packages[0]
    expected = root / 'rust/text_validation/Cargo.toml'
    if (package.get('name') != 'foundation-text-validation'
            or Path(package.get('manifest_path', '')).resolve() != expected or package.get('source') is not None
            or package.get('dependencies') or package.get('edition') != '2021'
            or package.get('rust_version') != '1.63'):
        raise ValueError('Rust pilot requires edition 2021, Rust 1.63 and zero external crates')
    targets = package.get('targets', [])
    if (len(targets) != 1 or targets[0].get('name') != 'foundation_rust'
            or set(targets[0].get('crate_types', [])) != {'staticlib', 'rlib'}
            or set(targets[0].get('kind', [])) != {'staticlib', 'rlib'}):
        raise ValueError('Rust pilot requires only the foundation_rust staticlib and rlib; no build scripts or macros')
    return {'package_id': package['id'], 'workspace_root': data['workspace_root'],
            'manifest_path': str(expected)}


def parse_native_static_libs(raw, system):
    lines = [line.split('native-static-libs:', 1)[1].strip() for line in raw.splitlines()
             if 'native-static-libs:' in line]
    if len(lines) > 1:
        raise ValueError('ambiguous Rust native-static-libs receipt')
    tokens = lines[0].split() if lines else []
    result = []
    for token in tokens:
        if system == 'Windows' and token.lower().endswith('.lib') and re.fullmatch(r'[A-Za-z0-9_]+\.lib', token):
            name = token[:-4].lower()
        elif token.startswith('-l') and re.fullmatch(r'-l[A-Za-z0-9_]+', token):
            name = token[2:]
        else:
            raise ValueError('unapproved Rust native linkage argument: ' + token)
        if name not in NATIVE_LIBRARIES[system]:
            raise ValueError('unapproved Rust native library: ' + name)
        if name not in result:
            result.append(name)
    return result


def _probe_native_libs(build, rustc, target, flags, environment):
    probe = build / 'link-probe'
    if probe.is_symlink():
        raise ValueError('Rust probe output must not be a symlink')
    probe.mkdir(exist_ok=True)
    source = probe / 'probe.rs'
    _save_bytes(source, b'#![no_std]\n#[panic_handler]\nfn panic(_: &core::panic::PanicInfo) -> ! { loop {} }\n#[no_mangle]\npub extern "C" fn foundation_link_probe() -> u32 { 1 }\n')
    artifact = probe / ('probe.lib' if TARGETS[target] == 'Windows' else 'libprobe.a')
    raw = _run([rustc, '--crate-name', 'foundation_link_probe', '--crate-type', 'staticlib',
                '--edition', '2021', '--target', target, '--print', 'native-static-libs',
                *flags, str(source), '-o', str(artifact)], cwd=build, environment=environment,
               compiler=True)
    if not artifact.is_file():
        raise ValueError('Rust target probe produced no static archive')
    return parse_native_static_libs(raw, TARGETS[target])


def _notices(sdk, tools, libraries, metadata=None):
    paths = set()
    if sdk:
        from rust_sdk import verify_rust_sdk
        data = metadata if metadata is not None else verify_rust_sdk(sdk, execute=False)
        for relative in data.get('licenses', []):
            paths.update(package_notices.notice_files(Path(sdk) / relative))
        if not paths:
            raise ValueError('Rust SDK has no retained target notices')
    else:
        for path in [row['path'] for row in tools.values()] + [path for path in libraries
                     if Path(path).name.startswith(('libcore-', 'libcompiler_builtins-'))]:
            _, notice = package_notices.distro_notice(path)
            paths.add(notice)
        for row in libraries.values():
            if 'link' in row:
                for provider in ('link_package', 'target_package'):
                    package = row[provider]['package'].split(':', 1)[0]
                    paths.add(package_notices.regular(DISTRO_USR / 'share/doc' / package / 'copyright'))
    notices = {str(path): _snapshot(path) for path in sorted(paths)}
    # Distro notices can reference separately installed complete license texts.
    for path in list(notices):
        for name in re.findall(r'/usr/share/common-licenses/([A-Za-z0-9.+_-]+)', Path(path).read_text(encoding='utf-8')):
            license_path = Path('/usr/share/common-licenses') / name
            if license_path.is_file():
                notices[str(license_path.resolve())] = _snapshot(license_path.resolve())
            else:
                raise ValueError('Rust notice references a missing complete license: ' + name)
    return notices


def _sdk_identity(sdk, cpp_sdk, target):
    if sdk:
        from rust_sdk import verify_rust_sdk
        identity = _snapshot(Path(sdk) / 'rust-sdk.json')
        verify_rust_sdk(sdk, cpp_sdk=cpp_sdk, target=target, execute=False)
        if _snapshot(Path(sdk) / 'rust-sdk.json') != identity:
            raise ValueError('Rust SDK metadata changed while verifying')
        return identity
    return None


def describe(source_root, build_dir, target, cargo, rustc, profile='debug', sdk_root=None,
             cpp_sdk_root=None):
    if target not in TARGETS or profile not in ('debug', 'release'):
        raise ValueError('unsupported Rust target or profile')
    root = _absolute(source_root, 'Rust source root', existing=True)
    build = _absolute(build_dir, 'Rust build directory')
    if build == root or root / 'rust' == build or root / 'rust' in build.parents:
        raise ValueError('Cargo outputs must be outside the Rust source tree')
    sdk = str(_absolute(sdk_root, 'Rust SDK root', existing=True)) if sdk_root else None
    cpp_sdk = str(_absolute(cpp_sdk_root, 'C++ SDK root', existing=True)) if cpp_sdk_root else None
    if not sdk and (TARGETS[target] != 'Linux' or cpp_sdk):
        raise ValueError('this Rust profile requires a prepared retained Rust SDK')
    build.mkdir(parents=True, exist_ok=True)
    _configs_absent(root / 'rust', root / 'rust/text_validation', build)
    tools = native_tool_identity(cargo, rustc)
    sdk_identity = _snapshot(Path(sdk) / 'rust-sdk.json') if sdk else None
    cpp_identity = _snapshot(Path(cpp_sdk) / 'sdk.json') if cpp_sdk else None
    if sdk:
        from rust_sdk import verify_rust_sdk
        manifest = verify_rust_sdk(sdk, cpp_sdk=cpp_sdk, target=target, execute=False)
        if _snapshot(Path(sdk) / 'rust-sdk.json') != sdk_identity:
            raise ValueError('Rust SDK metadata changed while describing')
        for name in ('cargo', 'rustc'):
            if Path(tools[name]['path']) != (Path(sdk) / manifest['compiler'][name]).resolve(strict=True):
                raise ValueError('selected Rust tool differs from its retained SDK')
    initial = _sources(root, bool(sdk))
    environment = child_environment(build, tools['cargo']['path'], tools['rustc']['path'], [])
    raw = _run([tools['rustc']['path'], '-vV'], cwd=build, environment=environment)
    fields = dict(line.split(': ', 1) for line in raw.splitlines() if ': ' in line)
    version = fields.get('release', '')
    if not re.fullmatch(r'\d+\.\d+\.\d+', version) or tuple(map(int, version.split('.'))) < (1, 63, 0):
        raise ValueError('Rust requires a stable compiler at least version 1.63.0')
    if not sdk and fields.get('host') != target:
        raise ValueError('unprepared native Rust must use its exact host target')
    tools['rustc'].update({'version': version, 'host': fields.get('host'), 'verbose_version': raw.strip()})
    tools['cargo']['version'] = _run([tools['cargo']['path'], '--version'], cwd=build, environment=environment).strip()
    cargo_version = re.match(r'^cargo (\d+\.\d+\.\d+)(?:\s|$)', tools['cargo']['version'])
    if not cargo_version or tuple(map(int, cargo_version.group(1).split('.'))) < (1, 63, 0):
        raise ValueError('Rust requires Cargo version 1.63.0 or newer')
    if sdk and (version != manifest['compiler']['version']
                or fields.get('host') != manifest['compiler']['host']
                or cargo_version.group(1) != manifest['compiler']['cargo_version']):
        raise ValueError('Rust executable versions differ from retained SDK metadata')
    sysroot = _run([tools['rustc']['path'], '--print', 'sysroot'], cwd=build, environment=environment).strip()
    libdir = _run([tools['rustc']['path'], '--print', 'target-libdir', '--target', target],
                  cwd=build, environment=environment).strip()
    sysroot = str(_absolute(sysroot, 'Rust sysroot', existing=True))
    libdir = str(_absolute(libdir, 'Rust target library directory', existing=True))
    if sdk and (Path(sysroot) != (Path(sdk) / manifest['compiler']['sysroot']).resolve(strict=True)
                or Path(libdir) != (Path(sdk) / manifest['target']['library_directory']).resolve(strict=True)):
        raise ValueError('Rust compiler target libraries differ from its retained SDK')
    libraries = _target_libraries(libdir, None if sdk else target,
                                 tools['rustc']['path'], version)
    flags = _flags(target, sysroot)
    environment = child_environment(build, tools['cargo']['path'], tools['rustc']['path'], flags)
    metadata = _metadata(root, tools['cargo']['path'], environment, build)
    libs = _probe_native_libs(build, tools['rustc']['path'], target, flags, environment)
    notices = _notices(sdk, tools, libraries, manifest if sdk else None)
    suffix = 'foundation_rust.lib' if TARGETS[target] == 'Windows' else 'libfoundation_rust.a'
    result = {'schema_version': 1, 'source_root': str(root), 'build_dir': str(build),
              'target': target, 'system': TARGETS[target], 'profile': profile, 'tools': tools,
              'sysroot': sysroot, 'target_libdir': libdir, 'target_libraries': libraries,
              'source_inputs': sorted(initial), 'sources': initial, 'flags': flags,
              'artifact_path': str(build / 'target' / target / profile / suffix),
              'receipt_path': str(build / 'receipt.json'), 'native_static_libs': libs,
              'notice_files': sorted(notices), 'notices': notices, 'sdk_root': sdk,
              'cpp_sdk_root': cpp_sdk, 'sdk_manifest': sdk_identity,
              'cpp_sdk_manifest': cpp_identity, 'metadata': metadata}
    _unchanged(result)
    return result


def _unchanged(config):
    _configs_absent(Path(config['source_root']) / 'rust',
                    Path(config['source_root']) / 'rust/text_validation', Path(config['build_dir']))
    if _sources(Path(config['source_root']), bool(config['sdk_root'])) != config['sources']:
        raise ValueError('Rust source inputs changed; reconfigure before building')
    for name, row in config['tools'].items():
        if _snapshot(row['path']) != {key: row[key] for key in ('path', 'sha256', 'identity')}:
            raise ValueError('selected Rust tool changed; use a fresh configured build tree')
    if _target_libraries(config['target_libdir'], None if config['sdk_root'] else config['target'],
                         config['tools']['rustc']['path'], config['tools']['rustc']['version']) != config['target_libraries']:
        raise ValueError('Rust target library inputs changed; reconfigure with the verified SDK')
    if any(_snapshot(path) != row for path, row in config['notices'].items()):
        raise ValueError('Rust dependency notice inputs changed')
    if _sdk_identity(config['sdk_root'], config['cpp_sdk_root'], config['target']) != config['sdk_manifest']:
        raise ValueError('Rust SDK identity changed')
    if config['cpp_sdk_root'] and _snapshot(Path(config['cpp_sdk_root']) / 'sdk.json') != config['cpp_sdk_manifest']:
        raise ValueError('paired C++ SDK identity changed')


def _save_bytes(path, raw):
    path = Path(path)
    if path.is_symlink():
        raise ValueError('Rust output must not be a symlink: ' + str(path))
    if path.exists() and path.read_bytes() == raw:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.' + path.name + '-', delete=False) as stream:
        temporary = Path(stream.name)
        stream.write(raw)
    try:
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


def save_config(path, data):
    path = Path(path)
    if set(data) == CONFIG_FIELDS and path.exists():
        previous = json.loads(path.read_text(encoding='utf-8'))
        fields = CONFIG_FIELDS - {'source_inputs', 'sources', 'metadata'}
        if set(previous) != CONFIG_FIELDS or any(previous[name] != data[name] for name in fields):
            raise ValueError('Rust toolchain or configuration changed; use a fresh build tree')
    _save_bytes(path, (json.dumps(data, indent=2, sort_keys=True) + '\n').encode('utf-8'))


def _load_config(path):
    path = _absolute(path, 'Rust configuration', existing=True)
    data = json.loads(path.read_text(encoding='utf-8'))
    if set(data) != CONFIG_FIELDS or data['schema_version'] != 1:
        raise ValueError('invalid Rust build configuration schema')
    build = _absolute(data['build_dir'], 'Rust build directory', existing=True)
    if path.parent != build:
        raise ValueError('Rust configuration must be inside its private build directory')
    if data['target'] not in TARGETS or data['system'] != TARGETS[data['target']] or data['profile'] not in ('debug', 'release'):
        raise ValueError('invalid Rust configuration target or profile')
    suffix = 'foundation_rust.lib' if data['system'] == 'Windows' else 'libfoundation_rust.a'
    if (data['flags'] != _flags(data['target'], data['sysroot'])
            or data['artifact_path'] != str(build / 'target' / data['target'] / data['profile'] / suffix)
            or data['receipt_path'] != str(build / 'receipt.json')
            or data['source_inputs'] != sorted(data['sources'])
            or data['notice_files'] != sorted(data['notices'])):
        raise ValueError('Rust configuration contains uncontrolled flags, inputs or outputs')
    for name in data['native_static_libs']:
        if name not in NATIVE_LIBRARIES[data['system']]:
            raise ValueError('Rust configuration contains unapproved native linkage')
    _unchanged(data)
    return data, _snapshot(path)


def _output_directories(data, tree='target'):
    build = Path(data['build_dir'])
    for path in (build / tree, build / tree / data['target'],
                 build / tree / data['target'] / data['profile']):
        if path.is_symlink() or (path.exists() and not path.is_dir()):
            raise ValueError('Rust output directory must be an ordinary directory: ' + str(path))
        if path.resolve() != path:
            raise ValueError('Rust output directory escapes its private build tree')


def _artifact(data):
    _output_directories(data)
    path = _absolute(data['artifact_path'], 'Rust generated archive', existing=True)
    if str(path) != data['artifact_path']:
        raise ValueError('Rust generated archive escapes its private build tree')
    return _snapshot(path)


def _clean_package(data, environment, target_dir):
    _run([data['tools']['cargo']['path'], 'clean', '--frozen', '--package', 'foundation-text-validation',
          '--manifest-path', str(Path(data['source_root']) / 'rust/Cargo.toml'),
          '--target', data['target'], '--target-dir', str(target_dir)],
         cwd=data['build_dir'], environment=environment)


def build(config_path):
    data, config_identity = _load_config(config_path)
    _output_directories(data)
    receipt_path = Path(data['receipt_path'])
    prior = None
    prior_identity = None
    if receipt_path.exists():
        prior_identity = _snapshot(receipt_path)
        prior = json.loads(receipt_path.read_text(encoding='utf-8'))
        if (set(prior) != {'schema_version', 'config', 'artifact', 'native_static_libs', 'target', 'profile', 'policy'}
                or prior['schema_version'] != 1 or prior['target'] != data['target']
                or prior['profile'] != data['profile'] or prior['native_static_libs'] != data['native_static_libs']
                or prior['policy'] != 'frozen-dependency-free-staticlib'
                or prior['artifact'].get('path') != data['artifact_path']):
            raise ValueError('invalid previous Rust build receipt')
    environment = child_environment(data['build_dir'], data['tools']['cargo']['path'],
                                    data['tools']['rustc']['path'], data['flags'])
    # Cargo 1.63 uses source mtimes for freshness. Changed identified inputs must
    # invalidate its private package cache even when source timestamps went back.
    rebound = prior is None or prior['config'] != config_identity
    if rebound:
        _clean_package(data, environment, Path(data['build_dir']) / 'target')
    argv = [data['tools']['cargo']['path'], 'build', '--frozen', '--jobs', '1',
            '--manifest-path', str(Path(data['source_root']) / 'rust/Cargo.toml'),
            '--target', data['target'], '--target-dir', str(Path(data['build_dir']) / 'target'),
            '--message-format', 'json-render-diagnostics']
    if data['profile'] == 'release':
        argv.append('--release')
    raw = _run(argv, cwd=data['build_dir'], environment=environment, compiler=True, timeout=600)
    artifacts = []
    for line in raw.splitlines():
        try:
            item = json.loads(line)
        except ValueError:
            continue
        if item.get('reason') == 'compiler-artifact':
            if item.get('package_id') != data['metadata']['package_id']:
                raise ValueError('Cargo produced an unapproved package artifact')
            artifacts.append(item)
        if item.get('reason') == 'compiler-message':
            rendered = item.get('message', {}).get('rendered')
            if rendered:
                print(rendered, end='', file=sys.stderr)
    if len(artifacts) != 1 or data['artifact_path'] not in artifacts[0].get('filenames', []):
        raise ValueError('Cargo did not identify the expected Rust static archive')
    if any(Path(name).suffix.lower() in ('.so', '.dylib', '.dll') for item in artifacts for name in item.get('filenames', [])):
        raise ValueError('Rust dynamic libraries are unsupported')
    _unchanged(data)
    if _snapshot(config_path) != config_identity:
        raise ValueError('Rust configuration changed during build')
    artifact = _artifact(data)
    if prior_identity is not None and _snapshot(receipt_path) != prior_identity:
        raise ValueError('Rust build receipt changed during compilation')
    if artifacts[0].get('fresh') and (rebound or prior['artifact'] != artifact):
        raise ValueError('Cargo reused an unbound or changed Rust archive; remove the archive and rebuild')
    receipt = {'schema_version': 1, 'config': config_identity, 'artifact': artifact,
               'native_static_libs': data['native_static_libs'], 'target': data['target'],
               'profile': data['profile'], 'policy': 'frozen-dependency-free-staticlib'}
    save_config(data['receipt_path'], receipt)
    print('RUST_BUILD_COMPLETION ' + json.dumps({'artifact': artifact['path'], 'sha256': artifact['sha256'],
                                               'fresh': bool(artifacts[0].get('fresh'))}, sort_keys=True))
    return receipt


def verify(config_path):
    data, config_identity = _load_config(config_path)
    receipt_path = _absolute(data['receipt_path'], 'Rust build receipt', existing=True)
    receipt = json.loads(receipt_path.read_text(encoding='utf-8'))
    expected = {'schema_version': 1, 'config': config_identity, 'artifact': _artifact(data),
                'native_static_libs': data['native_static_libs'], 'target': data['target'],
                'profile': data['profile'], 'policy': 'frozen-dependency-free-staticlib'}
    if receipt != expected:
        raise ValueError('Rust generated archive differs from its bound build receipt')
    _unchanged(data)
    if _snapshot(config_path) != config_identity:
        raise ValueError('Rust configuration changed during receipt verification')
    return receipt


def test(config_path):
    data, config_identity = _load_config(config_path)
    if data['target'] != data['tools']['rustc']['host'] or data['system'] == 'Emscripten':
        raise ValueError('Rust unit tests require an executable exact-host native target')
    _output_directories(data, 'unit-target')
    flags = [flag for flag in data['flags'] if flag != '-Cpanic=abort']
    environment = child_environment(data['build_dir'], data['tools']['cargo']['path'],
                                    data['tools']['rustc']['path'], flags)
    for name in ('CARGO_PROFILE_DEV_PANIC', 'CARGO_PROFILE_RELEASE_PANIC'):
        environment.pop(name)
    target_dir = str(Path(data['build_dir']) / 'unit-target')
    environment['CARGO_TARGET_DIR'] = target_dir
    state_path = Path(data['build_dir']) / 'unit-state.json'
    state = {'schema_version': 1, 'config': config_identity, 'target': data['target'], 'profile': data['profile']}
    previous_identity = None
    previous = None
    if state_path.exists():
        _absolute(state_path, 'Rust unit cache binding', existing=True)
        previous_identity = _snapshot(state_path)
        previous = json.loads(state_path.read_text(encoding='utf-8'))
    if previous != state:
        _clean_package(data, environment, target_dir)
    argv = [data['tools']['cargo']['path'], 'test', '--frozen', '--jobs', '1', '--lib',
            '--manifest-path', str(Path(data['source_root']) / 'rust/Cargo.toml'),
            '--target', data['target'], '--target-dir', target_dir]
    if data['profile'] == 'release':
        argv.append('--release')
    raw = _run(argv, cwd=data['build_dir'], environment=environment, compiler=True, timeout=600)
    summary = re.search(r'test result: ok\. (\d+) passed; (\d+) failed', raw)
    if summary is None or int(summary.group(1)) == 0 or int(summary.group(2)) != 0:
        raise ValueError('Rust unit test command executed no passing assertions')
    _unchanged(data)
    if _snapshot(config_path) != config_identity:
        raise ValueError('Rust configuration changed during unit tests')
    if previous_identity is not None and _snapshot(state_path) != previous_identity:
        raise ValueError('Rust unit cache binding changed during tests')
    save_config(state_path, state)
    print(raw, end='')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    describe_parser = commands.add_parser('describe')
    for name in ('source-root', 'build-dir', 'target', 'cargo', 'rustc', 'output'):
        describe_parser.add_argument('--' + name, required=True)
    describe_parser.add_argument('--profile', choices=('debug', 'release'), default='debug')
    describe_parser.add_argument('--sdk-root')
    describe_parser.add_argument('--cpp-sdk-root')
    for name in ('build', 'verify', 'test'):
        commands.add_parser(name).add_argument('--config', required=True)
    args = parser.parse_args(argv)
    try:
        if args.command == 'describe':
            data = describe(args.source_root, args.build_dir, args.target, args.cargo, args.rustc,
                            args.profile, args.sdk_root, args.cpp_sdk_root)
            output = _absolute(args.output, 'Rust configuration output')
            if output.parent != Path(data['build_dir']):
                raise ValueError('Rust configuration output must be in its private build directory')
            save_config(output, data)
        elif args.command == 'build':
            build(args.config)
        elif args.command == 'test':
            test(args.config)
        else:
            verify(args.config)
    except (ValueError, OSError, KeyError, subprocess.SubprocessError, process_tree.ProcessTreeError) as error:
        parser.exit(1, 'rust_build: ' + str(error) + '\n')


if __name__ == '__main__':
    main()

