#!/usr/bin/env python3
"""Bind a build to a complete portable source snapshot, including retained inputs."""
import argparse
import gzip
import hashlib
import os
from pathlib import Path
import shutil
import subprocess
import tarfile
import tempfile
from dependency_archive import archive_tree, digest, encoded, file_inventory, inspect_manifest_archive, read_json, relative, write_json

WINDOWS = os.name == 'nt'

SUPPLEMENT_PREFIX = 'third_party/retained/gui/'


def ignored_source_path(name):
    parts = Path(name).parts
    return (name == 'source.json' or parts[0] in ('build', '.agent-work', '.git') or
            '__pycache__' in parts or name.endswith('.pyc'))


def source_files_without_git(root):
    """Prune generated trees before enumeration; never follow source links."""
    def failed(error):
        raise error

    for directory, directories, filenames in os.walk(root, topdown=True, onerror=failed, followlinks=False):
        parent = Path(directory).relative_to(root)
        # File-only exclusions do not exclude directories named source.json or
        # *.pyc: their descendants remain ordinary source inputs.
        directories[:] = [name for name in directories
                          if '__pycache__' not in (parent / name).parts and
                          (parent / name).parts[0] not in ('build', '.agent-work', '.git')]
        for name in [*directories, *filenames]:
            relative_name = (parent / name).as_posix()
            if ignored_source_path(relative_name):
                continue
            path = Path(directory) / name
            if path.is_file() or path.is_symlink():
                yield relative_name


def selected_files(root):
    root = Path(root).resolve(strict=True)
    if (root / '.git').exists():
        result = subprocess.check_output(['git', '-C', str(root), 'ls-files', '--cached', '--others', '--exclude-standard', '-z'])
        names = set(item.decode('utf-8') for item in result.split(b'\0') if item)
    elif (root / 'source.json').is_file():
        names = set(read_json(root / 'source.json')['files'])
        # Extra source files cannot silently disappear from a restored snapshot.
        actual = set(source_files_without_git(root))
        if names != actual:
            raise ValueError('restored source inventory changed')
    else:
        names = set(source_files_without_git(root))
    result = {}
    for name in sorted(names):
        if ignored_source_path(name):
            continue
        path = root.joinpath(*relative(name).parts)
        if path.is_symlink() or root not in path.resolve().parents:
            raise ValueError('source snapshot contains an escaping or linked file')
        if not path.exists(): continue  # An intentional tracked deletion changes the identity.
        if not path.is_file(): raise ValueError('source snapshot needs an explicitly retained submodule tree')
        result[name] = path
    if not result: raise ValueError('source snapshot is empty')
    return result


def snapshot_paths(root, supplement=None):
    files = selected_files(root)
    if supplement:
        extra = selected_files(supplement)
        retained = {name: path for name, path in files.items() if name.startswith(SUPPLEMENT_PREFIX)}
        expected = {SUPPLEMENT_PREFIX + name: path for name, path in extra.items()}
        if retained and ({name: digest(path) for name, path in retained.items()} != {name: digest(path) for name, path in expected.items()}):
            raise ValueError('retained GUI source differs from explicit supplement')
        files.update(expected)
    return files


def portable_executables(root, paths):
    """Windows cannot represent POSIX mode bits; retain reviewed source metadata.

    Bytes and complete path inventory are still recomputed. POSIX always inspects
    actual file modes so a local chmod remains a source change.
    """
    root = Path(root).resolve(strict=True)
    if not WINDOWS:
        return {name for name, path in paths.items() if path.stat().st_mode & 0o111}
    if (root / '.git').exists():
        raw = subprocess.check_output(['git', '-C', str(root), 'ls-files', '--stage', '-z'])
        names = set(); seen = set()
        for row in raw.split(b'\0'):
            if not row: continue
            metadata, name = row.split(b'\t', 1)
            mode, _, stage = metadata.split()
            if stage != b'0': raise ValueError('unmerged source index cannot define portable modes')
            decoded = name.decode('utf-8')
            if mode not in (b'100644', b'100755') or decoded in seen:
                raise ValueError('unsupported or duplicate source index mode')
            seen.add(decoded)
            if mode == b'100755': names.add(decoded)
        return names & set(paths)
    authority = next((parent for parent in [root, *root.parents] if (parent / 'source.json').is_file()), None)
    if authority is not None:
        data = read_json(authority / 'source.json')
        names = data.get('executables')
        if (not isinstance(names, list) or len(names) != len(set(names)) or
                any(not isinstance(n, str) or n not in data.get('files', {}) for n in names)):
            raise ValueError('invalid retained executable inventory')
        prefix = '' if authority == root else root.relative_to(authority).as_posix() + '/'
        return {name[len(prefix):] for name in names if name.startswith(prefix)} & set(paths)
    return {name for name, path in paths.items() if path.stat().st_mode & 0o111}


def describe_paths(paths, executables=None):
    files = {name: digest(path) for name, path in sorted(paths.items())}
    executables = sorted(executables if executables is not None else
                         (name for name, path in paths.items() if path.stat().st_mode & 0o111))
    identity = hashlib.sha256(encoded({'files': files, 'executables': executables})).hexdigest()
    return {'schema_version': 1, 'tree_sha256': identity, 'files': files, 'executables': executables}


def source_tree(root, supplement=None):
    paths = snapshot_paths(root, supplement)
    executable = portable_executables(root, paths)
    if supplement:
        extra = selected_files(supplement)
        executable.difference_update({name for name in executable if name.startswith(SUPPLEMENT_PREFIX)})
        executable.update(SUPPLEMENT_PREFIX + name for name in portable_executables(supplement, extra))
    return describe_paths(paths, executable)


def archive_source(root, output, supplement=None, epoch=0):
    output = Path(output).resolve()
    source_root = Path(root).resolve(strict=True)
    if source_root in output.parents and source_root / 'build' not in output.parents:
        raise ValueError('source archive output must be outside source inputs or under ignored build/')
    if output.exists(): raise ValueError('source archive destination must be new')
    paths = snapshot_paths(root, supplement)
    before = source_tree(root, supplement)
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=output.parent, prefix='.source-') as temporary:
        staged = Path(temporary) / 'source'
        staged.mkdir()
        for name, path in paths.items():
            destination = staged / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(path, destination)
            destination.chmod(0o755 if name in before['executables'] else 0o644)
        write_json(staged / 'source.json', before)
        copied = source_tree(staged)
        if copied != before or source_tree(root, supplement) != before:
            raise ValueError('source inputs changed while snapshotting')
        # Set archive modes from the verified logical inventory, including on
        # Windows where chmod cannot represent POSIX executable permission.
        ready = Path(temporary) / 'source.tar.gz'
        with ready.open('xb') as raw, gzip.GzipFile(filename='', mode='wb', fileobj=raw, mtime=epoch, compresslevel=1) as zipped:
            with tarfile.open(fileobj=zipped, mode='w', format=tarfile.PAX_FORMAT) as archive:
                for name in sorted([*before['files'], 'source.json']):
                    path = staged / name
                    info = tarfile.TarInfo(name)
                    info.size = path.stat().st_size
                    info.mode = 0o755 if name in before['executables'] else 0o644
                    info.mtime = epoch
                    with path.open('rb') as stream: archive.addfile(info, stream)
        verify_source_archive(ready)
        # Same-filesystem link publishes complete bytes without replacing an
        # output another writer may have created after the initial inspection.
        os.link(ready, output)
    verify_source_archive(output)
    return before


def verify_source_archive(archive):
    data, _ = inspect_manifest_archive(archive, 'source.json')
    executables = []
    with tarfile.open(archive) as source:
        for member in source:
            if member.isfile() and member.name != 'source.json' and member.mode & 0o111:
                executables.append(member.name)
    if sorted(executables) != data.get('executables'):
        raise ValueError('source executable mode inventory mismatch')
    actual = hashlib.sha256(encoded({'files': data['files'], 'executables': sorted(executables)})).hexdigest()
    if actual != data.get('tree_sha256'):
        raise ValueError('source tree identity mismatch')
    return data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=('digest', 'archive', 'verify'))
    parser.add_argument('--root', type=Path)
    parser.add_argument('--supplement', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--archive', type=Path)
    parser.add_argument('--epoch', type=int, default=0)
    args = parser.parse_args()
    if args.action == 'verify':
        if not args.archive: parser.error('verify requires --archive')
        result = verify_source_archive(args.archive)
    else:
        if not args.root: parser.error('--root is required')
        if args.action == 'digest':
            print(source_tree(args.root, args.supplement)['tree_sha256'])
            return
        if not args.output: parser.error('archive requires --output')
        result = archive_source(args.root, args.output, args.supplement, args.epoch)
    print(encoded(result).decode(), end='')


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, KeyError, subprocess.CalledProcessError) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Copy an ELF runtime closure only from explicitly supplied target roots."""
import argparse
from pathlib import Path
import shutil
import subprocess
import tempfile
from dependency_archive import digest, write_json
from verify_abi import HOST_LIBRARIES, audit, elf, inspect, version


def normalize_empty_paths(path, readelf='readelf', elf_editor='patchelf'):
    """Remove wholly empty tags from a staged copy, preserving input provenance.

    An empty DT_RUNPATH supplies no directories but suppresses inherited RPATH.
    Do not erase nonempty paths (including empty colon-delimited components).
    The final installed-package audit must prove its inherited private closure.
    """
    before = inspect(path, readelf)
    if '' not in before['rpaths']:
        return None
    if any(before['rpaths']):
        raise ValueError('mixed empty and nonempty runtime paths: ' + str(path))
    editor = shutil.which(str(elf_editor))
    if editor is None:
        raise ValueError('empty runtime paths require the selected ELF editor: ' + str(elf_editor))
    editor_hash = digest(Path(editor))
    subprocess.run([editor, '--remove-rpath', str(path)], check=True)
    after = inspect(path, readelf)
    if after['rpaths'] or any(before[key] != after[key] for key in before
                             if key not in ('sha256', 'rpaths', 'rpath', 'runpath')):
        raise ValueError('ELF editor changed runtime contracts or left search-path tags: ' + str(path))
    if digest(Path(editor)) != editor_hash:
        raise ValueError('ELF editor changed during runtime normalization')
    return {'operation': 'remove-wholly-empty-rpath-tags', 'source_sha256': before['sha256'],
            'installed_sha256': after['sha256'], 'editor_sha256': editor_hash,
            'original_rpath': before['rpath'], 'original_runpath': before['runpath']}


def stage(executables, roots, destination, processor='x86_64', readelf='readelf', host_libraries=None,
          audit_baseline=True, elf_editor='patchelf'):
    """Collect target files; only an explicit native build may use observed floors."""
    if type(audit_baseline) is not bool:
        raise ValueError('runtime staging baseline policy must be explicit')
    destination = Path(destination).absolute()
    if destination.exists() or destination.is_symlink():
        raise ValueError('runtime staging destination must be new')
    host_libraries = HOST_LIBRARIES if host_libraries is None else set(host_libraries)
    if not host_libraries <= HOST_LIBRARIES:
        raise ValueError('undeclared host dependency exemption')
    providers = {}
    for root in map(lambda p: Path(p).resolve(strict=True), roots):
        for path in root.rglob('*'):
            if path.is_file() and '.so' in path.name:
                resolved = path.resolve(strict=True)
                if root not in resolved.parents:
                    raise ValueError('target library escapes selected root')
                providers.setdefault(path.name, []).append(resolved)
    queue = list(map(Path, executables))
    copied, host = {}, set()
    while queue:
        path = queue.pop(0)
        if not path.is_file() or not elf(path):
            raise ValueError('runtime input must be an ELF executable or library')
        for name in inspect(path, readelf)['needed']:
            if name in host_libraries:
                host.add(name)
                continue
            if name in copied:
                continue
            found = providers.get(name, [])
            if not found:
                raise ValueError('missing target runtime dependency: ' + name)
            identities = {digest(item) for item in found}
            if len(identities) != 1:
                raise ValueError('ambiguous target runtime provider: ' + name)
            copied[name] = found[0]
            queue.append(found[0])
    destination.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=destination.parent) as temporary:
        staged = Path(temporary) / 'lib'
        staged.mkdir()
        staged.chmod(0o755)
        transformations = {}
        for name, path in copied.items():
            shutil.copyfile(path, staged / name)
            (staged / name).chmod(0o755)
            changed = normalize_empty_paths(staged / name, readelf, elf_editor)
            if changed:
                transformations[name] = changed
        # files retains supplier identities used by dependency notice collection.
        report = {'schema_version': 2, 'files': {name: digest(path) for name, path in copied.items()},
                  'installed_files': {name: digest(staged / name) for name in copied},
                  'transformations': transformations,
                  'host_libraries': sorted(host), 'processor': processor}
        if copied:
            # Staging has no executable ancestor or final directory layout.
            # The complete installed package must pass the default audit next.
            ceilings = None
            if not audit_baseline:
                ceilings = {}
                for path in staged.iterdir():
                    for family, required in inspect(path, readelf)['requirements'].items():
                        if version(required) > version(ceilings.get(family, '0')):
                            ceilings[family] = required
            report['abi'] = audit(staged, processor, ceilings=ceilings, readelf=readelf, runtime_resolution=False)
        report['baseline_qualification'] = 'bookworm-abi-only' if audit_baseline else 'native-observed-requirements-only'
        report['runtime_resolution'] = 'requires_final_package_audit'
        inventory = staged / 'runtime-inventory.json'
        write_json(inventory, report)
        # Installed metadata is public even when the build uses a private umask.
        inventory.chmod(0o644)
        staged.rename(destination)
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--executable', type=Path, action='append', required=True)
    parser.add_argument('--root', type=Path, action='append', required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--processor', default='x86_64')
    parser.add_argument('--elf-editor', default='patchelf')
    args = parser.parse_args()
    stage(args.executable, args.root, args.output, args.processor, elf_editor=args.elf_editor)


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, subprocess.CalledProcessError) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Freeze test coverage, run disjoint shards, reject incomplete aggregation."""
import argparse
import hashlib
import json
import math
import os
import tempfile
import time
from pathlib import Path
import re
import subprocess
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(Path(__file__).resolve().parent))
import build as builder
import windows_compiler
import build_capacity
from sdk_environment import HOST_OVERRIDES, require_clean
from dependency_archive import read_json
from dependency_store import verify_group
from source_identity import source_tree


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def gui_source(cache):
    enabled = cache.get("FOUNDATION_BUILD_GUI", "OFF").upper() not in ("OFF", "NO", "FALSE", "0", "")
    value = cache.get("FOUNDATION_GUI_SOURCE")
    if enabled and not value:
        raise ValueError("enabled GUI has no configured source input")
    return Path(value).resolve(strict=True) if enabled else None


def source_id(build=None):
    supplement = gui_source(builder.cache_identity(build)) if build is not None else None
    return source_tree(ROOT, supplement)["tree_sha256"]


def execution_context(build):
    cache = builder.cache_identity(build)
    sdk = Path(cache["FOUNDATION_SDK_ROOT"]).resolve(strict=True) if cache.get("FOUNDATION_SDK_ROOT") else None
    if sdk:
        require_clean()
    programs = builder.host_programs(sdk)
    if not sdk:
        programs["cmake"] = cache.get("CMAKE_COMMAND", programs["cmake"])
        programs["ctest"] = cache.get("CMAKE_CTEST_COMMAND", programs["ctest"])
    environment = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")
    if sdk and read_json(sdk / "sdk.json")["target"]["system"] == "Emscripten":
        from sdk_wasm import environment as sdk_environment
        environment = sdk_environment(sdk)
    return programs, environment


def verify_gui_group(root):
    value = subprocess.check_output([sys.executable, "-B", str(ROOT / "gui/source_group.py"),
                                     "verify", str(root)], text=True, encoding="utf-8")
    return json.loads(value)["group_sha256"]


def native_rust_inputs(build, cache):
    """Verify CMake's selected native tools without discovery or execution."""
    if (not sys.platform.startswith("linux") or cache.get("FOUNDATION_SDK_ROOT")
            or cache.get("FOUNDATION_WINDOWS_DEPENDENCIES")):
        raise ValueError("this Rust target requires its configured retained SDK")
    from rust_build import _load_config, native_tool_identity
    cargo, rustc = cache.get("FOUNDATION_RUST_CARGO"), cache.get("FOUNDATION_RUST_RUSTC")
    if not cargo or not rustc:
        raise ValueError("native Rust configuration is missing its selected tools")
    tools = native_tool_identity(cargo, rustc)
    configurations = (cache["CMAKE_CONFIGURATION_TYPES"].split(";") if cache.get("CMAKE_CONFIGURATION_TYPES")
                      else [cache.get("CMAKE_BUILD_TYPE") or "NoConfig"])
    if (len(set(configurations)) != len(configurations)
            or any(not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_.+-]*", name) for name in configurations)):
        raise ValueError("invalid native Rust configuration names")
    descriptions = {}
    target = None
    for name in configurations:
        path = build / "rust" / name / "config.json"
        path.resolve(strict=True).relative_to(build.resolve(strict=True))
        description, _ = _load_config(str(path.absolute()))
        described_tools = {tool: {key: row[key] for key in ("path", "sha256", "identity")}
                           for tool, row in description["tools"].items()}
        if (description["source_root"] != str(ROOT.resolve(strict=True))
                or description["build_dir"] != str(path.parent.resolve(strict=True))
                or description["system"] != "Linux" or description["sdk_root"]
                or description["cpp_sdk_root"] or description["cpp_sdk_manifest"] or described_tools != tools
                or description["tools"]["rustc"]["host"] != description["target"]
                or description["profile"] != ("debug" if name.lower() == "debug" else "release")
                or (target is not None and target != description["target"])):
            raise ValueError("native Rust inputs differ from the configured CMake selection")
        target = description["target"]
        descriptions[name] = digest(normalize_locations(description, build))
    expected = hashlib.sha256(";".join((target, rustc, cargo, tools["rustc"]["sha256"],
                                      tools["cargo"]["sha256"], "none")).encode()).hexdigest()
    if (cache.get("FOUNDATION_CONFIGURED_RUST_IDENTITY") != expected
            or (cache.get("FOUNDATION_RUST_TARGET") and cache["FOUNDATION_RUST_TARGET"] != target)):
        raise ValueError("native Rust toolchain differs from its configured identity")
    return tools, descriptions


def build_inputs(build):
    """Recompute bytes, never trust a saved wrapper receipt as verification."""
    cache = builder.cache_identity(build)
    stamp = build / "wrapper-identity.json"
    configured = build / "configured-identity.json"
    wrapper = read_json(stamp) if stamp.exists() else None
    if wrapper is not None:
        if not configured.is_file() or read_json(configured) != cache:
            raise ValueError("configured compiler/options changed outside the build wrapper")
    elif configured.exists():
        raise ValueError("configured build receipt is missing its wrapper identity")
    # Pre-provider build trees remain C++; the current configure default is irrelevant.
    provider = cache.get("FOUNDATION_CORE_PROVIDER", "cpp")
    if provider not in ("cpp", "rust"):
        raise ValueError("unknown configured core provider")
    result = {"cache": cache, "wrapper": wrapper, "sdk": None, "dependencies": [], "windows_dependencies": None, "dependency_prefix": None,
              "core_provider": provider, "rust_sdk": None,
              "environment": {key: os.environ.get(key) for key in (*HOST_OVERRIDES, "CMAKE_GENERATOR")}}
    sdk_root = cache.get("FOUNDATION_SDK_ROOT")
    prefix_root = cache.get("FOUNDATION_DEPENDENCY_PREFIX")
    if prefix_root:
        if sdk_root or cache.get("FOUNDATION_WINDOWS_DEPENDENCIES"):
            raise ValueError("native dependency prefix cannot mix with prepared exports")
        from prepare_dependencies import verify
        prefix = Path(prefix_root).resolve(strict=True)
        verified = verify(prefix)
        result["dependency_prefix"] = {"root": str(prefix), "sha256": verified["sha256"], "prefix": str(verified["prefix"])}
    recipe_ids = []
    if sdk_root:
        sdk = Path(sdk_root).resolve(strict=True)
        require_clean()
        result["sdk"] = {"root": str(sdk), "sha256": builder.sdk_identity(sdk)}
        recipe_ids.append(read_json(sdk / "sdk.json")["recipe_id"])
    rust_root = cache.get("FOUNDATION_RUST_SDK_ROOT")
    if provider == "rust":
        if rust_root:
            from rust_sdk import verify_rust_sdk
            from dependency_archive import digest as file_digest
            rust = Path(rust_root).resolve(strict=True)
            metadata = verify_rust_sdk(rust, cpp_sdk=Path(sdk_root) if sdk_root else
                                       Path(cache["FOUNDATION_WINDOWS_DEPENDENCIES"]) if cache.get("FOUNDATION_WINDOWS_DEPENDENCIES") else None,
                                       target=cache.get("FOUNDATION_RUST_TARGET") or None, execute=True)
            result["rust_sdk"] = {"root": str(rust), "sha256": file_digest(rust / "rust-sdk.json")}
            recipe_ids.append(metadata["recipe_id"])
        else:
            result["rust_tools"], result["rust_configurations"] = native_rust_inputs(build, cache)
    elif rust_root:
        raise ValueError("C++ provider cannot retain a configured Rust SDK")
    if wrapper is not None:
        if wrapper.get("core_provider", "cpp") != provider or wrapper.get("rust_sdk") != result["rust_sdk"]:
            raise ValueError("core provider or Rust SDK differs from configured wrapper identity")
        if wrapper.get("rust_tools") != result.get("rust_tools"):
            raise ValueError("native Rust tools differ from configured wrapper identity")
        if wrapper.get("dependency_prefix") != result["dependency_prefix"]:
            raise ValueError("native dependency prefix differs from configured wrapper identity")
        if prefix_root and wrapper.get("windows_dependencies"):
            raise ValueError("native dependency prefix cannot mix with Windows exports")
        if wrapper.get("sdk") != result["sdk"]:
            raise ValueError("prepared SDK differs from configured wrapper identity")
        if any(os.environ.get(key) != value for key, value in wrapper.get("environment", {}).items()):
            raise ValueError("build environment differs from configured wrapper identity")
        expected_gui = str(gui_source(cache)) if gui_source(cache) else None
        if wrapper.get("gui") != expected_gui:
            raise ValueError("GUI source differs from configured wrapper identity")
        for item in wrapper.get("dependencies", []):
            payload = item.get("payload", "complete")
            if payload == "binary":
                from dependency_store import verify_binary_group
                files = verify_binary_group(item["root"], item["recipe"])
            elif payload == "complete":
                files = verify_group(item["root"], item["recipe"])
            else:
                raise ValueError("unknown retained dependency payload scope")
            actual = {"root": str(Path(item["root"]).resolve(strict=True)), "recipe": item["recipe"], "files": files}
            if payload == "binary":
                actual["payload"] = "binary"
            if actual != item or item["recipe"] in recipe_ids:
                raise ValueError("retained dependency group changed or is duplicated")
            recipe_ids.append(item["recipe"])
            result["dependencies"].append(actual)
        windows = wrapper.get("windows_dependencies")
        if windows:
            from sdk_manifest import verify_sdk
            path = Path(windows["root"]).resolve(strict=True)
            actual = {"root": str(path), "sha256": verify_sdk(path, release=True)}
            if actual != windows or read_json(path / "sdk.json")["recipe_id"] not in recipe_ids:
                raise ValueError("Windows dependency export differs from its retained identity")
            result["windows_dependencies"] = actual
        group = wrapper.get("gui_input_group")
        if group:
            actual = {"root": str(Path(group["root"]).resolve(strict=True)),
                      "sha256": verify_gui_group(group["root"])}
            if actual != group:
                raise ValueError("GUI input group differs from its retained identity")
            result["gui_input_group"] = actual
    declared = set(filter(None, cache.get("FOUNDATION_DEPENDENCY_RECIPES", "").split(";")))
    if sdk_root:
        declared.add(read_json(Path(sdk_root) / "sdk.json")["recipe_id"])
    if result["rust_sdk"]:
        declared.add(metadata["recipe_id"])
    primary = cache.get("FOUNDATION_DEPENDENCY_RECIPE", "native-unprepared")
    if (sorted(declared) != sorted(recipe_ids)
            or (primary != "native-unprepared" and primary not in recipe_ids)):
        raise ValueError("configured dependencies need complete verified retained input identities")
    return result


def normalize_locations(value, build):
    """Normalize declared and physical roots before JSON escaping.

    Windows tools may retain an 8.3 spelling while Path.resolve expands it.
    Both supplied and resolved root spellings represent the same input; leave
    unrelated compiler/dependency paths intact rather than resolving every value.
    """
    replacements = [(str(ROOT), "<SOURCE>")]
    for root, marker in ((build, "<BUILD>"), (ROOT, "<SOURCE>")):
        path = Path(root)
        spellings = {str(path.absolute()), str(path.resolve())}
        if path.is_absolute():
            spellings.add(str(path))
        replacements.extend((spelling, marker) for spelling in spellings)
    # CMake lowercases the Windows drive in CMAKE_CACHEFILE_DIR even when
    # other generated roots preserve it. Only that drive letter is equivalent;
    # preserve case-sensitive directory components and unrelated input values.
    replacements += [(path[0].swapcase() + path[1:], marker)
                     for path, marker in replacements if re.match(r"^[A-Za-z]:[/\\]", path)]
    replacements = sorted(set((spelling, marker) for path, marker in replacements
                             for spelling in (path, path.replace("\\", "/"))), key=lambda item:len(item[0]), reverse=True)
    # A root must end at a path component or a generated CMake delimiter.
    # Prefix siblings such as source-cache or "source cache" are external inputs.
    replacements = [(re.compile(re.escape(path) + r"""(?=$|[/\\;"')\]\r\n])"""), marker)
                    for path, marker in replacements]
    def visit(item):
        if isinstance(item, str):
            for pattern, marker in replacements: item = pattern.sub(marker, item)
            return item
        if isinstance(item, list): return [visit(row) for row in item]
        if isinstance(item, dict): return {visit(key):visit(row) for key,row in item.items()}
        return item
    return visit(value)


def test_definitions(build):
    programs, environment = execution_context(build)
    raw = subprocess.check_output([programs["ctest"], "--test-dir", str(build), "--show-only=json-v1"],
                                  text=True, env=environment)
    tests = json.loads(raw)["tests"]
    return normalize_locations(tests, build)


def inventory(build):
    return test_names(test_definitions(build))


def test_names(definitions):
    tests = sorted(item["name"] for item in definitions)
    if not tests or len(set(tests)) != len(tests):
        raise ValueError("test inventory is empty or duplicated")
    return tests


def ctest_declarations(build):
    """Read only CTest's declared tree, excluding tests' nested consumer builds."""
    root = Path(build).resolve(strict=True)
    pending, result = [root / "CTestTestfile.cmake"], {}
    while pending:
        path = pending.pop().resolve(strict=True)
        path.relative_to(root)
        relative = path.relative_to(root).as_posix()
        if relative in result:
            raise ValueError("recursive or duplicated CTest declaration directory")
        text = path.read_text(encoding="utf-8")
        result[relative] = text
        for line in text.splitlines():
            if line.strip().startswith("subdirs("):
                match = re.fullmatch(r'\s*subdirs\("([^"\\]+)"\)\s*', line)
                if not match:
                    raise ValueError("unsupported generated CTest subdirectory declaration")
                pending.append(path.parent / match[1] / "CTestTestfile.cmake")
    return result


def prerequisites(build):
    """Return the complete configured mapping; old external trees keep full builds."""
    return _prerequisites(build)


def _prerequisites(build, tests=None):
    path = Path(build) / "test-prerequisites.json"
    if not path.exists():
        if builder.cache_identity(build).get("FOUNDATION_HAS_TEST_PREREQUISITES") == "ON":
            raise ValueError("configured test prerequisite inventory is missing")
        return None
    value = read_json(path)
    if (set(value) != {"schema_version", "tests"} or value["schema_version"] != 1 or
            not isinstance(value["tests"], dict)):
        raise ValueError("invalid test prerequisite inventory")
    mapping = value["tests"]
    if sorted(mapping) != (inventory(build) if tests is None else tests):
        raise ValueError("test prerequisite inventory differs from complete CTest inventory")
    validate_prerequisites(mapping)
    return mapping


def validate_prerequisites(mapping):
    if not isinstance(mapping, dict) or not mapping:
        raise ValueError("empty or invalid test prerequisite inventory")
    for name, targets in mapping.items():
        if (not isinstance(name, str) or not name or not isinstance(targets, list) or
                any(not isinstance(x, str) or not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_.+-]*", x) for x in targets) or
                targets != sorted(set(targets))):
            raise ValueError("invalid or duplicate test prerequisites")


def selected_targets(mapping, names):
    validate_prerequisites(mapping)
    if not names or not set(names) <= set(mapping):
        raise ValueError("selected tests have missing prerequisites")
    return sorted({target for name in names for target in mapping[name]})


def named_selection(build, names, programs, environment):
    """Select literal names and ask CTest to expand its actual fixture graph.

    The complete registered mapping is authoritative. Never infer build targets
    from names, silently accept a typo, or fall back to the expensive all target.
    """
    if (not names or len(names) != len(set(names)) or
            any(not isinstance(name, str) or not name for name in names)):
        raise ValueError("named tests must be nonempty and unique")
    command = [programs["ctest"], "--test-dir", str(build), "--show-only=json-v1"]
    complete = json.loads(subprocess.check_output(command, text=True, env=environment))["tests"]
    available = test_names(complete)
    if not set(names) <= set(available):
        raise ValueError("unknown exact test name: " + ", ".join(sorted(set(names) - set(available))))
    mapping = _prerequisites(build, available)
    if mapping is None:
        raise ValueError("exact test selection requires the complete registered prerequisite inventory")
    pattern = "^(" + "|".join(re.escape(name) for name in sorted(names)) + ")$"
    selected = json.loads(subprocess.check_output(command + ["-R", pattern], text=True, env=environment))["tests"]
    executed = test_names(selected)
    if not set(names) <= set(executed) or not set(executed) <= set(available):
        raise ValueError("CTest exact selection differs from the complete inventory")
    return {"names": executed, "targets": selected_targets(mapping, executed), "pattern": pattern,
            "prerequisites": mapping}


def compile_targets(programs, environment, build, targets, jobs):
    # An empty script-only selection must not invoke CMake's default all target.
    if targets:
        windows_compiler.run([programs["cmake"], "--build", str(build), "--target", *targets,
                              "--parallel", str(jobs)], env=environment)


def configuration_id(build, *, declared_commands=False):
    definitions = test_definitions(build)
    mapping = _prerequisites(build, test_names(definitions))
    return _configuration_id(build, definitions, mapping, declared_commands=declared_commands)


def _configuration_id(build, tests, mapping, *, declared_commands=False):
    # Reuse one complete CTest observation only inside this verification phase.
    # Callers take a fresh observation after compilation and after execution.
    declared_build = build
    build = build.resolve()
    inputs = build_inputs(build)
    # Normalize checkout/build locations while preserving actual compiler and
    # retained-input digests, complete cache values and external locations.
    normalized = normalize_locations(inputs, declared_build)
    info = (build / "build-info.txt").read_text()
    identity = {"inputs": normalized, "build_info": info, "tests": tests}
    if mapping is not None:
        identity["prerequisites"] = mapping
    if declared_commands:
        # CTest omits command arrays for not-yet-built executables. Bind the exact
        # generated commands instead, so independent scope builds have the same
        # inventory identity without compiling unrelated executables.
        declarations = ctest_declarations(build)
        if not declarations:
            raise ValueError("candidate needs complete generated CTest declarations")
        identity["tests"] = [{key:value for key,value in item.items() if key != "command"} for item in tests]
        identity["declarations"] = normalize_locations(declarations, declared_build)
    return digest(identity)


def require_current(build, plan):
    declared = "prerequisites" in plan
    if declared and prerequisites(build) != plan["prerequisites"]:
        raise ValueError("test prerequisites changed since planning")
    if (configuration_id(build, declared_commands=declared) != plan["configuration"] or source_id(build) != plan["source"]
            or inventory(build) != plan["tests"]):
        raise ValueError("source, compiler, prepared inputs or test configuration changed since planning")


def make_plan(tests, shards, identity, configuration="unit-fixture", *, prerequisites=None):
    if shards < 1 or shards > len(tests):
        raise ValueError("shards must be between 1 and the test count")
    plan = {"schema_version": 1, "source": identity, "configuration": configuration, "tests": sorted(tests),
            "shards": [sorted(tests)[index::shards] for index in range(shards)]}
    if prerequisites is not None:
        validate_prerequisites(prerequisites)
        if sorted(prerequisites) != plan["tests"]:
            raise ValueError("test prerequisites do not cover the complete inventory")
        plan["prerequisites"] = prerequisites
    plan["id"] = digest(plan)
    return plan


def validate_plan(plan):
    body = {key: value for key, value in plan.items() if key != "id"}
    if plan.get("schema_version") != 1 or digest(body) != plan.get("id"):
        raise ValueError("plan identity mismatch")
    if "prerequisites" in plan:
        validate_prerequisites(plan["prerequisites"])
        if sorted(plan["prerequisites"]) != plan["tests"]:
            raise ValueError("test prerequisites do not cover the complete inventory")
    flat = [name for shard in plan["shards"] for name in shard]
    if not flat or any(not shard for shard in plan["shards"]) or sorted(flat) != plan["tests"] or len(set(flat)) != len(flat):
        raise ValueError("invalid shard inventory")


def junit_results(path, expected):
    cases = list(ET.parse(path).getroot().iter("testcase"))
    names = [case.attrib.get("name") for case in cases]
    if sorted(names) != sorted(expected) or len(set(names)) != len(names):
        raise ValueError("missing, unexpected or duplicate test results")
    statuses = {}
    for case in cases:
        passed = case.attrib.get("status", "run") in ("run", "passed")
        passed = passed and all(case.find(tag) is None for tag in ("failure", "error", "skipped"))
        statuses[case.attrib["name"]] = "passed" if passed else "failed_or_incomplete"
    return statuses



def test_timeouts(definitions):
    limits = {}
    for item in definitions:
        values = [prop["value"] for prop in item.get("properties", []) if prop["name"] == "TIMEOUT"]
        if len(values) > 1:
            raise ValueError("duplicate test timeout")
        limit = float(values[0]) if values else None
        if limit is not None and (not math.isfinite(limit) or limit < 0):
            raise ValueError("test timeout must be finite and nonnegative")
        limits[item["name"]] = limit or None
    return limits


def junit_timings(path, expected, timeouts):
    """Retain measured JUnit times; absent durations remain explicitly unknown."""
    statuses = junit_results(path, expected)
    if not set(expected) <= set(timeouts):
        raise ValueError("timing timeout inventory is incomplete")
    rows = []
    for case in ET.parse(path).getroot().iter("testcase"):
        name = case.attrib["name"]
        seconds = float(case.attrib["time"]) if "time" in case.attrib else None
        limit = timeouts[name]
        if seconds is not None and (not math.isfinite(seconds) or seconds < 0):
            raise ValueError("JUnit duration must be finite and nonnegative")
        if limit is not None and (not math.isfinite(limit) or limit <= 0):
            raise ValueError("test timeout must be finite and positive")
        rows.append(dict(name=name, status=statuses[name], seconds=seconds, timeout_seconds=limit,
                         near_timeout=statuses[name] == "passed" and seconds is not None and
                         limit is not None and seconds >= .8 * limit))
    return sorted(rows, key=lambda row: row["name"])


def timing_summary(timing, scope, summary=None):
    rows = timing["tests"]
    known = [row for row in rows if row["seconds"] is not None]
    phases = timing["phase_seconds"]
    lines = ["### Test timing: " + scope, "",
             "Build: %.2fs; test wall time: %.2fs; complete scope: %.2fs." %
             (phases["build"], phases["test"], phases["total"]), "",
             "Measured test durations total %.2fs across %d cases (concurrent tests may overlap)." %
             (sum(row["seconds"] for row in known), len(known)), ""]
    for row in sorted(known, key=lambda row: row["seconds"], reverse=True)[:5]:
        name = row["name"].replace("`", "'").replace("\n", " ").replace("\r", " ")
        warning = " — passed at 80% or more of its declared timeout" if row["near_timeout"] else ""
        lines.append("- `%s`: %.2fs (%s)%s" % (name, row["seconds"], row["status"], warning))
    if len(known) != len(rows):
        lines += ["", "%d cases have no reported JUnit duration." % (len(rows) - len(known))]
    warnings = [row["name"] for row in rows if row["near_timeout"]]
    if warnings:
        lines += ["", "Timeout margin warning: " + ", ".join(name.replace("\n", " ").replace("\r", " ") for name in warnings) + "."]
    text = "\n".join(lines) + "\n"
    print(text)
    if summary is not None:
        with Path(summary).open("a", encoding="utf-8") as stream:
            stream.write(text + "\n")
    return text


def merge(plan, reports):
    validate_plan(plan)
    seen = set()
    results = {}
    for report in reports:
        index = report["shard"]
        if report["plan"] != plan["id"] or index in seen or type(index) is not int or not 0 <= index < len(plan["shards"]):
            raise ValueError("duplicate, stale or invalid shard")
        if set(report["results"]) != set(plan["shards"][index]):
            raise ValueError("incomplete shard results")
        if report["exit_code"] != 0 or any(value != "passed" for value in report["results"].values()):
            raise ValueError("failed or incomplete coverage")
        seen.add(index)
        results.update(report["results"])
    if seen != set(range(len(plan["shards"]))) or set(results) != set(plan["tests"]):
        raise ValueError("missing shard coverage")
    return {"schema_version": 1, "plan": plan["id"], "source": plan["source"], "status": "passed", "tests": len(results)}


def save(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent,
                                     prefix=path.name + ".", delete=False) as output:
        staging = Path(output.name)
        output.write(json.dumps(value, indent=2) + "\n")
        output.flush()
        os.fsync(output.fileno())
    try:
        os.replace(staging, path)
    finally:
        staging.unlink(missing_ok=True)



CANDIDATE_SCOPES = ("core", "tools", "integration")


def candidate_plan(build):
    return _candidate_observation(build)[0]


def _candidate_observation(build):
    definitions = test_definitions(build)
    assignments = {scope: [] for scope in CANDIDATE_SCOPES}
    for item in definitions:
        labels = next((p["value"] for p in item.get("properties", []) if p["name"] == "LABELS"), [])
        selected = [scope for scope in ("tools", "integration") if scope in labels]
        if len(selected) > 1:
            raise ValueError("test has competing candidate owners")
        assignments[selected[0] if selected else "core"].append(item["name"])
    tests = sorted(x["name"] for x in definitions)
    if not tests or len(tests) != len(set(tests)) or any(not names for names in assignments.values()):
        raise ValueError("candidate inventory is empty, duplicated or has an empty required scope")
    platform_path = build / "test-platform.json"
    platform = read_json(platform_path)
    if (set(platform) != {"schema_version", "excluded_suites"} or platform["schema_version"] != 1 or
            not isinstance(platform["excluded_suites"], dict) or
            any(not name.startswith("tools.") or name in tests or not isinstance(reason, str) or not reason
                for name, reason in platform["excluded_suites"].items())):
        raise ValueError("invalid explicit platform exclusions")
    mapping = _prerequisites(build, tests)
    value = dict(schema_version=1, source=source_id(build),
                 configuration=_configuration_id(build, definitions, mapping, declared_commands=True),
                 tests=tests, scopes={key: sorted(value) for key, value in assignments.items()},
                 platform_exclusions=platform["excluded_suites"], timeouts=test_timeouts(definitions))
    value["id"] = digest(value)
    return value, mapping


def candidate_prerequisite_inputs(build):
    """Freeze declarations before CTest can resolve freshly compiled executables."""
    build = Path(build)
    paths = {build/name for name in ctest_declarations(build)}
    paths.update(build/name for name in ('build-info.txt', 'test-platform.json'))
    if (build / "test-prerequisites.json").exists():
        paths.add(build / "test-prerequisites.json")
    declarations = {path.relative_to(build).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
                    for path in sorted(paths)}
    return source_id(build), build_inputs(build), declarations


def candidate_run(build, scope, output, jobs=2, *, build_jobs=None, summary=None):
    """Freeze all tests; unlabelled new tests automatically belong to core."""
    if scope not in CANDIDATE_SCOPES or jobs < 1 or (build_jobs is not None and build_jobs < 1):
        raise ValueError("invalid candidate scope or concurrency")
    output = Path(output)
    if output.exists():
        raise ValueError("candidate receipt must name a new attempt")
    output.parent.mkdir(parents=True, exist_ok=True)
    from build_capacity import compile_jobs as selected_compile_jobs
    compile_jobs = build_jobs or selected_compile_jobs(os.environ.get("CMAKE_BUILD_PARALLEL_LEVEL"))
    started = time.monotonic()
    before = candidate_prerequisite_inputs(build)
    frozen, mapping = _candidate_observation(build)
    programs, environment = execution_context(build)
    targets = selected_targets(mapping, frozen["scopes"][scope]) if mapping is not None else ["foundation-tests-" + scope]
    compile_targets(programs, environment, build, targets, compile_jobs)
    compiled_at = time.monotonic()
    if candidate_prerequisite_inputs(build) != before:
        raise ValueError("candidate inputs changed during prerequisite compilation")
    if candidate_plan(build) != frozen:
        raise ValueError("candidate inventory changed during prerequisite compilation")
    names = frozen["scopes"][scope]
    junit = output.with_suffix(".junit.xml").resolve()
    if junit.exists():
        raise ValueError("candidate JUnit must name a new attempt")
    testing_at = time.monotonic()
    try:
        exit_code = windows_compiler.run([programs["ctest"], "--test-dir", str(build), "--no-tests=error", "--output-on-failure",
            "--parallel", str(jobs), "-R", "^(" + "|".join(re.escape(name) for name in names) + ")$",
            "--output-junit", str(junit)], env=environment).returncode
    except subprocess.CalledProcessError as error:
        # The owner raises this only after a nonzero command and its children
        # have joined. Ownership and timeout failures must bypass report creation.
        exit_code = error.returncode
    tested_at = time.monotonic()
    outcomes = junit_results(junit, names)
    timed_tests = junit_timings(junit, names, frozen["timeouts"])
    if candidate_plan(build) != frozen:
        raise ValueError("candidate inputs changed during execution")
    import importlib.util
    spec = importlib.util.spec_from_file_location("candidate_coverage", Path(__file__).with_name("coverage.py"))
    checked = importlib.util.module_from_spec(spec); spec.loader.exec_module(checked)
    inner = {name: checked.tool_report(read_json(build / "test-reports" / (name.removeprefix("tools.") + ".json")))
             for name in names if name.startswith("tools.")}
    result = dict(schema_version=1, plan=frozen, scope=scope, results=outcomes, tool_reports=inner,
                  exit_code=exit_code, junit_sha256=hashlib.sha256(junit.read_bytes()).hexdigest(),
                  timing=dict(tests=timed_tests, phase_seconds=dict(build=compiled_at-started,
                              test=tested_at-testing_at, total=time.monotonic()-started)))
    save(output, result)
    timing_summary(result["timing"], scope, summary)
    if exit_code or any(value != "passed" for value in outcomes.values()):
        raise ValueError("candidate scope failed")
    return result


def candidate_merge(paths, *, diagnostic=False):
    expected = {"core"} if diagnostic else set(CANDIDATE_SCOPES)
    reports = [read_json(Path(path)) for path in paths]
    if not reports or {x.get("scope") for x in reports} != expected or len(reports) != len(expected):
        raise ValueError("missing, duplicate or unexpected candidate scope")
    frozen = reports[0]["plan"]
    if frozen.get("id") != digest({key:value for key,value in frozen.items() if key != "id"}):
        raise ValueError("candidate plan digest differs")
    assigned = [name for names in frozen["scopes"].values() for name in names]
    if sorted(assigned) != frozen["tests"] or len(assigned) != len(set(assigned)) or set(frozen["scopes"]) != set(CANDIDATE_SCOPES):
        raise ValueError("candidate assignment is incomplete or duplicated")
    import importlib.util
    spec = importlib.util.spec_from_file_location("candidate_coverage", Path(__file__).with_name("coverage.py"))
    checked = importlib.util.module_from_spec(spec); spec.loader.exec_module(checked)
    excluded = {}
    for path, report in zip(paths, reports):
        names = frozen["scopes"][report["scope"]]
        if (report["plan"] != frozen or report["exit_code"] or sorted(report["results"]) != names or
                any(value != "passed" for value in report["results"].values())):
            raise ValueError("changed candidate identity or incomplete scope results")
        junit = Path(path).with_suffix(".junit.xml")
        if hashlib.sha256(junit.read_bytes()).hexdigest() != report["junit_sha256"] or junit_results(junit,names) != report["results"]:
            raise ValueError("candidate JUnit changed")
        if report["timing"]["tests"] != junit_timings(junit, names, frozen["timeouts"]):
            raise ValueError("candidate timing differs from retained JUnit")
        phases = report["timing"]["phase_seconds"]
        if (set(phases) != {"build", "test", "total"} or
                any(type(value) not in (int, float) or not math.isfinite(value) or value < 0 for value in phases.values()) or
                phases["total"] < phases["build"] + phases["test"]):
            raise ValueError("invalid candidate phase timings")
        if set(report["tool_reports"]) != {name for name in names if name.startswith("tools.")}:
            raise ValueError("candidate inner-case inventory missing")
        for name, inner in report["tool_reports"].items():
            checked.tool_report(inner)
            excluded[name] = inner["excluded"]
    return dict(schema_version=1, status="passed", mode="diagnostic" if diagnostic else "candidate",
                plan=frozen, executed_scopes=sorted(expected), inner_exclusions=excluded,
                omitted_scopes=sorted(set(CANDIDATE_SCOPES)-expected))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="action", required=True)
    plan_cmd = sub.add_parser("plan")
    plan_cmd.add_argument("--build", type=Path, required=True)
    plan_cmd.add_argument("--shards", type=int, default=2)
    plan_cmd.add_argument("--jobs", type=builder.positive, help="legacy explicit compile concurrency")
    plan_cmd.add_argument("--build-jobs", type=builder.positive)
    plan_cmd.add_argument("--output", type=Path, required=True)
    run_cmd = sub.add_parser("run")
    run_cmd.add_argument("--build", type=Path, required=True)
    run_cmd.add_argument("--plan", type=Path, required=True)
    run_cmd.add_argument("--shard", type=int, required=True)
    run_cmd.add_argument("--jobs", type=builder.positive, help="legacy explicit compile/test concurrency")
    run_cmd.add_argument("--build-jobs", type=builder.positive)
    run_cmd.add_argument("--summary", type=Path)
    run_cmd.add_argument("--output", type=Path, required=True)
    merge_cmd = sub.add_parser("merge")
    merge_cmd.add_argument("--plan", type=Path, required=True)
    merge_cmd.add_argument("--output", type=Path, required=True)
    merge_cmd.add_argument("reports", type=Path, nargs="+")
    candidate_cmd = sub.add_parser("candidate-run")
    candidate_cmd.add_argument("--build", type=Path, required=True)
    candidate_cmd.add_argument("--scope", choices=CANDIDATE_SCOPES, required=True)
    candidate_cmd.add_argument("--jobs", type=builder.positive, default=2, help="test concurrency")
    candidate_cmd.add_argument("--build-jobs", type=builder.positive)
    candidate_cmd.add_argument("--output", type=Path, required=True)
    candidate_cmd.add_argument("--summary", type=Path, help="append timing to the hosted job summary")
    candidate_merge_cmd = sub.add_parser("candidate-merge")
    candidate_merge_cmd.add_argument("--output", type=Path, required=True)
    candidate_merge_cmd.add_argument("--diagnostic", action="store_true")
    candidate_merge_cmd.add_argument("reports", type=Path, nargs="+")
    args = parser.parse_args()
    if args.action == "candidate-run":
        candidate_run(args.build, args.scope, args.output, args.jobs, build_jobs=args.build_jobs, summary=args.summary)
        return 0
    if args.action == "candidate-merge":
        if args.output.exists():
            raise ValueError("candidate merge must name a new attempt")
        save(args.output, candidate_merge(args.reports, diagnostic=args.diagnostic))
        return 0
    inputs = ([args.plan] if args.action != "plan" else []) + (args.reports if args.action == "merge" else [])
    if args.output.resolve() in [path.resolve() for path in inputs]:
        raise ValueError("output must not replace an input")
    # A failed attempt must never leave a previous successful receipt behind.
    args.output.unlink(missing_ok=True)
    started = time.monotonic()
    if args.action in ("plan", "run"):
        compile_concurrency = args.build_jobs or args.jobs or build_capacity.compile_jobs(os.environ.get("CMAKE_BUILD_PARALLEL_LEVEL"))
        cache = (args.build / "CMakeCache.txt").read_text()
        if re.search(r"^CMAKE_CONFIGURATION_TYPES:.*=.+", cache, flags=re.M):
            raise ValueError("test-plan example requires a single-configuration build tree")
        before, inputs_before = source_id(args.build), build_inputs(args.build)
        if args.action == "run":
            planned = json.loads(args.plan.read_text())
            validate_plan(planned)
            require_current(args.build, planned)
        programs, environment = execution_context(args.build)
        mapping = prerequisites(args.build)
        declarations_before = ctest_declarations(args.build) if mapping is not None else None
        if args.action == "run" and "prerequisites" in planned:
            if not 0 <= args.shard < len(planned["shards"]):
                raise ValueError("invalid shard or concurrency")
            targets = selected_targets(mapping, planned["shards"][args.shard])
        else:
            targets = [] if mapping is not None and args.action == "plan" else ["foundation-tests"]
        compile_targets(programs, environment, args.build, targets, compile_concurrency)
        compiled_at = time.monotonic()
        if (before != source_id(args.build) or inputs_before != build_inputs(args.build) or
                prerequisites(args.build) != mapping or
                (mapping is not None and ctest_declarations(args.build) != declarations_before)):
            raise ValueError("source, compiler or prepared inputs changed while compiling test prerequisites")
    if args.action == "plan":
        save(args.output, make_plan(inventory(args.build), args.shards, source_id(args.build),
            configuration_id(args.build, declared_commands=mapping is not None), prerequisites=mapping))
    else:
        plan = json.loads(args.plan.read_text())
        validate_plan(plan)
        if args.action == "merge":
            save(args.output, merge(plan, [json.loads(path.read_text()) for path in args.reports]))
        else:
            if not 0 <= args.shard < len(plan["shards"]):
                raise ValueError("invalid shard or concurrency")
            require_current(args.build, plan)
            expected = plan["shards"][args.shard]
            args.output.parent.mkdir(parents=True, exist_ok=True)
            junit = args.output.with_name(args.output.name + ".junit.xml").resolve()
            # Prevent stale JUnit data from surviving a failed test launch.
            junit.unlink(missing_ok=True)
            testing_at = time.monotonic()
            try:
                exit_code = windows_compiler.run([programs["ctest"], "--test-dir", str(args.build), "--no-tests=error", "--output-on-failure",
                    "--parallel", str(args.jobs or 2), "-R", "^(" + "|".join(re.escape(x) for x in expected) + ")$",
                    "--output-junit", str(junit)], env=environment).returncode
            except subprocess.CalledProcessError as error:
                exit_code = error.returncode
            tested_at = time.monotonic()
            results = junit_results(junit, expected)
            timed_tests = junit_timings(junit, expected, test_timeouts(test_definitions(args.build)))
            require_current(args.build, plan)
            timing = dict(tests=timed_tests, phase_seconds=dict(build=compiled_at-started,
                          test=tested_at-testing_at, total=time.monotonic()-started))
            save(args.output, {"schema_version": 1, "plan": plan["id"], "shard": args.shard,
                               "exit_code": exit_code, "results": results, "timing": timing})
            timing_summary(timing, "shard " + str(args.shard), args.summary)
            if exit_code or any(value != "passed" for value in results.values()):
                return 1
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError, ET.ParseError, subprocess.CalledProcessError) as error:
        print("test plan: " + str(error), file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Inspect ELF files without executing them; enforce the declared runtime floor."""
import argparse
from pathlib import Path
import re
import subprocess
from dependency_archive import digest, encoded, write_json

BOOKWORM = {'GLIBC': '2.36', 'GLIBCXX': '3.4.30', 'CXXABI': '1.3.13', 'GCC': '12.0.0'}
# Explicit capability-to-runtime floors; unknown names still fail version().
# glibc 2.36 NEWS and elf/Versions establish this loader capability.
NAMED_ABI_FLOORS = {('GLIBC', 'ABI_DT_RELR'): '2.36'}
MACHINES = {'x86_64': 'Advanced Micro Devices X86-64', 'aarch64': 'AArch64'}
HOST_LIBRARIES = {'libc.so.6', 'libm.so.6', 'libpthread.so.0', 'libdl.so.2', 'librt.so.1',
                  'libresolv.so.2', 'libutil.so.1', 'ld-linux-x86-64.so.2', 'ld-linux-aarch64.so.1'}

SDK_RUNTIME_ALIASES = {
    'libc_malloc_debug.so': 'libc_malloc_debug.so.0', 'libcrypt.so': 'libcrypt.so.1',
    'libmvec.so': 'libmvec.so.1', 'libresolv.so': 'libresolv.so.2',
    'libBrokenLocale.so': 'libBrokenLocale.so.1', 'libnss_compat.so': 'libnss_compat.so.2',
    'libnss_db.so': 'libnss_db.so.2', 'libnss_hesiod.so': 'libnss_hesiod.so.2', 'libnsl.so': 'libnsl.so.1',
}
SDK_RUNTIME_NAMES = HOST_LIBRARIES | {'libanl.so.1', 'libBrokenLocale.so.1', 'libnss_compat.so.2',
    'libnss_dns.so.2', 'libnss_files.so.2', 'libnss_hesiod.so.2', 'libnss_db.so.2',
    'libnsl.so.1', 'libmvec.so.1', 'libmemusage.so', 'libpcprofile.so', 'libc_malloc_debug.so.0', 'libcrypt.so.1'} | set(SDK_RUNTIME_ALIASES)


def version(value):
    if not re.fullmatch(r'\d+(?:\.\d+)*', value):
        raise ValueError('unsupported named ABI requirement: ' + value)
    return tuple(int(x) for x in value.split('.'))


def elf(path):
    with Path(path).open('rb') as stream:
        return stream.read(4) == b'\x7fELF'


def run(readelf, *args):
    return subprocess.check_output([str(readelf), '--wide', *map(str, args)], text=True,
                                   env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'}, stderr=subprocess.STDOUT)


def inspect(path, readelf='readelf', sdk_private=False):
    path = Path(path)
    header = run(readelf, '--file-header', path)
    machine = re.search(r'^\s*Machine:\s*(.+)$', header, re.M)
    if not machine or not re.search(r'^\s*Class:\s*ELF64$', header, re.M):
        raise ValueError('expected a supported 64-bit ELF file')
    dynamic = run(readelf, '--dynamic', path)
    needed = re.findall(r'\(NEEDED\).*?\[([^\]]+)\]', dynamic)
    rpath = re.findall(r'\(RPATH\).*?\[([^\]]*)\]', dynamic)
    runpath = re.findall(r'\(RUNPATH\).*?\[([^\]]*)\]', dynamic)
    headers = run(readelf, '--program-headers', path)
    loader = re.findall(r'Requesting program interpreter:\s*([^\]]+)', headers)
    info = run(readelf, '--version-info', path)
    requirements = {}
    named_requirements = {}
    # Only dependency imports matter; version definitions in an exported library
    # describe its capabilities rather than its own runtime requirements.
    needs = info.split('Version needs section', 1)
    if len(needs) == 2:
        for family, value in re.findall(r'Name:\s*(GLIBCXX|GLIBC|CXXABI|GCC)_([^\s]+)', needs[1]):
            if sdk_private and family == 'GLIBC' and value == 'PRIVATE':
                continue
            floor = NAMED_ABI_FLOORS.get((family, value))
            if floor is not None:
                named_requirements[family + '_' + value] = floor
                value = floor
            parsed = version(value)
            if parsed > version(requirements.get(family, '0')):
                requirements[family] = value
    result = {'sha256': digest(path), 'machine': machine.group(1).strip(), 'needed': sorted(needed),
            'rpaths': rpath + runpath, 'rpath': rpath, 'runpath': runpath,
            'loader': loader, 'requirements': requirements, 'named_requirements': named_requirements}
    if sdk_private:
        definitions = needs[0].split('Version definition section', 1)
        definition_text = definitions[1] if len(definitions) == 2 else ''
        result['glibc_definitions'] = sorted(set(re.findall(r'Name:\s*GLIBC_([0-9.]+)\b', definition_text)), key=version)
        result['defines_private'] = bool(re.search(r'Name:\s*GLIBC_PRIVATE\b', definition_text))
        private = []
        if len(needs) == 2:
            provider = None
            for line in needs[1].splitlines():
                match = re.search(r'File:\s*(\S+)', line)
                if match: provider = match[1]
                if re.search(r'Name:\s*GLIBC_PRIVATE\b', line):
                    if provider is None: raise ValueError('missing SDK private provider identity')
                    private.append(provider)
        result['private_requirements'] = sorted(set(private))
    return result


def resolve_closure(root, results):
    """Prove private edges using contained loader paths, without environment help."""
    base = root if root.is_dir() else root.parent
    paths = {name: base / name for name in results}
    by_path = {path.resolve(): name for name, path in paths.items()}
    for name in results:
        if Path(name).name in HOST_LIBRARIES:
            raise ValueError('package must not bundle the target libc or loader: ' + name)
    reached = set()
    resolutions = {}

    def directories(name, key):
        return tuple(dict.fromkeys((paths[name].parent / item.removeprefix('$ORIGIN').lstrip('/')).resolve()
                                   for value in results[name][key] for item in value.split(':')))

    def visit(name, inherited, active):
        context = (name, inherited)
        if context in active:
            return
        active = active | {context}
        reached.add(name)
        entry = results[name]
        own = directories(name, 'rpath') if not entry['runpath'] else ()
        chain = tuple(dict.fromkeys(own + inherited))
        # RUNPATH applies to direct edges only. RPATH may be inherited by
        # descendants; a requesting object's RUNPATH overrides that search.
        search = directories(name, 'runpath') if entry['runpath'] else chain
        for needed in entry['needed']:
            if not needed or '/' in needed or '\\' in needed:
                raise ValueError('target dependency must use a bare library name')
            if needed in HOST_LIBRARIES:
                continue
            candidates = set()
            for directory in search:
                provider = directory / needed
                if provider.exists():
                    resolved = provider.resolve(strict=True)
                    if resolved not in by_path:
                        raise ValueError('runtime provider is outside the inspected ELF inventory: ' + needed)
                    candidates.add(by_path[resolved])
            if not candidates:
                raise ValueError('package runtime closure is incomplete: loader cannot resolve ' + needed + ' from ' + name)
            if len(candidates) != 1:
                raise ValueError('ambiguous runtime loader providers: ' + needed + ' from ' + name)
            provider = next(iter(candidates))
            previous = resolutions.setdefault((name, needed), provider)
            if previous != provider:
                raise ValueError('runtime provider changes between executable contexts: ' + needed)
            visit(provider, chain, active)

    for name, entry in results.items():
        if entry['loader']:
            visit(name, (), set())
    # A library outside an executable's closure needs its own usable paths;
    # dynamically selected modules cannot silently borrow an unknown context.
    for name in results:
        if name not in reached:
            visit(name, (), set())
    return [{'from': name, 'needed': needed, 'provider': provider}
            for (name, needed), provider in sorted(resolutions.items())]


def sdk_runtime_context(root, processor, declaration):
    """Validate the declared, retained libc/loader cohort inside one target root."""
    if not root.is_dir() or declaration.get('glibc') != '2.36' or declaration.get('processor') != processor:
        raise ValueError('SDK runtime audit needs the exact Bookworm target sysroot')
    for key in ('recipe_id', 'source_sha256'):
        if not re.fullmatch(r'[0-9a-f]{64}', declaration.get(key, '')):
            raise ValueError('SDK runtime audit needs retained recipe and source identities')
    files = declaration.get('files')
    if not isinstance(files, dict) or not files: raise ValueError('missing SDK runtime cohort inventory')
    approved = set()
    for name, value in files.items():
        path = root / name
        if (str(Path(name)) != name or Path(name).is_absolute() or '..' in Path(name).parts
                or Path(name).parent.as_posix() not in ('lib', 'lib64', 'usr/lib', 'usr/lib64')
                or path.name not in SDK_RUNTIME_NAMES or path.is_symlink() or not path.is_file()
                or root not in path.resolve().parents or digest(path) != value):
            raise ValueError('SDK runtime cohort path or digest differs from retained input')
        approved.add(name)
    loader = 'ld-linux-x86-64.so.2' if processor == 'x86_64' else 'ld-linux-aarch64.so.1'
    if not {'libc.so.6', loader} <= {Path(name).name for name in approved}:
        raise ValueError('SDK runtime cohort must contain its matched libc and loader')
    by_name = {}
    for name in approved:
        by_name.setdefault(Path(name).name, set()).add(files[name])
    if any(len(values) != 1 for values in by_name.values()):
        raise ValueError('SDK runtime cohort has conflicting providers')
    # Materialization turns supplier development links into ordinary files.
    # An exact alias is eligible only with the identical retained SONAME file.
    for alias, provider in SDK_RUNTIME_ALIASES.items():
        if alias in by_name and by_name[alias] != by_name.get(provider):
            raise ValueError('SDK development alias lacks its identical runtime provider')
    return approved


def check_sdk_runtime(results, approved, declaration):
    providers = {Path(name).name: value for name, value in results.items() if name in approved}
    if set(approved) - set(results): raise ValueError('SDK runtime cohort contains a non-ELF input')
    for name in approved:
        entry = results[name]
        for defined in entry.get('glibc_definitions', []):
            if version(defined) > version(declaration['glibc']):
                raise ValueError('SDK libc definition exceeds its pinned runtime version')
        if Path(name).name == 'libc.so.6' and declaration['glibc'] not in entry.get('glibc_definitions', []):
            raise ValueError('SDK libc does not expose the pinned runtime version')
        for provider in entry.get('private_requirements', []):
            if provider not in providers or not providers[provider].get('defines_private'):
                raise ValueError('SDK private requirement lacks its matched runtime provider')


def requires_extended_x86_isa(notes):
    # Wide readelf may place NEEDED and USED properties on the same line.
    # USED describes optional dispatched code; only NEEDED raises the CPU floor.
    return bool(re.search(r'\bx86 ISA needed:[^:\r\n]*\bx86-64-v[234]\b', notes))


def audit(root, processor='x86_64', ceilings=None, readelf='readelf', host=False, runtime_resolution=True, sdk_sysroot=None):
    root = Path(root).resolve(strict=True)
    ceilings = BOOKWORM if ceilings is None else ceilings
    if processor not in MACHINES:
        raise ValueError('unsupported processor')
    if sdk_sysroot is not None and not host:
        raise ValueError('SDK runtime allowance cannot be used for application packages')
    approved = sdk_runtime_context(root, processor, sdk_sysroot) if sdk_sysroot is not None else set()
    results = {}
    for path in sorted(root.rglob('*')) if root.is_dir() else [root]:
        if path.is_symlink():
            if root.is_dir() and root not in path.resolve(strict=True).parents:
                raise ValueError('runtime path escapes the inspected tree')
            continue
        if not path.is_file() or not elf(path):
            continue
        name = path.relative_to(root).as_posix() if root.is_dir() else path.name
        entry = inspect(path, readelf, sdk_private=True) if name in approved else inspect(path, readelf)
        notes = run(readelf, '--notes', path)
        if not host and requires_extended_x86_isa(notes):
            raise ValueError('ELF requires instructions above the generic x86_64 baseline')
        if entry['machine'] != MACHINES[processor]:
            raise ValueError('wrong ELF architecture: ' + str(path))
        for family, required in entry['requirements'].items():
            if family not in ceilings or version(required) > version(ceilings[family]):
                raise ValueError('runtime requirement above ceiling: ' + family + '_' + required + ': ' + str(path))
        if not host:
            allowed_loader = '/lib64/ld-linux-x86-64.so.2' if processor == 'x86_64' else '/lib/ld-linux-aarch64.so.1'
            if any(item != allowed_loader for item in entry['loader']):
                raise ValueError('unexpected target loader path')
            for rpath in entry['rpaths']:
                for item in rpath.split(':'):
                    if not item or not (item == '$ORIGIN' or item.startswith('$ORIGIN/')):
                        raise ValueError('target runtime search path must be relative to its executable')
                    resolved = (path.parent / item.removeprefix('$ORIGIN').lstrip('/')).resolve()
                    if root.is_dir() and resolved != root and root not in resolved.parents:
                        raise ValueError('target runtime search path escapes package')
        name = path.relative_to(root).as_posix() if root.is_dir() else path.name
        results[name] = entry
    if not results:
        raise ValueError('no ELF files inspected')
    if sdk_sysroot is not None:
        check_sdk_runtime(results, approved, sdk_sysroot)
    resolution = []
    if not host:
        provided = {Path(name).name for name in results}
        for entry in results.values():
            absent = set(entry['needed']) - provided - HOST_LIBRARIES
            if absent:
                raise ValueError('package runtime closure is incomplete: ' + ', '.join(sorted(absent)))
        if runtime_resolution:
            resolution = resolve_closure(root, results)
    return {'schema_version': 1, 'processor': processor, 'ceilings': ceilings,
            'scope': 'sdk-sysroot' if sdk_sysroot is not None else ('host' if host else ('target' if runtime_resolution else 'staged-requirements')),
            'sdk_runtime': sdk_sysroot,
            'runtime_resolution': 'passed' if not host and runtime_resolution else 'not_checked',
            'resolution': resolution, 'files': results, 'status': 'passed'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root', type=Path)
    parser.add_argument('--processor', choices=tuple(MACHINES), default='x86_64')
    parser.add_argument('--readelf', default='readelf')
    parser.add_argument('--host', action='store_true')
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists(): args.output.unlink()
    write_json(args.output, audit(args.root, args.processor, readelf=args.readelf, host=args.host))


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, subprocess.CalledProcessError) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Inspect PE architecture and ordinary/delayed DLL closure without loading code."""
import argparse
from pathlib import Path
import struct
from dependency_archive import digest, write_json

MACHINES = {'x86_64': 0x8664, 'aarch64': 0xaa64}
SYSTEM_DLLS = {'kernel32.dll', 'kernelbase.dll', 'ntdll.dll', 'user32.dll', 'gdi32.dll',
              'advapi32.dll', 'shell32.dll', 'shlwapi.dll', 'ole32.dll', 'oleaut32.dll',
              'comdlg32.dll', 'comctl32.dll', 'ws2_32.dll', 'rpcrt4.dll', 'version.dll',
              'imm32.dll', 'dwmapi.dll', 'uxtheme.dll', 'setupapi.dll', 'winmm.dll',
              'normaliz.dll', 'msimg32.dll', 'opengl32.dll', 'glu32.dll'}


def inspect(path):
    data = Path(path).read_bytes()
    def unpack(fmt, offset):
        if offset < 0 or offset + struct.calcsize(fmt) > len(data): raise ValueError('truncated PE structure')
        return struct.unpack_from(fmt, data, offset)
    if len(data) < 64 or data[:2] != b'MZ': raise ValueError('not a PE file')
    pe, = unpack('<I', 60)
    if data[pe:pe + 4] != b'PE\0\0': raise ValueError('invalid PE signature')
    machine, count = unpack('<HH', pe + 4)
    optional_size, = unpack('<H', pe + 20)
    optional = pe + 24
    magic, = unpack('<H', optional)
    if magic != 0x20b or optional_size < 112: raise ValueError('expected 64-bit PE optional header')
    os_major, os_minor = unpack('<HH', optional + 40)
    subsystem_major, subsystem_minor = unpack('<HH', optional + 48)
    directory_count, = unpack('<I', optional + 108)
    if directory_count > 16 or optional_size < 112 + directory_count * 8: raise ValueError('invalid PE directory count')
    headers_size, = unpack('<I', optional + 60)
    sections = []
    for index in range(count):
        position = optional + optional_size + index * 40
        virtual_size, virtual_start, raw_size, raw_start = unpack('<IIII', position + 8)
        if raw_start + raw_size > len(data): raise ValueError('PE section exceeds file')
        sections.append((virtual_start, virtual_size, raw_start, raw_size))
    def offset(rva, length=1):
        matches = []
        if rva < headers_size and rva + length <= len(data): matches.append(rva)
        for start, size, raw, raw_size in sections:
            if start <= rva and rva + length <= start + min(max(size, raw_size), raw_size):
                matches.append(raw + rva - start)
        if len(matches) != 1: raise ValueError('unmapped or ambiguous PE address')
        return matches[0]
    def name(rva):
        start = offset(rva)
        end = data.find(b'\0', start, min(start + 260, len(data)))
        if end < 0: raise ValueError('unterminated PE dependency name')
        result = data[start:end].decode('ascii').lower()
        if not result.endswith('.dll') or any(c in result for c in '/\\:'):
            raise ValueError('invalid PE dependency filename')
        return result
    imports = set()
    for index, width in ((1, 20), (13, 32)):
        if index >= directory_count: continue
        rva, size = unpack('<II', optional + 112 + index * 8)
        if not rva and not size: continue
        if not rva or size < width: raise ValueError('invalid PE import directory')
        terminated = False
        for displacement in range(0, size - width + 1, width):
            values = unpack('<' + 'I' * (width // 4), offset(rva + displacement, width))
            if not any(values):
                terminated = True
                break
            if index == 13 and values[0] != 1: raise ValueError('unsupported delayed-import address mode')
            imports.add(name(values[3] if index == 1 else values[1]))
        if not terminated: raise ValueError('unterminated PE import directory')
    return {'sha256': digest(path), 'machine': machine, 'minimum_os': [os_major, os_minor], 'minimum_subsystem': [subsystem_major, subsystem_minor], 'imports': sorted(imports)}


def audit(root, processor='x86_64', static_crt=True):
    root = Path(root).resolve(strict=True)
    if processor not in MACHINES: raise ValueError('unsupported PE processor')
    paths = sorted(root.rglob('*')) if root.is_dir() else [root]
    files, providers = {}, {}
    for path in paths:
        if path.is_symlink(): raise ValueError('linked Windows package entry')
        if not path.is_file() or path.suffix.lower() not in ('.exe', '.dll'): continue
        data = inspect(path)
        if data['machine'] != MACHINES[processor]: raise ValueError('PE architecture mismatch')
        if data['minimum_os'] > [10, 0] or data['minimum_subsystem'] > [10, 0]: raise ValueError('PE minimum OS exceeds the declared Windows 10 baseline')
        key = path.name.lower()
        if key in providers: raise ValueError('ambiguous DLL/executable basename')
        providers[key] = path
        files[path.relative_to(root).as_posix() if root.is_dir() else path.name] = data
    if not files: raise ValueError('no PE files inspected')
    for relative_name, data in files.items():
        dependent = root / relative_name if root.is_dir() else root
        for name in data['imports']:
            runtime = name.startswith(('vcruntime', 'msvcp', 'api-ms-win-crt-')) or name in ('ucrtbase.dll', 'msvcr120.dll')
            if static_crt and runtime: raise ValueError('shared compiler runtime violates static CRT policy: ' + name)
            # Do not exempt arbitrary files merely because they were found in
            # System32. API-set extensions require an explicitly reviewed rule.
            if name in providers and providers[name].parent != dependent.parent:
                raise ValueError('private Windows DLL is not beside its dependent image: ' + name)
            if name not in providers and name not in SYSTEM_DLLS:
                raise ValueError('Windows package dependency closure is incomplete: ' + name)
    return {'schema_version': 1, 'status': 'passed', 'processor': processor, 'static_crt': static_crt, 'files': files}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root', type=Path)
    parser.add_argument('--processor', choices=tuple(MACHINES), default='x86_64')
    parser.add_argument('--shared-crt', action='store_true')
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists(): args.output.unlink()
    write_json(args.output, audit(args.root, args.processor, not args.shared_crt))


if __name__ == '__main__':
    try: main()
    except (ValueError, OSError, UnicodeError, struct.error) as error: raise SystemExit(str(error))

#!/usr/bin/env python3
"""Own explicitly selected MSVC build commands and their private compiler services.

Microsoft BuildXL sets _MSPDBSRV_ENDPOINT_ per invocation because a reused PDB
server can perform another invocation's I/O outside its process tree:
https://github.com/microsoft/BuildXL/blob/main/Public/Sdk/Experimental/Msvc/Native/Tools/Link/Link.dsc
This implementation keeps the server inside its no-breakaway Job and joins it.
The endpoint behavior must be qualified on the selected native MSVC toolset.
"""
from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import subprocess
import sys
import tempfile
import uuid

import process_tree
import windows_toolchain

ENDPOINT = '_MSPDBSRV_ENDPOINT_'
HELPERS = ('vctip.exe', 'mspdbsrv.exe')


def _environment_value(environment, name):
    matches = [value for key, value in environment.items() if key.upper() == name.upper()]
    if len(matches) != 1 or not matches[0]:
        raise ValueError('one selected MSVC environment value required: ' + name)
    return matches[0]


def _snapshot(path):
    path = Path(path)
    before = os.stat(path, follow_symlinks=False)
    if (not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or
            getattr(before, 'st_file_attributes', 0) & 0x400):
        raise ValueError('MSVC toolkit input must be an ordinary singly linked file')
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    def identity(value):
        return (value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_ctime_ns)
    if identity(os.stat(path, follow_symlinks=False)) != identity(before):
        raise ValueError('MSVC toolkit input changed while being identified')
    return identity(before), {'path': str(path), 'sha256': digest.hexdigest()}


def _select_toolkit(environment):
    directory = Path(_environment_value(environment, 'VCToolsInstallDir')) / 'bin/Hostx64/x64'
    directory = directory.resolve(strict=True)
    selected = {}
    for name in ('cl.exe', 'link.exe'):
        found = shutil.which(name, path=_environment_value(environment, 'PATH'))
        expected = directory / name
        if found is None or not Path(found).samefile(expected):
            raise ValueError('selected MSVC executable differs from its toolkit: ' + name)
        selected[name] = expected
    for name in HELPERS:
        path = directory / name
        if name == 'vctip.exe' and not path.exists():
            continue
        selected[name] = path
    for path in selected.values():
        _snapshot(path)
        windows_toolchain.pe_identity(path)
    return selected


class BuildSession:
    """A fresh endpoint belongs to this Job only, including for nested owners."""
    def __init__(self, environment):
        self.paths = _select_toolkit(environment)
        self.identities = {name: _snapshot(path) for name, path in self.paths.items()}
        self.endpoint = 'foundation-' + uuid.uuid4().hex
        self.environment = {key: value for key, value in environment.items() if key.upper() != ENDPOINT}
        self.environment[ENDPOINT] = self.endpoint
        self.observed = []
        self.completed = False

    def unchanged(self):
        if any(_snapshot(self.paths[name]) != identity for name, identity in self.identities.items()):
            raise ValueError('selected MSVC toolkit changed during its owned build')

    def validate(self, pid, image):
        # ProcessTree queried this image through its already pinned, verified Job
        # member handle. Canonical file identity also accepts Windows 8.3 aliases.
        self.unchanged()
        image = Path(image).resolve(strict=True)
        matches = [name for name in HELPERS if name in self.paths and image.samefile(self.paths[name])]
        if len(matches) != 1:
            raise process_tree.ProcessTreeError('unknown live MSVC build descendant: ' +
                                               json.dumps({'pid': pid, 'image': str(image)}))
        name = matches[0]
        self.observed.append(dict(self.identities[name][1], name=name, pid=pid))
        return True

    def finish(self, owner):
        if self.completed:
            raise ValueError('MSVC build session already completed')
        self.unchanged()
        # Every live member must pass validation before stopping; new assignments
        # and uncertain images fail closed. Generic finish still rejects writers.
        owner.terminate(validate_live=self.validate)
        self.unchanged()
        owner.finish()
        self.completed = True
        return self.receipt()

    def receipt(self):
        if not self.completed:
            raise ValueError('MSVC build session completion is unconfirmed')
        return {'policy': 'private-msvc-build-session', 'endpoint': self.endpoint,
                'toolkit': {name: item[1] for name, item in self.identities.items()},
                'outcome': 'verified-helpers-terminated-and-joined' if self.observed else 'no-surviving-helper',
                'helpers': list(self.observed)}



@contextmanager
def workspace(prefix):
    """Preserve consumer outputs when writer cleanup could not be confirmed."""
    directory = Path(tempfile.mkdtemp(prefix=prefix))
    safe = True
    try:
        yield directory
    except BaseException as error:
        pending, seen = [error], set()
        while pending:
            current = pending.pop()
            if current is None or id(current) in seen:
                continue
            seen.add(id(current))
            if isinstance(current, process_tree.ProcessTreeError):
                safe = False
                break
            pending.extend((current.__cause__, current.__context__))
        raise
    finally:
        if safe:
            shutil.rmtree(directory)


def run(command, *, cwd=None, env=None, timeout=3600):
    """Run a compiler-capable region; other platforms retain subprocess semantics.

    This is explicit build ownership, not a generic successful-command exception.
    The caller keeps its output stream and work tree owned until this returns.
    Each invocation, even nested inside another owner, gets its own PDB endpoint.
    """
    if os.name != 'nt':
        return subprocess.run(command, cwd=cwd, env=env, check=True)
    session = BuildSession(dict(os.environ if env is None else env))
    owner = process_tree.launch(command, Path.cwd() if cwd is None else cwd, sys.stdout, env=session.environment)
    receipt = None
    try:
        code = owner.wait(timeout=timeout)
        if code == 0:
            receipt = session.finish(owner)
        else:
            owner.terminate()
            owner.finish()
            raise subprocess.CalledProcessError(code, command)
    finally:
        owner.close()
    print('MSVC_BUILD_COMPLETION ' + json.dumps(receipt, sort_keys=True), flush=True)
    return subprocess.CompletedProcess(command, code)

// Native Windows host qualification only. Keep the executable beside the exact
// staged OpenGL DLLs. The caller must bound its process tree lifetime: a driver
// call can block inside foreign code. This probe never changes driver overrides.
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <GL/gl.h>

#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdio>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>

namespace {
constexpr std::size_t max_gl_string = 1024;
constexpr std::size_t max_report = 512 * 1024;
constexpr GLenum gl_major_version = 0x821b;
constexpr GLenum gl_minor_version = 0x821c;
constexpr GLenum gl_num_extensions = 0x821d;
using CreateContext = HGLRC (WINAPI *)(HDC, HGLRC, const int*);
using ChooseFormat = BOOL (WINAPI *)(HDC, const int*, const FLOAT*, UINT, int*, UINT*);
using GetStringIndex = const GLubyte* (APIENTRY *)(GLenum, GLuint);

struct Report {
    bool passed = false;
    std::string error, opengl32_path, libgallium_wgl_path, version, vendor, renderer;
    GLint major = 0, minor = 0;
    bool create_context = false, choose_format = false;
    bool arb_buffer_storage = false, gl_buffer_storage = false;
};

std::string escaped(std::string_view value) {
    // Inputs are validated UTF-8. Escape every JSON control character explicitly.
    constexpr char hex[] = "0123456789abcdef";
    std::string result = "\"";
    for (const unsigned char c : value) {
        if (c == '"' || c == '\\') {
            result += '\\'; result += static_cast<char>(c);
        } else if (c < 0x20) {
            result += "\\u00"; result += hex[c >> 4]; result += hex[c & 15];
        } else {
            result += static_cast<char>(c);
        }
    }
    result += '"';
    return result;
}

std::string json(const Report& r) {
    std::ostringstream out;
    out << std::boolalpha << "{\"schema_version\":1,\"status\":"
        << escaped(r.passed ? "passed" : "failed")
        << ",\"error\":" << escaped(r.error)
        << ",\"opengl32_path\":" << escaped(r.opengl32_path)
        << ",\"libgallium_wgl_path\":" << escaped(r.libgallium_wgl_path)
        << ",\"version\":" << escaped(r.version)
        << ",\"vendor\":" << escaped(r.vendor)
        << ",\"renderer\":" << escaped(r.renderer)
        << ",\"major\":" << r.major << ",\"minor\":" << r.minor
        << ",\"wgl_create_context_attribs_arb\":" << r.create_context
        << ",\"wgl_choose_pixel_format_arb\":" << r.choose_format
        << ",\"arb_buffer_storage\":" << r.arb_buffer_storage
        << ",\"gl_buffer_storage\":" << r.gl_buffer_storage << "}\n";
    return out.str();
}

[[noreturn]] void failed(const char* operation) {
    throw std::runtime_error(std::string(operation) + " failed (Win32 " +
                             std::to_string(GetLastError()) + ")");
}

std::string module_path(const wchar_t* name) {
    const HMODULE module = GetModuleHandleW(name);
    if (!module) failed("loaded module lookup");
    std::array<wchar_t, 32768> path{};
    const DWORD length = GetModuleFileNameW(module, path.data(), static_cast<DWORD>(path.size()));
    if (!length || length >= path.size()) failed("bounded loaded module path");
    const int size = WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, path.data(),
        static_cast<int>(length), nullptr, 0, nullptr, nullptr);
    if (size <= 0) failed("module path UTF-8 conversion");
    std::string result(static_cast<std::size_t>(size), '\0');
    if (WideCharToMultiByte(CP_UTF8, WC_ERR_INVALID_CHARS, path.data(), static_cast<int>(length),
                           result.data(), size, nullptr, nullptr) != size) failed("module path UTF-8 conversion");
    return result;
}

std::string gl_text(const GLubyte* value) {
    if (!value) throw std::runtime_error("missing OpenGL string");
    std::size_t length = 0;
    while (length < max_gl_string && value[length]) ++length;
    if (length == max_gl_string) throw std::runtime_error("OpenGL string exceeds byte limit");
    const auto* bytes = reinterpret_cast<const char*>(value);
    if (length && !MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, bytes,
                                     static_cast<int>(length), nullptr, 0))
        throw std::runtime_error("OpenGL string is not valid UTF-8");
    return std::string(bytes, length);
}

bool present(PROC function) {
    const auto value = reinterpret_cast<std::intptr_t>(function);
    return value != 0 && value != 1 && value != 2 && value != 3 && value != -1;
}

class WindowClass {
public:
    HINSTANCE instance = GetModuleHandleW(nullptr);
    std::wstring name = L"FoundationGraphicsProbe-" + std::to_wstring(GetCurrentProcessId());
    WindowClass() {
        WNDCLASSEXW type{};
        type.cbSize = static_cast<UINT>(sizeof(type));
        type.style = CS_OWNDC;
        type.lpfnWndProc = DefWindowProcW;
        type.hInstance = instance;
        type.lpszClassName = name.c_str();
        if (!RegisterClassExW(&type)) failed("private window class registration");
    }
    ~WindowClass() { UnregisterClassW(name.c_str(), instance); }
    WindowClass(const WindowClass&) = delete;
    WindowClass& operator=(const WindowClass&) = delete;
};

class Context {
public:
    HWND window = nullptr;
    HDC dc = nullptr;
    HGLRC context = nullptr;
    Context() = default;
    ~Context() { close(); }
    Context(const Context&) = delete;
    Context& operator=(const Context&) = delete;
    void create(const WindowClass& type) {
        // No ShowWindow or visible style: host qualification has no user UI.
        window = CreateWindowExW(0, type.name.c_str(), L"", WS_OVERLAPPEDWINDOW,
                                 0, 0, 8, 8, nullptr, nullptr, type.instance, nullptr);
        if (!window) failed("private hidden window creation");
        dc = GetDC(window);
        if (!dc) failed("private window DC acquisition");
    }
    bool close() noexcept {
        bool clean = true;
        if (context) {
            if (wglGetCurrentContext() == context && !wglMakeCurrent(nullptr, nullptr)) clean = false;
            if (!wglDeleteContext(context)) clean = false;
            context = nullptr;
        }
        if (dc && window) ReleaseDC(window, dc);
        dc = nullptr;
        // Destroying a CS_OWNDC window also releases its private DC.
        if (window && !DestroyWindow(window)) clean = false;
        window = nullptr;
        return clean;
    }
};

void set_format(HDC dc, int format, const PIXELFORMATDESCRIPTOR& descriptor) {
    if (!format || !SetPixelFormat(dc, format, &descriptor)) failed("pixel format selection");
}

bool extension(GetStringIndex get, const char* required) {
    GLint count = 0;
    glGetIntegerv(gl_num_extensions, &count);
    if (glGetError() != GL_NO_ERROR || count < 0 || count > 4096)
        throw std::runtime_error("invalid or excessive OpenGL extension count");
    for (GLint index = 0; index < count; ++index) {
        if (gl_text(get(GL_EXTENSIONS, static_cast<GLuint>(index))) == required) return true;
    }
    return false;
}

void probe(Report& report) {
    for (const wchar_t* name : {L"MESA_GL_VERSION_OVERRIDE", L"MESA_GLSL_VERSION_OVERRIDE", L"MESA_EXTENSION_OVERRIDE"}) {
        if (GetEnvironmentVariableW(name, nullptr, 0))
            throw std::runtime_error("version or extension overrides are forbidden");
    }
    report.opengl32_path = module_path(L"opengl32.dll");
    WindowClass type;
    Context bootstrap;
    bootstrap.create(type);
    PIXELFORMATDESCRIPTOR descriptor{};
    descriptor.nSize = static_cast<WORD>(sizeof(descriptor));
    descriptor.nVersion = 1;
    descriptor.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    descriptor.iPixelType = PFD_TYPE_RGBA;
    descriptor.cColorBits = 32; descriptor.cAlphaBits = 8;
    descriptor.cDepthBits = 24; descriptor.cStencilBits = 8;
    set_format(bootstrap.dc, ChoosePixelFormat(bootstrap.dc, &descriptor), descriptor);
    bootstrap.context = wglCreateContext(bootstrap.dc);
    if (!bootstrap.context || !wglMakeCurrent(bootstrap.dc, bootstrap.context)) failed("bootstrap WGL context");
    const PROC create_proc = wglGetProcAddress("wglCreateContextAttribsARB");
    const PROC choose_proc = wglGetProcAddress("wglChoosePixelFormatARB");
    report.create_context = present(create_proc); report.choose_format = present(choose_proc);
    if (!report.create_context || !report.choose_format)
        throw std::runtime_error("required WGL context or pixel format entrypoint is absent");
    const auto create = reinterpret_cast<CreateContext>(create_proc);
    const auto choose = reinterpret_cast<ChooseFormat>(choose_proc);
    Context modern;
    modern.create(type);
    // WGL_DRAW_TO_WINDOW_ARB, SUPPORT_OPENGL, DOUBLE_BUFFER, PIXEL_TYPE/RGBA,
    // COLOR_BITS, ALPHA_BITS, DEPTH_BITS and STENCIL_BITS.
    const int attributes[] = {0x2001, 1, 0x2010, 1, 0x2011, 1, 0x2013, 0x202b,
                              0x2014, 32, 0x201b, 8, 0x2022, 24, 0x2023, 8, 0};
    int format = 0; UINT count = 0;
    if (!choose(modern.dc, attributes, nullptr, 1, &format, &count) || count != 1 || !format)
        failed("WGL attributed pixel format query");
    if (!DescribePixelFormat(modern.dc, format, static_cast<UINT>(sizeof(descriptor)), &descriptor))
        failed("attributed pixel format description");
    set_format(modern.dc, format, descriptor);
    for (const int minor : {4, 3}) {
        const int requested[] = {0x2091, 4, 0x2092, minor, 0x9126, 1, 0};
        modern.context = create(modern.dc, nullptr, requested);
        if (modern.context) break;
    }
    if (!modern.context || !wglMakeCurrent(modern.dc, modern.context)) failed("OpenGL 4.4 or 4.3 core context");
    // Query entrypoints for this actual context/pixel format, not only bootstrap.
    report.create_context = present(wglGetProcAddress("wglCreateContextAttribsARB"));
    report.choose_format = present(wglGetProcAddress("wglChoosePixelFormatARB"));
    report.version = gl_text(glGetString(GL_VERSION));
    report.vendor = gl_text(glGetString(GL_VENDOR));
    report.renderer = gl_text(glGetString(GL_RENDERER));
    report.libgallium_wgl_path = module_path(L"libgallium_wgl.dll");
    glGetIntegerv(gl_major_version, &report.major);
    glGetIntegerv(gl_minor_version, &report.minor);
    if (glGetError() != GL_NO_ERROR || report.major < 0 || report.major > 99 || report.minor < 0 || report.minor > 99)
        throw std::runtime_error("invalid OpenGL version query");
    const PROC get_proc = wglGetProcAddress("glGetStringi");
    if (!present(get_proc)) throw std::runtime_error("indexed OpenGL extension query unavailable");
    report.arb_buffer_storage = extension(reinterpret_cast<GetStringIndex>(get_proc), "GL_ARB_buffer_storage");
    report.gl_buffer_storage = present(wglGetProcAddress("glBufferStorage"));
    std::string renderer = report.renderer;
    std::transform(renderer.begin(), renderer.end(), renderer.begin(), [](unsigned char c) {
        return static_cast<char>(c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c);
    });
    if (renderer.find("llvmpipe") == std::string::npos)
        throw std::runtime_error("host input profile requires llvmpipe");
    const bool core = report.major > 4 || (report.major == 4 && report.minor >= 4);
    const bool extended = report.major == 4 && report.minor >= 3 && report.arb_buffer_storage;
    if (!report.create_context || !report.choose_format || !report.gl_buffer_storage || !(core || extended))
        throw std::runtime_error("required OpenGL buffer storage capabilities are absent");
    const bool modern_clean = modern.close();
    const bool bootstrap_clean = bootstrap.close();
    if (!modern_clean || !bootstrap_clean) throw std::runtime_error("WGL context cleanup failed");
    report.passed = true;
}
} // namespace

int main(int argc, char**) {
    Report report;
    try {
        if (argc != 1) throw std::runtime_error("this probe accepts no arguments");
        probe(report);
    } catch (const std::exception& error) {
        // Error diagnostics remain bounded ASCII even for foreign exceptions.
        for (std::size_t i = 0; i < 256 && error.what()[i]; ++i) {
            const unsigned char c = static_cast<unsigned char>(error.what()[i]);
            report.error += static_cast<char>(c >= 0x20 && c <= 0x7e ? c : '?');
        }
        report.passed = false;
    } catch (...) {
        report.error = "unexpected probe failure";
        report.passed = false;
    }
    const std::string result = json(report);
    if (result.size() > max_report) {
        std::fputs("{\"schema_version\":1,\"status\":\"failed\",\"error\":\"report exceeds byte limit\"}\n", stdout);
        return 1;
    }
    const bool written = std::fwrite(result.data(), 1, result.size(), stdout) == result.size();
    return written && std::fflush(stdout) == 0 && report.passed ? 0 : 1;
}

#!/usr/bin/env python3
"""Pinned host-only Windows graphics inputs; offline selective staging by default."""
import argparse
from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request

import process_tree

LOCK_PATH = Path(__file__).resolve().parents[1] / 'third_party/host-graphics/mesa-windows.json'
FORBIDDEN_ENV = ('MESA_GL_VERSION_OVERRIDE', 'MESA_GLSL_VERSION_OVERRIDE', 'MESA_EXTENSION_OVERRIDE')
SELECTED = ('opengl32.dll', 'libgallium_wgl.dll')


class GraphicsError(ValueError):
    pass


def retain_required(error):
    """Whether outer extraction/output cleanup must preserve uncertain writers."""
    pending, seen = [error], set()
    while pending:
        current = pending.pop()
        if current is None or id(current) in seen:
            continue
        seen.add(id(current))
        receipt = getattr(current, 'graphics_receipt', None)
        if (isinstance(current, process_tree.ProcessTreeError)
                or (isinstance(receipt, dict) and receipt.get('cleanup') != 'removed')):
            return True
        pending.extend((getattr(current, '__cause__', None), getattr(current, '__context__', None)))
    return False


class Staging:
    def __init__(self, environment, receipt):
        self.environment, self.receipt = environment, receipt
        self.writers_uncertain = False

    def mark_writers_uncertain(self):
        """Preserve staging if the caller cannot prove descendant completion."""
        self.writers_uncertain = True


def _json(raw):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise GraphicsError('duplicate JSON field')
            result[key] = value
        return result
    return json.loads(raw, object_pairs_hook=unique)


def lock():
    value = _json(LOCK_PATH.read_bytes())
    if (value.get('schema_version') != 1 or value.get('scope') != 'host-qualification-only'
            or value.get('architecture') != 'x86_64' or value.get('redistribution', {}).get('approved') is not False
            or set(value.get('files', {})) != set(SELECTED)):
        raise GraphicsError('unsupported host graphics lock')
    for item in [value['archive'], *value['files'].values()]:
        if (type(item.get('size')) is not int or not 0 < item['size'] < 256 * 1024 * 1024
                or not re.fullmatch('[0-9a-f]{64}', item.get('sha256', ''))):
            raise GraphicsError('invalid locked file identity')
    for name in SELECTED:
        if value['files'][name].get('member') != 'x64/' + name:
            raise GraphicsError('unexpected selected archive member')
    _https(value['archive']['url'])
    return value


def _plain(info):
    return not (getattr(info, 'st_file_attributes', 0) & 0x400)  # Windows reparse point.


def _directory(value):
    path = Path(os.path.abspath(value))
    if '..' in Path(value).parts:
        raise GraphicsError('dot-dot destination is unsupported')
    for component in reversed((path, *path.parents)):
        info = component.lstat()
        if not stat.S_ISDIR(info.st_mode) or not _plain(info):
            raise GraphicsError('directory must not contain links or reparse points')
    return path


def _identity(path):
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or not _plain(info) or info.st_nlink != 1:
        raise GraphicsError('input must be a singly linked regular file')
    return (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns)


def _protected_root(value):
    path = Path(os.path.abspath(value))
    if '..' in Path(value).parts:
        raise GraphicsError('dot-dot protected root is unsupported')
    for component in reversed((path, *path.parents)):
        try:
            info = component.lstat()
        except FileNotFoundError:
            continue
        if not stat.S_ISDIR(info.st_mode) or not _plain(info):
            raise GraphicsError('protected root contains a link, reparse point or non-directory')
    return path


def _checked_file(path, expected):
    path = _directory(Path(path).parent) / Path(path).name
    before = _identity(path)
    if before[2] != expected['size']:
        raise GraphicsError('file size differs from locked identity')
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        opened = os.fstat(stream.fileno())
        if (opened.st_dev, opened.st_ino, opened.st_size, opened.st_mtime_ns) != before:
            raise GraphicsError('file changed before reading')
        remaining = expected['size']
        while remaining:
            data = stream.read(min(1024 * 1024, remaining))
            if not data:
                raise GraphicsError('file changed while reading')
            remaining -= len(data)
            digest.update(data)
        if stream.read(1):
            raise GraphicsError('file exceeded locked size')
    if _identity(path) != before or digest.hexdigest() != expected['sha256']:
        raise GraphicsError('file bytes differ from locked identity')
    return before


def verify_archive(path):
    metadata = lock()
    _checked_file(Path(path), metadata['archive'])
    return {'schema_version': 1, 'scope': metadata['scope'], 'architecture': metadata['architecture'],
            'archive': {key: metadata['archive'][key] for key in ('name', 'size', 'sha256')},
            'redistribution_approved': False}


def _https(url):
    try:
        parsed = urllib.parse.urlsplit(url)
        if (parsed.scheme != 'https' or not parsed.hostname or parsed.username is not None
                or parsed.password is not None or parsed.fragment or any(ord(c) <= 32 for c in url)):
            raise ValueError('invalid transport URL')
        parsed.port
    except (TypeError, ValueError) as error:
        raise GraphicsError('a credential-free HTTPS URL is required') from error
    return url


class _HTTPSRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, response, code, message, headers, newurl):
        _https(newurl)
        return super().redirect_request(request, response, code, message, headers, newurl)


def _publish(temporary, target):
    # Atomic no-replace publication, supported on the qualified NTFS and POSIX
    # fixtures. Unsupported filesystems fail without a direct-write fallback.
    if any(path.name.casefold() == target.name.casefold() for path in target.parent.iterdir()):
        raise GraphicsError('destination already exists; nothing replaced')
    try:
        os.link(temporary, target, follow_symlinks=False)
    except OSError as error:
        raise GraphicsError('atomic no-replace publication failed') from error
    temporary.unlink()


def _download(url, archive_path, acquisition):
    _https(url)
    target = _directory(Path(archive_path).parent) / Path(archive_path).name
    if target.exists() or target.is_symlink():
        receipt = verify_archive(target)
        receipt['acquisition'] = 'verified-cache'
        return receipt
    metadata = lock()['archive']
    # The URL may contain an operator access query; never include it or exception
    # text from urllib in diagnostics or receipts.
    temporary = None
    try:
        fd, name = tempfile.mkstemp(prefix='.graphics-fetch-', dir=target.parent)
        temporary = Path(name)
        opener = urllib.request.build_opener(_HTTPSRedirect())
        started = time.monotonic()
        with os.fdopen(fd, 'wb') as output:
            with opener.open(urllib.request.Request(url, headers={'User-Agent': 'Foundation-host-input/1'}),
                             timeout=30) as response:
                _https(response.geturl())
                length = response.headers.get('Content-Length')
                if length is not None and length != str(metadata['size']):
                    raise GraphicsError('download size differs from locked archive')
                remaining = metadata['size']
                while remaining:
                    if time.monotonic() - started > 300:
                        raise GraphicsError('archive download exceeded its time bound')
                    data = response.read(min(1024 * 1024, remaining))
                    if not data:
                        raise GraphicsError('incomplete host archive download')
                    output.write(data)
                    remaining -= len(data)
                if response.read(1):
                    raise GraphicsError('download exceeded locked archive size')
            output.flush()
            os.fsync(output.fileno())
        _checked_file(temporary, metadata)
        _publish(temporary, target)
        temporary = None
        receipt = verify_archive(target)
        receipt['acquisition'] = acquisition
        return receipt
    except (urllib.error.URLError, TimeoutError, OSError) as error:
        raise GraphicsError('host archive acquisition failed; retained inputs remain unchanged') from None
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def fetch(archive_path, *, network=False):
    if Path(archive_path).exists() or Path(archive_path).is_symlink():
        receipt = verify_archive(archive_path)
        receipt['acquisition'] = 'verified-cache'
        return receipt
    if not network:
        raise GraphicsError('archive is absent; explicit maintenance network acquisition is required')
    return _download(lock()['archive']['url'], archive_path, 'supplier-maintenance')


def fetch_retained(url, archive_path):
    """Explicit operator HTTPS transfer of exactly the already pinned archive."""
    return _download(url, archive_path, 'operator-retained-https')


def child_environment(environment=None):
    result = dict(os.environ if environment is None else environment)
    if any(key.upper() in FORBIDDEN_ENV for key in result):
        raise GraphicsError('graphics capability override variables are prohibited')
    # Environment names are case-insensitive on Windows, including in fixtures
    # prepared on another system.
    result = {key: value for key, value in result.items() if key.upper() != 'GALLIUM_DRIVER'}
    result['GALLIUM_DRIVER'] = 'llvmpipe'
    return result


class _MsvcTelemetry:
    """The selected MSVC toolkit's optional VCTIP, never a basename allowlist.

    Microsoft documents this as a non-output telemetry child of cl.exe:
    https://github.com/microsoft/BuildXL/blob/main/Public/Sdk/Experimental/Msvc/VisualCpp/visualCpp.dsc
    Keep it contained and join it; do not grant it breakaway or a grace period.
    """
    def __init__(self, compiler, helper):
        self.compiler = Path(compiler).resolve(strict=True)
        self.helper = Path(helper).resolve(strict=True)
        if self.helper != self.compiler.with_name('vctip.exe'):
            raise GraphicsError('MSVC telemetry helper differs from the exact selected toolkit')
        self.identities = {path: self._identity(path) for path in (self.compiler, self.helper)}
        self.stopped_pids = []
        self.completed = False

    @staticmethod
    def _identity(path):
        before = _identity(path)
        value = {'path': str(path), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}
        if _identity(path) != before:
            raise GraphicsError('MSVC toolkit input changed while being identified')
        return before, value

    def unchanged(self):
        if any(self._identity(path) != expected for path, expected in self.identities.items()):
            raise GraphicsError('MSVC compiler or telemetry helper changed during compilation')

    def validate(self, pid, image):
        self.unchanged()
        if Path(image).resolve(strict=True) != self.helper:
            raise process_tree.ProcessTreeError('live compiler descendant is not the exact selected VCTIP: ' +
                                               json.dumps({'pid': pid, 'image': image}))
        # The supervisor pinned and verified this identity, and queried its image
        # through that handle. The prelaunch file identity and bytes still match.
        self.stopped_pids.append(pid)
        return True

    def finish(self, owner):
        self.unchanged()
        owner.terminate(validate_live=self.validate)
        self.unchanged()
        owner.finish()
        self.completed = True

    def receipt(self):
        if not self.completed:
            raise GraphicsError('MSVC helper completion has not been established')
        return {'policy': 'exact-msvc-vctip',
                'outcome': 'verified-helper-terminated-and-joined' if self.stopped_pids else 'no-surviving-helper',
                'compiler': self.identities[self.compiler][1], 'helper': self.identities[self.helper][1],
                'stopped_pids': list(self.stopped_pids)}


def _msvc_telemetry(compiler):
    if os.name != 'nt':
        return None
    selected = Path(compiler).resolve(strict=True)
    helper = selected.with_name('vctip.exe')
    # A toolkit without this optional helper needs ordinary strict completion.
    try:
        helper.lstat()
    except FileNotFoundError:
        return None
    return _MsvcTelemetry(selected, helper)


def _command(argv, *, directory, environment, limit, timeout, record=None, compiler_helper=None):
    if record is not None:
        record = _directory(Path(record).parent) / Path(record).name
        if any(path.name.casefold() == record.name.casefold() for path in record.parent.iterdir()):
            raise GraphicsError('command log already exists; nothing replaced')
    with tempfile.TemporaryFile(dir=directory) as output:
        owner = process_tree.launch(argv, cwd=directory, stream=output, env=environment)
        try:
            deadline = time.monotonic() + timeout
            while owner.poll() is None:
                if os.fstat(output.fileno()).st_size > limit or time.monotonic() > deadline:
                    owner.terminate()
                    raise GraphicsError('host input command exceeded its output or time bound')
                time.sleep(0.01)
            if compiler_helper is not None and owner.process.returncode == 0:
                compiler_helper.finish(owner)
            else:
                owner.finish()
            if os.fstat(output.fileno()).st_size > limit:
                raise GraphicsError('host input command failed or exceeded its output bound')
            output.seek(0)
            raw = output.read(limit + 1)
            if owner.process.returncode != 0:
                raise GraphicsError('host input command failed; inspect its bounded log when supplied')
            return raw
        finally:
            try:
                owner.close()
            except BaseException as error:
                raise process_tree.ProcessTreeError('host command writer cleanup remains uncertain') from error
            if record is not None:
                output.seek(0)
                with record.open('xb') as log:
                    log.write(output.read(limit))


def run_owned(argv, cwd, log_path, *, environment=None, timeout=1800, max_bytes=16 * 1024 * 1024):
    """Run a bounded supervised command; retain a bounded log after all writers stop.

    Failures raise GraphicsError. ProcessTreeError means supervision was invalid
    or completion is uncertain; a surrounding stage preserves its DLLs. Never
    suppress that error and continue packaging.
    """
    if type(max_bytes) is not int or max_bytes <= 0 or timeout <= 0:
        raise GraphicsError('positive output and time bounds are required')
    directory = _directory(cwd)
    _command(argv, directory=directory, environment=child_environment(environment),
             limit=max_bytes, timeout=timeout, record=log_path)
    return {'schema_version': 1, 'returncode': 0, 'log_path': str(Path(log_path).absolute()),
            'log_sha256': hashlib.sha256(Path(log_path).read_bytes()).hexdigest()}


def _listing(raw, metadata):
    try:
        text = raw.decode('utf-8-sig')
    except UnicodeDecodeError as error:
        raise GraphicsError('archive listing must be UTF-8') from error
    entries = {}
    separator = None
    for block in re.split(r'\r?\n\s*\r?\n', text.strip()):
        fields = {}
        for line in block.splitlines():
            if ' = ' not in line:
                raise GraphicsError('unexpected archive listing output')
            key, value = line.split(' = ', 1)
            if key in fields:
                raise GraphicsError('duplicate archive metadata')
            fields[key] = value
        displayed = fields.get('Path', '')
        # 7-Zip displays archive names with the host's separator. Interpret one
        # consistent form, then apply the same canonical member checks below.
        style = '\\' if '\\' in displayed else '/' if '/' in displayed else None
        if ('\\' in displayed and '/' in displayed or
                style is not None and separator is not None and style != separator):
            raise GraphicsError('mixed archive entry path separators: ' + repr(displayed[:240]))
        if style is not None:
            separator = style
        path = displayed.replace('\\', '/')
        posix = PurePosixPath(path)
        if (not path or ':' in path or posix.is_absolute() or '..' in posix.parts
                or str(posix) != path or any(ord(char) < 32 for char in path)):
            raise GraphicsError('unsafe archive entry path: ' + repr(displayed[:240]))
        fields['Path'] = path
        key = path.casefold()
        if key in entries:
            raise GraphicsError('duplicate archive entry')
        entries[key] = fields
    for name, expected in metadata['files'].items():
        entry = entries.get(expected['member'].casefold())
        if (not entry or entry.get('Path') != expected['member'] or entry.get('Size') != str(expected['size'])
                or entry.get('Folder', '-') != '-' or any('link' in key.lower() for key in entry)
                or 'D' in entry.get('Attributes', '') or 'l' in entry.get('Mode', '')):
            raise GraphicsError('selected archive member is absent, unsafe or has unexpected size')


def _directory_identity(path):
    _directory(path)
    info = path.stat()
    return info.st_dev, info.st_ino


@contextmanager
def stage(archive_path, directories, *, environment=None, extractor='7z', protected_roots=()):
    """Temporarily place only two verified DLLs beside owned test executables.

    Callers must finish all children before leaving this context. Cooperative
    exclusive ownership of the directories is required through cleanup.
    """
    metadata = lock()
    receipt = verify_archive(archive_path)
    archive_path = _directory(Path(archive_path).parent) / Path(archive_path).name
    archive_identity = _identity(archive_path)
    environment = child_environment(environment)
    roots = [_protected_root(value) for value in protected_roots]
    destinations = [_directory(value) for value in directories]
    if not destinations or len({str(value).casefold() for value in destinations}) != len(destinations):
        raise GraphicsError('unique existing staging directories are required')
    directory_ids = {}
    for destination in destinations:
        if any(destination == root or root in destination.parents or destination in root.parents for root in roots):
            raise GraphicsError('staging overlaps a protected SDK, dependency or install root')
        directory_ids[destination] = _directory_identity(destination)
        for name in SELECTED:
            if any(item.name.casefold() == name for item in destination.iterdir()):
                raise GraphicsError('driver destination already exists; nothing replaced')
    receipt.update({'driver': 'llvmpipe', 'files': [], 'cleanup': 'pending'})
    result = Staging(environment, receipt)
    owned = []
    try:
        listing = _command([extractor, 'l', '-slt', '-ba', '-sccUTF-8', str(archive_path)],
                           directory=destinations[0], environment=environment, limit=128 * 1024, timeout=30)
        _listing(listing, metadata)
        for name in SELECTED:
            item = metadata['files'][name]
            content = _command([extractor, 'x', '-so', '-spd', '-y', '-bso0', '-bsp0', '-bse2',
                                str(archive_path), item['member']], directory=destinations[0],
                               environment=environment, limit=item['size'], timeout=120)
            if len(content) != item['size'] or hashlib.sha256(content).hexdigest() != item['sha256']:
                raise GraphicsError('selected driver bytes differ from pinned identity')
            if _identity(archive_path) != archive_identity:
                raise GraphicsError('retained archive changed during extraction')
            for directory in destinations:
                if _directory_identity(directory) != directory_ids[directory]:
                    raise GraphicsError('staging directory changed')
                fd, temporary_name = tempfile.mkstemp(prefix='.graphics-stage-', dir=directory)
                temporary = Path(temporary_name)
                try:
                    with os.fdopen(fd, 'wb') as output:
                        output.write(content)
                        output.flush()
                        os.fsync(output.fileno())
                    destination = directory / name
                    _publish(temporary, destination)
                    owned.append((destination, _identity(destination), item))
                    receipt['files'].append({'path': str(destination), 'size': item['size'],
                                             'sha256': item['sha256'], 'member': item['member']})
                finally:
                    temporary.unlink(missing_ok=True)
        verify_archive(archive_path)
        yield result
    except BaseException as error:
        if retain_required(error):
            result.mark_writers_uncertain()
        raise
    finally:
        failure = sys.exc_info()[1]
        preserved = []
        for path, identity, item in reversed(owned):
            if result.writers_uncertain:
                preserved.append(str(path))
                continue
            try:
                if _directory_identity(path.parent) != directory_ids[path.parent] or _identity(path) != identity:
                    raise GraphicsError('staged driver identity changed')
                _checked_file(path, item)
                path.unlink()
            except (OSError, GraphicsError):
                preserved.append(str(path))
        receipt['cleanup'] = ('retained-uncertain' if result.writers_uncertain else
                              'preserved-changed-files' if preserved else 'removed')
        if preserved:
            receipt['preserved_files'] = preserved
            error = GraphicsError('cleanup preserved uncertain, changed or inaccessible staged files; inspect owned output')
            error.graphics_receipt = receipt
            raise error from failure
        if failure is not None:
            failure.graphics_receipt = receipt


def run_probe(executable, *, environment, expected_directory):
    directory = _directory(expected_directory)
    executable = Path(os.path.abspath(executable))
    if executable.parent != directory:
        raise GraphicsError('probe executable must be beside the staged driver files')
    _identity(executable)
    metadata = lock()
    identities = {name: _checked_file(directory / name, metadata['files'][name]) for name in SELECTED}
    raw = _command([str(executable)], directory=directory, environment=child_environment(environment),
                   limit=65536, timeout=30)
    try:
        result = _json(raw)
    except (ValueError, UnicodeDecodeError) as error:
        raise GraphicsError('invalid native graphics probe receipt') from error
    if (not isinstance(result, dict) or result.get('schema_version') != 1 or result.get('status') != 'passed'
            or any(type(result.get(key)) is not int for key in ('major', 'minor'))
            or result.get('wgl_create_context_attribs_arb') is not True
            or result.get('wgl_choose_pixel_format_arb') is not True
            or result.get('gl_buffer_storage') is not True
            or type(result.get('arb_buffer_storage')) is not bool
            or not ((result['major'], result['minor']) >= (4, 4)
                    or ((result['major'], result['minor']) >= (4, 3) and result['arb_buffer_storage']))
            or any(not isinstance(result.get(key), str) or not result[key] or len(result[key]) > 4096
                   for key in ('version', 'vendor', 'renderer'))
            or 'llvmpipe' not in result['renderer'].lower() or result.get('error') != ''):
        raise GraphicsError('native driver capabilities did not satisfy the required profile')
    for name, field in (('opengl32.dll', 'opengl32_path'), ('libgallium_wgl.dll', 'libgallium_wgl_path')):
        path = result.get(field)
        if not isinstance(path, str) or not Path(path).is_absolute() or Path(path) != directory / name:
            raise GraphicsError('probe loaded a driver outside the staged directory')
        if _checked_file(directory / name, metadata['files'][name]) != identities[name]:
            raise GraphicsError('staged driver changed during native probe')
    return {'schema_version': 1, 'scope': 'host-qualification-only', 'probe': result,
            'archive_sha256': metadata['archive']['sha256'],
            'driver_files': {name: metadata['files'][name]['sha256'] for name in SELECTED}}


def compile_probe(probe_directory, compile_log, *, environment=None, protected_roots=(), strict_completion=False):
    """Compile the exact host probe with selected MSVC, without acquiring a driver.

    A fresh owned directory and log are required; supervisor completion, source
    stability and output identity checks are shared with graphics qualification.
    """
    environment = child_environment(environment)
    directory = _directory(probe_directory)
    protected = [_protected_root(root) for root in protected_roots]
    if any(directory == root or root in directory.parents or directory in root.parents for root in protected):
        raise GraphicsError('probe output overlaps a protected SDK, dependency or install root')
    compile_log = _directory(Path(compile_log).parent) / Path(compile_log).name
    executable, object_file = directory / 'windows-gl-probe.exe', directory / 'windows-gl-probe.obj'
    for target in (executable, object_file, compile_log):
        if any(path.name.casefold() == target.name.casefold() for path in target.parent.iterdir()):
            raise GraphicsError('probe output already exists; use a fresh owned directory')
    compiler = shutil.which('cl.exe', path=environment.get('PATH', environment.get('Path', '')))
    if compiler is None:
        raise GraphicsError('selected MSVC cl.exe is unavailable in the supplied environment')
    if type(strict_completion) is not bool:
        raise GraphicsError('strict compiler completion must be an explicit boolean')
    compiler_helper = None if strict_completion else _msvc_telemetry(compiler)
    source = Path(__file__).with_name('windows_gl_probe.cpp')
    before = source.read_bytes()
    _command([compiler, '/nologo', '/std:c++20', '/EHsc', str(source), '/Fo:' + str(object_file),
              '/Fe:' + str(executable), '/link', '/INCREMENTAL:NO', 'opengl32.lib', 'gdi32.lib', 'user32.lib'],
             directory=directory, environment=environment, limit=1024 * 1024, timeout=300, record=compile_log,
             compiler_helper=compiler_helper)
    if source.read_bytes() != before:
        raise GraphicsError('native probe source changed during compilation')
    _identity(executable)
    completion = (compiler_helper.receipt() if compiler_helper is not None else
                  {'policy': 'strict', 'outcome': 'no-surviving-descendants', 'stopped_pids': []})
    return executable, {'completion': completion, 'source_sha256': hashlib.sha256(before).hexdigest(),
                        'executable_sha256': hashlib.sha256(executable.read_bytes()).hexdigest(),
                        'log_sha256': hashlib.sha256(compile_log.read_bytes()).hexdigest(),
                        'compiler': str(Path(compiler).absolute())}


@contextmanager
def _qualified_stage(archive_path, directories, *, probe_directory, compile_log,
                     environment=None, protected_roots=(), extractor='7z'):
    """Compile with the caller's selected MSVC, probe, then expose owned staging.

    Probe executable, object and bounded compiler log are retained as evidence;
    the two host DLLs are temporary. This requires a fresh owned probe directory.
    """
    environment = child_environment(environment)
    directory = _directory(probe_directory)
    protected = [_protected_root(root) for root in protected_roots]
    executable, compilation = compile_probe(directory, compile_log, environment=environment,
                                             protected_roots=protected)
    with stage(archive_path, [directory, *directories], environment=environment,
               extractor=extractor, protected_roots=protected) as staged:
        staged.receipt['compile'] = compilation
        staged.probe_receipt = run_probe(executable, environment=staged.environment, expected_directory=directory)
        staged.receipt['native_probe'] = staged.probe_receipt
        yield staged


@contextmanager
def qualified_stage(archive_path, directories, *, probe_directory, compile_log,
                    environment=None, protected_roots=(), extractor='7z'):
    """Expose shared native qualification and attach cleanup evidence on failure."""
    try:
        with _qualified_stage(archive_path, directories, probe_directory=probe_directory,
                              compile_log=compile_log, environment=environment,
                              protected_roots=protected_roots, extractor=extractor) as staged:
            yield staged
    except BaseException as error:
        if not hasattr(error, 'graphics_receipt'):
            error.graphics_receipt = {'schema_version': 1, 'scope': 'host-qualification-only',
                                      'files': [], 'native_probe': None,
                                      'cleanup': ('retained-uncertain' if retain_required(error)
                                                  else 'removed')}
        raise


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='operation', required=True)
    for name in ('verify', 'fetch'):
        item = sub.add_parser(name)
        item.add_argument('archive', type=Path)
        if name == 'fetch':
            item.add_argument('--network', action='store_true')
    args = parser.parse_args()
    try:
        result = fetch(args.archive, network=args.network) if args.operation == 'fetch' else verify_archive(args.archive)
        print(json.dumps(result, sort_keys=True))
    except (GraphicsError, OSError, ValueError) as error:
        parser.exit(1, str(error) + '\n')


if __name__ == '__main__':
    main()

